const clinicaLoteUmBlocos=[
["Eventos adversos",["evento adverso é ocorrência indesejada associada ao uso de medicamento, com ou sem relação causal confirmada.","suspeita de reação adversa merece avaliação mesmo quando a causalidade não está definida.","gravidade, cronologia e medicamentos concomitantes ajudam na avaliação de evento adverso.","registro detalhado favorece acompanhamento e comunicação de segurança.","sinais de gravidade exigem orientação e encaminhamento compatíveis com o caso."],["evento adverso só existe após comprovação absoluta de causalidade.","suspeita sem confirmação não deve ser registrada.","cronologia não contribui para avaliação de segurança.","registro de evento não tem utilidade para acompanhamento.","sinal de gravidade pode aguardar orientação de rotina."]],
["Interações medicamentosas",["interação pode alterar efeito, concentração ou toxicidade de um ou mais medicamentos.","risco de interação depende de medicamentos envolvidos, dose, tempo de uso e características do paciente.","interações farmacodinâmicas podem ocorrer quando fármacos atuam sobre efeitos fisiológicos relacionados.","interações farmacocinéticas podem alterar absorção, metabolismo, distribuição ou eliminação.","identificação de interação exige avaliar relevância clínica, e não apenas sua possibilidade teórica."],["interação ocorre apenas entre medicamentos da mesma classe.","dose e condição clínica não influenciam risco de interação.","interação farmacodinâmica sempre altera concentração plasmática.","interação farmacocinética se limita à aparência do medicamento.","qualquer interação teórica apresenta a mesma relevância clínica."]],
["Função renal",["função renal pode influenciar eliminação de medicamentos e metabólitos.","ajuste de dose pode ser necessário conforme medicamento e grau de comprometimento renal.","avaliação renal deve considerar dados clínicos e laboratoriais apropriados ao caso.","acúmulo de medicamento pode aumentar risco de efeitos adversos em insuficiência renal.","decisão de ajuste depende da substância, indicação e função do paciente."],["função renal não interfere na eliminação de fármacos.","todo medicamento exige o mesmo ajuste em qualquer disfunção renal.","um único dado isolado substitui toda avaliação clínica.","insuficiência renal impede qualquer acúmulo de medicamentos.","ajuste depende apenas da idade, sem relação com o medicamento."]],
["Função hepática",["doença hepática pode alterar metabolismo de medicamentos sujeitos a biotransformação hepática.","risco de acúmulo depende das características do fármaco e da extensão da disfunção.","sinais clínicos e exames podem auxiliar a individualizar a farmacoterapia.","medicamentos hepatotóxicos requerem atenção quando há fator de risco hepático.","monitoramento deve ser definido conforme fármaco, indicação e condição do paciente."],["fígado não participa do metabolismo de medicamentos.","todo fármaco apresenta risco idêntico em doença hepática.","condição clínica não interfere na escolha do tratamento.","hepatotoxicidade não depende do medicamento utilizado.","monitoramento hepático é igual para todos os tratamentos."]],
["Adesão ao tratamento",["adesão pode ser prejudicada por esquema complexo, efeitos adversos, custo ou dificuldade de acesso.","orientação clara sobre finalidade, modo de uso e duração favorece o uso adequado.","escuta do paciente ajuda a identificar barreiras reais ao tratamento.","simplificação do esquema pode ser considerada quando clinicamente apropriada.","não adesão deve ser abordada sem julgamento, buscando solução compartilhada."],["adesão depende apenas de força de vontade do paciente.","orientação sobre uso não altera a continuidade do tratamento.","barreiras relatadas pelo paciente não precisam ser consideradas.","esquema complexo sempre melhora adesão.","abordagem julgadora favorece comunicação terapêutica."]],
["Antimicrobianos",["uso racional de antimicrobianos considera indicação, agente provável, dose, intervalo e duração adequados.","adesão ao tratamento antimicrobiano deve ser orientada conforme prescrição e condição clínica.","uso inadequado pode contribuir para seleção de microrganismos resistentes.","avaliação de alergia relatada deve considerar manifestação, cronologia e medicamento envolvido.","sintomas de piora ou reação relevante exigem reavaliação clínica."],["antimicrobianos são indicados para qualquer síndrome viral.","intervalo entre doses não influencia resultado do tratamento.","uso inadequado não participa da resistência microbiana.","qualquer relato de alergia tem a mesma interpretação clínica.","piora durante tratamento deve ser ignorada até o fim da prescrição."]],
["Analgésicos",["escolha de analgésico considera causa, intensidade da dor, comorbidades e medicamentos concomitantes.","uso de múltiplos produtos exige conferência para evitar duplicidade de princípio ativo.","anti-inflamatórios podem demandar atenção a riscos gastrointestinais, renais e cardiovasculares conforme o paciente.","opioides exigem atenção a sedação, depressão respiratória e outros riscos clínicos.","orientação sobre duração e sinais de alerta integra o uso seguro de analgésicos."],["intensidade e causa da dor não influenciam escolha de analgésico.","produtos diferentes nunca compartilham princípio ativo.","anti-inflamatórios não apresentam riscos dependentes do paciente.","opioides não exigem acompanhamento de segurança.","orientação de sinais de alerta não tem função no uso de analgésicos."]],
["Insulinoterapia",["insulina exige orientação sobre técnica de aplicação e conservação conforme a apresentação utilizada.","alternância de locais de aplicação ajuda a reduzir alterações locais associadas ao uso repetido.","hipoglicemia deve ser reconhecida e manejada conforme orientação clínica individual.","dose de insulina não deve ser alterada de forma autônoma sem plano previamente definido.","monitoramento glicêmico pode orientar ajustes conforme o esquema terapêutico."],["toda insulina pode ser armazenada nas mesmas condições após aberta.","aplicar repetidamente no mesmo ponto não produz efeito local.","hipoglicemia não precisa ser reconhecida pelo usuário.","dose deve ser modificada livremente sem plano terapêutico.","monitoramento glicêmico não contribui para acompanhamento."]],
["Dispositivos inalatórios",["efetividade de medicamento inalatório depende de técnica compatível com o dispositivo prescrito.","demonstração e retorno da técnica ajudam a identificar erros de uso.","dispositivos diferentes podem exigir etapas distintas de preparo e inalação.","uso de espaçador pode ser recomendado em situações específicas conforme o tipo de inalador.","higienização do dispositivo deve seguir orientação do fabricante ou do serviço de saúde."],["técnica de inalação não altera a deposição do medicamento.","explicação verbal dispensa demonstração da técnica.","todos os inaladores são utilizados exatamente da mesma forma.","espaçador pode ser usado indistintamente em qualquer dispositivo.","higienização não interfere no funcionamento do inalador."]],
["Conciliação medicamentosa",["conciliação compara listas de medicamentos para identificar discrepâncias em transições de cuidado.","fontes múltiplas podem ser necessárias para obter lista mais confiável de uso do paciente.","discrepância identificada deve ser avaliada e comunicada à equipe responsável.","medicamentos de uso eventual e produtos sem prescrição também podem ser relevantes na conciliação.","conciliação reduz risco de omissões, duplicidades e divergências não intencionais."],["conciliação considera somente a prescrição mais recente.","uma única fonte garante lista completa em todos os casos.","discrepância pode ser ignorada quando o nome do medicamento é conhecido.","produtos sem prescrição não interferem na conciliação.","conciliação aumenta necessariamente risco de duplicidade."]]
];
