const clinicaLoteDoisBlocos=[
["Anticoagulantes",["anticoagulante exige avaliação de indicação, risco de sangramento e medicamentos concomitantes.","sinais de sangramento devem ser orientados e avaliados conforme gravidade e contexto clínico.","adesão e regularidade de uso são relevantes para a efetividade de anticoagulantes.","interações podem aumentar ou reduzir o efeito anticoagulante, conforme o medicamento envolvido.","troca ou suspensão de anticoagulante deve ocorrer conforme orientação profissional."],["anticoagulante não exige atenção a sinais de sangramento.","uso irregular mantém sempre o mesmo efeito clínico.","interações não afetam medicamentos anticoagulantes.","suspensão pode ser decidida sem avaliação clínica.","risco de sangramento independe das condições do paciente."]],
["Anti-hipertensivos",["tratamento anti-hipertensivo pode exigir acompanhamento de pressão, tolerabilidade e adesão.","tontura ou sintomas de hipotensão devem ser avaliados no contexto do tratamento.","uso concomitante de outros medicamentos pode influenciar resposta hemodinâmica.","interrupção abrupta de tratamento deve ser evitada quando não há orientação específica.","medidas não farmacológicas podem complementar o tratamento conforme plano de cuidado."],["pressão arterial não precisa de acompanhamento durante tratamento.","sintomas de hipotensão não têm relação com tratamento em uso.","medicamentos concomitantes não influenciam resposta hemodinâmica.","interrupção abrupta é sempre a conduta preferível.","medidas não farmacológicas não participam do cuidado da hipertensão."]],
["Antidiabéticos orais",["escolha de antidiabético considera perfil glicêmico, comorbidades e risco de eventos adversos.","hipoglicemia pode ocorrer com alguns esquemas e deve ser reconhecida pelo paciente.","função renal pode influenciar segurança ou necessidade de ajuste de determinados antidiabéticos.","orientação sobre alimentação e monitoramento integra o cuidado farmacoterapêutico.","uso combinado exige revisão de duplicidades, interações e metas terapêuticas."],["todos os antidiabéticos apresentam o mesmo risco de hipoglicemia.","função renal não influencia tratamento antidiabético.","alimentação não se relaciona ao controle glicêmico.","associação de medicamentos dispensa revisão de segurança.","comorbidades não interferem na escolha do tratamento."]],
["Corticosteroides",["corticosteroides podem exigir atenção à dose, duração e risco de efeitos sistêmicos.","uso prolongado deve ser acompanhado conforme medicamento, indicação e condição clínica.","suspensão após uso prolongado pode requerer planejamento clínico individualizado.","via de administração influencia exposição sistêmica e perfil de risco.","orientação ao paciente deve incluir uso correto e sinais que justifiquem reavaliação."],["dose e duração não alteram risco de corticosteroides.","uso prolongado dispensa acompanhamento.","suspensão é igual para todo paciente independentemente do contexto.","via de administração não altera exposição ao fármaco.","orientação ao paciente não influencia uso seguro."]],
["Medicamentos para asma",["controle da asma depende de técnica inalatória, adesão e avaliação dos sintomas.","medicação de alívio e medicação de controle possuem papéis distintos no plano terapêutico.","necessidade frequente de alívio pode indicar necessidade de reavaliação do controle.","dispositivo inalatório deve ser revisado periodicamente quanto à técnica de uso.","plano de ação orienta conduta diante de piora dos sintomas conforme avaliação clínica."],["técnica inalatória não interfere no controle da asma.","medicação de alívio substitui sempre toda estratégia de controle.","uso frequente de alívio confirma controle adequado.","técnica não precisa ser revisada após a primeira orientação.","piora de sintomas não exige plano de ação ou reavaliação."]],
["Uso pediátrico",["dose pediátrica pode depender de peso, idade, indicação e apresentação disponível.","dispositivo dosador apropriado reduz erro de medida em preparações líquidas.","cálculo e conferência são essenciais quando a dose é individualizada para criança.","orientação ao cuidador deve incluir forma de administração e armazenamento.","medicamentos de adultos não devem ser adaptados à criança sem avaliação adequada."],["idade e peso não influenciam dose pediátrica.","colher doméstica oferece sempre medida precisa.","dose individualizada dispensa conferência.","cuidador não precisa receber orientação de administração.","medicamento de adulto pode ser adaptado livremente para criança."]],
["Pessoa idosa",["polifarmácia aumenta a necessidade de revisão de indicação, duplicidades e interações.","alterações fisiológicas podem modificar resposta e tolerabilidade a medicamentos.","simplificação do esquema pode favorecer adesão quando clinicamente viável.","risco de queda, confusão ou hipotensão pode ser relevante para alguns medicamentos.","revisão periódica contribui para identificar medicamentos potencialmente inadequados."],["número de medicamentos não altera necessidade de revisão.","idade não modifica resposta ou tolerabilidade a medicamentos.","esquema complexo favorece sempre adesão.","risco de queda não tem relação com farmacoterapia.","revisão periódica não identifica oportunidades de ajuste."]],
["Gestação e lactação",["avaliação de medicamento na gestação considera risco materno, fetal e benefício clínico esperado.","medicamento de uso contínuo não deve ser suspenso sem avaliação profissional.","exposição durante lactação depende de características do fármaco e do contexto do lactente.","automedicação deve ser evitada quando há gestação ou amamentação sem orientação adequada.","decisão terapêutica deve ser individualizada conforme condição clínica e evidência disponível."],["todo medicamento apresenta risco idêntico na gestação.","medicamento contínuo deve ser suspenso automaticamente ao confirmar gestação.","lactação não depende das características do fármaco.","automedicação é segura em qualquer fase da gestação.","decisão terapêutica independe de condição clínica individual."]],
["Vacinação",["conservação de vacinas depende do cumprimento das condições recomendadas para cada produto.","excursão de temperatura deve ser registrada e avaliada antes da utilização do imunobiológico.","identificação de lote e validade integra a rastreabilidade da vacinação.","orientação após vacinação pode incluir informações sobre eventos esperados e sinais de alerta.","não conformidade na cadeia de frio exige conduta documentada e avaliação técnica."],["todas as vacinas permanecem estáveis em qualquer temperatura.","excursão de temperatura não precisa ser registrada.","lote e validade não são relevantes na vacinação.","orientação após vacinação não tem utilidade.","não conformidade de cadeia de frio pode ser ignorada se o frasco estiver fechado."]],
["Uso racional de medicamentos",["uso racional envolve medicamento apropriado, dose adequada, tempo necessário e menor custo compatível para o paciente e a comunidade.","prescrição, dispensação e acompanhamento são etapas complementares do uso seguro.","informação ao paciente favorece participação consciente no tratamento.","avaliação de efetividade e segurança pode indicar necessidade de ajuste terapêutico.","decisão farmacoterapêutica deve integrar evidência, condição clínica e preferências do paciente."],["uso racional significa utilizar o maior número possível de medicamentos.","prescrição isolada elimina necessidade de dispensação e acompanhamento.","paciente não precisa compreender seu tratamento.","efetividade e segurança não exigem reavaliação.","preferências e condição clínica não participam da decisão terapêutica."]]
];
