const respostasOriginaisMatematicaRedistribuicao = new Map(questionBank.questions.filter(question=>question.subjectId === "matematica").map(question=>[question.number,question.answer]));
const matematicaRedistribuicaoPorNumero = new Map(matematicaRedistribuicaoHibrida.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = respostasOriginaisMatematicaRedistribuicao.get(number) ?? "ABCDE"[(number-1)%5];
  return [number,{id:`matematica-${number}`,subjectId:"matematica",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation}];
}));
questionBank.questions = questionBank.questions.map(question => matematicaRedistribuicaoPorNumero.get(question.number) && question.subjectId === "matematica" ? matematicaRedistribuicaoPorNumero.get(question.number) : question);
questionBank.review.matematicaRedistribuicaoHibridaReviewed = matematicaRedistribuicaoHibrida.map(([number])=>number);
questionBank.subjects.forEach(subject => {
  subject.count = questionBank.questions.filter(question => question.subjectId === subject.id).length;
});
// Reforma editorial de Farmácia — bloco 1: remove cabeçalhos repetidos da
