// Direito Constitucional — lote 1 (51–100). Revisado conforme Constituição Federal.
const direitoConstitucionalLoteUm = [
  [51,"Princípios fundamentais","Princípios fundamentais","A República Federativa do Brasil constitui-se em Estado Democrático de Direito e tem, entre seus fundamentos:","a cidadania, a dignidade da pessoa humana e o pluralismo político.",["a supremacia de uma religião oficial, a cidadania e a livre iniciativa.","a soberania popular direta como única forma de exercício do poder estatal.","a erradicação da pobreza, a defesa da paz e a cidadania.","a independência nacional, a autodeterminação dos povos e o pluralismo político."],"Os fundamentos do art. 1º incluem soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo político. Os demais itens misturam objetivos ou princípios das relações internacionais."],
  [52,"Princípios fundamentais","Princípios fundamentais","Segundo a Constituição, todo poder emana do povo, que o exerce:","por meio de representantes eleitos ou diretamente, nos termos constitucionais.",["apenas por representantes escolhidos em eleições proporcionais.","somente de modo direto, mediante plebiscitos e referendos nacionais.","por delegação permanente aos Poderes Executivo, Legislativo e Judiciário.","por meio de partidos políticos previamente autorizados pelo Poder Judiciário."],"O parágrafo único do art. 1º prevê as duas formas de exercício da soberania popular: representantes eleitos e exercício direto, nos termos da Constituição."],
  [53,"Princípios fundamentais","Princípios fundamentais","É objetivo fundamental da República Federativa do Brasil:","reduzir as desigualdades sociais e regionais.",["instituir religião oficial que represente a maioria da população.","assegurar prioridade absoluta aos interesses econômicos nacionais sobre os direitos humanos.","centralizar nos Estados todas as competências legislativas concorrentes.","subordinar os Municípios à administração direta da União."],"A redução das desigualdades sociais e regionais está expressamente no art. 3º, III. Os demais itens não correspondem aos objetivos fundamentais."],
  [54,"Princípios fundamentais","Princípios fundamentais","No plano das relações internacionais, a Constituição determina que o Brasil se rege, entre outros, pelo princípio da:","prevalência dos direitos humanos.",["intervenção obrigatória em Estados que descumpram tratados multilaterais.","subordinação da cooperação entre os povos à autorização prévia de potências estrangeiras.","preferência pela solução militar de controvérsias internacionais.","recusa do asilo político em qualquer hipótese."],"O art. 4º inclui a prevalência dos direitos humanos, a não intervenção, a defesa da paz, a solução pacífica dos conflitos e a concessão de asilo político."],
  [55,"Princípios fundamentais","Princípios fundamentais","A organização política brasileira é estruturada pela separação de Poderes. Nessa lógica, os Poderes da União são:","Legislativo, Executivo e Judiciário, independentes e harmônicos entre si.",["Legislativo, Moderador e Judiciário, subordinados ao Presidente da República.","Executivo, Militar e Judiciário, com hierarquia definida pelo Congresso Nacional.","Legislativo, Executivo e Ministério Público, todos submetidos ao Poder Judiciário.","Executivo, Legislativo e Tribunal de Contas, com competências intercambiáveis."],"O art. 2º estabelece que Legislativo, Executivo e Judiciário são Poderes da União, independentes e harmônicos entre si."],
  [56,"Princípios fundamentais","Princípios fundamentais","A forma de Estado adotada pela Constituição brasileira decorre da união indissolúvel:","dos Estados, dos Municípios e do Distrito Federal.",["da União, das regiões metropolitanas e dos Territórios autônomos.","dos Estados, dos partidos políticos e das Forças Armadas.","dos Municípios, dos consórcios públicos e das autarquias federais.","da União e dos Estados, sem participação constitucional dos Municípios."],"O caput do art. 1º refere-se à união indissolúvel dos Estados, Municípios e Distrito Federal. A União é pessoa federativa, mas a fórmula constitucional é essa."],
  [57,"Princípios fundamentais","Princípios fundamentais","A promoção do bem de todos, sem preconceitos de origem, raça, sexo, cor, idade e quaisquer outras formas de discriminação, é:","objetivo fundamental da República.",["competência privativa da União em matéria de segurança pública.","princípio exclusivo das relações internacionais brasileiras.","atribuição constitucional reservada ao Poder Judiciário.","condição para a criação de novos Municípios."],"O art. 3º, IV, qualifica a promoção do bem de todos sem discriminação como objetivo fundamental da República."],
  [58,"Princípios fundamentais","Princípios fundamentais","A Constituição prevê que o Brasil buscará a integração econômica, política, social e cultural dos povos da:","América Latina, visando à formação de uma comunidade latino-americana de nações.",["Europa, mediante transferência progressiva de soberania aos órgãos comunitários.","Comunidade dos Países de Língua Portuguesa, com adoção de cidadania única obrigatória.","América do Sul, exclusivamente por meio de acordos de defesa militar.","Organização das Nações Unidas, mediante instituição de governo mundial."],"O parágrafo único do art. 4º fixa a busca da integração latino-americana, sem limitar a iniciativa a defesa militar ou a uma única organização."],
  [59,"Princípios fundamentais","Princípios fundamentais","A erradicação da pobreza e da marginalização, bem como a redução das desigualdades sociais e regionais, são classificadas constitucionalmente como:","objetivos fundamentais da República.",["direitos individuais de eficácia condicionada à lei complementar.","princípios exclusivos da ordem econômica.","competências comuns de Estados e Municípios.","garantias institucionais das Forças Armadas."],"São objetivos fundamentais previstos no art. 3º, III, e não competências federativas ou direitos individuais isolados."],
  [60,"Princípios fundamentais","Princípios fundamentais","Entre os princípios constitucionais que orientam as relações internacionais do Brasil encontra-se o repúdio:","ao terrorismo e ao racismo.",["à cooperação entre os povos para o progresso da humanidade.","à concessão de asilo político em situações humanitárias.","à solução pacífica dos conflitos internacionais.","à igualdade entre os Estados."],"O art. 4º, VIII, prevê o repúdio ao terrorismo e ao racismo. Cooperação, asilo, solução pacífica e igualdade são princípios acolhidos pela Constituição."],
  [61,"Nacionalidade","Nacionalidade","É brasileiro nato, nos termos da Constituição, o nascido na República Federativa do Brasil, ainda que de pais estrangeiros, desde que estes:","não estejam a serviço de seu país de origem.",["tenham residência permanente no Brasil há pelo menos cinco anos.","optem pela nacionalidade brasileira antes do nascimento.","não possuam outra nacionalidade reconhecida.","sejam naturais de Estado que adote língua portuguesa."],"O art. 12, I, a, considera nato o nascido no Brasil, salvo se os pais estrangeiros estiverem a serviço de seu país."],
  [62,"Nacionalidade","Nacionalidade","A pessoa nascida no exterior, de pai brasileiro ou mãe brasileira a serviço da República Federativa do Brasil, é:","brasileira nata.",["brasileira naturalizada após registro consular.","estrangeira até completar dezoito anos.","brasileira somente se residir no País por quinze anos.","portuguesa equiparada, desde que haja reciprocidade."],"O art. 12, I, b, reconhece a nacionalidade nata ao nascido no exterior de pai ou mãe brasileira a serviço da República."],
  [63,"Nacionalidade","Nacionalidade","O brasileiro naturalizado pode ocupar, entre outros cargos, o de:","Ministro de Estado, ressalvado o cargo de Ministro da Defesa.",["Presidente da República.","Presidente do Senado Federal.","oficial das Forças Armadas.","membro da carreira diplomática."],"O art. 12, § 3º reserva determinados cargos aos brasileiros natos, entre eles Presidente da República, Presidente do Senado, oficial das Forças Armadas, carreira diplomática e Ministro da Defesa. Ministro de Estado, em regra, não é reservado."],
  [64,"Nacionalidade","Nacionalidade","A Constituição admite a extradição de brasileiro naturalizado quando houver:","comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei.",["pedido formulado por qualquer Estado estrangeiro, independentemente do fato imputado.","crime político praticado no Brasil após a naturalização.","infração administrativa grave cometida antes da naturalização.","condenação por contravenção penal no exterior."],"O art. 5º, LI, admite a extradição do naturalizado por crime comum praticado antes da naturalização ou por comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins."],
  [65,"Nacionalidade","Nacionalidade","O brasileiro nato:","não será extraditado.",["pode ser extraditado por crime hediondo praticado fora do País.","pode ser extraditado se adquirir outra nacionalidade após os dezoito anos.","pode ser extraditado por ato contra a administração pública estrangeira.","somente não pode ser extraditado para países sul-americanos."],"A vedação de extradição do brasileiro nato é expressa no art. 5º, LI. As exceções constitucionais citadas dizem respeito ao naturalizado."],
  [66,"Nacionalidade","Nacionalidade","A lei não pode estabelecer distinção entre brasileiros natos e naturalizados, salvo:","nos casos previstos pela própria Constituição.",["para o acesso a qualquer emprego público federal.","quando o naturalizado possuir residência inferior a vinte anos.","nas relações privadas entre brasileiros e estrangeiros.","por decisão administrativa motivada do Ministério da Justiça."],"O art. 12, § 2º, veda distinções entre natos e naturalizados, exceto nos casos expressamente previstos pela Constituição."],
  [67,"Nacionalidade","Nacionalidade","Os originários de países de língua portuguesa podem obter naturalização brasileira, na forma constitucional, mediante:","residência por um ano ininterrupto e idoneidade moral.",["residência por quinze anos ininterruptos, sem condenação penal.","aprovação em concurso público federal e domicílio eleitoral.","renúncia obrigatória à nacionalidade de origem.","casamento com brasileiro nato por, no mínimo, cinco anos."],"O art. 12, II, a, prevê para originários de países de língua portuguesa residência por um ano ininterrupto e idoneidade moral."],
  [68,"Nacionalidade","Nacionalidade","Aos portugueses com residência permanente no País, se houver reciprocidade em favor de brasileiros, podem ser atribuídos:","os direitos inerentes ao brasileiro, salvo os casos previstos na Constituição.",["todos os cargos privativos de brasileiro nato.","a nacionalidade brasileira nata, automaticamente.","direitos políticos sem necessidade de requerimento administrativo.","imunidade penal equivalente à de agente diplomático."],"O art. 12, § 1º, prevê a equiparação de direitos, salvo exceções constitucionais, condicionada à reciprocidade. Não transforma o português em brasileiro nato."],
  [69,"Nacionalidade","Nacionalidade","É cargo privativo de brasileiro nato:","Presidente da Câmara dos Deputados.",["Ministro de Estado da Saúde.","Prefeito municipal.","Deputado estadual.","membro de conselho profissional."],"O art. 12, § 3º, reserva aos natos, entre outros, os cargos de Presidente da Câmara dos Deputados e Presidente do Senado Federal."],
  [70,"Nacionalidade","Nacionalidade","A naturalização extraordinária é reconhecida ao estrangeiro de qualquer nacionalidade que, na forma constitucional, resida no Brasil há mais de:","quinze anos ininterruptos, sem condenação penal, desde que requeira a nacionalidade brasileira.",["cinco anos, desde que tenha filho brasileiro nato.","dez anos, desde que exerça atividade econômica no País.","um ano, mediante idoneidade moral e domínio da língua portuguesa.","vinte anos, independentemente de requerimento."],"O art. 12, II, b, prevê residência ininterrupta por mais de quinze anos, ausência de condenação penal e requerimento do interessado."],
  [71,"Direitos políticos","Direitos políticos","O alistamento eleitoral e o voto são obrigatórios para os maiores de:","dezoito anos, ressalvadas as exceções constitucionais.",["dezesseis anos, sem qualquer exceção.","vinte e um anos, salvo os servidores públicos.","dezoito anos apenas quando houver filiação partidária.","vinte e cinco anos, para todos os cargos eletivos."],"O voto é obrigatório para maiores de dezoito anos e facultativo nas hipóteses do art. 14, § 1º, II, como analfabetos, maiores de setenta e jovens de dezesseis e dezessete anos."],
  [72,"Direitos políticos","Direitos políticos","O voto é facultativo para:","os maiores de setenta anos.",["os estrangeiros residentes há mais de quinze anos.","os conscritos durante o período do serviço militar obrigatório.","os maiores de vinte e um anos que não exerçam atividade remunerada.","os ocupantes de cargo público em comissão."],"Entre os grupos com voto facultativo estão os maiores de setenta anos. Estrangeiros e conscritos não podem alistar-se como eleitores."],
  [73,"Direitos políticos","Direitos políticos","Não podem alistar-se como eleitores:","os estrangeiros e, durante o período do serviço militar obrigatório, os conscritos.",["os brasileiros natos maiores de setenta anos.","os brasileiros naturalizados sem filiação partidária.","os analfabetos e os jovens com dezesseis anos completos.","os servidores públicos militares aposentados."],"O art. 14, § 2º, veda o alistamento eleitoral de estrangeiros e conscritos durante o serviço militar obrigatório. Analfabetos e jovens de 16 e 17 podem votar facultativamente."],
  [74,"Direitos políticos","Direitos políticos","Constitui condição de elegibilidade, na forma da lei:","a filiação partidária.",["a nacionalidade estrangeira equiparada.","a ausência de domicílio eleitoral na circunscrição.","o exercício prévio de mandato eletivo.","a idade mínima de dezoito anos para todos os cargos."],"O art. 14, § 3º, inclui nacionalidade brasileira, pleno exercício dos direitos políticos, alistamento, domicílio eleitoral, filiação partidária e idades mínimas específicas."],
  [75,"Direitos políticos","Direitos políticos","São inelegíveis, nos termos constitucionais:","os inalistáveis e os analfabetos.",["os brasileiros naturalizados e os maiores de setenta anos.","os eleitores que tenham votado facultativamente.","os filiados a partido político há mais de um ano.","os candidatos que exerçam atividade profissional privada."],"O art. 14, § 4º, estabelece que são inelegíveis os inalistáveis e os analfabetos."],
  [76,"Direitos políticos","Direitos políticos","A idade mínima para concorrer ao cargo de Presidente da República é de:","trinta e cinco anos.",["vinte e um anos.","vinte e cinco anos.","trinta anos.","dezoito anos."],"O art. 14, § 3º, VI, a, fixa trinta e cinco anos para Presidente e Vice-Presidente da República e Senador."],
  [77,"Direitos políticos","Direitos políticos","Os partidos políticos devem observar, entre outros preceitos:","caráter nacional e proibição de recebimento de recursos financeiros de entidade ou governo estrangeiros.",["subordinação administrativa ao Poder Executivo federal.","autorização prévia do Supremo Tribunal Federal para sua criação.","organização de milícias partidárias para proteção de seus dirigentes.","vinculação obrigatória a uma federação de partidos durante toda a existência."],"O art. 17 garante autonomia partidária, mas exige caráter nacional e proíbe recebimento de recursos estrangeiros e organização paramilitar."],
  [78,"Direitos políticos","Direitos políticos","A soberania popular é exercida, segundo a Constituição, pelo sufrágio universal e pelo voto direto e secreto, com valor igual para todos, e também mediante:","plebiscito, referendo e iniciativa popular.",["consulta obrigatória ao Conselho da República em toda lei ordinária.","decisão vinculante de associações civis reconhecidas pelo Congresso.","eleição indireta para todos os cargos do Poder Executivo.","veto popular automático a qualquer ato administrativo."],"O art. 14 prevê plebiscito, referendo e iniciativa popular como formas de exercício direto da soberania popular."],
  [79,"Direitos políticos","Direitos políticos","O mandato eletivo poderá ser impugnado perante a Justiça Eleitoral no prazo de quinze dias contados da diplomação, instruída a ação com provas de:","abuso do poder econômico, corrupção ou fraude.",["incompatibilidade ideológica entre candidato e partido.","ausência de experiência prévia no cargo disputado.","mudança de domicílio eleitoral após a posse.","desempenho insuficiente em debates públicos."],"O art. 14, § 10, permite a ação de impugnação de mandato eletivo por abuso do poder econômico, corrupção ou fraude, em quinze dias da diplomação."],
  [80,"Direitos políticos","Direitos políticos","A perda ou suspensão de direitos políticos somente se dará nos casos previstos na Constituição, entre eles:","condenação criminal transitada em julgado, enquanto durarem seus efeitos.",["inadimplência tributária reconhecida por autoridade administrativa.","mudança de residência para outro Município.","falta de filiação partidária do eleitor.","recusa em exercer cargo público em comissão."],"O art. 15 veda a cassação de direitos políticos e admite perda ou suspensão nas hipóteses listadas, incluindo condenação criminal transitada em julgado."],
  [81,"Organização do Estado","Organização do Estado","A organização político-administrativa da República Federativa do Brasil compreende:","União, Estados, Distrito Federal e Municípios, todos autônomos, nos termos da Constituição.",["União, Estados e Municípios, subordinados hierarquicamente ao Distrito Federal.","União, Territórios, regiões metropolitanas e Municípios, todos soberanos.","Estados, Municípios e autarquias federais, com personalidade internacional.","União e Estados, cabendo aos Municípios autonomia apenas administrativa."],"O art. 18 enumera União, Estados, Distrito Federal e Municípios como entes autônomos. Soberania pertence à República Federativa do Brasil, não a cada ente."],
  [82,"Organização do Estado","Organização do Estado","O Distrito Federal:","não pode ser dividido em Municípios.",["pode criar Municípios mediante lei distrital aprovada por maioria simples.","possui competência legislativa apenas municipal.","integra um Estado-membro para fins de organização político-administrativa.","não exerce competências legislativas reservadas aos Estados."],"O art. 32 veda a divisão do Distrito Federal em Municípios e assegura-lhe competências legislativas reservadas aos Estados e Municípios."],
  [83,"Organização do Estado","Organização do Estado","Compete privativamente à União legislar sobre:","direito civil, comercial, penal, processual, eleitoral, agrário, marítimo, aeronáutico, espacial e do trabalho.",["proteção ao meio ambiente e controle da poluição, em regime exclusivo.","educação, cultura, ensino, desporto, ciência, tecnologia, pesquisa e inovação, em regime exclusivo.","procedimentos em matéria processual, em regime exclusivo.","direito tributário, financeiro, penitenciário, econômico e urbanístico, em regime exclusivo."],"O art. 22 lista matérias de competência privativa da União, incluindo os ramos jurídicos mencionados. Meio ambiente, educação e direito tributário aparecem em competências comuns ou concorrentes."],
  [84,"Organização do Estado","Organização do Estado","É competência comum da União, dos Estados, do Distrito Federal e dos Municípios:","cuidar da saúde e assistência pública, da proteção e garantia das pessoas com deficiência.",["legislar privativamente sobre direito penal.","emitir moeda e administrar reservas cambiais.","declarar guerra e celebrar a paz.","organizar e manter o Poder Judiciário estadual."],"O art. 23, II, atribui competência comum para cuidar da saúde e assistência pública. Emissão de moeda e relações de guerra são competências da União."],
  [85,"Organização do Estado","Organização do Estado","No âmbito da legislação concorrente, a competência da União limita-se a estabelecer:","normas gerais.",["normas locais de interesse municipal.","normas específicas para cada Estado, sem participação estadual.","leis orgânicas dos Municípios.","atos administrativos individuais de todos os entes."],"Pelo art. 24, § 1º, no âmbito concorrente a União estabelece normas gerais; os Estados suplementam a legislação federal."],
  [86,"Organização do Estado","Organização do Estado","Compete aos Municípios legislar sobre assuntos de:","interesse local.",["direito penal, de forma suplementar à União.","segurança nacional, de modo concorrente com os Estados.","relações internacionais e comércio exterior.","organização da Justiça Eleitoral."],"O art. 30, I, atribui aos Municípios a competência para legislar sobre assuntos de interesse local."],
  [87,"Organização do Estado","Organização do Estado","São bens da União, entre outros:","os lagos, rios e quaisquer correntes de água em terrenos de seu domínio, ou que banhem mais de um Estado.",["as águas superficiais situadas inteiramente em território municipal, em qualquer caso.","todos os bens imóveis pertencentes a Estados e Municípios.","as terras devolutas indispensáveis à defesa das fronteiras estaduais.","as ilhas fluviais e lacustres localizadas exclusivamente em áreas urbanas municipais, sem exceção."],"O art. 20 enumera os bens da União, entre eles águas em seu domínio ou que banhem mais de um Estado. Outros bens podem pertencer a Estados ou Municípios conforme o caso."],
  [88,"Organização do Estado","Organização do Estado","A criação, incorporação, fusão e desmembramento de Municípios dependem, na forma constitucional, de:","lei estadual, dentro do período determinado por lei complementar federal, com consulta prévia mediante plebiscito às populações envolvidas.",["decreto municipal aprovado pela Câmara local, sem necessidade de consulta popular.","lei federal ordinária e autorização do Senado Federal em sessão secreta.","lei distrital, em qualquer época, após consulta apenas aos eleitores da sede.","ato do Poder Executivo estadual, desde que haja estudo de viabilidade."],"O art. 18, § 4º, exige lei estadual, período fixado por lei complementar federal, plebiscito prévio e estudos de viabilidade municipal divulgados na forma legal."],
  [89,"Organização do Estado","Organização do Estado","Aos Estados são reservadas as competências que:","não lhes sejam vedadas pela Constituição.",["estejam expressamente atribuídas apenas aos Municípios.","dependam de autorização anual da União para existir.","se refiram exclusivamente à política monetária nacional.","tenham natureza de competência privativa do Poder Judiciário."],"O art. 25, § 1º, reconhece a competência residual dos Estados: cabe-lhes o que não lhes seja vedado pela Constituição."],
  [90,"Organização do Estado","Organização do Estado","No sistema constitucional, os Territórios Federais:","integram a União.",["são entes federativos autônomos equivalentes aos Estados.","possuem soberania própria e representação diplomática.","integram o Distrito Federal para fins administrativos.","podem legislar privativamente sobre direito penal."],"O art. 18, § 2º, estabelece que os Territórios Federais integram a União; não são entes autônomos da Federação."],
  [91,"Segurança pública","Segurança pública","A segurança pública é definida constitucionalmente como dever do Estado, direito e responsabilidade de todos, exercida para a preservação:","da ordem pública e da incolumidade das pessoas e do patrimônio.",["da soberania monetária e do equilíbrio fiscal da União.","da disciplina partidária e da estabilidade dos mandatos eletivos.","da integridade exclusiva dos bens federais.","da ordem econômica, com exclusão da proteção das pessoas."],"O caput do art. 144 associa a segurança pública à preservação da ordem pública e da incolumidade das pessoas e do patrimônio."],
  [92,"Segurança pública","Segurança pública","À Polícia Federal incumbe exercer, com exclusividade, as funções de:","polícia judiciária da União.",["policiamento ostensivo dos Municípios.","defesa civil estadual.","polícia judiciária dos Estados.","guarda patrimonial das instalações municipais."],"O art. 144, § 1º, IV, atribui à Polícia Federal, com exclusividade, as funções de polícia judiciária da União."],
  [93,"Segurança pública","Segurança pública","Às polícias civis, dirigidas por delegados de polícia de carreira, incumbem, ressalvada a competência da União:","as funções de polícia judiciária e a apuração de infrações penais, exceto as militares.",["o policiamento ostensivo e a preservação da ordem pública.","a execução exclusiva das atividades de defesa civil.","a patrulha ostensiva das rodovias federais.","a proteção dos bens, serviços e instalações municipais."],"O art. 144, § 4º, atribui às polícias civis funções de polícia judiciária e apuração de infrações penais, exceto as militares."],
  [94,"Segurança pública","Segurança pública","Às polícias militares cabem:","a polícia ostensiva e a preservação da ordem pública.",["a polícia judiciária da União e o controle de fronteiras.","a apuração de toda infração penal comum praticada no Estado.","a investigação de crimes federais contra bens da União.","a perícia oficial criminal e a expedição de laudos médicos-legais."],"O art. 144, § 5º, atribui às polícias militares a polícia ostensiva e a preservação da ordem pública."],
  [95,"Segurança pública","Segurança pública","Aos corpos de bombeiros militares, além das atribuições definidas em lei, incumbe a execução de atividades de:","defesa civil.",["polícia judiciária estadual.","controle migratório e de fronteiras.","perícia oficial em crimes financeiros.","fiscalização exclusiva de rodovias federais."],"O art. 144, § 5º, prevê que aos corpos de bombeiros militares incumbe a execução de atividades de defesa civil, além das atribuições legais."],
  [96,"Segurança pública","Segurança pública","A Polícia Rodoviária Federal é órgão permanente, organizado e mantido pela União e estruturado em carreira, destinado ao:","patrulhamento ostensivo das rodovias federais, na forma da lei.",["patrulhamento de todas as vias urbanas municipais.","exercício da polícia judiciária da União.","julgamento de infrações de trânsito em segunda instância.","controle exclusivo das fronteiras marítimas."],"O art. 144, § 2º, define a Polícia Rodoviária Federal e sua destinação ao patrulhamento ostensivo das rodovias federais."],
  [97,"Segurança pública","Segurança pública","A Polícia Ferroviária Federal é destinada, na forma da lei, ao patrulhamento ostensivo:","das ferrovias federais.",["das ferrovias estaduais e municipais, com exclusividade.","de aeroportos internacionais, em substituição à Polícia Federal.","das rodovias federais, em conjunto com a Polícia Rodoviária Federal.","das instalações de empresas ferroviárias privadas, qualquer que seja a via."],"O art. 144, § 3º, destina a Polícia Ferroviária Federal ao patrulhamento ostensivo das ferrovias federais, na forma da lei."],
  [98,"Segurança pública","Segurança pública","A Constituição faculta aos Municípios constituir guardas municipais destinadas à proteção de:","seus bens, serviços e instalações, conforme dispuser a lei.",["todas as vias públicas estaduais, inclusive rodovias federais delegadas.","fronteiras nacionais e postos de imigração.","atividades de polícia judiciária e persecução penal estadual.","unidades militares e instalações diplomáticas estrangeiras."],"Pelo art. 144, § 8º, as guardas municipais destinam-se à proteção de bens, serviços e instalações municipais, na forma da lei."],
  [99,"Segurança pública","Segurança pública","A remuneração dos servidores policiais integrantes dos órgãos de segurança pública será fixada na forma do art. 39, § 4º, sendo vedado o acréscimo de:","gratificações, adicionais, abonos, prêmios, verbas de representação ou outra espécie remuneratória, observado o modelo de subsídio quando aplicável.",["qualquer parcela de natureza indenizatória, ainda que prevista em lei.","vencimento básico em valor compatível com a carreira pública.","revisão geral anual concedida na mesma data e sem distinção de índices.","benefício previdenciário regulado pela legislação específica."],"O art. 144, § 9º, remete ao regime remuneratório do art. 39, § 4º. A questão exige distinguir parcelas remuneratórias vedadas no subsídio de verbas indenizatórias legalmente cabíveis."],
  [100,"Segurança pública","Segurança pública","As polícias penais federal, estaduais e distrital vinculam-se ao órgão administrador do sistema penal da unidade federativa a que pertencem e têm como atribuição constitucional:","a segurança dos estabelecimentos penais.",["a polícia judiciária da União em todas as investigações.","o patrulhamento ostensivo das rodovias federais.","a proteção dos bens, serviços e instalações municipais.","a apuração exclusiva de crimes militares."],"O art. 144, § 5º-A, atribui às polícias penais a segurança dos estabelecimentos penais, vinculando-as ao órgão administrador do sistema penal correspondente."]
];
const direitoConstitucionalLoteUmComResposta = direitoConstitucionalLoteUm.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 51) % 5];
  return {id:`direito-constitucional-${String(number).padStart(3,"0")}`,subjectId:"direito-constitucional",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoConstitucionalLoteUmComResposta);
questionBank.review.direitoConstitucionalLoteUmReviewed = direitoConstitucionalLoteUmComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Penal — lote 5 (201–250): revisão aplicada e conclusão da matéria.
const direitoPenalLoteCinco = [
  [201,"Teoria do delito","Lei penal no tempo","Se lei posterior deixa de considerar criminosa determinada conduta, ela deve alcançar os fatos anteriores, ainda que decididos por sentença condenatória transitada em julgado. Trata-se de:","abolitio criminis.",["novatio legis in pejus.","ultratividade de lei mais gravosa.","erro de proibição.","crime impossível."],"A abolitio criminis elimina a incriminação e retroage para beneficiar o agente, alcançando inclusive condenações definitivas quanto aos efeitos penais."],
  [202,"Teoria do delito","Lei penal no tempo","Quando sobrevém lei penal mais benéfica após a prática do fato, aplica-se a ela, ainda que o processo esteja em curso ou a sentença tenha transitado em julgado. Essa regra decorre da:","retroatividade da lei penal mais benéfica.",["irretroatividade absoluta de toda lei penal.","territorialidade incondicionada.","responsabilidade objetiva.","indisponibilidade da ação penal."],"A Constituição e o Código Penal admitem retroatividade da lei penal quando favorável ao réu."],
  [203,"Teoria do delito","Territorialidade","A lei penal brasileira aplica-se, em regra, ao crime cometido no território nacional, sem prejuízo de convenções, tratados e regras de direito internacional. Essa diretriz expressa a:","territorialidade temperada.",["extraterritorialidade incondicionada como regra geral.","personalidade passiva absoluta.","universalidade obrigatória.","ubiquidade para tempo do crime."],"O art. 5º do Código Penal adota a territorialidade temperada, pois preserva exceções previstas em tratados, convenções e direito internacional."],
  [204,"Teoria do delito","Nexo causal","Causa relativamente independente que, por si só, produz o resultado rompe a imputação do resultado ao antecedente, sem prejuízo da responsabilização pelos fatos anteriores. Essa conclusão decorre da disciplina do:","nexo causal.",["erro de proibição.","arrependimento posterior.","concurso de pessoas.","princípio da insignificância."],"O art. 13, § 1º, trata da superveniência de causa relativamente independente que, por si só, produz o resultado, rompendo a imputação desse resultado."],
  [205,"Teoria do delito","Crime omissivo","O médico plantonista que, tendo dever jurídico e possibilidade de agir, deliberadamente deixa de prestar intervenção indispensável para evitar morte previsível pode responder pelo resultado porque sua omissão é:","penalmente relevante.",["sempre atípica por não haver ação física.","apenas falta ética, sem repercussão penal.","crime impossível.","forma de arrependimento eficaz."],"Quem tem dever legal de cuidado, proteção ou vigilância e pode agir para evitar o resultado pode responder por omissão imprópria, nos termos do art. 13, § 2º."],
  [206,"Teoria do delito","Dolo eventual","No dolo eventual, o agente prevê a possibilidade de produzir o resultado e:","assume o risco de produzi-lo.",["confia sinceramente que o resultado não ocorrerá, sem aceitá-lo.","desconhece por completo qualquer risco.","atua com imperícia técnica.","age sob coação moral irresistível."],"Dolo eventual envolve previsão e aceitação do risco. Na culpa consciente, o agente prevê o resultado, mas confia que ele não ocorrerá."],
  [207,"Teoria do delito","Culpa consciente","Na culpa consciente, o agente prevê o resultado, mas acredita sinceramente que poderá evitá-lo ou que ele não ocorrerá. A distinção em relação ao dolo eventual está na:","não aceitação do resultado como risco assumido.",["ausência de previsão do resultado.","existência de motivo torpe.","necessidade de resultado morte.","impossibilidade de punição penal."],"Na culpa consciente há previsão sem aceitação do risco; no dolo eventual, o agente assume o risco de produção do resultado."],
  [208,"Teoria do delito","Erro de tipo","Quem toma objeto alheio por seu, por erro sobre elemento essencial da situação fática, atua em hipótese que pode excluir:","o dolo.",["a existência da conduta.","a necessidade de lei penal anterior.","a competência jurisdicional.","a responsabilidade civil em qualquer circunstância."],"Erro sobre elemento constitutivo do tipo exclui o dolo, admitindo punição culposa se houver previsão legal."],
  [209,"Teoria do delito","Tentativa","A tentativa é punível, salvo disposição em contrário, com pena correspondente ao crime consumado, diminuída de:","um a dois terços.",["metade obrigatoriamente.","dois a três quartos.","um sexto a um terço.","nenhuma fração, pois a pena é sempre igual."],"O parágrafo único do art. 14 prevê redução de um a dois terços para a tentativa, conforme proximidade da consumação e circunstâncias do caso."],
  [210,"Teoria do delito","Concurso formal","Quando o agente, mediante uma só ação ou omissão, pratica dois ou mais crimes, idênticos ou não, pode ocorrer:","concurso formal de crimes.",["crime impossível.","arrependimento posterior.","erro de proibição inevitável.","abolitio criminis."],"O art. 70 disciplina o concurso formal, decorrente de uma só ação ou omissão que produz dois ou mais crimes."],
  [211,"Crimes contra a pessoa","Homicídio e lesão","A intenção de matar diferencia o homicídio tentado da lesão corporal. Para essa distinção, importa especialmente a análise do:","dolo do agente, revelado pelas circunstâncias do fato.",["valor econômico do bem da vítima.","local de registro da ocorrência.","tempo de duração do processo.","vínculo contratual entre autor e vítima."],"A distinção entre tentativa de homicídio e lesão corporal depende da vontade dirigida à morte, extraída das circunstâncias concretas, como meio empregado e dinâmica da agressão."],
  [212,"Crimes contra a pessoa","Omissão de socorro","A pessoa que presencia acidente com vítima ferida, pode chamar socorro sem risco pessoal e nada faz, poderá responder por omissão de socorro se não possuir dever especial de garantidor. A ausência desse dever especial afasta, em regra:","a imputação por homicídio omissivo, não necessariamente a omissão de socorro.",["qualquer responsabilidade penal possível.","o dever geral de solidariedade previsto no tipo de omissão de socorro.","a ilicitude de abandonar a vítima.","a exigência de que a assistência seja possível sem risco pessoal."],"Sem dever de garantidor, não se imputa o resultado morte por omissão imprópria; ainda assim, pode haver omissão de socorro se presentes seus requisitos."],
  [213,"Crimes contra a pessoa","Crimes contra a honra","Ao afirmar falsamente que determinado colega praticou crime, o agente, em tese, pratica calúnia. Se apenas atribui fato desonroso que prejudica a reputação, sem imputar crime, a figura tende a ser:","difamação.",["injúria.","ameaça.","desacato.","falsa identidade."],"Calúnia atribui falsamente fato criminoso; difamação imputa fato ofensivo à reputação; injúria ofende dignidade ou decoro."],
  [214,"Crimes contra a pessoa","Crimes contra a honra","Chamar alguém de expressão ofensiva à sua dignidade, sem narrar fato concreto e sem imputar crime, aproxima-se de:","injúria.",["calúnia.","difamação.","extorsão.","desobediência."],"Injúria atinge dignidade ou decoro por qualificações ofensivas, sem exigir imputação de fato criminoso ou ofensivo à reputação."],
  [215,"Crimes contra a pessoa","Liberdade individual","Privar uma pessoa de liberdade em local fechado, sem violência ou grave ameaça, mas sem base legal e contra sua vontade, pode configurar:","cárcere privado.",["roubo impróprio.","omissão de socorro.","prevaricação.","receptação."],"A privação ilegal de liberdade pode caracterizar sequestro ou cárcere privado, conforme a dinâmica do fato."],
  [216,"Crimes contra o patrimônio","Furto e apropriação indébita","Pessoa recebe notebook emprestado para reparar e, depois, decide vendê-lo como se fosse seu. A conduta, em tese, aproxima-se de:","apropriação indébita.",["furto, pois sempre houve subtração inicial.","roubo, por envolver bem móvel.","receptação, pois o bem é alheio.","dano, pois houve prejuízo ao proprietário."],"A posse ou detenção inicial legítima, seguida da inversão do ânimo de possuidor, caracteriza apropriação indébita."],
  [217,"Crimes contra o patrimônio","Roubo e extorsão","Sob grave ameaça, a vítima é obrigada a realizar transferência bancária para conta indicada pelo agente. A dinâmica aproxima-se de:","extorsão.",["furto simples.","roubo, pois o dinheiro é bem móvel.","receptação.","apropriação de coisa achada."],"Na extorsão, a vítima constrangida realiza ou tolera ato que produz a vantagem patrimonial. No roubo, a subtração é realizada pelo agente."],
  [218,"Crimes contra o patrimônio","Estelionato","O vendedor anuncia produto inexistente, recebe pagamento e nunca envia a mercadoria. Havendo indução da vítima em erro para obtenção de vantagem ilícita, a conduta pode caracterizar:","estelionato.",["furto simples.","receptação culposa.","dano.","violação de segredo profissional."],"A fraude que induz a vítima em erro e leva à vantagem ilícita em prejuízo alheio preenche, em tese, a estrutura do estelionato."],
  [219,"Crimes contra o patrimônio","Receptação","Ao comprar aparelho eletrônico por valor muito abaixo do mercado, de desconhecido e em circunstâncias suspeitas, o adquirente deve avaliar a origem do bem. Se deveria presumir origem criminosa, pode haver:","receptação culposa.",["furto qualificado.","apropriação indébita.","extorsão.","crime impossível."],"Circunstâncias como preço desproporcional, natureza da coisa e condição de quem a oferece podem caracterizar receptação culposa."],
  [220,"Crimes contra o patrimônio","Dano e furto","Pessoa risca deliberadamente o veículo de terceiro, sem intenção de ficar com o bem. Em tese, a figura patrimonial é:","dano.",["furto.","roubo.","apropriação indébita.","receptação."],"Sem intenção de assenhoramento, a destruição ou deterioração de coisa alheia tende a configurar dano, não furto."],
  [221,"Crimes contra a fé pública","Documento público","Servidor altera fisicamente certificado público verdadeiro para fazer parecer que contém nota diversa. Em tese, a conduta recai sobre:","falsificação ou alteração material de documento público.",["falsidade ideológica sem alteração física.","uso de documento falso por terceiro.","receptação.","calúnia."],"Alterar materialmente documento público verdadeiro se enquadra na falsificação material de documento público; a falsidade ideológica refere-se ao conteúdo declarado em documento formalmente verdadeiro."],
  [222,"Crimes contra a fé pública","Falsidade ideológica","Contador insere, em declaração fiscal verdadeira quanto à forma, informação falsa sobre fato juridicamente relevante para gerar obrigação indevida. Em tese, pode haver:","falsidade ideológica.",["falsificação material obrigatória.","uso de documento de identidade alheia.","dano simples.","ameaça."],"Quando a forma do documento é verdadeira, mas seu conteúdo contém declaração falsa relevante com finalidade típica, a figura pode ser falsidade ideológica."],
  [223,"Crimes contra a fé pública","Uso de documento falso","Pessoa que apresenta carteira de identidade falsificada em repartição pública, mesmo não tendo produzido a falsificação, pode responder por:","uso de documento falso.",["peculato.","furto mediante fraude.","violação de sigilo funcional.","omissão de socorro."],"O uso de documento falso é tipo autônomo e pode ser praticado por pessoa distinta do falsificador, desde que presentes os requisitos legais."],
  [224,"Crimes contra a fé pública","Falsa identidade","Indivíduo diz ser outra pessoa para obter acesso a benefício indevido, sem apresentar documento materialmente falsificado. Em tese, a conduta pode configurar:","falsa identidade.",["uso de documento falso necessariamente.","falsificação de documento público.","peculato.","desobediência."],"A falsa identidade pode ocorrer sem documento falsificado, quando o agente se atribui identidade alheia ou falsa para obter vantagem ou causar dano."],
  [225,"Crimes contra a fé pública","Moeda falsa","Quem recebe moeda falsa de boa-fé e, após descobrir a falsidade, a restitui à circulação para evitar prejuízo próprio pode praticar conduta penalmente relevante porque:","passa a agir com conhecimento da falsidade.",["a boa-fé inicial torna qualquer conduta posterior atípica.","a moeda deixa de ser falsa após a circulação.","a vítima precisa ser necessariamente banco público.","não há tutela penal sobre moeda de curso legal."],"A boa-fé no recebimento não autoriza a colocação consciente da moeda falsa em circulação depois de descoberta a falsidade."],
  [226,"Crimes contra a fé pública","Proteção documental","A fé pública documental é lesada não apenas pela fabricação de documento falso, mas também por condutas como alterar documento verdadeiro, inserir declaração falsa relevante ou usar documento:","falsificado.",["sem valor econômico.","emitido por particular com consentimento.","original de propriedade própria, em qualquer contexto.","sem assinatura, ainda que inexistente."],"Diversos tipos protegem a confiabilidade de documentos: falsificação material, falsidade ideológica, uso de documento falso e supressão, entre outros."],
  [227,"Crimes contra a fé pública","Identidade","Usar documento de identidade alheia como próprio pode ser crime mesmo que o documento seja materialmente autêntico, pois a ilicitude está em:","utilizá-lo como se identificasse seu verdadeiro titular.",["alterar obrigatoriamente seus elementos físicos.","falsificar necessariamente a assinatura do titular.","subtrair o documento sempre com violência.","não possuir nacionalidade brasileira."],"O uso de documento de identidade alheia pressupõe documento verdadeiro de outra pessoa empregado como se fosse do agente."],
  [228,"Crimes contra a fé pública","Concurso aparente","A análise entre falsificação e uso posterior do mesmo documento exige atenção à possibilidade de uma conduta absorver a outra. Esse exame busca evitar:","dupla punição pelo mesmo desvalor fático.",["a existência de processo judicial.","a aplicação de normas penais mais benéficas.","a produção de prova documental.","a atuação do Ministério Público."],"A consunção é critério de solução de concurso aparente de normas, evitando dupla valoração quando uma conduta funciona como meio ou exaurimento de outra."],
  [229,"Crimes contra a fé pública","Síntese","A falsidade documental pode atingir a forma física do documento ou a veracidade de seu conteúdo. A distinção é relevante porque:","cada hipótese possui elementos típicos próprios.",["nenhuma delas é punível pelo Código Penal.","ambas dependem sempre de dano patrimonial efetivo.","somente documentos privados são protegidos.","o uso posterior do documento torna irrelevante sua origem."],"A correta subsunção exige distinguir falsidade material de ideológica, além de uso de documento falso e outras figuras relacionadas."],
  [230,"Crimes contra a fé pública","Síntese","A função central dos crimes contra a fé pública é preservar a confiança coletiva em meios de prova e circulação jurídica. Por isso, a proteção alcança principalmente:","documentos, moeda, selos, sinais e declarações relevantes.",["somente contratos privados escritos.","apenas bens patrimoniais de alto valor.","opiniões sem repercussão jurídica.","unicamente atos do Poder Judiciário."],"Moeda, documentos, sinais e declarações juridicamente relevantes integram o núcleo da tutela da fé pública."],
  [231,"Crimes contra a Administração Pública","Peculato","Tesoureiro de órgão público transfere para sua conta quantia que administrava em razão do cargo. A conduta, em tese, configura:","peculato-apropriação.",["concussão.","corrupção ativa.","prevaricação.","desacato."],"A apropriação de dinheiro ou bem sob posse funcional caracteriza peculato, nos termos do art. 312."],
  [232,"Crimes contra a Administração Pública","Concussão","Fiscal afirma que aplicará penalidade inexistente se o particular não lhe pagar valor em dinheiro. A exigência de vantagem indevida em razão da função aproxima-se de:","concussão.",["corrupção ativa.","peculato-furto.","prevaricação.","advocacia administrativa."],"Concussão tem como núcleo exigir vantagem indevida. Não é necessário que a vantagem seja efetivamente recebida para a consumação do tipo."],
  [233,"Crimes contra a Administração Pública","Corrupção passiva","Servidor solicita dinheiro para acelerar análise de processo que está sob sua competência. Em tese, a conduta caracteriza:","corrupção passiva.",["concussão necessariamente.","peculato.","resistência.","desobediência."],"Solicitar vantagem indevida em razão da função é núcleo da corrupção passiva. Exigir vantagem caracteriza concussão."],
  [234,"Crimes contra a Administração Pública","Corrupção ativa","Empresa oferece vantagem a agente público para que ele deixe de fiscalizar irregularidade. Quem oferece a vantagem pode praticar:","corrupção ativa.",["corrupção passiva.","peculato.","prevaricação.","violação de sigilo funcional."],"Corrupção ativa é praticada por quem oferece ou promete vantagem indevida ao funcionário para influenciar ato de ofício."],
  [235,"Crimes contra a Administração Pública","Prevaricação","Servidor deixa de praticar ato obrigatório porque deseja beneficiar amigo, sem receber ou exigir vantagem. O fato aproxima-se de:","prevaricação.",["concussão.","corrupção ativa.","peculato.","resistência."],"A satisfação de interesse ou sentimento pessoal mediante omissão ou prática indevida de ato de ofício caracteriza prevaricação."],
  [236,"Crimes contra a Administração Pública","Advocacia administrativa","Funcionário utiliza sua posição no órgão para defender interesse privado de conhecido perante a própria Administração. Em tese, pratica:","advocacia administrativa.",["tráfico de influência praticado por particular, necessariamente.","peculato.","concussão.","desobediência."],"Advocacia administrativa pressupõe funcionário que patrocina interesse privado perante a Administração, valendo-se da qualidade funcional."],
  [237,"Crimes contra a Administração Pública","Resistência","Durante cumprimento de ordem legal de apreensão, o proprietário ameaça fisicamente o agente público para impedir a medida. A conduta pode caracterizar:","resistência.",["desobediência simples apenas.","desacato sem outro crime.","prevaricação.","peculato."],"Oposição mediante violência ou ameaça à execução de ato legal caracteriza resistência, sem prejuízo de outros delitos eventualmente praticados."],
  [238,"Crimes contra a Administração Pública","Desobediência","Notificado regularmente a cumprir ordem legal de autoridade pública, o particular recusa-se sem empregar violência ou ameaça. Em tese, a conduta aproxima-se de:","desobediência.",["resistência.","desacato.","concussão.","prevaricação."],"Desobediência consiste em descumprir ordem legal de funcionário público. Violência ou ameaça na oposição ao ato pode configurar resistência."],
  [239,"Crimes contra a Administração Pública","Desacato","Ofensas dirigidas ao agente público em razão da função, sem impedir fisicamente o ato nem descumprir ordem específica, podem configurar:","desacato.",["resistência obrigatoriamente.","desobediência necessariamente.","peculato.","corrupção ativa."],"Desacato tutela o respeito à função pública diante de ofensa ao funcionário no exercício ou em razão dela."],
  [240,"Crimes contra a Administração Pública","Descaminho","Importador declara valor inferior da mercadoria para reduzir imposto devido pela entrada do produto. Em tese, a conduta aproxima-se de:","descaminho.",["contrabando, pois toda mercadoria importada é proibida.","receptação.","furto.","prevaricação."],"O descaminho envolve iludir pagamento de tributo ou direito devido. Contrabando requer mercadoria proibida."],
  [241,"Crimes contra a Administração Pública","Contrabando","A importação de produto cuja entrada é proibida por norma legal aproxima-se de:","contrabando.",["descaminho, necessariamente.","peculato.","furto qualificado.","falsidade ideológica."],"Contrabando recai sobre mercadoria proibida. Se o bem é permitido e há fraude tributária, a figura tende a ser descaminho."],
  [242,"Crimes contra a Administração Pública","Funcionário público penal","Pessoa contratada por empresa conveniada para executar atividade típica da Administração Pública pode ser equiparada a funcionário público para fins penais quando:","presentes os requisitos do art. 327.",["atuar apenas em atividade comercial privada sem relação com serviço público.","prestar qualquer serviço eventual a pessoa física.","não tiver qualquer atribuição ligada à Administração.","exercer atividade exclusivamente doméstica."],"O conceito penal de funcionário público é amplo e abrange hipóteses de equiparação para quem atua em atividade típica da Administração por entidade ou empresa vinculada."],
  [243,"Crimes contra a Administração Pública","Sigilo funcional","Servidor divulga em rede social informação sigilosa obtida exclusivamente em razão do cargo, sem fundamento legal. Em tese, pode haver:","violação de sigilo funcional.",["falsa identidade.","receptação.","furto de dados necessariamente.","crime impossível."],"A divulgação injustificada de segredo conhecido em razão do cargo pode caracterizar violação de sigilo funcional."],
  [244,"Crimes contra a Administração Pública","Dados em sistema público","Funcionário altera sem autorização cadastro público para beneficiar terceiro. A depender da finalidade e dos elementos legais, a conduta pode caracterizar:","inserção de dados falsos ou modificação não autorizada de sistema de informações.",["prevaricação apenas, em qualquer hipótese.","furto simples.","desacato.","omissão de socorro."],"Os arts. 313-A e 313-B tipificam condutas relacionadas à inserção, alteração ou exclusão indevida de dados e a modificação não autorizada de sistemas públicos."],
  [245,"Crimes contra a Administração Pública","Condescendência criminosa","Chefe que, por indulgência, deixa de responsabilizar subordinado que comete infração funcional pode responder por:","condescendência criminosa.",["peculato.","resistência.","desobediência.","calúnia."],"A indulgência com subordinado infrator é elemento característico da condescendência criminosa."],
  [246,"Crimes contra a Administração Pública","Abandono de função","Servidor deixa o cargo sem amparo legal e a interrupção causa prejuízo ao serviço público. Em tese, há:","abandono de função, podendo incidir forma mais grave conforme as circunstâncias legais.",["mera infração administrativa sem possível repercussão penal.","prevaricação necessariamente.","desacato.","contrabando."],"Abandono de função é crime funcional; certas circunstâncias, como prejuízo público ou local de fronteira, podem agravar a resposta penal."],
  [247,"Crimes contra a Administração Pública","Interesse protegido","A repressão penal à corrupção e ao peculato protege a Administração Pública não apenas contra prejuízo econômico, mas também contra quebra de:","probidade e regularidade funcional.",["relações familiares privadas.","liberdade de crença religiosa.","integridade física da vítima em qualquer caso.","sigilo de voto."],"Esses crimes atentam contra moralidade, probidade e regularidade da função pública, além de eventualmente afetarem o patrimônio estatal."],
  [248,"Revisão integrada","Subsunção penal","A correta classificação penal de uma conduta exige identificar elementos objetivos, subjetivos, sujeito ativo, bem jurídico e circunstâncias de execução. Essa operação é chamada de:","subsunção do fato à norma penal.",["criação judicial livre de crimes.","aplicação retroativa de lei mais gravosa.","responsabilidade objetiva.","abolitio criminis."],"Subsunção é o enquadramento do fato concreto nos elementos do tipo penal, sempre sob reserva legal e análise de ilicitude e culpabilidade."],
  [249,"Revisão integrada","Teoria do crime","A conclusão de que uma conduta é típica não encerra a análise penal, pois ainda se verifica se há causa de exclusão de ilicitude e se o agente é culpável. Essa sequência evita:","condenar conduta amparada por excludente ou praticada sem culpabilidade.",["a aplicação de qualquer norma penal escrita.","a produção de prova no processo.","a possibilidade de defesa do acusado.","a análise da materialidade do fato."],"A estrutura analítica fato típico, ilicitude e culpabilidade impede que a mera adequação formal leve a responsabilização quando houver excludente ou ausência de culpabilidade."],
  [250,"Revisão integrada","Síntese final","Em questões de concurso sobre Direito Penal, a alternativa correta tende a depender da identificação precisa de verbos como subtrair, apropriar-se, exigir, solicitar, oferecer, ameaçar ou falsificar, pois eles:","delimitam o núcleo de cada tipo penal.",["são expressões sem relevância para a classificação jurídica.","substituem a análise do contexto e dos demais elementos.","impedem a existência de causas de exclusão.","tornam todos os crimes automaticamente dolosos."],"Os verbos nucleares indicam a conduta proibida por cada tipo. A resposta correta exige combiná-los com sujeito, objeto, meio, finalidade e circunstâncias legais." ]
];
const direitoPenalLoteCincoComResposta = direitoPenalLoteCinco.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 201) % 5];
  return {id:`direito-penal-${String(number).padStart(3,"0")}`,subjectId:"direito-penal",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoPenalLoteCincoComResposta);
questionBank.review.direitoPenalLoteCincoReviewed = direitoPenalLoteCincoComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Ajuste editorial final dos dois blocos jurídicos: preserva o conteúdo, mas
// elimina enunciados que coincidiam literalmente com questões anteriores.
const reescritasJuridicasSemDuplicidade = new Map([
  ["direito-constitucional-034", "Em quais hipóteses constitucionais o eleitor pode exercer, facultativamente, o direito de voto?"],
  ["direito-constitucional-081", "Quais entes integram a organização político-administrativa brasileira com autonomia constitucional?"],
  ["direito-constitucional-084", "Assinale uma atribuição administrativa compartilhada pela União, pelos Estados, pelo Distrito Federal e pelos Municípios."],
  ["direito-penal-198", "Entre os delitos funcionais e os praticados contra a Administração, qual associação está tecnicamente correta?"]
]);
questionBank.questions = questionBank.questions.map(question=>{
  const stem = reescritasJuridicasSemDuplicidade.get(question.id);
  return stem ? {...question, stem} : question;
});
questionBank.review.auditoriaJuridicaFinal = [...reescritasJuridicasSemDuplicidade.keys()];
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Penal — lote 4 (151–200): fechamento de fé pública e crimes contra a Administração Pública.
const direitoPenalLoteQuatro = [
  [151,"Crimes contra a fé pública","Petrechos de falsificação","Fabricar, adquirir, fornecer, possuir ou guardar objeto especialmente destinado à falsificação de papéis públicos configura:","petrechos de falsificação.",["uso de documento falso, necessariamente.","falsidade ideológica em qualquer hipótese.","receptação culposa.","dano simples."],"O art. 294 tipifica condutas relacionadas a objetos especialmente destinados à falsificação de papéis públicos, antecipando a tutela da fé pública."],
  [152,"Crimes contra a fé pública","Falsificação de sinal público","Falsificar, fabricar ou alterar selo público destinado a autenticar atos oficiais da União, Estado ou Município pode configurar:","falsificação de sinal público.",["furto qualificado.","estelionato necessariamente.","violação de segredo profissional.","apropriação indébita."],"O art. 296 protege sinais públicos de autenticação, como selos ou sinais destinados a identificar atos oficiais."],
  [153,"Crimes contra a fé pública","Documento público","Para fins penais, equiparam-se a documento público determinados documentos emitidos por entidades paraestatais ou títulos ao portador transmissíveis por endosso. Essa equiparação amplia:","a tutela da fé pública documental.",["a liberdade de locomoção.","a proteção penal exclusiva do patrimônio privado.","a competência municipal em matéria penal.","a possibilidade de emitir moeda privada."],"O art. 297, § 2º, equipara certos documentos a públicos para reforçar a tutela penal de sua autenticidade."],
  [154,"Crimes contra a fé pública","Falsidade ideológica","A falsidade ideológica pode recair tanto em documento público quanto particular, desde que haja inserção ou omissão de declaração com finalidade de prejudicar direito, criar obrigação ou alterar a verdade sobre fato:","juridicamente relevante.",["meramente imaginário e sem qualquer efeito.","exclusivamente moral, sem registro.","futuro e impossível de ocorrer.","estranho a qualquer documento."],"O art. 299 exige relevância jurídica do fato cuja verdade se pretende alterar, além da finalidade típica descrita na lei."],
  [155,"Crimes contra a fé pública","Síntese","O uso de documento falso tutela a fé pública porque a apresentação do documento busca fazer terceiros acreditarem em sua:","autenticidade ou veracidade.",["origem exclusivamente privada.","utilidade econômica obrigatória.","validade apenas moral.","irrelevância jurídica."],"A conduta de usar documento falso explora a confiança social na autenticidade e veracidade documental, razão da proteção penal da fé pública."],
  [156,"Crimes contra a Administração Pública","Peculato","Apropriar-se o funcionário público de dinheiro, valor ou qualquer outro bem móvel, público ou particular, de que tem a posse em razão do cargo, ou desviá-lo, em proveito próprio ou alheio, configura:","peculato.",["concussão.","corrupção passiva.","prevaricação.","desobediência."],"O art. 312 define peculato por apropriação ou desvio de bem cuja posse decorre do cargo público."],
  [157,"Crimes contra a Administração Pública","Peculato-furto","Subtrair ou concorrer para que seja subtraído, em proveito próprio ou alheio, bem público ou particular, valendo-se o funcionário de facilidade proporcionada pela qualidade de funcionário, caracteriza:","peculato-furto.",["furto simples sem relação com função pública.","corrupção passiva.","concussão.","advocacia administrativa."],"O art. 312, § 1º, prevê o chamado peculato-furto, no qual o agente se vale das facilidades do cargo para subtrair bem."],
  [158,"Crimes contra a Administração Pública","Peculato culposo","No peculato culposo, o funcionário concorre culposamente para o crime de outrem. Se repara o dano antes da sentença irrecorrível, a punibilidade:","é extinta.",["aumenta automaticamente.","permanece idêntica, sem efeito jurídico.","transforma-se em crime de menor potencial ofensivo.","é substituída por pena de morte."],"O art. 312, § 3º, prevê extinção da punibilidade se a reparação do dano ocorre antes da sentença irrecorrível; se posterior, reduz a pena pela metade."],
  [159,"Crimes contra a Administração Pública","Inserção de dados falsos","Inserir ou facilitar a inserção de dados falsos, alterar ou excluir indevidamente dados corretos nos sistemas informatizados ou bancos de dados da Administração Pública, com fim de obter vantagem indevida ou causar dano, pode configurar:","inserção de dados falsos em sistema de informações.",["falsidade ideológica apenas, sem tipo específico.","dano culposo.","receptação.","calúnia."],"O art. 313-A prevê tipo próprio para inserção, alteração ou exclusão indevida de dados em sistemas da Administração, com finalidade de vantagem ou dano."],
  [160,"Crimes contra a Administração Pública","Modificação não autorizada de sistema","Modificar ou alterar, o funcionário, sistema de informações ou programa de informática sem autorização ou solicitação de autoridade competente configura:","modificação ou alteração não autorizada de sistema de informações.",["peculato culposo.","concussão.","abandono de função.","desacato."],"O art. 313-B tipifica a modificação ou alteração não autorizada de sistema de informações pelo funcionário público."],
  [161,"Crimes contra a Administração Pública","Extravio de livro oficial","Extraviar livro oficial ou qualquer documento de que tem a guarda em razão do cargo; sonegá-lo ou inutilizá-lo, total ou parcialmente, caracteriza:","extravio, sonegação ou inutilização de livro ou documento.",["prevaricação.","uso de documento falso.","furto simples.","violação de domicílio."],"O art. 314 protege documentos e livros oficiais sob guarda funcional contra extravio, sonegação ou inutilização."],
  [162,"Crimes contra a Administração Pública","Concussão","Exigir, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, configura:","concussão.",["corrupção passiva.","peculato.","prevaricação.","advocacia administrativa."],"O art. 316 define concussão pelo verbo exigir vantagem indevida em razão da função. A exigência diferencia o crime da solicitação própria da corrupção passiva."],
  [163,"Crimes contra a Administração Pública","Excesso de exação","Exigir tributo ou contribuição social que sabe ou deveria saber indevido, ou, quando devido, empregar na cobrança meio vexatório ou gravoso não autorizado por lei, caracteriza:","excesso de exação.",["peculato-furto.","concussão sem modalidade específica.","corrupção ativa.","desobediência."],"O art. 316, § 1º, prevê o excesso de exação, que envolve cobrança indevida ou forma vexatória/gravosa não autorizada na cobrança de tributo ou contribuição."],
  [164,"Crimes contra a Administração Pública","Corrupção passiva","Solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, ou aceitar promessa de tal vantagem, caracteriza:","corrupção passiva.",["concussão, em qualquer situação.","corrupção ativa.","peculato.","resistência."],"O art. 317 define corrupção passiva por solicitar, receber ou aceitar promessa de vantagem indevida em razão da função."],
  [165,"Crimes contra a Administração Pública","Corrupção ativa","Oferecer ou prometer vantagem indevida a funcionário público, para determiná-lo a praticar, omitir ou retardar ato de ofício, caracteriza:","corrupção ativa.",["corrupção passiva.","concussão.","prevaricação.","peculato culposo."],"O art. 333 tipifica corrupção ativa, praticada por quem oferece ou promete vantagem ao funcionário para influenciar ato de ofício."],
  [166,"Crimes contra a Administração Pública","Diferença entre corrupção e concussão","A principal diferença entre concussão e corrupção passiva é que, na concussão, o funcionário:","exige a vantagem indevida.",["recebe vantagem por meio de fraude documental.","subtrai bem que estava sob sua posse funcional.","retarda ato de ofício por interesse pessoal.","oferece vantagem a outro funcionário."],"Na concussão há exigência de vantagem; na corrupção passiva há solicitar, receber ou aceitar promessa. Os demais verbos descrevem outros crimes."],
  [167,"Crimes contra a Administração Pública","Prevaricação","Retardar ou deixar de praticar, indevidamente, ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento:","pessoal.",["da vítima, exclusivamente.","econômico de terceiro, sem vínculo pessoal.","coletivo, previsto em lei.","institucional, sempre legítimo."],"O art. 319 define prevaricação pela prática ou omissão indevida de ato de ofício para satisfazer interesse ou sentimento pessoal."],
  [168,"Crimes contra a Administração Pública","Condescendência criminosa","Deixar o funcionário, por indulgência, de responsabilizar subordinado que cometeu infração no exercício do cargo ou, quando lhe falte competência, não levar o fato ao conhecimento da autoridade competente, caracteriza:","condescendência criminosa.",["prevaricação necessariamente.","peculato culposo.","desacato.","corrupção ativa."],"O art. 320 tipifica a condescendência criminosa, cujo elemento distintivo é a indulgência com subordinado infrator."],
  [169,"Crimes contra a Administração Pública","Advocacia administrativa","Patrocinar, direta ou indiretamente, interesse privado perante a Administração Pública, valendo-se da qualidade de funcionário, caracteriza:","advocacia administrativa.",["patrocínio infiel.","corrupção ativa.","usurpação de função pública.","falsa identidade."],"O art. 321 prevê advocacia administrativa quando o funcionário patrocina interesse privado perante a Administração usando a qualidade funcional."],
  [170,"Crimes contra a Administração Pública","Violência arbitrária","Praticar violência, no exercício de função ou a pretexto de exercê-la, pode configurar:","violência arbitrária, sem prejuízo da pena correspondente à violência.",["legítima defesa automática.","exercício regular de direito em qualquer circunstância.","crime impossível.","furto qualificado."],"O art. 322 prevê a violência arbitrária praticada no exercício ou a pretexto de exercer função, sem prejuízo da pena relativa à violência."],
  [171,"Crimes contra a Administração Pública","Abandono de função","Abandonar cargo público, fora dos casos permitidos em lei, configura:","abandono de função.",["prevaricação necessariamente.","desobediência de particular.","concussão.","corrupção ativa."],"O art. 323 tipifica abandonar cargo público fora das hipóteses legais, com formas mais graves em certas circunstâncias."],
  [172,"Crimes contra a Administração Pública","Exercício funcional ilegal","Entrar no exercício de função pública antes de satisfeitas as exigências legais, ou continuar a exercê-la, sem autorização, depois de saber oficialmente que foi exonerado, removido, substituído ou suspenso, caracteriza:","exercício funcional ilegalmente antecipado ou prolongado.",["usurpação de função pública por particular.","abandono de função.","prevaricação.","desacato."],"O art. 324 trata do funcionário que inicia ou prolonga indevidamente o exercício funcional em situações legalmente descritas."],
  [173,"Crimes contra a Administração Pública","Violação de sigilo funcional","Revelar fato de que tem ciência em razão do cargo e que deva permanecer em segredo, ou facilitar-lhe a revelação, caracteriza:","violação de sigilo funcional.",["violação de segredo profissional, necessariamente.","falsidade ideológica.","receptação.","omissão de socorro."],"O art. 325 protege o sigilo funcional. Distingue-se do segredo profissional, que decorre de função, ministério, ofício ou profissão em sentido diverso."],
  [174,"Crimes contra a Administração Pública","Violação de sigilo de proposta","Devassar o sigilo de proposta de concorrência pública, ou proporcionar a terceiro o ensejo de devassá-lo, caracteriza:","violação do sigilo de proposta de concorrência.",["prevaricação.","peculato.","corrupção ativa.","desobediência."],"O art. 326 tutela o sigilo de proposta de concorrência pública, protegendo lisura e igualdade do procedimento."],
  [175,"Crimes praticados por particular contra a Administração","Usurpação de função pública","Usurpar o exercício de função pública caracteriza:","usurpação de função pública.",["exercício funcional ilegalmente antecipado, sempre.","prevaricação.","desobediência.","resistência."],"O art. 328 alcança quem, sem ser funcionário competente, usurpa função pública. O art. 324, por sua vez, trata de funcionário que inicia ou prolonga exercício ilegalmente."],
  [176,"Crimes praticados por particular contra a Administração","Resistência","Opor-se à execução de ato legal, mediante violência ou ameaça a funcionário competente para executá-lo ou a quem lhe esteja prestando auxílio, caracteriza:","resistência.",["desobediência simples.","desacato.","concussão.","prevaricação."],"O art. 329 tipifica resistência e exige violência ou ameaça contra funcionário competente ou seu auxiliar, diante de ato legal."],
  [177,"Crimes praticados por particular contra a Administração","Desobediência","Desobedecer a ordem legal de funcionário público caracteriza:","desobediência.",["resistência, ainda que sem violência ou ameaça.","desacato, necessariamente.","prevaricação.","corrupção ativa."],"O art. 330 tipifica desobediência a ordem legal de funcionário público. Resistência exige violência ou ameaça à execução do ato legal."],
  [178,"Crimes praticados por particular contra a Administração","Desacato","Desacatar funcionário público no exercício da função ou em razão dela configura:","desacato.",["calúnia exclusivamente.","resistência, sempre.","prevaricação.","falsa identidade."],"O art. 331 tipifica desacato ao funcionário público no exercício da função ou em razão dela, distinguindo-se de resistência e desobediência."],
  [179,"Crimes praticados por particular contra a Administração","Tráfico de influência","Solicitar, exigir, cobrar ou obter, para si ou para outrem, vantagem ou promessa de vantagem, a pretexto de influir em ato praticado por funcionário público no exercício da função, caracteriza:","tráfico de influência.",["corrupção passiva.","concussão.","advocacia administrativa.","peculato."],"O art. 332 tipifica tráfico de influência, praticado por quem negocia falsa ou real influência sobre ato de funcionário público."],
  [180,"Crimes praticados por particular contra a Administração","Contrabando","Importar ou exportar mercadoria proibida configura:","contrabando.",["descaminho.","receptação.","furto.","estelionato."],"O art. 334-A trata do contrabando, que recai sobre mercadoria proibida. Descaminho envolve iludir pagamento de direito ou imposto devido."],
  [181,"Crimes praticados por particular contra a Administração","Descaminho","Iludir, no todo ou em parte, o pagamento de direito ou imposto devido pela entrada, saída ou consumo de mercadoria configura:","descaminho.",["contrabando.","concussão.","receptação qualificada.","violação de domicílio."],"O art. 334 define descaminho como iludir pagamento de direito ou imposto devido. A mercadoria não precisa ser proibida."],
  [182,"Crimes praticados por particular contra a Administração","Contrabando e descaminho","A distinção correta entre contrabando e descaminho é:","contrabando envolve mercadoria proibida; descaminho envolve ilusão de tributo ou direito devido.",["contrabando é sempre crime culposo e descaminho, doloso.","descaminho exige violência e contrabando, fraude documental.","contrabando atinge apenas bens públicos e descaminho, apenas particulares.","os dois crimes são sinônimos jurídicos."],"Os tipos possuem objetos distintos: proibição da mercadoria no contrabando e fraude fiscal aduaneira no descaminho."],
  [183,"Crimes praticados por particular contra a Administração","Impedimento ou perturbação de concorrência","Impedir, perturbar ou fraudar concorrência pública ou venda em hasta pública pode configurar crime contra:","a Administração Pública.",["a honra individual exclusivamente.","a liberdade de locomoção.","a família.","a incolumidade pública, sem relação administrativa."],"O Código Penal prevê figura específica para proteção da regularidade de concorrência pública e hasta pública, bens ligados à Administração."],
  [184,"Crimes praticados por particular contra a Administração","Inutilização de edital","Rasgar ou, de qualquer forma, inutilizar ou conspurcar edital afixado por ordem de funcionário público; violar ou inutilizar selo ou sinal empregado por determinação legal ou por ordem de funcionário público, pode configurar:","inutilização de edital ou de sinal.",["falsidade ideológica.","prevaricação.","furto qualificado.","calúnia."],"O art. 336 prevê inutilização de edital ou de sinal, tutelando a eficácia de comunicações e sinais oficiais."],
  [185,"Crimes praticados por particular contra a Administração","Subtração de documento","Subtrair ou inutilizar, total ou parcialmente, livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público, caracteriza:","subtração ou inutilização de livro ou documento.",["supressão de documento particular, apenas.","peculato-furto, em qualquer hipótese.","violação de correspondência.","desobediência."],"O art. 337 protege livro, processo ou documento sob custódia relacionada ao serviço público contra subtração ou inutilização."],
  [186,"Crimes contra a Administração Pública","Peculato e corrupção","Um servidor que se apropria de valor que tinha sob guarda funcional pratica, em tese, peculato; se apenas solicita vantagem indevida em razão do cargo, pratica, em tese:","corrupção passiva.",["concussão, pois sempre há exigência.","prevaricação, pois retarda ato de ofício.","desacato, pois ofende a Administração.","descaminho, por envolver vantagem econômica."],"Apropriação de bem sob posse funcional caracteriza peculato. Solicitar vantagem indevida em razão do cargo caracteriza corrupção passiva; exigir caracteriza concussão."],
  [187,"Crimes contra a Administração Pública","Prevaricação","O servidor que deixa de praticar ato de ofício apenas por satisfação de interesse pessoal, sem exigir ou solicitar vantagem indevida, tende a enquadrar-se em:","prevaricação.",["concussão.","corrupção passiva.","peculato.","resistência."],"Prevaricação exige interesse ou sentimento pessoal na prática, retardamento ou omissão indevida de ato de ofício."],
  [188,"Crimes contra a Administração Pública","Resistência e desobediência","Durante o cumprimento de ordem legal, a pessoa empurra e ameaça o agente público para impedir o ato. Em tese, a conduta aproxima-se de:","resistência.",["desobediência simples, pois não há violência relevante.","desacato exclusivamente.","prevaricação.","concussão."],"Resistência pressupõe oposição à execução de ato legal mediante violência ou ameaça. Desobediência consiste em descumprir ordem legal sem esse elemento."],
  [189,"Crimes contra a Administração Pública","Sigilo funcional","O funcionário que revela dado sigiloso conhecido em razão do cargo, fora de hipótese legal que justifique a divulgação, pode responder por:","violação de sigilo funcional.",["falsa identidade.","furto mediante fraude.","omissão de socorro.","crime impossível."],"A revelação injustificada de segredo funcional é prevista no art. 325, que tutela a confiança e regularidade da Administração."],
  [190,"Crimes contra a Administração Pública","Funcionário público para fins penais","Para efeitos penais, considera-se funcionário público quem, embora transitoriamente ou sem remuneração, exerce cargo, emprego ou:","função pública.",["atividade privada sem delegação ou vínculo com o Estado.","trabalho doméstico em residência particular.","atividade exclusivamente empresarial própria.","qualquer atividade voluntária sem interesse público."],"O art. 327 adota conceito amplo de funcionário público para fins penais, incluindo exercício transitório ou não remunerado de cargo, emprego ou função pública."],
  [191,"Crimes contra a Administração Pública","Equiparação funcional","Equipara-se a funcionário público, para fins penais, quem trabalha para empresa prestadora de serviço contratada ou conveniada para a execução de atividade típica da Administração Pública, nos termos:","da lei penal.",["de qualquer relação de consumo privada.","de autorização verbal do superior.","da vontade exclusiva da empresa.","de decisão judicial individual obrigatória."],"O art. 327, § 1º, equipara determinadas pessoas a funcionário público quando atuam em entidade paraestatal ou empresa contratada/conveniada para atividade típica da Administração."],
  [192,"Crimes contra a Administração Pública","Causa de aumento","A pena será aumentada da terça parte quando os autores dos crimes contra a Administração previstos no capítulo pertinente forem ocupantes de cargo em comissão ou de função de:","direção ou assessoramento de órgão da administração direta, sociedade de economia mista, empresa pública ou fundação instituída pelo poder público.",["qualquer emprego privado sem vínculo estatal.","mandato eletivo municipal, em qualquer crime comum.","cargo técnico sem atribuição de direção.","atividade autônoma em empresa privada."],"O art. 327, § 2º, prevê causa de aumento para certos ocupantes de cargo em comissão ou função de direção/assessoramento nas entidades indicadas."],
  [193,"Crimes contra a Administração Pública","Bem jurídico","Os crimes contra a Administração Pública protegem não apenas patrimônio estatal, mas também probidade, regularidade, eficiência e prestígio da função:","administrativa.",["legislativa privada.","religiosa estatal.","familiar exclusivamente.","desportiva."],"A tutela penal administrativa alcança probidade e regularidade do funcionamento estatal, além de patrimônio público em figuras específicas."],
  [194,"Crimes contra a Administração Pública","Ato de ofício","Nos crimes de corrupção e prevaricação, a referência a ato de ofício vincula a conduta à função pública exercida. Não é necessário que o ato seja:","necessariamente praticado de imediato, desde que a vantagem ou interesse se relacione à função nos termos do tipo.",["de competência de qualquer órgão público.","sempre um ato judicial.","apenas um ato legislativo.","estranho às atribuições do agente."],"A relação com a função e com ato de ofício é elemento central nos tipos; a análise concreta verifica atribuições e nexo funcional."],
  [195,"Crimes contra a Administração Pública","Particular e funcionário","Nos crimes contra a Administração, o particular pode ser sujeito ativo de tipos como corrupção ativa, resistência, desacato, desobediência e:","tráfico de influência.",["peculato-apropriação, que exige posse funcional.","prevaricação, que exige ato de ofício do funcionário.","condescendência criminosa, que pressupõe superioridade funcional.","abandono de função, que exige cargo público."],"Diversos crimes são praticados por particulares contra a Administração. Peculato, prevaricação, condescendência e abandono, em regra, exigem qualidade funcional."],
  [196,"Crimes contra a Administração Pública","Concurso de crimes","Se um funcionário público exige vantagem indevida e, para obtê-la, pratica violência autônoma não absorvida pelo tipo, a resposta penal pode envolver análise de:","concurso de crimes, conforme as circunstâncias.",["atipicidade automática da violência.","exclusão de ilicitude por interesse público.","crime impossível.","perdão judicial obrigatório."],"A presença de conduta autônoma com desvalor próprio pode gerar concurso de crimes; a definição depende da estrutura concreta dos fatos e dos tipos aplicáveis."],
  [197,"Crimes contra a Administração Pública","Dolo","Os crimes funcionais como peculato, concussão, corrupção passiva e prevaricação exigem análise do elemento subjetivo. Em regra, não se configuram por:","mera responsabilidade objetiva pelo resultado administrativo.",["conduta dolosa do agente que pratica os verbos típicos.","relação funcional com o ato ou bem envolvido, quando exigida.","finalidade específica descrita no tipo, quando houver.","ciência da atuação funcional nas hipóteses legais."],"O Direito Penal não admite responsabilidade objetiva. Cada tipo demanda seus elementos objetivos e subjetivos, inclusive dolo e finalidades quando previstas."],
  [198,"Crimes contra a Administração Pública","Síntese","Assinale a associação correta:","Concussão: exigir vantagem indevida em razão da função.",["Peculato: oferecer vantagem ao funcionário para obter ato de ofício.","Corrupção ativa: apropriar-se de bem sob posse funcional.","Prevaricação: empregar violência para impedir ato legal.","Resistência: revelar segredo funcional."],"Concussão é exigir vantagem indevida. Peculato, corrupção ativa, prevaricação, resistência e violação de sigilo possuem núcleos distintos."],
  [199,"Crimes contra a Administração Pública","Síntese","Sobre a diferenciação entre contrabando, descaminho e delitos funcionais, assinale a associação correta:","Descaminho: iludir o pagamento de direito ou imposto devido pela entrada, saída ou consumo de mercadoria.",["Contrabando: importar mercadoria permitida sem recolher tributo.","Desacato: opor-se com violência à execução de ato legal.","Desobediência: ofender funcionário no exercício da função.","Resistência: simplesmente deixar de cumprir ordem legal sem ameaça."],"Descaminho envolve fraude ao pagamento de tributos ou direitos devidos; contrabando, mercadoria proibida. Resistência exige violência ou ameaça, desobediência é descumprimento de ordem e desacato é ofensa funcional."],
  [200,"Crimes contra a Administração Pública","Síntese","A distinção precisa entre peculato, corrupção, concussão e prevaricação exige observar principalmente:","o verbo nuclear, a relação funcional e a finalidade exigida em cada tipo.",["apenas a gravidade subjetiva atribuída pela vítima.","somente o valor econômico envolvido.","a existência de notícia em meio de comunicação.","a condição financeira do agente público."],"Os crimes contra a Administração possuem verbos e elementos próprios. A correta subsunção depende da conduta, vínculo funcional, vantagem ou finalidade exigida pela lei." ]
];
const direitoPenalLoteQuatroComResposta = direitoPenalLoteQuatro.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 151) % 5];
  return {id:`direito-penal-${String(number).padStart(3,"0")}`,subjectId:"direito-penal",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoPenalLoteQuatroComResposta);
questionBank.review.direitoPenalLoteQuatroReviewed = direitoPenalLoteQuatroComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Penal — lote 3 (101–150): patrimônio e fé pública.
const direitoPenalLoteTres = [
  [101,"Crimes contra o patrimônio","Furto noturno","A prática de furto durante o repouso noturno pode produzir consequência específica prevista no Código Penal. O fundamento da maior reprovação está ligado, entre outros fatores, à:","maior vulnerabilidade da vigilância patrimonial naquele período.",["necessidade de violência ou grave ameaça à vítima.","existência obrigatória de concurso de pessoas.","qualificação automática como roubo.","inexistência de bem jurídico patrimonial."],"O Código Penal prevê circunstância própria para o furto praticado durante o repouso noturno. A incidência concreta depende dos requisitos legais e não transforma o fato em roubo."],
  [102,"Crimes contra o patrimônio","Furto privilegiado","No furto, sendo o criminoso primário e de pequeno valor a coisa furtada, o juiz pode substituir a pena de reclusão por detenção, diminuí-la ou aplicar somente:","multa.",["medida de segurança obrigatória.","pena de morte.","advertência administrativa sem processo.","perdimento de todos os bens do agente."],"O art. 155, § 2º, prevê o privilégio do furto para agente primário e coisa de pequeno valor, permitindo as respostas penais indicadas."],
  [103,"Crimes contra o patrimônio","Furto de energia","Equipara-se à coisa móvel, para fins penais, a energia elétrica ou qualquer outra que tenha:","valor econômico.",["origem exclusivamente pública.","registro obrigatório em cartório.","natureza corporal e física permanente.","utilização apenas industrial."],"O art. 155, § 3º, equipara à coisa móvel a energia elétrica ou outra que tenha valor econômico."],
  [104,"Crimes contra o patrimônio","Roubo impróprio","O roubo impróprio ocorre quando, logo depois de subtraída a coisa, o agente emprega violência ou grave ameaça para assegurar a impunidade do crime ou a detenção da coisa:","para si ou para terceiro.",["somente para a vítima recuperar o bem.","apenas se a violência ocorrer antes da subtração.","exclusivamente quando houver concurso de agentes.","desde que a coisa seja de valor elevado."],"O art. 157, § 1º, descreve o roubo impróprio: violência ou grave ameaça após a subtração para assegurar impunidade ou detenção da coisa."],
  [105,"Crimes contra o patrimônio","Roubo","No roubo, a violência ou grave ameaça pode ser dirigida à pessoa para viabilizar a subtração. O objeto jurídico tutelado é complexo porque alcança patrimônio e:","liberdade ou integridade pessoal.",["somente a fé pública.","unicamente a administração tributária.","apenas a organização do trabalho.","somente a incolumidade documental."],"O roubo é crime complexo: protege o patrimônio e também a liberdade ou integridade da vítima diante da violência, ameaça ou redução de resistência."],
  [106,"Crimes contra o patrimônio","Extorsão mediante sequestro","Sequestrar pessoa com o fim de obter, para si ou para outrem, qualquer vantagem como condição ou preço do resgate configura:","extorsão mediante sequestro.",["cárcere privado simples, sem finalidade patrimonial.","constrangimento ilegal apenas.","roubo impróprio.","apropriação indébita."],"O art. 159 tipifica extorsão mediante sequestro quando há privação de liberdade com finalidade de obtenção de vantagem vinculada a resgate."],
  [107,"Crimes contra o patrimônio","Extorsão","Na extorsão, a vantagem econômica pretendida pelo agente deve ser:","indevida.",["necessariamente proveniente de bem público.","sempre representada por coisa móvel física.","limitada ao valor de um salário mínimo.","obtida sem qualquer participação da vítima."],"O art. 158 exige intuito de obter indevida vantagem econômica. A vítima é constrangida a fazer, tolerar ou deixar de fazer algo."],
  [108,"Crimes contra o patrimônio","Usurpação","Suprimir ou deslocar tapume, marco ou qualquer outro sinal indicativo de linha divisória, para apropriar-se, no todo ou em parte, de coisa imóvel alheia, caracteriza:","usurpação.",["furto simples.","estelionato.","dano culposo.","receptação."],"O art. 161, § 1º, I, trata do esbulho possessório por supressão ou deslocamento de marco divisório com finalidade de apropriação de imóvel alheio."],
  [109,"Crimes contra o patrimônio","Dano qualificado","O dano pode ser qualificado quando cometido, por exemplo, com violência à pessoa ou grave ameaça. Nessa hipótese, a violência ou ameaça:","agrava a resposta penal além da lesão patrimonial.",["transforma obrigatoriamente o fato em furto.","elimina a necessidade de dolo de danificar.","impede a existência de qualquer concurso de crimes.","torna a conduta atípica."],"O art. 163, parágrafo único, prevê hipóteses de dano qualificado, incluindo violência ou grave ameaça à pessoa, sem prejuízo da pena correspondente à violência."],
  [110,"Crimes contra o patrimônio","Introdução ou abandono de animais","Introduzir ou deixar animais em propriedade alheia, sem consentimento de quem de direito, desde que resulte prejuízo, configura:","dano previsto em tipo específico.",["furto de semovente automaticamente.","estelionato por fraude documental.","crime contra a honra.","violação de segredo profissional."],"O art. 164 tipifica introduzir ou abandonar animais em propriedade alheia sem consentimento, desde que haja prejuízo."],
  [111,"Crimes contra o patrimônio","Apropriação indébita","A apropriação indébita diferencia-se do furto porque, na primeira, o agente recebe previamente a coisa em posse ou detenção e depois:","passa a agir como se fosse proprietário.",["a subtrai com violência ou grave ameaça.","induz a vítima em erro para que entregue a coisa.","a encontra por acaso e a devolve imediatamente.","destrói a coisa sem intenção de assenhoramento."],"A inversão do ânimo de possuidor sobre coisa previamente recebida distingue a apropriação indébita da subtração própria do furto."],
  [112,"Crimes contra o patrimônio","Apropriação previdenciária","Deixar de repassar à previdência social as contribuições recolhidas dos contribuintes, no prazo e forma legal ou convencional, pode configurar:","apropriação indébita previdenciária.",["furto de energia.","receptação culposa.","dano simples.","violação de domicílio."],"O art. 168-A prevê hipóteses de apropriação indébita previdenciária relacionadas ao não repasse de contribuições nos termos legais."],
  [113,"Crimes contra o patrimônio","Estelionato","No estelionato, a vítima entrega ou dispõe do bem porque foi induzida ou mantida em erro. No furto mediante fraude, por outro lado:","a fraude serve para facilitar a subtração realizada pelo agente.",["a vítima sempre age livremente e sem engano.","não existe finalidade patrimonial.","a posse prévia do bem é requisito indispensável.","há violência física obrigatória."],"No estelionato, a fraude provoca disposição patrimonial da vítima. No furto mediante fraude, ela apenas reduz vigilância ou cria oportunidade para a subtração."],
  [114,"Crimes contra o patrimônio","Fraude eletrônica","A obtenção de vantagem ilícita em prejuízo alheio mediante fraude cometida com utilização de informações fornecidas pela vítima ou por terceiro por meio de redes sociais, contatos telefônicos ou e-mail pode enquadrar-se em:","estelionato na forma eletrônica, observados os requisitos legais.",["furto simples, independentemente do modo de execução.","dano culposo.","violação de domicílio físico.","crime impossível por ocorrer em ambiente digital."],"O Código Penal prevê modalidade ligada à fraude eletrônica. O meio digital não elimina o caráter patrimonial e fraudulento da conduta."],
  [115,"Crimes contra o patrimônio","Fraude no pagamento","Fraudar, em prejuízo alheio, o pagamento por meio de cheque, mediante emissão sem suficiente provisão de fundos ou não pagamento, quando presentes os requisitos legais, pode caracterizar:","fraude no pagamento por meio de cheque.",["furto privilegiado.","receptação dolosa.","omissão de socorro.","prevaricação."],"O art. 171, § 2º, VI, traz hipótese específica de fraude no pagamento por meio de cheque, sujeita à análise dos elementos concretos."],
  [116,"Crimes contra o patrimônio","Duplicata simulada","Emitir fatura, duplicata ou nota de venda que não corresponda à mercadoria vendida, em quantidade ou qualidade, ou ao serviço prestado, pode configurar:","fraude ligada à emissão de documento comercial.",["crime de calúnia.","violação de domicílio.","lesão corporal culposa.","abandono material."],"O Código Penal prevê modalidade de estelionato relacionada à emissão de duplicata ou documento comercial que não corresponda à operação efetivamente realizada."],
  [117,"Crimes contra o patrimônio","Receptação qualificada","No exercício de atividade comercial ou industrial, adquirir, receber, transportar, conduzir, ocultar, ter em depósito, desmontar, montar, remontar, vender, expor à venda ou utilizar coisa que deve saber ser produto de crime pode caracterizar:","receptação qualificada.",["furto de uso.","apropriação de coisa achada.","dano culposo.","exercício arbitrário das próprias razões."],"O art. 180, § 1º, prevê forma qualificada de receptação ligada a atividade comercial ou industrial e ao dever de saber a origem criminosa."],
  [118,"Crimes contra o patrimônio","Receptação","Para a configuração da receptação dolosa, não é necessário que o agente tenha participado do crime antecedente, mas é indispensável que a coisa seja:","produto de crime e que o agente conheça essa origem.",["de propriedade exclusiva da União.","imóvel registrado.","de valor superior a determinado limite legal fixo.","objeto de sentença civil definitiva."],"A receptação pressupõe coisa produto de crime e conhecimento de sua origem ilícita; o receptador pode ser pessoa diversa do autor do crime antecedente."],
  [119,"Crimes contra o patrimônio","Disposição de coisa alheia como própria","Vender, permutar, dar em pagamento, em locação ou em garantia coisa alheia como própria pode constituir:","disposição de coisa alheia como própria.",["furto simples necessariamente.","roubo impróprio.","dano atípico.","crime contra a administração pública."],"O art. 171, § 2º, I, trata da disposição de coisa alheia como própria, como modalidade de estelionato."],
  [120,"Crimes contra o patrimônio","Defraudação de penhor","Defraudar, mediante alienação não consentida pelo credor ou por outro modo, a garantia pignoratícia, quando o agente tem a posse do bem empenhado, pode configurar:","defraudação de penhor.",["receptação culposa.","furto de energia.","lesão corporal grave.","violação de correspondência."],"O Código Penal prevê a defraudação de penhor como modalidade de fraude patrimonial envolvendo garantia pignoratícia."],
  [121,"Crimes contra o patrimônio","Violação de direito autoral","Violar direitos de autor e os que lhe são conexos configura crime contra:","a propriedade imaterial.",["a vida humana.","a administração da justiça.","a liberdade de locomoção.","a fé pública exclusivamente."],"O art. 184 tutela direitos autorais e conexos, que integram a esfera da propriedade imaterial."],
  [122,"Crimes contra o patrimônio","Usurpação de nome ou pseudônimo","Usurpar o nome ou pseudônimo alheio para obter vantagem ou causar dano pode configurar:","crime relacionado à propriedade imaterial e à identidade pessoal.",["furto simples.","receptação.","omissão de socorro.","prevaricação."],"O art. 185 prevê figura relacionada à usurpação de nome ou pseudônimo alheio, observados os elementos de vantagem ou dano."],
  [123,"Crimes contra o patrimônio","Crime de dano","A diferença central entre dano e furto é que no dano o agente:","destrói, inutiliza ou deteriora coisa alheia, sem necessidade de intenção de assenhoramento.",["subtrai a coisa para si ou para outrem.","obtém vantagem por fraude da vítima.","recebe coisa sabendo ser produto de crime.","constrange a vítima a entregar bem por grave ameaça."],"O dano atinge a integridade da coisa; no furto há subtração com intenção de assenhoramento."],
  [124,"Crimes contra o patrimônio","Patrimônio","O patrimônio é bem jurídico protegido por diversas figuras penais. Para identificar o tipo aplicável, é necessário verificar, entre outros pontos:","como o agente obteve ou atingiu o bem e quais meios empregou.",["somente o valor econômico do bem, independentemente da conduta.","a opinião pessoal da vítima sobre o autor.","o local de nascimento do agente.","a existência de sentença civil prévia."],"Furto, roubo, estelionato, apropriação e receptação diferenciam-se pelos meios de execução, relação prévia com o bem e elemento subjetivo."],
  [125,"Crimes contra o patrimônio","Extorsão","A extorsão distingue-se do roubo porque, naquela, a vítima, constrangida, realiza, tolera ou deixa de realizar um ato que viabiliza a vantagem econômica. No roubo, em regra, o bem é:","subtraído diretamente pelo agente.",["entregue livremente pela vítima sem ameaça.","transferido após contrato civil válido.","deixado pelo dono em razão de caso fortuito.","recebido pelo agente em depósito legítimo."],"No roubo a subtração é executada pelo agente; na extorsão a vítima participa do ato patrimonial sob constrangimento."],
  [126,"Crimes contra o patrimônio","Escusas familiares","As escusas absolutórias em crimes patrimoniais não se aplicam, entre outras hipóteses, quando o crime é praticado:","com violência ou grave ameaça à pessoa.",["entre cônjuges durante a sociedade conjugal.","em prejuízo de ascendente ou descendente, nas hipóteses legais.","entre parentes previstos expressamente na lei, sem exceção.","com consentimento válido do proprietário."],"As imunidades patrimoniais familiares possuem limites. O art. 183 afasta sua aplicação, por exemplo, nos crimes com violência ou grave ameaça à pessoa."],
  [127,"Crimes contra o patrimônio","Ação penal","Em crimes patrimoniais, a necessidade de representação ou a natureza da ação penal pode variar conforme o tipo e as circunstâncias. Por isso, afirmar que todo crime patrimonial depende de representação é:","incorreto.",["correto, sem exceção.","correto apenas quando o bem é público.","correto se houver violência ou grave ameaça.","correto sempre que a vítima for pessoa jurídica."],"O regime de ação penal depende do tipo legal e de circunstâncias específicas; não há regra única de representação para todos os crimes patrimoniais."],
  [128,"Crimes contra o patrimônio","Consumação","Em crimes de subtração patrimonial, a consumação não depende, necessariamente, de posse mansa e pacífica prolongada, mas da retirada do bem da esfera de disponibilidade da vítima conforme a dinâmica concreta. Essa análise relaciona-se ao:","momento de consumação do delito.",["princípio da insignificância, exclusivamente.","erro de proibição inevitável.","estado de necessidade.","concurso formal de crimes."],"A consumação de crimes patrimoniais exige análise dos elementos do tipo e da inversão ou deslocamento da posse, conforme a figura delitiva."],
  [129,"Crimes contra o patrimônio","Tentativa","A tentativa é, em tese, possível em crimes patrimoniais quando o agente inicia a execução e a consumação não ocorre por circunstâncias:","alheias à sua vontade.",["exclusivamente posteriores à sentença.","decorrentes do arrependimento posterior.","relacionadas a ato plenamente consumado.","produzidas por decisão livre de não iniciar a execução."],"Aplica-se a regra geral da tentativa: início de execução e não consumação por circunstâncias alheias à vontade do agente, salvo incompatibilidade com o tipo concreto."],
  [130,"Crimes contra o patrimônio","Síntese patrimonial","Assinale a associação correta:","Estelionato: vantagem ilícita obtida mediante fraude que induz ou mantém a vítima em erro.",["Furto: subtração mediante grave ameaça à pessoa.","Roubo: posse prévia legítima convertida em apropriação.","Receptação: destruição de coisa alheia sem intenção de assenhoramento.","Dano: aquisição de coisa que se sabe produto de crime."],"Estelionato envolve fraude e erro da vítima. As demais alternativas descrevem incorretamente elementos de roubo, apropriação indébita, receptação e dano."],
  [131,"Crimes contra a fé pública","Moeda falsa","Falsificar, fabricando-a ou alterando-a, moeda metálica ou papel-moeda de curso legal no País ou no estrangeiro configura:","moeda falsa.",["falsidade ideológica.","receptação.","estelionato, em qualquer hipótese.","prevaricação."],"O art. 289 tipifica a falsificação, fabricação ou alteração de moeda metálica ou papel-moeda de curso legal."],
  [132,"Crimes contra a fé pública","Moeda falsa","Importar ou exportar, adquirir, vender, trocar, ceder, emprestar, guardar ou introduzir na circulação moeda falsa pode configurar crime quando o agente:","tem ciência da falsidade.",["acredita justificadamente que a moeda é autêntica.","atua sem contato algum com a moeda.","apenas recebe informação posterior sobre a existência de falsificação.","recusa-se a utilizar a moeda."],"O art. 289 abrange diversas condutas relacionadas à moeda falsa e exige o elemento subjetivo correspondente, em especial o conhecimento da falsidade nas modalidades dolosas."],
  [133,"Crimes contra a fé pública","Falsificação de documento público","Falsificar, no todo ou em parte, documento público, ou alterar documento público verdadeiro, configura:","falsificação de documento público.",["falsidade ideológica exclusivamente.","uso de documento falso apenas.","receptação qualificada.","violação de segredo profissional."],"O art. 297 trata da falsificação material ou alteração de documento público verdadeiro."],
  [134,"Crimes contra a fé pública","Falsificação de documento particular","Falsificar, no todo ou em parte, documento particular ou alterar documento particular verdadeiro configura:","falsificação de documento particular.",["falsa identidade necessariamente.","peculato.","desacato.","lesão corporal."],"O art. 298 prevê a falsificação ou alteração de documento particular verdadeiro."],
  [135,"Crimes contra a fé pública","Falsidade ideológica","Ocorre falsidade ideológica quando alguém omite, em documento público ou particular, declaração que dele devia constar, ou nele insere declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre:","fato juridicamente relevante.",["qualquer opinião sem repercussão jurídica.","fato exclusivamente futuro e impossível.","sentimento pessoal sem registro documental.","conduta que não envolva documento."],"O art. 299 tipifica a falsidade ideológica, que recai sobre o conteúdo ideológico do documento, e não sobre sua forma material."],
  [136,"Crimes contra a fé pública","Falsidade material e ideológica","A principal diferença entre falsidade material e falsidade ideológica é que a primeira recai sobre a autenticidade ou integridade física do documento, enquanto a segunda recai sobre:","a veracidade do conteúdo declarado.",["a existência de dano patrimonial obrigatório.","a culpabilidade do julgador.","o local em que o documento foi encontrado.","a nacionalidade do declarante."],"Na falsidade material há fabricação ou alteração física do documento; na ideológica, o documento é formalmente verdadeiro, mas contém declaração falsa ou omissa relevante."],
  [137,"Crimes contra a fé pública","Uso de documento falso","Fazer uso de qualquer dos papéis falsificados ou alterados a que se referem os dispositivos legais sobre falsidade documental pode configurar:","uso de documento falso.",["apropriação indébita.","furto simples.","crime impossível.","omissão de socorro."],"O art. 304 tipifica o uso de documento falsificado ou alterado. O usuário pode responder mesmo sem ter sido o falsificador, conforme o caso."],
  [138,"Crimes contra a fé pública","Supressão de documento","Destruir, suprimir ou ocultar, em benefício próprio ou de outrem, ou em prejuízo alheio, documento público ou particular verdadeiro, de que não podia dispor, pode configurar:","supressão de documento.",["falsidade ideológica.","calúnia.","dano simples necessariamente.","receptação culposa."],"O art. 305 prevê supressão de documento verdadeiro quando o agente não podia dele dispor e atua com finalidade de benefício ou prejuízo."],
  [139,"Crimes contra a fé pública","Falsa identidade","Atribuir-se ou atribuir a terceiro falsa identidade para obter vantagem, em proveito próprio ou alheio, ou para causar dano a outrem, configura:","falsa identidade.",["uso de documento falso em qualquer hipótese.","furto de identidade civil.","calúnia.","exercício arbitrário das próprias razões."],"O art. 307 tipifica a falsa identidade. Nem sempre há necessidade de documento falso; o núcleo é atribuir identidade falsa com finalidade de vantagem ou dano."],
  [140,"Crimes contra a fé pública","Uso de documento de identidade alheia","Usar, como própria, carteira de identidade, título de eleitor, passaporte ou qualquer documento de identidade alheia ou ceder a outrem, para que dele se utilize, documento dessa natureza, configura:","uso de documento de identidade alheia.",["falsidade ideológica obrigatoriamente.","desobediência.","furto de uso.","receptação."],"O art. 308 prevê figura específica para o uso como próprio ou cessão de documento de identidade alheia."],
  [141,"Crimes contra a fé pública","Fraude de lei sobre estrangeiro","Usar o agente, para entrar ou permanecer no território nacional, nome que não é o seu ou atribuir-se falsa qualidade, nacionalidade ou naturalidade, pode configurar:","fraude de lei sobre estrangeiro.",["crime de moeda falsa.","violação de domicílio.","prevaricação.","abandono de incapaz."],"O Código Penal prevê figura específica para fraude relacionada ao ingresso ou permanência de estrangeiro no território nacional mediante falsa identidade ou qualidade."],
  [142,"Crimes contra a fé pública","Falso reconhecimento de firma","Reconhecer, como verdadeira, no exercício de função pública, firma ou letra que o não seja, pode configurar:","falso reconhecimento de firma ou letra.",["falsidade ideológica praticada por particular.","furto qualificado.","estelionato.","lesão corporal."],"O art. 300 pune o funcionário público que reconhece como verdadeira firma ou letra que não o seja."],
  [143,"Crimes contra a fé pública","Certidão ou atestado ideologicamente falso","Atestar ou certificar falsamente, em razão de função pública, fato ou circunstância que habilite alguém a obter cargo público, isenção de ônus ou serviço de caráter público, pode configurar:","certidão ou atestado ideologicamente falso.",["calúnia contra a administração.","furto mediante fraude.","receptação.","crime impossível."],"O art. 301 prevê hipótese ligada a atestado ou certidão falsa em razão de função pública, com finalidade de habilitar obtenção de vantagem administrativa."],
  [144,"Crimes contra a fé pública","Atestado médico falso","Dar o médico, no exercício da profissão, atestado falso constitui:","atestado médico falso.",["falsa identidade.","violação de segredo profissional.","receptação culposa.","exercício regular de direito."],"O art. 302 tipifica o fornecimento de atestado falso por médico no exercício da profissão."],
  [145,"Crimes contra a fé pública","Reprodução ou adulteração de selo","Reproduzir ou alterar selo ou peça filatélica que tenha valor para coleção, salvo quando a reprodução ou alteração está visivelmente anotada na face ou no verso, pode configurar:","crime contra a fé pública relacionado a selo ou peça filatélica.",["furto de energia.","crime contra a honra.","abandono material.","dano culposo."],"O Código Penal disciplina a reprodução ou alteração de selo ou peça filatélica com relevância para colecionismo, ressalvando situações de anotação visível."],
  [146,"Crimes contra a fé pública","Fé pública","Os crimes contra a fé pública protegem, em essência, a confiança social na autenticidade e veracidade de documentos, moedas, sinais ou declarações com relevância:","jurídica.",["apenas afetiva.","exclusivamente privada e sem repercussão coletiva.","somente econômica, sem relação documental.","unicamente eleitoral."],"A fé pública representa confiança coletiva em instrumentos e declarações que produzem efeitos jurídicos, como moeda e documentos."],
  [147,"Crimes contra a fé pública","Documento público","Documento público, para fins penais, abrange instrumentos emitidos por autoridade pública competente ou por quem exerça função pública nos limites de suas atribuições. Sua falsificação é tratada de forma:","mais grave que a do documento particular, em regra.",["atípica se não houver dano patrimonial imediato.","idêntica à de qualquer declaração verbal.","exclusivamente administrativa.","impossível quando o agente é particular."],"O Código Penal diferencia falsificação de documento público e particular, atribuindo maior gravidade, em regra, ao documento público pela relevância da fé pública."],
  [148,"Crimes contra a fé pública","Concurso de crimes","Quem falsifica documento e depois o utiliza pode, conforme a situação concreta e a relação entre as condutas, responder de acordo com as regras de consunção ou concurso aplicáveis. O ponto central para a análise é:","a autonomia ou absorção das condutas no caso concreto.",["a nacionalidade da vítima, exclusivamente.","a existência de dano físico à pessoa.","o valor econômico fixo do documento.","a obrigatoriedade de punir sempre duas vezes pelo mesmo fato."],"A relação entre falsificação e uso do documento pode demandar análise de consunção ou concurso, evitando duplicidade de punição pelo mesmo desvalor quando houver absorção."],
  [149,"Crimes contra a fé pública","Síntese documental","Sobre falsidade documental, assinale a associação correta:","Falsidade ideológica: inserção ou omissão de declaração falsa em documento verdadeiro, com finalidade juridicamente relevante.",["Falsificação de documento público: simples uso de documento verdadeiro de terceiro.","Uso de documento falso: destruição de documento próprio sem dano a ninguém.","Falsa identidade: fabricação física obrigatória de passaporte falso.","Supressão de documento: mera crítica ao conteúdo de documento público."],"A falsidade ideológica atinge o conteúdo do documento. Falsificação material atinge sua forma; uso de documento falso envolve apresentação do documento falsificado; os demais conceitos são distintos."] ,
  [150,"Crimes contra a fé pública","Síntese","A proteção penal da fé pública é especialmente relevante porque documentos, moeda e sinais oficiais permitem que relações sociais e jurídicas se desenvolvam com:","confiança na autenticidade e na veracidade dos instrumentos utilizados.",["dispensa total de verificação por autoridades e particulares.","eliminação de qualquer responsabilização por fraude.","substituição das normas penais por regras privadas.","impossibilidade de falsificação no mundo real."],"Os crimes contra a fé pública buscam preservar a confiança coletiva em instrumentos relevantes para relações jurídicas, econômicas e sociais." ]
];
const direitoPenalLoteTresComResposta = direitoPenalLoteTres.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 101) % 5];
  return {id:`direito-penal-${String(number).padStart(3,"0")}`,subjectId:"direito-penal",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoPenalLoteTresComResposta);
questionBank.review.direitoPenalLoteTresReviewed = direitoPenalLoteTresComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Penal — lote 2 (51–100): crimes contra a pessoa e introdução aos crimes patrimoniais.
const direitoPenalLoteDois = [
  [51,"Crimes contra a pessoa","Homicídio","O núcleo do tipo penal de homicídio simples consiste em:","matar alguém.",["ofender a integridade corporal de alguém.","expor alguém a perigo de contágio.","subtrair bem móvel alheio.","constranger alguém mediante violência."],"O homicídio, previsto no art. 121 do Código Penal, tem por núcleo matar alguém. Ofensas corporais e patrimoniais configuram outros delitos."],
  [52,"Crimes contra a pessoa","Homicídio","O bem jurídico primordialmente protegido pelo crime de homicídio é:","a vida humana extrauterina.",["o patrimônio da vítima.","a honra subjetiva do ofendido.","a liberdade de locomoção.","a administração pública."],"O homicídio tutela a vida humana extrauterina. Outros crimes podem envolver bens diversos, mas este é o objeto jurídico central."],
  [53,"Crimes contra a pessoa","Homicídio privilegiado","O homicídio pode ser privilegiado se o agente o comete impelido por motivo de relevante valor social ou moral, ou sob domínio de violenta emoção, logo em seguida a:","injusta provocação da vítima.",["qualquer desavença ocorrida anos antes.","ordem legal de autoridade competente.","simples suspeita sem provocação identificável.","reação de terceiro desconhecido."],"O art. 121, § 1º, prevê redução para motivo de relevante valor social ou moral ou violenta emoção logo após injusta provocação da vítima."],
  [54,"Crimes contra a pessoa","Homicídio culposo","No homicídio culposo, a morte decorre de violação do dever objetivo de cuidado, sem que o agente queira o resultado ou assuma o risco de produzi-lo. É exemplo de modalidade culposa:","imperícia técnica na execução de atividade que exige conhecimento especializado.",["vontade direta de causar a morte.","assunção consciente do risco de matar.","motivo torpe previamente escolhido.","emprego de meio cruel para atingir a vítima."],"A imperícia é modalidade de culpa. Vontade ou assunção do risco caracteriza dolo; qualificadoras não definem culpa."],
  [55,"Crimes contra a pessoa","Induzimento ao suicídio","Induzir ou instigar alguém a suicidar-se ou prestar-lhe auxílio para que o faça é conduta prevista no Código Penal, cuja responsabilização depende das circunstâncias e do resultado. O delito protege principalmente:","a vida humana.",["a propriedade privada.","a fé pública.","a administração da justiça.","a organização do trabalho."],"O art. 122 trata da participação em suicídio ou automutilação e protege a vida e integridade da pessoa vulnerada pela indução, instigação ou auxílio."],
  [56,"Crimes contra a pessoa","Infanticídio","O infanticídio caracteriza-se quando a mãe mata o próprio filho:","durante o parto ou logo após, sob influência do estado puerperal.",["em qualquer momento da vida da vítima, por motivo econômico.","antes do parto, sem que exista nascimento com vida.","por ordem de terceiro, sem relação com o puerpério.","após a maioridade do filho, por motivo passional."],"O art. 123 exige que a mãe, sob influência do estado puerperal, mate o próprio filho durante ou logo após o parto."],
  [57,"Crimes contra a pessoa","Aborto","Provocar aborto em si mesma ou consentir que outrem lho provoque configura, em regra, crime previsto no:","art. 124 do Código Penal.",["art. 121, como homicídio simples.","art. 155, como furto.","art. 213, como crime contra a dignidade sexual.","art. 288, como associação criminosa."],"O art. 124 tipifica o aborto provocado pela gestante ou com seu consentimento, ressalvadas as hipóteses legais de não punição."],
  [58,"Crimes contra a pessoa","Aborto legal","Não se pune o aborto praticado por médico, entre outras hipóteses, se não há outro meio de salvar a vida da:","gestante.",["pessoa que realizou o procedimento médico.","autoridade policial que registrou a ocorrência.","pessoa indicada pela família, sem vínculo com a gestação.","testemunha do fato."],"O art. 128, I, prevê o aborto necessário, praticado por médico quando não há outro meio de salvar a vida da gestante."],
  [59,"Crimes contra a pessoa","Lesão corporal","Ofender a integridade corporal ou a saúde de outrem configura, em regra:","lesão corporal.",["homicídio tentado necessariamente.","crime contra o patrimônio.","crime de falsidade documental.","mera infração administrativa."],"O art. 129 define lesão corporal como ofensa à integridade corporal ou à saúde de outrem."],
  [60,"Crimes contra a pessoa","Lesão corporal grave","A incapacidade para as ocupações habituais, por mais de trinta dias, é circunstância que pode qualificar a lesão corporal como:","grave.",["leve, sem qualquer consequência típica.","privilegiada por motivo de relevante valor moral.","culposa obrigatoriamente.","atípica por ausência de dano."],"O art. 129, § 1º, I, inclui incapacidade para ocupações habituais por mais de trinta dias entre as hipóteses de lesão corporal grave."],
  [61,"Crimes contra a pessoa","Lesão corporal gravíssima","A perda ou inutilização de membro, sentido ou função é resultado que caracteriza lesão corporal:","gravíssima.",["leve.","culposa simples em qualquer circunstância.","atípica quando houver tratamento médico.","contra o patrimônio."],"O art. 129, § 2º, III, prevê como lesão corporal gravíssima a perda ou inutilização de membro, sentido ou função."],
  [62,"Crimes contra a pessoa","Lesão corporal seguida de morte","Se da lesão corporal resulta morte e as circunstâncias evidenciam que o agente não quis o resultado nem assumiu o risco de produzi-lo, configura-se:","lesão corporal seguida de morte.",["homicídio doloso simples.","infanticídio.","omissão de socorro.","crime impossível."],"O art. 129, § 3º, trata da lesão corporal seguida de morte, crime preterdoloso: dolo na lesão e culpa no resultado morte."],
  [63,"Crimes contra a pessoa","Perigo de contágio","Expor alguém, por meio de relações sexuais ou qualquer ato libidinoso, a contágio de moléstia venérea, sabendo ou devendo saber que está contaminado, configura:","perigo de contágio venéreo.",["abandono material.","violação de domicílio.","furto mediante fraude.","desobediência."],"O art. 130 prevê o crime de perigo de contágio venéreo, exigindo a exposição mediante relações sexuais ou ato libidinoso e conhecimento ou dever de saber da moléstia."],
  [64,"Crimes contra a pessoa","Perigo para vida ou saúde","Expor a vida ou a saúde de outrem a perigo direto e iminente, sem que haja tipo penal mais específico aplicável, pode caracterizar:","perigo para a vida ou saúde de outrem.",["calúnia.","receptação.","prevaricação.","crime impossível."],"O art. 132 tipifica expor a vida ou saúde de outrem a perigo direto e iminente, observada a subsidiariedade diante de tipos específicos."],
  [65,"Crimes contra a pessoa","Abandono de incapaz","Abandonar pessoa que está sob seu cuidado, guarda, vigilância ou autoridade e que, por qualquer motivo, não pode defender-se dos riscos resultantes do abandono constitui:","abandono de incapaz.",["omissão de socorro comum, sem especial dever de cuidado.","exercício regular de direito.","furto de coisa comum.","violação de segredo profissional."],"O art. 133 exige relação de cuidado, guarda, vigilância ou autoridade e incapacidade de defesa da vítima perante os riscos do abandono."],
  [66,"Crimes contra a pessoa","Omissão de socorro","Deixar de prestar assistência, quando possível fazê-lo sem risco pessoal, à criança abandonada ou extraviada, ou pessoa inválida ou ferida, ao desamparo ou em grave e iminente perigo, caracteriza:","omissão de socorro.",["abandono material.","homicídio culposo automaticamente.","crime contra a honra.","apropriação indébita."],"O art. 135 tipifica a omissão de socorro quando a assistência é possível sem risco pessoal, abrangendo também deixar de pedir socorro da autoridade pública."],
  [67,"Crimes contra a pessoa","Maus-tratos","Expor a perigo a vida ou a saúde de pessoa sob sua autoridade, guarda ou vigilância, para fim de educação, ensino, tratamento ou custódia, privando-a de alimentação ou cuidados indispensáveis, pode configurar:","maus-tratos.",["exercício regular de direito, em qualquer hipótese.","lesão corporal atípica.","furto qualificado.","crime contra a fé pública."],"O art. 136 prevê maus-tratos em relação de autoridade, guarda ou vigilância, quando há exposição a perigo mediante as condutas descritas."],
  [68,"Crimes contra a pessoa","Rixa","Participar de rixa, salvo para separar os contendores, é conduta tipificada como:","rixa.",["associação criminosa necessariamente.","legítima defesa recíproca automática.","crime impossível.","desobediência."],"O art. 137 tipifica a participação em rixa, excetuando quem atua apenas para separar os contendores."],
  [69,"Crimes contra a honra","Calúnia","Caluniar alguém consiste em:","imputar-lhe falsamente fato definido como crime.",["atribuir fato ofensivo à reputação, sem imputação de crime.","ofender a dignidade ou o decoro com xingamento.","ameaçar causar mal injusto e grave.","divulgar segredo de que se tem ciência em razão de função."],"O art. 138 define calúnia como imputação falsa de fato definido como crime."],
  [70,"Crimes contra a honra","Difamação","Difamar alguém consiste em imputar-lhe:","fato ofensivo à sua reputação.",["falsamente fato definido como crime, necessariamente.","qualidade negativa diretamente relacionada ao decoro, sem fato.","ameaça de mal injusto e grave.","conduta que exponha a perigo a vida."],"O art. 139 define difamação como imputação de fato ofensivo à reputação. Não exige que o fato seja crime nem que seja falso."],
  [71,"Crimes contra a honra","Injúria","Injuriar alguém consiste em:","ofender-lhe a dignidade ou o decoro.",["atribuir-lhe falsamente fato definido como crime.","imputar fato ofensivo exclusivamente à reputação.","subtrair coisa móvel alheia.","constranger mediante violência ou grave ameaça."],"O art. 140 define injúria como ofensa à dignidade ou ao decoro, normalmente por qualificações ou expressões ofensivas."],
  [72,"Crimes contra a honra","Exceção da verdade","A exceção da verdade, na disciplina dos crimes contra a honra, tem aplicação típica especialmente em relação à:","calúnia, observadas as exceções legais.",["injúria simples, em qualquer caso.","ameaça.","constrangimento ilegal.","violação de domicílio."],"A exceção da verdade é regra ligada à calúnia, pois a veracidade do fato imputado pode afastar a falsidade; há hipóteses legais de inadmissibilidade."],
  [73,"Crimes contra a honra","Retratação","O querelado que, antes da sentença, se retrata cabalmente da calúnia ou da difamação fica:","isento de pena.",["obrigado a cumprir pena privativa de liberdade mínima.","isento apenas de indenização civil, mantendo-se a pena criminal.","automaticamente condenado por injúria.","impedido de responder a qualquer processo futuro."],"O art. 143 prevê que a retratação cabal antes da sentença isenta de pena nos crimes de calúnia ou difamação."],
  [74,"Crimes contra a liberdade individual","Constrangimento ilegal","Constranger alguém, mediante violência ou grave ameaça, ou depois de lhe haver reduzido a capacidade de resistência, a não fazer o que a lei permite ou a fazer o que ela não manda configura:","constrangimento ilegal.",["ameaça simples apenas.","violação de domicílio.","exercício arbitrário das próprias razões sempre.","crime contra a fé pública."],"O art. 146 define constrangimento ilegal por violência, grave ameaça ou redução da resistência para obrigar alguém a fazer ou deixar de fazer o que a lei permite."],
  [75,"Crimes contra a liberdade individual","Ameaça","Ameaçar alguém, por palavra, escrito ou gesto, ou qualquer outro meio simbólico, de causar-lhe mal injusto e grave configura:","ameaça.",["difamação.","perigo de contágio venéreo.","furto simples.","receptação culposa."],"O art. 147 tipifica a ameaça de mal injusto e grave, por diversos meios de exteriorização."],
  [76,"Crimes contra a liberdade individual","Sequestro e cárcere privado","Privar alguém de sua liberdade, mediante sequestro ou cárcere privado, tutela diretamente:","a liberdade de locomoção.",["o patrimônio exclusivamente.","a fé pública.","a administração tributária.","a organização do trabalho."],"O art. 148 protege a liberdade de locomoção contra privação ilegal por sequestro ou cárcere privado."],
  [77,"Crimes contra a liberdade individual","Redução a condição análoga à de escravo","Reduzir alguém a condição análoga à de escravo pode ocorrer, entre outras formas, submetendo-o a trabalhos forçados, jornada exaustiva ou condições degradantes de:","trabalho.",["moradia, apenas se houver contrato civil.","ensino, sem qualquer relação laborativa.","lazer, em ambiente privado.","tratamento médico legalmente indicado."],"O art. 149 tipifica a redução à condição análoga à de escravo, incluindo trabalhos forçados, jornada exaustiva e condições degradantes de trabalho."],
  [78,"Crimes contra a inviolabilidade do domicílio","Violação de domicílio","Entrar ou permanecer, clandestina ou astuciosamente, ou contra a vontade expressa ou tácita de quem de direito, em casa alheia ou suas dependências, configura:","violação de domicílio.",["furto qualificado necessariamente.","constrangimento ilegal em qualquer hipótese.","crime contra a administração pública.","calúnia."],"O art. 150 tipifica entrar ou permanecer indevidamente em casa alheia ou dependências, ressalvadas as hipóteses legais."],
  [79,"Crimes contra a inviolabilidade de correspondência","Violação de correspondência","Devassar indevidamente o conteúdo de correspondência fechada dirigida a outrem pode configurar:","violação de correspondência.",["receptação.","prevaricação.","lesão corporal.","exercício regular de direito, sem limites."],"O art. 151 tutela a inviolabilidade da correspondência, punindo a devassa indevida de correspondência fechada dirigida a outrem."],
  [80,"Crimes contra a inviolabilidade de segredos","Divulgação de segredo","Divulgar, sem justa causa, conteúdo de documento particular ou de correspondência confidencial de que é destinatário ou detentor, capaz de produzir dano a outrem, pode configurar:","divulgação de segredo.",["falsidade ideológica.","furto de uso.","omissão de socorro.","crime impossível."],"O art. 153 trata da divulgação de segredo quando há ausência de justa causa e potencial de dano a outrem."],
  [81,"Crimes contra a inviolabilidade de segredos","Violação de segredo profissional","Revelar alguém, sem justa causa, segredo de que tem ciência em razão de função, ministério, ofício ou profissão, cuja revelação possa produzir dano a outrem, caracteriza:","violação de segredo profissional.",["violação de domicílio.","calúnia.","apropriação indébita.","desacato."],"O art. 154 tipifica a revelação injustificada de segredo conhecido em razão de função, ministério, ofício ou profissão."],
  [82,"Crimes contra o patrimônio","Furto","Subtrair, para si ou para outrem, coisa alheia móvel configura:","furto.",["roubo, mesmo sem violência ou grave ameaça.","apropriação indébita, em qualquer contexto.","extorsão.","receptação."],"O art. 155 define furto como subtração de coisa alheia móvel para si ou para outrem, sem violência ou grave ameaça."],
  [83,"Crimes contra o patrimônio","Furto","Para a caracterização do furto, a coisa subtraída deve ser:","alheia e móvel.",["necessariamente imóvel e registrada em cartório.","de propriedade pública federal exclusivamente.","de valor econômico elevado em qualquer hipótese.","pertencente a pessoa física capaz."],"O objeto material do furto é coisa alheia móvel. A proteção pode alcançar bens de pessoas físicas, jurídicas ou do poder público."],
  [84,"Crimes contra o patrimônio","Furto qualificado","O furto pode ser qualificado, entre outras hipóteses, quando cometido com destruição ou rompimento de obstáculo à subtração da coisa. Nessa situação, o dado qualificante é:","o meio de execução empregado.",["a condição de funcionário público da vítima.","a ocorrência de lesão corporal na vítima.","o arrependimento posterior do agente.","a ausência de intenção de subtrair."],"O art. 155, § 4º, I, prevê qualificação pelo rompimento ou destruição de obstáculo à subtração da coisa."],
  [85,"Crimes contra o patrimônio","Roubo","Subtrair coisa móvel alheia, para si ou para outrem, mediante grave ameaça ou violência à pessoa, ou depois de havê-la por qualquer meio reduzido à impossibilidade de resistência, configura:","roubo.",["furto simples.","apropriação indébita.","estelionato.","receptação."],"O art. 157 define roubo pela subtração patrimonial acrescida de violência, grave ameaça ou redução da resistência."],
  [86,"Crimes contra o patrimônio","Roubo","A diferença central entre furto e roubo reside na presença, no roubo, de:","violência ou grave ameaça à pessoa, ou redução da resistência.",["coisa alheia móvel como objeto material.","intenção de assenhoramento do bem.","subtração para si ou para outrem.","dano patrimonial à vítima."],"Furto e roubo envolvem subtração patrimonial; o roubo se distingue pelo emprego de violência, grave ameaça ou redução da resistência."],
  [87,"Crimes contra o patrimônio","Extorsão","Constranger alguém, mediante violência ou grave ameaça, e com o intuito de obter para si ou para outrem indevida vantagem econômica, a fazer, tolerar que se faça ou deixar de fazer alguma coisa, caracteriza:","extorsão.",["roubo simples.","furto mediante fraude.","apropriação de coisa achada.","dano simples."],"O art. 158 define extorsão. Diferentemente do roubo, na extorsão a vítima participa da entrega ou da conduta patrimonial constrangida."],
  [88,"Crimes contra o patrimônio","Apropriação indébita","Apropriar-se de coisa alheia móvel, de que tem a posse ou a detenção, configura:","apropriação indébita.",["furto simples.","receptação dolosa.","extorsão.","violação de domicílio."],"No art. 168, a posse ou detenção inicial da coisa é legítima ou tolerada; a ilicitude surge com a inversão do ânimo de possuidor."],
  [89,"Crimes contra o patrimônio","Estelionato","Obter, para si ou para outrem, vantagem ilícita, em prejuízo alheio, induzindo ou mantendo alguém em erro mediante artifício, ardil ou qualquer outro meio fraudulento, configura:","estelionato.",["furto qualificado por fraude, necessariamente.","roubo impróprio.","receptação culposa.","dano qualificado."],"O art. 171 define estelionato por vantagem ilícita obtida mediante fraude que induz ou mantém a vítima em erro."],
  [90,"Crimes contra o patrimônio","Receptação","Adquirir, receber, transportar, conduzir ou ocultar, em proveito próprio ou alheio, coisa que sabe ser produto de crime configura:","receptação dolosa.",["furto simples.","apropriação indébita.","dano culposo.","exercício arbitrário das próprias razões."],"O art. 180 tipifica receptação quando o agente sabe que a coisa é produto de crime e pratica uma das condutas descritas."],
  [91,"Crimes contra o patrimônio","Receptação culposa","A receptação culposa ocorre quando o agente adquire ou recebe coisa que, por sua natureza, desproporção entre valor e preço ou condição de quem oferece, deve presumir-se obtida por meio criminoso. O elemento subjetivo é:","culpa, por violação do dever de cuidado.",["dolo direto de subtrair a coisa.","dolo eventual de matar a vítima.","erro de proibição inevitável.","motivo torpe obrigatório."],"A receptação culposa está prevista no art. 180, § 3º, e decorre de circunstâncias que impõem ao agente o dever de suspeitar da origem criminosa."],
  [92,"Crimes contra o patrimônio","Dano","Destruir, inutilizar ou deteriorar coisa alheia configura:","dano.",["furto.","receptação.","estelionato.","calúnia."],"O art. 163 tipifica o dano, que atinge a integridade da coisa alheia sem exigir intenção de assenhoramento."],
  [93,"Crimes contra o patrimônio","Violação de dispositivo informático","Invadir dispositivo informático de uso alheio, conectado ou não à rede de computadores, mediante violação indevida de mecanismo de segurança e com finalidade legalmente descrita pode caracterizar:","invasão de dispositivo informático.",["furto de uso necessariamente.","violação de domicílio físico.","receptação qualificada.","crime impossível por envolver bem imaterial."],"O art. 154-A disciplina a invasão de dispositivo informático mediante violação indevida de mecanismo de segurança, conforme os elementos do tipo."],
  [94,"Crimes contra o patrimônio","Fraude e subtração","Quando o agente usa fraude para diminuir a vigilância da vítima e ele próprio subtrai o bem, a figura tende a aproximar-se de:","furto mediante fraude.",["estelionato, em qualquer hipótese.","extorsão mediante sequestro.","apropriação indébita previdenciária.","receptação culposa."],"No furto mediante fraude, a fraude facilita a subtração realizada pelo agente; no estelionato, a fraude leva a vítima a entregar ou dispor do bem."],
  [95,"Crimes contra o patrimônio","Crime complexo","O roubo é classificado como crime complexo porque reúne tutela do patrimônio com ofensa ou ameaça à:","liberdade ou integridade da pessoa.",["fé pública exclusivamente.","administração tributária.","organização do trabalho.","ordem econômica sem vítima determinada."],"O roubo protege patrimônio e também a liberdade/integridade pessoal, pois pressupõe violência, grave ameaça ou redução de resistência."],
  [96,"Crimes contra o patrimônio","Extorsão","Na extorsão, a colaboração da vítima na obtenção da vantagem patrimonial decorre de:","constrangimento mediante violência ou grave ameaça.",["ato espontâneo de liberalidade sem erro.","subtração clandestina praticada sem contato com a vítima.","posse prévia legítima convertida em apropriação.","descoberta posterior de coisa produto de crime."],"A vítima realiza, tolera ou deixa de realizar conduta patrimonial sob violência ou grave ameaça, característica da extorsão."],
  [97,"Crimes contra o patrimônio","Apropriação de coisa achada","Apropriar-se de coisa alheia vinda ao poder do agente por erro, caso fortuito ou força da natureza, deixando de restituí-la ao dono ou legítimo possuidor ou de entregá-la à autoridade competente dentro do prazo legal, configura:","apropriação de coisa achada.",["furto qualificado.","estelionato.","receptação.","dano."],"O art. 169, parágrafo único, II, disciplina a apropriação de coisa achada, com referência ao dever de restituição ou entrega à autoridade no prazo legal."],
  [98,"Crimes contra o patrimônio","Escusas absolutórias","Em determinadas hipóteses de crimes patrimoniais sem violência ou grave ameaça, o Código Penal prevê isenção de pena em razão de relações familiares. Essas hipóteses constituem:","escusas absolutórias pessoais.",["causas de inexistência do fato típico.","excludentes de ilicitude aplicáveis a todos os autores.","causas de aumento de pena.","formas de extinção da propriedade civil."],"Os arts. 181 e seguintes preveem imunidades penais patrimoniais em relações familiares, de natureza pessoal e sujeitas a limites legais."],
  [99,"Crimes contra o patrimônio","Patrimônio","Crimes patrimoniais protegem, em regra, a relação juridicamente tutelada entre pessoa e bens ou valores. A existência de prejuízo patrimonial não transforma automaticamente o fato em:","crime de furto, pois cada tipo exige elementos próprios.",["ilícito penal em qualquer circunstância.","crime contra a vida.","crime contra a honra.","infração de trânsito."],"A lesão patrimonial pode enquadrar-se em diversos tipos ou até configurar apenas ilícito civil; é necessária a presença dos elementos específicos de cada crime."],
  [100,"Crimes contra o patrimônio","Síntese comparativa","Assinale a associação correta entre crime e elemento distintivo:","Apropriação indébita: posse ou detenção prévia da coisa, seguida de inversão do ânimo de possuidor.",["Furto: violência ou grave ameaça contra a vítima.","Roubo: obtenção de vantagem por indução da vítima em erro, sem violência.","Estelionato: subtração clandestina de bem sem participação da vítima.","Receptação: destruição de coisa alheia sem intenção de assenhoramento."],"A apropriação indébita pressupõe posse ou detenção prévia. Furto é subtração sem violência, roubo envolve violência ou grave ameaça, estelionato envolve fraude e receptação trata de produto de crime." ]
];
const direitoPenalLoteDoisComResposta = direitoPenalLoteDois.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 51) % 5];
  return {id:`direito-penal-${String(number).padStart(3,"0")}`,subjectId:"direito-penal",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoPenalLoteDoisComResposta);
questionBank.review.direitoPenalLoteDoisReviewed = direitoPenalLoteDoisComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Penal — lote 1 (1–50): teoria do delito e culpabilidade.
const direitoPenalLoteUm = [
  [1,"Infração penal","Teoria da infração","No sistema brasileiro, a expressão infração penal abrange:","crimes e contravenções penais.",["somente crimes dolosos previstos no Código Penal.","crimes, ilícitos civis e faltas administrativas.","apenas condutas punidas com reclusão.","somente contravenções praticadas sem violência."],"Infração penal é gênero que compreende crime e contravenção penal. Ilícitos civis e administrativos pertencem a outras esferas de responsabilização."],
  [2,"Princípios penais","Legalidade","O princípio da legalidade penal estabelece que não há crime sem lei anterior que o defina, nem pena sem:","prévia cominação legal.",["decisão judicial posterior ao fato.","autorização administrativa da autoridade policial.","manifestação da vítima sobre a punição.","previsão em regulamento interno."],"O Código Penal e a Constituição consagram a reserva legal e a anterioridade: crime e pena dependem de lei anterior e de cominação legal prévia."],
  [3,"Princípios penais","Anterioridade","Uma lei penal mais gravosa publicada após a prática do fato:","não pode retroagir para alcançar o agente.",["deve ser aplicada se o processo ainda não foi iniciado.","incide automaticamente sobre crimes em investigação.","vale para fatos anteriores quando houver clamor público.","pode ser aplicada por decisão administrativa fundamentada."],"A lei penal mais severa não retroage. A retroatividade penal somente é admitida quando beneficia o réu."],
  [4,"Aplicação da lei penal","Tempo do crime","Considera-se praticado o crime, para fins de tempo, no momento:","da ação ou omissão, ainda que outro seja o momento do resultado.",["em que o resultado se torna irreversível.","da instauração do inquérito policial.","da denúncia oferecida pelo Ministério Público.","da sentença condenatória."],"O art. 4º do Código Penal adota a teoria da atividade: considera-se praticado o crime no momento da ação ou omissão."],
  [5,"Aplicação da lei penal","Lugar do crime","Para efeitos de aplicação da lei penal brasileira, considera-se praticado o crime tanto no lugar em que ocorreu a ação ou omissão quanto onde:","se produziu ou deveria produzir-se o resultado.",["foi instaurado o inquérito policial.","reside a vítima do fato.","a autoridade policial tomou conhecimento do crime.","foi proferida a sentença."],"O art. 6º do Código Penal adota a teoria da ubiquidade para o lugar do crime."],
  [6,"Fato típico","Conduta","Em regra, a conduta penalmente relevante é comportamento humano voluntário, que pode consistir em:","ação ou omissão.",["pensamento isolado, sem exteriorização.","mera condição pessoal do agente.","resultado naturalístico sem comportamento humano.","suspeita administrativa sem fato concreto."],"A conduta é elemento do fato típico e pode ser comissiva ou omissiva. Pensamentos ou condições pessoais, isoladamente, não configuram conduta penal."],
  [7,"Fato típico","Nexo causal","O resultado de que depende a existência do crime somente é imputável a quem lhe deu causa. Considera-se causa:","a ação ou omissão sem a qual o resultado não teria ocorrido.",["qualquer condição remota, mesmo que não influencie o resultado.","apenas o comportamento intencional do autor direto.","a decisão posterior da autoridade judicial.","a conduta exclusiva da vítima, em qualquer caso."],"O art. 13 do Código Penal adota a equivalência dos antecedentes causais: causa é a ação ou omissão sem a qual o resultado não teria ocorrido."],
  [8,"Fato típico","Omissão imprópria","A omissão é penalmente relevante quando o omitente devia e podia agir para evitar o resultado. Entre as fontes desse dever está:","a assunção da responsabilidade de impedir o resultado.",["a simples presença casual no local do fato, sem vínculo algum.","o conhecimento posterior do resultado já consumado.","a antipatia pessoal em relação à vítima.","a inexistência de qualquer relação jurídica ou fática com o bem protegido."],"O art. 13, § 2º, prevê dever de agir para quem tem obrigação legal de cuidado, assumiu a responsabilidade de impedir o resultado ou criou o risco de sua ocorrência."],
  [9,"Fato típico","Crime material","Crime material é aquele cuja consumação exige a produção de:","resultado naturalístico previsto no tipo penal.",["qualquer pensamento criminoso do agente.","sentença condenatória definitiva.","dano moral reconhecido em ação civil.","prova pericial obrigatória em todos os casos."],"Nos crimes materiais, a consumação depende do resultado naturalístico descrito no tipo. Nos formais e de mera conduta, a estrutura é diversa."],
  [10,"Fato típico","Crime formal","No crime formal, o tipo penal descreve resultado, mas a consumação:","ocorre com a prática da conduta, independentemente da produção efetiva desse resultado.",["depende sempre da produção do resultado naturalístico.","exige prisão em flagrante para existir.","só ocorre após recebimento da denúncia.","é afastada quando não houver prejuízo patrimonial."],"Nos crimes formais, a lei antecipa a consumação para a conduta, embora possa descrever resultado ulterior."],
  [11,"Iter criminis","Consumação","Diz-se consumado o crime quando nele se reúnem:","todos os elementos de sua definição legal.",["apenas a intenção de praticá-lo.","a preparação remota de meios para a execução.","a decisão da vítima de registrar ocorrência.","a confissão do agente perante a autoridade."],"O art. 14, I, define o crime consumado como aquele em que se reúnem todos os elementos da definição legal."],
  [12,"Iter criminis","Tentativa","Há tentativa quando o agente inicia a execução do crime, que não se consuma por circunstâncias:","alheias à sua vontade.",["relacionadas exclusivamente ao arrependimento eficaz.","posteriores ao trânsito em julgado.","decorrentes apenas de erro da vítima.","ligadas à ausência de representação policial."],"O art. 14, II, caracteriza a tentativa pelo início de execução e não consumação por circunstâncias alheias à vontade do agente."],
  [13,"Iter criminis","Desistência voluntária","Na desistência voluntária, o agente iniciado o ato de execução decide não prosseguir, respondendo:","somente pelos atos já praticados.",["pela tentativa do crime originalmente visado, em qualquer hipótese.","pelo crime consumado, ainda que nada resulte da conduta.","por fato atípico, mesmo que já tenha causado lesão autônoma.","apenas por contravenção penal."],"Pelo art. 15, quem desiste voluntariamente de prosseguir na execução responde pelos atos já praticados, não pela tentativa do delito inicialmente pretendido."],
  [14,"Iter criminis","Arrependimento eficaz","No arrependimento eficaz, o agente esgota os atos executórios, mas depois impede que o resultado se produza. Nessa situação, ele responde:","pelos atos já praticados.",["necessariamente pelo crime tentado.","pelo crime consumado, pois a execução foi completa.","por nenhum fato, ainda que os atos anteriores sejam autônomos.","por contravenção administrativa."],"O art. 15 equipara o arrependimento eficaz à desistência voluntária quanto à responsabilização pelos atos já praticados."],
  [15,"Iter criminis","Arrependimento posterior","Nos crimes cometidos sem violência ou grave ameaça à pessoa, a reparação do dano ou restituição da coisa, por ato voluntário do agente e antes do recebimento da denúncia ou queixa, permite:","redução da pena de um a dois terços.",["extinção automática de toda punibilidade.","absolvição obrigatória, independentemente do dano.","substituição da pena por advertência verbal.","reconhecimento de atipicidade do fato."],"O art. 16 prevê o arrependimento posterior como causa de diminuição de pena, não como exclusão do crime."],
  [16,"Iter criminis","Crime impossível","Não se pune a tentativa quando, por ineficácia absoluta do meio ou por absoluta impropriedade do objeto, é impossível consumar-se o crime. Trata-se de:","crime impossível.",["arrependimento posterior.","desistência voluntária.","erro de proibição inevitável.","concurso formal de crimes."],"O art. 17 prevê o crime impossível, hipótese em que a tentativa não é punida por absoluta ineficácia do meio ou impropriedade do objeto."],
  [17,"Elemento subjetivo","Dolo","O crime é doloso quando o agente:","quis o resultado ou assumiu o risco de produzi-lo.",["produz resultado por imprudência, negligência ou imperícia.","atua sem consciência da conduta e do resultado.","age sob coação física irresistível.","não possui qualquer possibilidade de prever o resultado."],"O art. 18, I, define dolo como vontade de produzir o resultado ou assunção do risco de produzi-lo."],
  [18,"Elemento subjetivo","Culpa","O crime é culposo quando o agente dá causa ao resultado por imprudência, negligência ou:","imperícia.",["vingança.","premeditação.","motivo torpe.","dolo eventual."],"O art. 18, II, prevê as modalidades clássicas da culpa: imprudência, negligência e imperícia."],
  [19,"Elemento subjetivo","Excepcionalidade da culpa","Salvo os casos expressos em lei, ninguém pode ser punido por fato previsto como crime senão quando o pratica:","dolosamente.",["com simples antipatia em relação à vítima.","em estado emocional intenso, ainda que sem conduta.","sob ignorância inevitável da lei penal.","por ordem manifestamente ilegal."],"O parágrafo único do art. 18 estabelece que a punição por crime culposo exige previsão legal expressa."],
  [20,"Sujeitos do crime","Sujeito ativo","Sujeito ativo do crime é, em regra:","a pessoa que pratica a conduta descrita no tipo penal.",["somente a vítima que sofre a lesão ao bem jurídico.","o juiz que aplica a pena ao final do processo.","a autoridade policial que investiga a infração.","o bem jurídico protegido pela norma."],"Sujeito ativo é quem realiza a conduta típica. Em crimes comuns pode ser qualquer pessoa; em crimes próprios, exige-se qualidade especial."],
  [21,"Sujeitos do crime","Sujeito passivo","Sujeito passivo do crime é o titular do bem jurídico lesado ou exposto a perigo pela infração. Pode ser sujeito passivo, conforme o crime:","uma pessoa física, uma pessoa jurídica ou o Estado.",["apenas pessoa física plenamente capaz.","somente pessoa jurídica de direito público.","exclusivamente a autoridade policial.","apenas a coletividade, nunca indivíduo determinado."],"O sujeito passivo pode ser pessoa física, pessoa jurídica, Estado ou coletividade, conforme o bem jurídico protegido."],
  [22,"Sujeitos do crime","Crime próprio","Crime próprio é aquele cujo tipo penal exige do sujeito ativo:","qualidade ou condição especial.",["resultado naturalístico obrigatório.","violência física em toda hipótese.","participação de mais de uma vítima.","pena exclusivamente de reclusão."],"Nos crimes próprios, a lei exige condição especial do agente, como funcionário público em certos delitos funcionais."],
  [23,"Sujeitos do crime","Sujeito passivo","A pessoa jurídica pode figurar como sujeito passivo de crime quando o bem jurídico atingido lhe pertença, como ocorre, por exemplo, em delitos contra:","seu patrimônio.",["a liberdade de locomoção exclusivamente humana.","a integridade corporal própria de pessoa natural.","a vida humana individual.","a dignidade sexual, em qualquer modalidade."],"Pessoas jurídicas podem ser titulares de bens como patrimônio, honra objetiva e organização, podendo ser vítimas em crimes compatíveis com tais bens."],
  [24,"Fato típico","Objeto jurídico","Objeto jurídico do crime é:","o bem ou interesse protegido pela norma penal.",["a pessoa que necessariamente pratica o delito.","o instrumento material utilizado pelo agente.","a decisão judicial que encerra o processo.","a pena aplicada após condenação."],"Objeto jurídico é o bem protegido pelo tipo penal, como vida, patrimônio, administração pública ou fé pública."],
  [25,"Fato típico","Objeto material","Objeto material é a pessoa ou coisa sobre a qual recai a conduta criminosa, distinguindo-se do:","objeto jurídico, que é o bem protegido pela norma.",["sujeito ativo, que sempre é a vítima.","resultado jurídico, que inexiste no crime.","tipo penal, que é apenas a pena prevista.","inquérito policial, que substitui a prova do fato."],"O objeto material é o alvo físico da ação; o objeto jurídico é o interesse protegido pela norma."],
  [26,"Fato típico","Tipicidade","A tipicidade formal consiste na adequação da conduta praticada ao modelo abstrato previsto na:","lei penal.",["jurisprudência isolada de tribunal local.","orientação administrativa sem força normativa.","vontade da vítima manifestada após o fato.","norma moral sem previsão legal."],"Tipicidade formal é o encaixe da conduta na descrição legal. A análise material considera também a relevância da lesão ao bem jurídico."],
  [27,"Fato típico","Tipicidade","A tipicidade material está relacionada à efetiva lesão ou perigo relevante ao bem jurídico protegido, funcionando como limite à incidência penal em condutas:","destituídas de ofensividade significativa.",["praticadas com resultado doloso em qualquer intensidade.","descritas em regulamento administrativo.","que tenham sido investigadas pela polícia.","que envolvam apenas bens públicos."],"A tipicidade material exige ofensividade relevante, aproximando-se da ideia de intervenção mínima e evitando incidência penal em lesões insignificantes quando cabível."],
  [28,"Ilicitude","Estado de necessidade","Considera-se em estado de necessidade quem pratica o fato para salvar de perigo atual, que não provocou por sua vontade, direito próprio ou alheio, cujo sacrifício não era razoável exigir-se, desde que:","não tivesse dever legal de enfrentar o perigo.",["atuasse para vingar ofensa passada.","pudesse evitar o perigo sem qualquer sacrifício e preferisse lesar terceiro.","o perigo fosse meramente imaginário e remoto.","agisse por motivo de diversão."],"O art. 24 define o estado de necessidade e ressalva que não pode alegá-lo quem tinha dever legal de enfrentar o perigo."],
  [29,"Ilicitude","Legítima defesa","Age em legítima defesa quem, usando moderadamente os meios necessários, repele injusta agressão, atual ou iminente, a direito:","seu ou de outrem.",["somente próprio, nunca de terceiro.","exclusivamente patrimonial e de valor econômico elevado.","que já tenha sido definitivamente violado no passado.","contra agressão lícita praticada por autoridade competente."],"O art. 25 admite legítima defesa própria ou de terceiro, contra agressão injusta, atual ou iminente, com uso moderado dos meios necessários."],
  [30,"Ilicitude","Excludentes de ilicitude","Não há crime quando o agente pratica o fato em estado de necessidade, legítima defesa, estrito cumprimento de dever legal ou:","exercício regular de direito.",["erro de proibição evitável.","embriaguez voluntária.","emoção ou paixão.","motivo fútil."],"O art. 23 lista as causas legais de exclusão da ilicitude, incluindo exercício regular de direito."],
  [31,"Ilicitude","Excesso punível","O agente que, em qualquer das hipóteses de exclusão da ilicitude, excede dolosa ou culposamente os limites legais:","responde pelo excesso.",["fica isento de toda responsabilidade pelo fato.","responde apenas administrativamente.","tem a conduta automaticamente convertida em contravenção.","pode invocar a excludente para qualquer resultado produzido."],"O parágrafo único do art. 23 determina responsabilização pelo excesso doloso ou culposo."],
  [32,"Ilicitude","Estrito cumprimento do dever legal","O agente público que realiza prisão em flagrante observando os requisitos legais atua, em regra, em:","estrito cumprimento de dever legal.",["estado de necessidade defensivo.","erro de tipo essencial.","arrependimento posterior.","coação moral irresistível."],"Quando a conduta decorre de dever imposto pelo ordenamento e é praticada dentro de seus limites, pode incidir a excludente do estrito cumprimento de dever legal."],
  [33,"Ilicitude","Exercício regular de direito","A prática de atividade esportiva dentro das regras, ainda que produza lesão típica e previsível inerente ao jogo, pode caracterizar:","exercício regular de direito.",["legítima defesa contra a própria vítima.","crime impossível.","erro de proibição inevitável.","coação física irresistível."],"A atuação dentro das regras de direito reconhecido pode excluir a ilicitude. A análise depende dos limites concretos da prática."],
  [34,"Culpabilidade","Elementos","A culpabilidade, na concepção normativa predominante, compreende imputabilidade, potencial consciência da ilicitude e:","exigibilidade de conduta diversa.",["resultado naturalístico obrigatório.","nexo causal entre conduta e dano.","objeto material do delito.","tipicidade formal exclusivamente."],"A culpabilidade reúne imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa."],
  [35,"Culpabilidade","Imputabilidade","Os menores de dezoito anos são penalmente:","inimputáveis, ficando sujeitos às normas da legislação especial.",["imputáveis com redução obrigatória de metade da pena.","imputáveis apenas em crimes graves.","responsáveis pelo Código Penal a partir dos dezesseis anos.","isentos de qualquer consequência jurídica."],"O art. 27 do Código Penal dispõe que menores de dezoito anos são penalmente inimputáveis e submetidos à legislação especial."],
  [36,"Culpabilidade","Imputabilidade","É isento de pena o agente que, por doença mental ou desenvolvimento mental incompleto ou retardado, era ao tempo da ação ou omissão inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento. Trata-se de:","inimputabilidade por incapacidade psíquica.",["arrependimento eficaz.","erro de tipo permissivo.","crime impossível.","causa de aumento de pena."],"O art. 26 prevê inimputabilidade quando a doença ou desenvolvimento mental impede integralmente entendimento da ilicitude ou autodeterminação."],
  [37,"Culpabilidade","Semi-imputabilidade","Quando o agente, em razão de perturbação de saúde mental ou desenvolvimento mental incompleto ou retardado, não era inteiramente capaz de entender o caráter ilícito do fato, o juiz pode:","reduzir a pena de um a dois terços.",["declarar extinta a punibilidade obrigatoriamente.","aplicar pena de morte em caso de reincidência.","afastar qualquer medida de segurança.","converter automaticamente o crime em contravenção."],"O parágrafo único do art. 26 prevê redução de pena de um a dois terços para a semi-imputabilidade."],
  [38,"Culpabilidade","Emoção e paixão","A emoção ou a paixão, em regra:","não excluem a imputabilidade penal.",["tornam o agente automaticamente inimputável.","eliminam a ilicitude de qualquer conduta.","impedem o reconhecimento do dolo.","transformam crime em mero ilícito civil."],"O art. 28, I, afirma que emoção ou paixão não excluem a imputabilidade penal, embora possam ter relevância em situações específicas previstas em lei."],
  [39,"Culpabilidade","Embriaguez","A embriaguez voluntária ou culposa pelo álcool ou substância de efeitos análogos:","não exclui a imputabilidade penal.",["sempre exclui o dolo e a culpa.","gera inimputabilidade automática.","elimina toda responsabilidade pelos resultados causados.","impede a aplicação de pena privativa de liberdade."],"O art. 28, II, dispõe que embriaguez voluntária ou culposa não exclui a imputabilidade penal."],
  [40,"Culpabilidade","Embriaguez completa","A embriaguez completa proveniente de caso fortuito ou força maior pode isentar de pena o agente que, ao tempo da ação ou omissão, era inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se conforme esse entendimento. A hipótese depende de:","ausência de voluntariedade na embriaguez e incapacidade total.",["qualquer consumo voluntário de álcool em quantidade elevada.","simples alegação do agente, sem exame das circunstâncias.","embriaguez parcial necessariamente.","fato cometido apenas sem violência."],"O art. 28, § 1º, exige embriaguez completa por caso fortuito ou força maior e incapacidade integral."],
  [41,"Culpabilidade","Coação moral irresistível","Se o fato é cometido sob coação irresistível, responde pelo crime:","o coator.",["o coagido, em qualquer hipótese.","a vítima que sofreu a conduta.","a autoridade policial que registrou o fato.","o juiz que aprecia o processo."],"O art. 22 prevê que, na coação irresistível, é punível o autor da coação, afastando-se a culpabilidade do coagido."],
  [42,"Culpabilidade","Obediência hierárquica","A obediência hierárquica pode afastar a culpabilidade do subordinado quando a ordem não é:","manifestamente ilegal.",["proveniente de superior hierárquico.","emitida em ambiente administrativo.","relacionada a atividade pública.","cumprida durante o expediente."],"Pelo art. 22, na obediência a ordem não manifestamente ilegal de superior hierárquico, pune-se o autor da ordem."],
  [43,"Erro","Erro de proibição","O erro sobre a ilicitude do fato, se inevitável:","isenta de pena.",["aumenta obrigatoriamente a pena.","exclui a tipicidade formal, sem afetar a culpabilidade.","gera apenas responsabilidade civil.","torna o crime impossível."],"O art. 21 estabelece que o erro inevitável sobre a ilicitude isenta de pena; se evitável, pode reduzir a pena."],
  [44,"Erro","Erro de proibição","Se o erro sobre a ilicitude do fato for evitável, poderá o juiz:","diminuir a pena de um sexto a um terço.",["absolver obrigatoriamente o agente.","declarar inexistente o fato típico.","aumentar a pena de um a dois terços.","aplicar somente medida administrativa."],"O art. 21 prevê redução de um sexto a um terço quando o erro de proibição for evitável."],
  [45,"Erro","Erro de tipo","O erro sobre elemento constitutivo do tipo legal de crime exclui:","o dolo, mas permite punição por crime culposo, se previsto em lei.",["a ilicitude em qualquer hipótese.","a culpabilidade e a responsabilidade civil de modo automático.","a existência material da conduta.","a ação penal pública incondicionada."],"O art. 20 dispõe que erro sobre elemento do tipo exclui o dolo, admitindo punição culposa se houver previsão legal."],
  [46,"Erro","Erro sobre a pessoa","O erro quanto à pessoa contra a qual o crime é praticado não isenta de pena. Consideram-se, nesse caso, as qualidades da pessoa contra quem o agente queria praticar o crime. Trata-se de:","erro sobre a pessoa.",["arrependimento posterior.","desistência voluntária.","erro de proibição inevitável.","estado de necessidade."],"O art. 20, § 3º, disciplina o erro sobre a pessoa, preservando a responsabilização e considerando as qualidades da vítima visada."],
  [47,"Concurso de pessoas","Autoria e participação","Quem, de qualquer modo, concorre para o crime incide nas penas a este cominadas, na medida de sua:","culpabilidade.",["condição econômica.","posição social da vítima.","capacidade civil para contratar.","preferência por determinada pena."],"O art. 29 adota a regra de que quem concorre para o crime responde nas penas a ele cominadas, na medida de sua culpabilidade."],
  [48,"Concurso de pessoas","Participação de menor importância","Se a participação for de menor importância, a pena pode ser diminuída:","de um sexto a um terço.",["obrigatoriamente pela metade.","em dois terços, sem apreciação judicial.","somente mediante perdão da vítima.","apenas em crimes culposos."],"O art. 29, § 1º, prevê diminuição de um sexto a um terço para participação de menor importância."],
  [49,"Concurso de pessoas","Cooperação dolosamente distinta","Se algum dos concorrentes quis participar de crime menos grave, ser-lhe-á aplicada a pena deste. Essa pena poderá ser aumentada até a metade se era previsível o resultado mais grave. A regra expressa:","cooperação dolosamente distinta.",["princípio da territorialidade.","erro de proibição inevitável.","crime impossível.","inimputabilidade por doença mental."],"O art. 29, § 2º, disciplina a cooperação dolosamente distinta, limitando a responsabilização conforme o dolo do concorrente, com aumento pela previsibilidade."],
  [50,"Teoria do delito","Síntese estrutural","Na análise sequencial tradicional do crime, verifica-se inicialmente o fato típico, depois a ilicitude e, por fim:","a culpabilidade.",["a sentença penal condenatória.","a prisão do agente.","a representação da vítima.","a reparação civil do dano."],"A estrutura analítica mais difundida do crime é fato típico, ilicitude e culpabilidade. Processo e pena são etapas ou consequências distintas." ]
];
const direitoPenalLoteUmComResposta = direitoPenalLoteUm.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 1) % 5];
  return {id:`direito-penal-${String(number).padStart(3,"0")}`,subjectId:"direito-penal",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoPenalLoteUmComResposta);
questionBank.review.direitoPenalLoteUmReviewed = direitoPenalLoteUmComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Constitucional — lote 4 (201–250): fechamento de cobertura do programa-base.
const direitoConstitucionalLoteQuatro = [
  [201,"Princípios fundamentais","Relações internacionais","A autodeterminação dos povos e a não intervenção são princípios que regem, segundo a Constituição, as relações internacionais do Brasil. Eles se harmonizam com:","a igualdade entre os Estados e a solução pacífica dos conflitos.",["a submissão automática da soberania nacional a governos estrangeiros.","a utilização obrigatória da força militar para resolver controvérsias.","a exclusão da cooperação entre os povos para o progresso da humanidade.","a vedação de concessão de asilo político."],"Os princípios do art. 4º formam um conjunto: autodeterminação, não intervenção, igualdade entre Estados, defesa da paz, solução pacífica dos conflitos, cooperação e asilo político, entre outros."],
  [202,"Princípios fundamentais","Princípios fundamentais","Os valores sociais do trabalho e da livre iniciativa são, na Constituição brasileira:","fundamentos da República Federativa do Brasil.",["objetivos fundamentais vinculados apenas à política urbana.","princípios exclusivos da ordem tributária.","direitos sociais atribuídos apenas a trabalhadores com vínculo público.","competências privativas dos Municípios."],"O art. 1º, IV, prevê os valores sociais do trabalho e da livre iniciativa como fundamentos da República."],
  [203,"Princípios fundamentais","Princípios fundamentais","Construir uma sociedade livre, justa e solidária constitui:","objetivo fundamental da República Federativa do Brasil.",["competência administrativa exclusiva da União.","direito político condicionado à filiação partidária.","atribuição exclusiva do Poder Judiciário.","princípio aplicável apenas às relações internacionais."],"O art. 3º, I, enuncia esse objetivo fundamental da República."],
  [204,"Princípios fundamentais","Relações internacionais","A concessão de asilo político é expressamente prevista pela Constituição como:","princípio das relações internacionais do Brasil.",["causa de perda de nacionalidade brasileira.","competência legislativa privativa dos Municípios.","forma de intervenção federal nos Estados.","atribuição exclusiva das polícias civis."],"O art. 4º, X, inclui a concessão de asilo político entre os princípios que regem as relações internacionais brasileiras."],
  [205,"Princípios fundamentais","Princípios fundamentais","A soberania, no contexto do art. 1º da Constituição, é fundamento da República e não se confunde com:","a autonomia dos entes federativos.",["a cidadania como fundamento constitucional.","a dignidade da pessoa humana como fundamento constitucional.","o pluralismo político como fundamento constitucional.","os valores sociais do trabalho e da livre iniciativa."],"Soberania pertence à República Federativa do Brasil; União, Estados, Distrito Federal e Municípios possuem autonomia, não soberania."],
  [206,"Princípios fundamentais","Princípios fundamentais","A República Federativa do Brasil tem como forma de governo a República e constitui-se em:","Estado Democrático de Direito.",["Estado unitário de organização centralizada.","monarquia parlamentar de bases federativas.","confederação de Municípios soberanos.","Estado teocrático de religião oficial."],"O caput do art. 1º define a República Federativa do Brasil como Estado Democrático de Direito."],
  [207,"Princípios fundamentais","Relações internacionais","O princípio constitucional da defesa da paz impede que o Brasil:","participe de organizações internacionais ou celebre tratados.",["adote a solução pacífica de conflitos.","coopere com outros povos para o progresso da humanidade.","mantenha relações diplomáticas com outros Estados.","se submeta às regras constitucionais sobre declaração de guerra."],"A defesa da paz não impede relações internacionais ou tratados; ela orienta a atuação estatal junto com a solução pacífica das controvérsias."],
  [208,"Princípios fundamentais","Relações internacionais","O Brasil rege-se, em suas relações internacionais, pelo princípio da cooperação entre os povos para o progresso da humanidade. Esse princípio é compatível com:","a busca de integração latino-americana nos planos econômico, político, social e cultural.",["a recusa constitucional de celebrar qualquer acordo regional.","a substituição da Constituição por normas estrangeiras.","a eliminação da soberania nacional dos Estados latino-americanos.","a criação compulsória de uma única nacionalidade regional."],"O parágrafo único do art. 4º prevê a busca de integração latino-americana, coerente com a cooperação entre os povos."],
  [209,"Princípios fundamentais","Princípios fundamentais","O pluralismo político, como fundamento da República, é incompatível com:","a imposição de pensamento político único pelo Estado.",["a existência de partidos políticos com caráter nacional.","o exercício de direitos políticos nos termos constitucionais.","a representação popular por meio de eleições.","a liberdade de manifestação do pensamento, vedado o anonimato."],"O pluralismo político pressupõe convivência de concepções e opções políticas diversas, vedada a imposição estatal de pensamento único."],
  [210,"Princípios fundamentais","Princípios fundamentais","A cidadania, na Constituição, figura como fundamento da República e relaciona-se diretamente com:","a participação das pessoas na vida política e no exercício de direitos.",["a substituição do voto por decisões administrativas.","a restrição do sufrágio apenas a proprietários de imóveis.","a exclusão de mecanismos de participação direta.","a concentração de todo poder em órgão não eleito."],"A cidadania é fundamento republicano e sustenta a participação política, o sufrágio e mecanismos de exercício da soberania popular."],
  [211,"Organização do Estado","Competências federativas","Compete privativamente à União legislar sobre normas gerais de organização, efetivos, material bélico, garantias, convocação, mobilização, inatividades e pensões das:","polícias militares e dos corpos de bombeiros militares.",["guardas municipais, exclusivamente.","polícias civis municipais, inexistentes na Constituição.","forças de segurança privadas contratadas pelos Estados.","defensorias públicas de cada Município."],"O art. 22, XXI, reserva à União a legislação sobre normas gerais das polícias militares e corpos de bombeiros militares."],
  [212,"Organização do Estado","Competências federativas","A competência para legislar concorrentemente sobre direito tributário, financeiro, penitenciário, econômico e urbanístico pertence:","à União, aos Estados e ao Distrito Federal.",["somente à União e aos Municípios.","exclusivamente aos Estados.","apenas aos Municípios, por interesse local.","ao Poder Judiciário, mediante precedentes vinculantes."],"O art. 24, I, atribui competência concorrente à União, Estados e Distrito Federal nessas matérias; Municípios podem suplementar legislação no interesse local."],
  [213,"Organização do Estado","Competências federativas","Na competência legislativa concorrente, os Municípios podem:","suplementar a legislação federal e estadual no que couber.",["editar normas gerais federais para todos os Estados.","revogar leis estaduais por interesse local.","legislar privativamente sobre direito penal.","substituir a União na edição de normas nacionais."],"O art. 30, II, atribui aos Municípios a suplementação da legislação federal e estadual no que couber."],
  [214,"Organização do Estado","Competências federativas","A competência para instituir impostos sobre propriedade predial e territorial urbana é do:","Município.",["Estado.","Distrito Federal somente quando atuar como Estado.","Congresso Nacional, por lei complementar.","Poder Judiciário, mediante decisão administrativa."],"O IPTU é imposto municipal, nos termos do art. 156, I. O Distrito Federal acumula competências tributárias estaduais e municipais."],
  [215,"Organização do Estado","Competências federativas","Compete à União explorar, diretamente ou mediante autorização, concessão ou permissão, os serviços de telecomunicações, nos termos da lei. Trata-se de competência:","material da União.",["legislativa concorrente dos Municípios.","comum de todos os entes federativos.","residual dos Estados.","privativa das agências reguladoras, sem vínculo com a União."],"O art. 21, XI, atribui à União a exploração dos serviços de telecomunicações, diretamente ou mediante os instrumentos legais."],
  [216,"Organização do Estado","Competências federativas","Compete aos Estados explorar os serviços locais de gás canalizado. Aos Municípios, por sua vez, compete organizar e prestar os serviços públicos de interesse local. Essa divisão demonstra:","repartição constitucional de competências materiais entre entes autônomos.",["subordinação hierárquica dos Municípios aos Estados.","soberania própria de cada Município.","competência exclusiva da União sobre todos os serviços públicos.","inexistência de autonomia administrativa municipal."],"A Constituição distribui competências entre entes autônomos. A autonomia não elimina a repartição constitucional de atribuições."],
  [217,"Organização do Estado","Competências federativas","É vedado à União, aos Estados, ao Distrito Federal e aos Municípios recusar fé aos documentos públicos. Essa regra expressa:","limitação constitucional ao poder dos entes federativos.",["competência concorrente em matéria documental.","privilégio processual exclusivo da União.","faculdade administrativa sem força normativa.","norma aplicável apenas a documentos estrangeiros."],"O art. 19, II, veda aos entes federativos recusar fé aos documentos públicos."],
  [218,"Organização do Estado","Competências federativas","É vedado aos entes federativos estabelecer cultos religiosos ou igrejas, subvencioná-los, embaraçar-lhes o funcionamento ou manter com eles relações de dependência ou aliança, ressalvada:","na forma da lei, a colaboração de interesse público.",["a adoção de religião oficial em Municípios pequenos.","a fiscalização prévia de toda cerimônia religiosa.","a exigência de filiação religiosa para acesso a cargo público.","a proibição de assistência religiosa em entidades civis e militares."],"O art. 19, I, consagra a laicidade estatal e admite colaboração de interesse público, na forma da lei."],
  [219,"Organização do Estado","Competências federativas","A União, os Estados, o Distrito Federal e os Municípios não podem criar distinções entre brasileiros ou preferências entre si. A vedação protege:","a igualdade federativa e a unidade nacional.",["a possibilidade de cada Estado negar direitos a brasileiros de outros Estados.","a criação de tributos interestaduais discriminatórios por Municípios.","o tratamento privilegiado obrigatório de residentes locais.","a recusa de serviços públicos a cidadãos de outras unidades federativas."],"O art. 19, III, veda distinções entre brasileiros ou preferências entre entes federativos."],
  [220,"Organização do Estado","Organização municipal","O número de Vereadores será proporcional à população do Município, observados os limites estabelecidos na Constituição. A regra está ligada diretamente à:","organização do Poder Legislativo municipal.",["organização do Supremo Tribunal Federal.","composição obrigatória do Senado Federal.","nomeação de Ministros de Estado.","estrutura das polícias civis."],"O art. 29, IV, regula os limites de composição das Câmaras Municipais conforme a população."],
  [221,"Organização do Estado","Organização estadual","Os Governadores e Vice-Governadores de Estado e do Distrito Federal serão eleitos para mandato de:","quatro anos, na forma do art. 28.",["cinco anos, sem possibilidade de reeleição.","seis anos, mediante eleição indireta.","oito anos, com renovação parcial.","dois anos, com possibilidade de reeleição ilimitada."],"O art. 28 determina mandato de quatro anos para Governador e Vice-Governador, aplicando-se regras eleitorais pertinentes."],
  [222,"Organização do Estado","Organização estadual","O Poder Legislativo dos Estados é exercido por:","Assembleias Legislativas.",["Câmaras Estaduais de Vereadores.","Conselhos estaduais subordinados ao Executivo.","Tribunais de Contas estaduais.","Congresso Estadual bicameral obrigatório."],"Os Estados organizam-se e regem-se por Constituições e leis próprias, e seu Poder Legislativo é exercido pelas Assembleias Legislativas."],
  [223,"Organização do Estado","Intervenção","A intervenção federal nos Estados e no Distrito Federal poderá ocorrer para prover a execução de lei federal, ordem ou decisão judicial. Para tanto, deve ser observado o procedimento constitucional, não sendo correto afirmar que:","o Presidente da República pode intervir por simples conveniência política, sem hipótese constitucional.",["a Constituição prevê intervenção para assegurar execução de lei federal, ordem ou decisão judicial.","a intervenção é medida excepcional disciplinada pelo art. 34.","existem pressupostos materiais e formais para sua decretação.","a autonomia dos entes não é absoluta diante das hipóteses constitucionais."],"A intervenção é excepcional e só cabe nas hipóteses constitucionais; conveniência política isolada não a autoriza."],
  [224,"Organização do Estado","Competências federativas","A proteção de documentos, obras e outros bens de valor histórico, artístico e cultural, bem como de monumentos, paisagens naturais notáveis e sítios arqueológicos, é competência:","comum dos entes federativos.",["privativa da União.","exclusiva dos Estados.","municipal somente em cidades históricas.","do Poder Judiciário."],"O art. 23, III, estabelece competência comum para proteger o patrimônio histórico, artístico e cultural."],
  [225,"Organização do Estado","Competências federativas","Combater as causas da pobreza e os fatores de marginalização, promovendo a integração social dos setores desfavorecidos, é competência:","comum da União, dos Estados, do Distrito Federal e dos Municípios.",["privativa do Poder Executivo federal.","exclusiva das entidades privadas assistenciais.","legislativa concorrente apenas da União e dos Estados.","residual dos Municípios, sem participação estadual."],"O art. 23, X, atribui essa atuação como competência comum a todos os entes federativos."],
  [226,"Direitos e garantias fundamentais","Direitos individuais","É assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou:","à imagem.",["institucional, sem proteção individual.","eleitoral, exclusivamente.","administrativo, sem necessidade de prejuízo.","político, vedada reparação civil."],"O art. 5º, V, garante direito de resposta proporcional ao agravo e indenização por dano material, moral ou à imagem."],
  [227,"Direitos e garantias fundamentais","Direitos individuais","São invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua:","violação.",["divulgação consentida em qualquer circunstância.","utilização lícita e autorizada.","proteção constitucional regular.","manifestação de crença religiosa."],"O art. 5º, X, protege intimidade, vida privada, honra e imagem e garante indenização em caso de violação."],
  [228,"Direitos e garantias fundamentais","Direitos individuais","É livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus:","bens.",["direitos políticos automaticamente suspensos.","documentos públicos recusados pelos demais entes.","bens apenas se for brasileiro nato.","recursos somente mediante autorização judicial."],"O art. 5º, XV, assegura a liberdade de locomoção em tempo de paz, inclusive com bens, nos termos da lei."],
  [229,"Direitos e garantias fundamentais","Direitos individuais","Todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, ressalvadas aquelas cujo sigilo seja imprescindível à:","segurança da sociedade e do Estado.",["conveniência política da autoridade administrativa.","proteção de atos ilegais do Poder Público.","preservação de qualquer informação sem justificativa legal.","vantagem econômica de agentes públicos."],"O art. 5º, XXXIII, assegura acesso a informações, ressalvado o sigilo imprescindível à segurança da sociedade e do Estado."],
  [230,"Direitos e garantias fundamentais","Direitos individuais","A lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a:","direito.",["interesse político de órgão público, exclusivamente.","ato administrativo já publicado, em qualquer hipótese.","decisão judicial transitada em julgado, sem exceção.","ato legislativo abstrato sem possibilidade de controle constitucional."],"O art. 5º, XXXV, consagra a inafastabilidade da jurisdição diante de lesão ou ameaça a direito."],
  [231,"Direitos e garantias fundamentais","Direitos individuais","A lei não prejudicará o direito adquirido, o ato jurídico perfeito e a:","coisa julgada.",["orientação administrativa interna.","conveniência econômica posterior.","decisão política não formalizada.","expectativa abstrata de direito."],"O art. 5º, XXXVI, protege direito adquirido, ato jurídico perfeito e coisa julgada."],
  [232,"Direitos e garantias fundamentais","Direitos individuais","Não haverá juízo ou tribunal de exceção. Essa garantia relaciona-se ao princípio do:","juiz natural.",["sigilo absoluto dos processos.","duplo grau obrigatório em qualquer processo.","livre convencimento sem fundamentação.","poder de polícia administrativa."],"O art. 5º, XXXVII, veda juízo ou tribunal de exceção, assegurando o juiz natural e a imparcialidade jurisdicional."],
  [233,"Direitos e garantias fundamentais","Direitos individuais","É reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados, entre outros:","a plenitude de defesa, o sigilo das votações, a soberania dos veredictos e a competência para crimes dolosos contra a vida.",["a competência para qualquer infração penal, inclusive contravenções.","a eliminação do direito de defesa técnica.","a publicidade obrigatória dos votos dos jurados.","a revisão administrativa dos veredictos pelo Poder Executivo."],"O art. 5º, XXXVIII, garante essas características do júri, cuja competência mínima abrange crimes dolosos contra a vida."],
  [234,"Direitos e garantias fundamentais","Direitos individuais","A prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de:","reclusão, nos termos da lei.",["detenção simples, sem previsão legal complementar.","multa administrativa exclusiva.","prestação de serviço comunitário obrigatória como única sanção.","advertência pública sem processo criminal."],"O art. 5º, XLII, determina inafiançabilidade, imprescritibilidade e pena de reclusão para o racismo."],
  [235,"Direitos e garantias fundamentais","Direitos individuais","A Constituição estabelece que nenhuma pena pode ter caráter de:","perpétuo.",["restritivo de direitos.","multa.","perda de bens, nos casos previstos em lei.","suspensão ou interdição de direitos, nos limites legais."],"O art. 5º, XLVII, veda penas de morte salvo guerra declarada, perpétua, trabalhos forçados, banimento e cruéis. Restrições de direitos podem ser espécies de pena."],
  [236,"Direitos e garantias fundamentais","Direitos individuais","Às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de:","amamentação.",["cumprimento integral da pena, independentemente de idade.","investigação policial, sem necessidade de prisão.","medida socioeducativa aplicada aos filhos.","estágio probatório no serviço público."],"O art. 5º, L, assegura às presidiárias condições para permanecerem com seus filhos durante o período de amamentação."],
  [237,"Direitos e garantias fundamentais","Direitos individuais","O preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência:","da família e de advogado.",["apenas de autoridade policial.","somente de defensor particular contratado pela família.","de sindicato profissional, obrigatoriamente.","de representante do empregador."],"O art. 5º, LXIII, assegura direito ao silêncio e assistência da família e de advogado ao preso."],
  [238,"Direitos e garantias fundamentais","Direitos individuais","Ninguém será levado à prisão ou nela mantido quando a lei admitir:","a liberdade provisória, com ou sem fiança.",["a prisão administrativa por dívida civil.","a suspensão indefinida do processo sem decisão judicial.","a execução de pena sem processo legal.","a custódia obrigatória por simples suspeita."],"O art. 5º, LXVI, assegura liberdade provisória, com ou sem fiança, quando a lei a admitir."],
  [239,"Direitos e garantias fundamentais","Direitos individuais","O Estado prestará assistência jurídica integral e gratuita aos que comprovarem:","insuficiência de recursos.",["filiação partidária regular.","domicílio na capital federal.","condição de servidor público efetivo.","interesse exclusivamente eleitoral."],"O art. 5º, LXXIV, impõe ao Estado assistência jurídica integral e gratuita a quem comprovar insuficiência de recursos."],
  [240,"Direitos e garantias fundamentais","Direitos individuais","O Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na:","sentença.",["denúncia do Ministério Público.","portaria da autoridade policial.","decisão administrativa de custódia.","investigação preliminar."],"O art. 5º, LXXV, prevê indenização por erro judiciário e por prisão além do tempo fixado na sentença."],
  [241,"Segurança pública","Segurança pública","A Polícia Federal destina-se, entre outras atribuições, a apurar infrações penais contra a ordem política e social ou em detrimento de bens, serviços e interesses da:","União ou de suas entidades autárquicas e empresas públicas.",["administração municipal, exclusivamente.","iniciativa privada, em qualquer circunstância.","Justiça estadual, como regra geral.","polícia militar, por ato administrativo."],"O art. 144, § 1º, I, trata da apuração de infrações contra ordem política e social ou em detrimento de bens, serviços e interesses da União, autarquias e empresas públicas federais."],
  [242,"Segurança pública","Segurança pública","Incumbe à Polícia Federal prevenir e reprimir o tráfico ilícito de entorpecentes e drogas afins, o contrabando e o descaminho, sem prejuízo da ação:","fazendária e de outros órgãos públicos nas respectivas áreas de competência.",["exclusiva dos Municípios, que substitui a atuação federal.","somente das polícias civis, vedada atuação federal.","dos particulares, sem participação de órgãos públicos.","do Poder Judiciário, sem investigação policial."],"O art. 144, § 1º, II, atribui essa atividade à PF, sem prejuízo da atuação fazendária e de outros órgãos públicos competentes."],
  [243,"Segurança pública","Segurança pública","A investigação criminal conduzida pela polícia civil não alcança, em regra, infrações:","penais militares.",["contra o patrimônio privado.","contra a fé pública.","contra a administração pública estadual.","de menor potencial ofensivo."],"O art. 144, § 4º, reserva às polícias civis a apuração de infrações penais, excetuadas as militares."],
  [244,"Segurança pública","Segurança pública","A Constituição prevê que lei disciplinará a organização e o funcionamento dos órgãos responsáveis pela segurança pública, de maneira a garantir:","a eficiência de suas atividades.",["a eliminação do controle judicial sobre atos policiais.","a centralização obrigatória de todas as polícias na União.","a substituição das polícias por empresas privadas.","a suspensão de direitos fundamentais em operações ordinárias."],"O art. 144, § 7º, determina que a lei discipline organização e funcionamento dos órgãos de segurança pública para garantir eficiência."],
  [245,"Segurança pública","Segurança pública","A remuneração dos servidores policiais integrantes dos órgãos de segurança pública será fixada na forma do art. 39, § 4º. O dispositivo constitucional busca adotar, quando aplicável, o regime de:","subsídio.",["comissão por produtividade sem limite legal.","pagamento secreto fora do orçamento.","remuneração negociada individualmente.","gratificação automática por tempo de serviço."],"O art. 144, § 9º, remete ao art. 39, § 4º, que disciplina o subsídio em parcela única para as carreiras por ele abrangidas."],
  [246,"Segurança pública","Segurança pública","A segurança viária, exercida para preservação da ordem pública e da incolumidade das pessoas e de seu patrimônio nas vias públicas, compreende:","educação, engenharia e fiscalização de trânsito, além de outras atividades previstas em lei.",["apenas aplicação de multas administrativas.","somente investigação criminal posterior a acidentes.","exclusivamente policiamento rodoviário federal.","atividade privada sem fiscalização pública."],"O art. 144, § 10, define segurança viária e menciona educação, engenharia e fiscalização de trânsito, além de outras atividades legais."],
  [247,"Segurança pública","Segurança pública","Os Municípios podem constituir guardas municipais destinadas à proteção de seus bens, serviços e instalações. Essa previsão não lhes confere, por si só:","o exercício exclusivo de polícia judiciária estadual.",["competência para organizar sua própria guarda nos limites legais.","dever de proteger patrimônio municipal.","possibilidade de atuação nos limites da legislação aplicável.","natureza de instituição voltada à proteção municipal."],"O art. 144, § 8º, define a finalidade das guardas municipais, sem transferir a elas a polícia judiciária estadual."],
  [248,"Segurança pública","Segurança pública","As polícias penais federal, estaduais e distrital são órgãos de segurança pública. Seus integrantes são admitidos por meio de:","concurso público e vinculados ao órgão administrador do sistema penal.",["nomeação política livre, sem concurso.","eleição direta pelos internos dos estabelecimentos penais.","contratação terceirizada obrigatória por empresas privadas.","indicação exclusiva do Poder Judiciário."],"O art. 144, § 5º-A, prevê as polícias penais e estabelece que seus integrantes são admitidos por concurso público, vinculando-as ao órgão administrador do sistema penal."],
  [249,"Segurança pública","Segurança pública","A proteção de pessoas e do patrimônio integra a finalidade constitucional da segurança pública. Essa finalidade não autoriza:","a prática de tortura ou tratamento desumano ou degradante.",["a atuação dos órgãos policiais dentro de suas competências.","a investigação de infrações penais nos termos legais.","o patrulhamento ostensivo atribuído às polícias militares.","a execução de atividades de defesa civil pelos corpos de bombeiros."],"A finalidade de segurança pública deve ser exercida sob a Constituição, que veda tortura e tratamento desumano ou degradante no art. 5º, III."],
  [250,"Segurança pública","Segurança pública","A arquitetura constitucional da segurança pública distribui funções entre órgãos diversos. Assinale a associação correta:","Polícia Militar: polícia ostensiva e preservação da ordem pública.",["Polícia Civil: patrulhamento ostensivo de rodovias federais.","Polícia Rodoviária Federal: polícia judiciária da União.","Corpo de Bombeiros Militar: apuração de crimes comuns.","Guarda Municipal: investigação exclusiva de crimes federais."],"O art. 144 atribui às polícias militares a polícia ostensiva e preservação da ordem pública. As demais associações trocam atribuições constitucionais." ]
];
const direitoConstitucionalLoteQuatroComResposta = direitoConstitucionalLoteQuatro.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 201) % 5];
  return {id:`direito-constitucional-${String(number).padStart(3,"0")}`,subjectId:"direito-constitucional",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoConstitucionalLoteQuatroComResposta);
questionBank.review.direitoConstitucionalLoteQuatroReviewed = direitoConstitucionalLoteQuatroComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Constitucional — lote 3 (151–200): organização federativa e Administração Pública na Constituição.
const direitoConstitucionalLoteTres = [
  [151,"Organização do Estado","Competências federativas","É competência privativa da União:","manter relações com Estados estrangeiros e participar de organizações internacionais.",["instituir e arrecadar tributos de competência municipal.","legislar sobre interesse local, de forma exclusiva.","organizar e prestar diretamente todos os serviços públicos municipais.","criar Municípios por ato administrativo federal."],"O art. 21, I, atribui à União a manutenção de relações com Estados estrangeiros e a participação em organizações internacionais."],
  [152,"Organização do Estado","Competências federativas","Compete à União declarar a guerra e celebrar a paz, observadas as condições previstas na Constituição. Essa atribuição é classificada como:","competência material da União.",["competência legislativa concorrente dos Estados.","competência comum de todos os entes federativos.","competência privativa dos Municípios.","atribuição exclusiva do Poder Judiciário."],"A declaração de guerra e a celebração da paz constam do art. 21, II, entre as competências materiais da União."],
  [153,"Organização do Estado","Competências federativas","É competência comum da União, dos Estados, do Distrito Federal e dos Municípios:","proteger o meio ambiente e combater a poluição em qualquer de suas formas.",["legislar privativamente sobre direito processual penal.","emitir moeda e administrar as reservas cambiais.","declarar guerra e celebrar a paz.","manter o serviço postal nacional."],"O art. 23, VI, prevê competência comum para proteção do meio ambiente e combate à poluição."],
  [154,"Organização do Estado","Competências federativas","No âmbito da competência concorrente, inexistindo lei federal sobre normas gerais, os Estados exercerão:","competência legislativa plena, para atender a suas peculiaridades.",["competência meramente administrativa, sem poder normativo.","competência delegada pelos Municípios, mediante convênio.","competência exclusiva para revogar a Constituição Federal.","competência subsidiária que depende de autorização judicial."],"Pelo art. 24, § 3º, a inexistência de lei federal sobre normas gerais autoriza os Estados a exercer competência legislativa plena para atender a peculiaridades locais."],
  [155,"Organização do Estado","Competências federativas","A superveniência de lei federal sobre normas gerais, em matéria de competência concorrente:","suspende a eficácia da lei estadual no que lhe for contrário.",["revoga integralmente toda a legislação estadual anterior.","não produz qualquer efeito sobre normas estaduais.","transforma automaticamente a lei estadual em lei municipal.","exige nova aprovação pelo Poder Legislativo estadual para ter validade."],"O art. 24, § 4º, estabelece que a superveniência de lei federal sobre normas gerais suspende a eficácia da lei estadual no que lhe for contrário."],
  [156,"Organização do Estado","Competências federativas","Compete aos Municípios organizar e prestar, diretamente ou sob regime de concessão ou permissão, os serviços públicos de:","interesse local, incluído o transporte coletivo, que tem caráter essencial.",["segurança nacional e defesa das fronteiras.","emissão de moeda e política cambial.","polícia judiciária e investigação criminal.","declaração de guerra e paz."],"O art. 30, V, atribui aos Municípios a organização e prestação de serviços públicos de interesse local, incluindo transporte coletivo."],
  [157,"Organização do Estado","Competências federativas","A fiscalização do Município será exercida pelo Poder Legislativo municipal, mediante controle externo, e pelos sistemas de controle interno do:","Poder Executivo municipal, na forma da lei.",["Poder Judiciário estadual, com exclusividade.","Ministério Público municipal, como órgão integrante da Câmara.","Tribunal de Contas da União, em todos os assuntos locais.","Presidente da República, por delegação constitucional."],"O art. 31 prevê fiscalização municipal pelo Legislativo local, mediante controle externo, e pelos sistemas de controle interno do Executivo municipal."],
  [158,"Organização do Estado","Competências federativas","O controle externo da Câmara Municipal será exercido com auxílio dos:","Tribunais de Contas dos Estados ou do Município ou dos Conselhos ou Tribunais de Contas dos Municípios, onde houver.",["Ministérios Públicos estaduais, sem participação de órgãos de contas.","juízes eleitorais da respectiva circunscrição.","conselhos comunitários formados por eleitores.","órgãos da União, necessariamente."],"O art. 31, § 1º, prevê o auxílio dos Tribunais de Contas dos Estados ou do Município, ou dos Conselhos ou Tribunais de Contas dos Municípios, onde existirem."],
  [159,"Organização do Estado","Competências federativas","As contas dos Municípios ficarão, durante sessenta dias, anualmente, à disposição de qualquer contribuinte para exame e apreciação, podendo este:","questionar-lhes a legitimidade, nos termos da lei.",["anular diretamente atos da Prefeitura por decisão particular.","substituir a Câmara Municipal no julgamento das contas.","exigir sigilo integral dos documentos contábeis.","aplicar sanção administrativa ao Prefeito."],"O art. 31, § 3º, assegura exame, apreciação e questionamento da legitimidade das contas pelo contribuinte, na forma da lei."],
  [160,"Organização do Estado","Competências federativas","A União não intervirá nos Estados nem no Distrito Federal, exceto para:","manter a integridade nacional, entre outras hipóteses constitucionais.",["alterar livremente a Constituição estadual por decreto.","substituir o governador sempre que houver divergência política.","assumir a arrecadação tributária estadual por conveniência administrativa.","regular a organização interna de qualquer Município sem previsão legal."],"O art. 34 enumera hipóteses taxativas de intervenção federal, incluindo manutenção da integridade nacional."],
  [161,"Organização do Estado","Competências federativas","A intervenção do Estado em seus Municípios poderá ocorrer quando deixar de ser paga, sem motivo de força maior, por dois anos consecutivos, a dívida fundada. Trata-se de hipótese prevista no:","art. 35 da Constituição.",["art. 5º, como direito individual.","art. 21, como competência da União.","art. 37, como princípio administrativo.","art. 144, como regra de segurança pública."],"O art. 35, I, admite intervenção estadual no Município nessa hipótese específica de inadimplemento da dívida fundada."],
  [162,"Organização do Estado","Competências federativas","A lei orgânica municipal será votada em dois turnos, com interstício mínimo de dez dias, e aprovada por:","dois terços dos membros da Câmara Municipal.",["maioria simples dos eleitores do Município.","maioria absoluta da população em plebiscito obrigatório.","três quintos do Congresso Nacional.","unanimidade dos Vereadores presentes."],"O art. 29 exige dois turnos, interstício mínimo de dez dias e aprovação por dois terços dos membros da Câmara para a lei orgânica municipal."],
  [163,"Organização do Estado","Competências federativas","Os Estados podem instituir regiões metropolitanas, aglomerações urbanas e microrregiões, mediante:","lei complementar estadual, para integrar organização, planejamento e execução de funções públicas de interesse comum.",["decreto do governador, dispensada participação legislativa.","lei federal ordinária, por se tratar de matéria urbana.","lei municipal aprovada por cada Câmara isoladamente.","emenda à Constituição Federal para cada nova região."],"O art. 25, § 3º, autoriza os Estados, por lei complementar, a instituir essas estruturas para funções públicas de interesse comum."],
  [164,"Organização do Estado","Competências federativas","Os Estados podem explorar diretamente, ou mediante concessão, os serviços locais de gás canalizado, na forma da lei, sendo vedada:","a edição de medida provisória para sua regulamentação.",["a prestação direta do serviço pelo próprio Estado.","a concessão do serviço mediante procedimento legal.","a edição de lei estadual sobre o tema.","a fiscalização estatal da atividade concedida."],"O art. 25, § 2º, atribui aos Estados essa exploração e veda a edição de medida provisória para regulamentá-la."],
  [165,"Organização do Estado","Competências federativas","A repartição constitucional de competências busca conciliar autonomia dos entes federativos e unidade nacional. Nesse modelo, cabe aos Estados, em regra:","exercer competências remanescentes, desde que não lhes sejam vedadas pela Constituição.",["editar normas penais gerais em substituição à União.","declarar guerra contra Estado estrangeiro.","emitir moeda própria para circulação regional.","subordinar Municípios a suas secretarias como órgãos sem autonomia."],"A competência residual dos Estados deriva do art. 25, § 1º. Autonomia municipal e competências da União impedem as demais conclusões."],
  [166,"Administração Pública na Constituição","Princípios administrativos","A administração pública direta e indireta de qualquer dos Poderes da União, Estados, Distrito Federal e Municípios obedecerá aos princípios de:","legalidade, impessoalidade, moralidade, publicidade e eficiência.",["hierarquia, supremacia privada, informalidade, sigilo e eficiência.","legalidade, pessoalidade, conveniência, publicidade e economicidade.","moralidade, discricionariedade, segredo, eficiência e subordinação.","publicidade, informalidade, favorecimento e eficiência."],"O caput do art. 37 reúne os princípios conhecidos pela sigla LIMPE: legalidade, impessoalidade, moralidade, publicidade e eficiência."],
  [167,"Administração Pública na Constituição","Acesso a cargos públicos","A investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, ressalvadas:","as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração.",["as contratações permanentes por decisão da autoridade administrativa.","as funções de confiança exercidas por qualquer pessoa sem vínculo público.","as indicações de parentes de agentes públicos para cargos efetivos.","as admissões por contrato verbal em situação ordinária."],"O art. 37, II, exige concurso para cargos e empregos, excetuando os cargos em comissão legalmente declarados de livre nomeação e exoneração."],
  [168,"Administração Pública na Constituição","Acesso a cargos públicos","As funções de confiança serão exercidas exclusivamente por:","servidores ocupantes de cargo efetivo.",["particulares escolhidos livremente pela autoridade competente.","empregados de empresas privadas contratadas pelo Poder Público.","agentes políticos sem vínculo com a administração.","quaisquer candidatos aprovados em seleção simplificada."],"O art. 37, V, reserva as funções de confiança exclusivamente a servidores ocupantes de cargo efetivo."],
  [169,"Administração Pública na Constituição","Acesso a cargos públicos","Os cargos em comissão devem ser destinados apenas às atribuições de:","direção, chefia e assessoramento.",["execução rotineira de atividades permanentes.","polícia ostensiva e investigação criminal.","jurisdição e julgamento de processos.","fiscalização tributária sem subordinação hierárquica."],"O art. 37, V, limita cargos em comissão às atribuições de direção, chefia e assessoramento."],
  [170,"Administração Pública na Constituição","Concurso público","O prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por:","igual período.",["prazo indeterminado, enquanto houver candidatos aprovados.","seis meses, em qualquer hipótese.","período fixado livremente por ato administrativo sem limite.","quatro anos, vedada prorrogação."],"O art. 37, III, fixa validade de até dois anos, prorrogável uma vez por igual período."],
  [171,"Administração Pública na Constituição","Concurso público","Durante o prazo improrrogável previsto no edital de convocação, o aprovado em concurso público será convocado com prioridade sobre novos concursados para assumir:","cargo ou emprego na carreira.",["qualquer função de confiança existente no órgão.","cargo político eletivo vago.","mandato representativo municipal.","atividade terceirizada de natureza privada."],"O art. 37, IV, garante prioridade ao aprovado durante o prazo improrrogável previsto no edital para assumir cargo ou emprego na carreira."],
  [172,"Administração Pública na Constituição","Remuneração","A remuneração dos servidores públicos e o subsídio de que trata a Constituição somente poderão ser fixados ou alterados por:","lei específica, observada a iniciativa privativa em cada caso.",["decreto do chefe do Poder Executivo.","portaria do órgão de recursos humanos.","acordo individual entre servidor e administrador.","resolução interna sem publicação oficial."],"O art. 37, X, exige lei específica para fixação ou alteração de remuneração e subsídio, observada a iniciativa competente."],
  [173,"Administração Pública na Constituição","Remuneração","A remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos não podem exceder o subsídio mensal, em espécie, dos Ministros do:","Supremo Tribunal Federal.",["Superior Tribunal de Justiça.","Tribunal de Contas da União.","Congresso Nacional.","Conselho Nacional de Justiça."],"O art. 37, XI, estabelece como teto geral o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal."],
  [174,"Administração Pública na Constituição","Acumulação de cargos","É vedada a acumulação remunerada de cargos públicos, exceto, havendo compatibilidade de horários, a de:","dois cargos de professor.",["três cargos técnicos ou científicos.","cargo de magistrado e cargo de delegado de polícia.","cargo de prefeito e cargo de governador.","dois cargos privativos de advogado público."],"O art. 37, XVI, admite, com compatibilidade de horários, dois cargos de professor, professor com técnico/científico ou dois cargos privativos de profissionais de saúde com profissões regulamentadas."],
  [175,"Administração Pública na Constituição","Acumulação de cargos","Com compatibilidade de horários, a Constituição admite a acumulação de:","um cargo de professor com outro técnico ou científico.",["dois cargos de juiz de direito.","um cargo policial com outro cargo policial, sem qualquer condição.","três empregos públicos de profissionais de saúde.","um mandato eletivo com qualquer cargo efetivo, sem regras constitucionais."],"O art. 37, XVI, b, prevê a acumulação de um cargo de professor com outro técnico ou científico, desde que haja compatibilidade de horários."],
  [176,"Administração Pública na Constituição","Responsabilidade civil do Estado","As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado:","o direito de regresso contra o responsável nos casos de dolo ou culpa.",["o afastamento total de responsabilidade estatal em qualquer situação.","regresso automático mesmo sem dolo ou culpa do agente.","responsabilidade exclusiva e direta do agente, sem participação da entidade.","indenização somente após condenação criminal definitiva."],"O art. 37, § 6º, estabelece responsabilidade objetiva da entidade perante o terceiro e direito de regresso contra o agente se houver dolo ou culpa."],
  [177,"Administração Pública na Constituição","Improbidade e moralidade","Os atos de improbidade administrativa importarão, na forma e gradação previstas em lei, entre outras consequências:","suspensão dos direitos políticos, perda da função pública e indisponibilidade dos bens.",["pena de morte e perda automática da nacionalidade.","apenas advertência administrativa, sem repercussão patrimonial.","prisão perpétua e cassação de direitos fundamentais.","perda do cargo eletivo sem necessidade de processo."],"O art. 37, § 4º, prevê sanções como suspensão de direitos políticos, perda da função, indisponibilidade dos bens e ressarcimento ao erário, na forma legal."],
  [178,"Administração Pública na Constituição","Publicidade e controle","A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar:","nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.",["informações sobre o objeto, custo ou finalidade da política pública.","identificação institucional do órgão responsável pela campanha.","dados necessários à prestação de contas da administração.","orientações sociais dirigidas à população."],"O art. 37, § 1º, veda propaganda oficial com promoção pessoal de autoridades ou servidores."],
  [179,"Administração Pública na Constituição","Acesso à informação","A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:","as reclamações relativas à prestação dos serviços públicos em geral.",["a substituição de concursos por indicação pessoal.","o sigilo absoluto de informações administrativas.","a exclusão do usuário de qualquer avaliação de qualidade.","a transferência da função de controle interno ao particular."],"O art. 37, § 3º, prevê participação do usuário, inclusive reclamações sobre serviços, acesso a registros e representação contra exercício negligente ou abusivo."],
  [180,"Administração Pública na Constituição","Controle e responsabilidade","A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas:","as respectivas ações de ressarcimento.",["as ações penais, que se tornam sempre imprescritíveis.","as sanções administrativas, que nunca podem prescrever.","as ações eleitorais, que dependem de decisão administrativa.","as cobranças privadas sem relação com o erário."],"O art. 37, § 5º, prevê prescrição para ilícitos que causem prejuízo ao erário, ressalvando as ações de ressarcimento."],
  [181,"Administração Pública na Constituição","Planejamento de pessoal","A União, os Estados, o Distrito Federal e os Municípios instituirão conselho de política de administração e remuneração de pessoal, integrado por servidores designados pelos respectivos Poderes. Esse conselho é previsto no art.:","39 da Constituição.",["5º da Constituição.","21 da Constituição.","37, exclusivamente para concursos públicos.","144, para segurança pública."],"O art. 39, caput, prevê o conselho de política de administração e remuneração de pessoal em cada ente federativo."],
  [182,"Administração Pública na Constituição","Servidores públicos","A União, os Estados, o Distrito Federal e os Municípios manterão escolas de governo para a formação e o aperfeiçoamento dos servidores públicos, constituindo-se a participação em cursos requisito para:","a promoção na carreira, facultada a celebração de convênios ou contratos entre os entes federados.",["a aquisição imediata de estabilidade no cargo.","a dispensa de concurso público para novo cargo efetivo.","a vitaliciedade de todo servidor público.","a substituição de avaliação periódica de desempenho."],"O art. 39, § 2º, prevê escolas de governo e estabelece participação em cursos como requisito para promoção na carreira, admitindo convênios."],
  [183,"Administração Pública na Constituição","Servidores públicos","Ao servidor público da administração direta, autárquica e fundacional, no exercício de mandato eletivo, aplicam-se regras constitucionais. Tratando-se de mandato eletivo federal, estadual ou distrital, ficará:","afastado de seu cargo, emprego ou função.",["obrigado a acumular integralmente o mandato e a jornada ordinária.","exonerado definitivamente do cargo efetivo.","impedido de receber qualquer remuneração do mandato.","subordinado ao governador do Estado, independentemente do mandato."],"O art. 38, I, determina afastamento do servidor investido em mandato eletivo federal, estadual ou distrital."],
  [184,"Administração Pública na Constituição","Servidores públicos","Investido no mandato de Prefeito, o servidor público será:","afastado do cargo, emprego ou função, sendo-lhe facultado optar pela remuneração.",["mantido obrigatoriamente no cargo efetivo, com dupla jornada.","exonerado do cargo efetivo e impedido de retornar ao serviço público.","obrigado a receber apenas a remuneração do cargo efetivo.","transferido automaticamente para outro Município."],"O art. 38, II, determina afastamento do servidor investido no mandato de Prefeito, facultando-lhe optar pela remuneração."],
  [185,"Administração Pública na Constituição","Servidores públicos","Em caso de mandato eletivo de Vereador, havendo compatibilidade de horários, o servidor público:","perceberá as vantagens de seu cargo, emprego ou função, sem prejuízo da remuneração do cargo eletivo.",["deverá afastar-se obrigatoriamente, sem direito a escolher remuneração.","será exonerado do cargo efetivo após a diplomação.","não poderá receber remuneração referente ao mandato.","perderá o tempo de serviço para todos os efeitos legais."],"O art. 38, III, a, assegura a acumulação remunerada quando houver compatibilidade de horários; sem compatibilidade, aplica-se o afastamento com opção remuneratória."],
  [186,"Administração Pública na Constituição","Estabilidade","São estáveis, após três anos de efetivo exercício, os servidores nomeados para cargo de provimento efetivo em virtude de:","concurso público.",["processo seletivo simplificado temporário.","nomeação para cargo em comissão.","contrato de prestação de serviço terceirizado.","eleição para mandato político."],"O art. 41 assegura estabilidade após três anos de efetivo exercício aos nomeados para cargo efetivo em virtude de concurso público."],
  [187,"Administração Pública na Constituição","Estabilidade","O servidor público estável só perderá o cargo em virtude de sentença judicial transitada em julgado, processo administrativo disciplinar com ampla defesa ou:","procedimento de avaliação periódica de desempenho, na forma de lei complementar, assegurada ampla defesa.",["decisão verbal da chefia imediata, por conveniência administrativa.","mudança de governo após eleição majoritária.","redução de jornada sem prévia lei.","resultado desfavorável em pesquisa de opinião realizada pelo órgão."],"O art. 41, § 1º, admite perda do cargo nas hipóteses constitucionais, inclusive avaliação periódica de desempenho regulamentada por lei complementar e com ampla defesa."],
  [188,"Administração Pública na Constituição","Estabilidade","Invalidada por sentença judicial a demissão de servidor estável, será ele:","reintegrado, e o eventual ocupante da vaga será reconduzido ao cargo de origem, aproveitado em outro cargo ou posto em disponibilidade.",["readmitido apenas se houver nova aprovação em concurso.","indenizado sem possibilidade de retorno ao cargo.","automaticamente aposentado com proventos proporcionais.","substituído definitivamente pelo atual ocupante, sem outra consequência."],"O art. 41, § 2º, prevê reintegração do estável e disciplina a situação do eventual ocupante da vaga."],
  [189,"Administração Pública na Constituição","Estabilidade","Extinto o cargo ou declarada sua desnecessidade, o servidor estável ficará:","em disponibilidade, com remuneração proporcional ao tempo de serviço, até seu adequado aproveitamento em outro cargo.",["exonerado sem qualquer direito remuneratório.","obrigado a prestar serviço voluntário até surgir vaga.","automaticamente transferido para emprego privado.","aposentado compulsoriamente, sem possibilidade de retorno."],"O art. 41, § 3º, prevê disponibilidade com remuneração proporcional até o adequado aproveitamento em outro cargo."],
  [190,"Administração Pública na Constituição","Estabilidade","Como condição para aquisição da estabilidade, é obrigatória a avaliação especial de desempenho por comissão instituída para:","essa finalidade.",["substituir a autoridade competente em todos os processos administrativos.","realizar julgamento eleitoral dos servidores.","aplicar sanções penais aos agentes públicos.","fiscalizar exclusivamente contratos administrativos."],"O art. 41, § 4º, exige avaliação especial de desempenho por comissão instituída para essa finalidade."],
  [191,"Administração Pública na Constituição","Regime previdenciário","O regime próprio de previdência social dos servidores titulares de cargos efetivos terá caráter contributivo e solidário, mediante contribuição do respectivo ente público, de servidores ativos, aposentados e pensionistas, observados critérios que preservem:","o equilíbrio financeiro e atuarial.",["a ausência total de contribuição dos aposentados em qualquer hipótese.","a livre escolha individual do valor do benefício sem base legal.","a equiparação automática com qualquer plano privado.","a substituição integral do regime geral sem lei."],"O art. 40 estrutura o regime próprio com caráter contributivo e solidário e exige equilíbrio financeiro e atuarial."],
  [192,"Administração Pública na Constituição","Servidores públicos","É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 com remuneração de cargo, emprego ou função pública, ressalvados, entre outros:","os cargos acumuláveis na forma da Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração.",["qualquer emprego temporário, independentemente de previsão constitucional.","toda função exercida em empresa privada contratada pelo Estado.","somente os cargos privativos de brasileiro nato.","qualquer cargo policial, sem compatibilidade de horários."],"O art. 37, § 10, traz a vedação e as ressalvas relativas a cargos acumuláveis, eletivos e em comissão de livre nomeação e exoneração."],
  [193,"Administração Pública na Constituição","Servidores públicos","A administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma:","da lei.",["de regulamento secreto expedido pelo Poder Executivo.","de decisão individual do chefe de repartição.","de decreto municipal aplicável obrigatoriamente a todos os entes.","de acordo coletivo entre servidores e contribuintes."],"O art. 37, XVIII, confere essa precedência à administração fazendária e seus servidores fiscais, na forma da lei."],
  [194,"Administração Pública na Constituição","Servidores públicos","A administração tributária da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, será exercida por servidores de:","carreiras específicas.",["livre nomeação e exoneração, sem necessidade de carreira.","contratação temporária para funções permanentes.","mandato eletivo, com alternância bienal.","empresas privadas sem fiscalização estatal."],"O art. 37, XXII, afirma que as administrações tributárias são atividades essenciais e serão exercidas por servidores de carreiras específicas."],
  [195,"Administração Pública na Constituição","Servidores públicos","A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato a ser firmado entre seus administradores e o Poder Público, com fixação de metas de:","desempenho.",["lucro privado obrigatório.","substituição do controle externo.","eliminação da prestação de contas.","supressão do concurso público."],"O art. 37, § 8º, admite ampliação de autonomia por contrato de gestão, com metas de desempenho e controles previstos em lei."],
  [196,"Administração Pública na Constituição","Servidores públicos","A lei reservará percentual dos cargos e empregos públicos para as pessoas com deficiência e definirá os critérios de sua:","admissão.",["exoneração automática após o estágio probatório.","remuneração diferenciada em qualquer hipótese.","dispensa de concurso para cargo efetivo.","substituição por terceirizados."],"O art. 37, VIII, determina reserva percentual e definição legal dos critérios de admissão de pessoas com deficiência."],
  [197,"Administração Pública na Constituição","Contratação temporária","A lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de:","excepcional interesse público.",["atividade permanente e ordinária sem concurso.","substituição de todo quadro efetivo do órgão.","nomeação política em período eleitoral.","qualquer demanda empresarial de empresa estatal."],"O art. 37, IX, admite contratação temporária apenas nos casos previstos em lei para necessidade temporária de excepcional interesse público."],
  [198,"Administração Pública na Constituição","Controle e responsabilidade","Os atos de improbidade administrativa poderão gerar, na forma legal, ressarcimento ao erário. Essa responsabilização ocorre sem prejuízo da:","ação penal cabível.",["impossibilidade de qualquer outra sanção jurídica.","dispensa de processo e de contraditório.","extinção automática da responsabilidade civil.","necessidade de condenação política pelo Congresso Nacional."],"O art. 37, § 4º, dispõe que as sanções por improbidade ocorrem sem prejuízo da ação penal cabível."],
  [199,"Administração Pública na Constituição","Princípios administrativos","O princípio da impessoalidade impede que a atuação administrativa seja orientada por favorecimentos pessoais. Uma consequência constitucional direta é a vedação de:","promoção pessoal de autoridades ou servidores em publicidade oficial.",["publicação de atos administrativos no órgão oficial.","realização de concursos públicos de provas e títulos.","prestação de informações de interesse coletivo.","controle judicial de atos administrativos."],"A vedação de promoção pessoal em publicidade oficial, prevista no art. 37, § 1º, concretiza especialmente a impessoalidade."],
  [200,"Administração Pública na Constituição","Princípios administrativos","A exigência de que os atos administrativos sejam divulgados para possibilitar conhecimento e controle social corresponde, em regra, ao princípio da:","publicidade.",["pessoalidade.","supremacia privada.","irrevogabilidade.","sigilo administrativo absoluto."],"A publicidade é princípio expresso no caput do art. 37 e favorece transparência e controle, ressalvadas hipóteses legais de sigilo." ]
];
const direitoConstitucionalLoteTresComResposta = direitoConstitucionalLoteTres.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 151) % 5];
  return {id:`direito-constitucional-${String(number).padStart(3,"0")}`,subjectId:"direito-constitucional",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoConstitucionalLoteTresComResposta);
questionBank.review.direitoConstitucionalLoteTresReviewed = direitoConstitucionalLoteTresComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Constitucional — lote 2 (101–150): direitos e garantias fundamentais.
const direitoConstitucionalLoteDois = [
  [101,"Direitos e garantias fundamentais","Direitos individuais","A Constituição assegura a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, garantindo-se aos brasileiros e aos estrangeiros residentes no País:","a proteção desses direitos nos termos do art. 5º.",["a aplicação desses direitos somente após regulamentação por lei complementar.","a proteção apenas quando o titular for brasileiro nato.","a prevalência automática da propriedade sobre todos os demais direitos.","a suspensão desses direitos por ato administrativo motivado."],"O caput do art. 5º assegura esses direitos a brasileiros e estrangeiros residentes, sem exigir lei complementar para sua eficácia geral."],
  [102,"Direitos e garantias fundamentais","Direitos individuais","Pelo princípio da legalidade, ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de:","lei.",["decreto autônomo do Poder Executivo.","regulamento interno de órgão público.","orientação administrativa divulgada ao cidadão.","decisão de autoridade policial sem controle judicial."],"O art. 5º, II, consagra a reserva legal: obrigações e proibições dirigidas ao particular exigem fundamento em lei."],
  [103,"Direitos e garantias fundamentais","Direitos individuais","A Constituição veda a submissão de qualquer pessoa a:","tortura ou tratamento desumano ou degradante.",["identificação civil em qualquer hipótese legalmente prevista.","prisão em flagrante delito.","restrição de liberdade decorrente de sentença transitada em julgado.","busca domiciliar durante o dia com ordem judicial."],"O art. 5º, III, traz vedação absoluta à tortura e ao tratamento desumano ou degradante. As demais medidas podem ser constitucionais se observados seus requisitos."],
  [104,"Direitos e garantias fundamentais","Direitos individuais","É livre a manifestação do pensamento, sendo:","vedado o anonimato.",["necessária autorização estatal prévia para opiniões políticas.","permitida a ocultação de autoria em meios digitais.","exigido registro administrativo para críticas a agentes públicos.","proibida qualquer responsabilização civil posterior."],"O art. 5º, IV, assegura liberdade de manifestação do pensamento, mas veda o anonimato; abusos podem gerar responsabilização posterior."],
  [105,"Direitos e garantias fundamentais","Direitos individuais","A liberdade de consciência e de crença assegura o livre exercício dos cultos religiosos e garante, na forma da lei:","a proteção aos locais de culto e a suas liturgias.",["a instituição de religião oficial pela União.","a imposição de participação em cerimônia religiosa pública.","a dispensa de toda obrigação legal por motivo de crença.","a censura prévia de manifestações de natureza religiosa."],"O art. 5º, VI, protege consciência, crença, cultos, locais de culto e liturgias. O Estado brasileiro é laico e não pode impor religião."],
  [106,"Direitos e garantias fundamentais","Direitos individuais","A casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo, entre outras hipóteses:","durante o dia, por determinação judicial.",["a qualquer hora, por ordem verbal de autoridade administrativa.","durante a noite, por mandado judicial ordinário.","somente em caso de condenação penal definitiva do morador.","apenas quando houver autorização do Ministério Público."],"O art. 5º, XI, admite ingresso sem consentimento em flagrante delito, desastre, prestação de socorro ou, durante o dia, por determinação judicial."],
  [107,"Direitos e garantias fundamentais","Direitos individuais","É inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e telefônicas, salvo, no último caso:","por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal.",["por requisição de qualquer autoridade administrativa, em processo disciplinar.","por decisão unilateral da autoridade policial, quando houver suspeita fundada.","por autorização da vítima de outro crime, independentemente de ordem judicial.","por ato do Ministério Público, sem controle jurisdicional."],"O art. 5º, XII, prevê exceção expressa para comunicações telefônicas, mediante ordem judicial e finalidade legal ligada à investigação criminal ou instrução penal."],
  [108,"Direitos e garantias fundamentais","Direitos individuais","É assegurado a todos o acesso à informação, resguardado o sigilo da fonte quando:","necessário ao exercício profissional.",["a fonte exigir anonimato absoluto em qualquer atividade.","houver interesse econômico do veículo de comunicação.","a informação envolver exclusivamente agente público.","o comunicador não possuir registro profissional."],"O art. 5º, XIV, garante acesso à informação e resguarda o sigilo da fonte quando necessário ao exercício profissional."],
  [109,"Direitos e garantias fundamentais","Direitos individuais","Ninguém será privado da liberdade ou de seus bens sem:","o devido processo legal.",["autorização prévia da autoridade administrativa competente.","decisão de maioria simples da coletividade afetada.","manifestação favorável do Ministério Público, ainda que sem processo.","prova exclusivamente testemunhal produzida fora do contraditório."],"O art. 5º, LIV, estabelece o devido processo legal como condição para privação de liberdade ou de bens."],
  [110,"Direitos e garantias fundamentais","Direitos individuais","No processo judicial ou administrativo, aos litigantes e acusados em geral são assegurados:","o contraditório e a ampla defesa, com os meios e recursos a ela inerentes.",["apenas a defesa técnica, sem possibilidade de produção de provas.","contraditório somente nos processos judiciais criminais.","ampla defesa apenas após decisão final da autoridade competente.","recurso administrativo sem direito de conhecer os fundamentos da acusação."],"O art. 5º, LV, assegura contraditório e ampla defesa tanto em processos judiciais quanto administrativos."],
  [111,"Remédios constitucionais","Garantias constitucionais","Conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção por:","ilegalidade ou abuso de poder.",["erro meramente contábil praticado por órgão público.","omissão legislativa que inviabilize direito social.","recusa de acesso a dados pessoais constantes de banco público.","lesão ao patrimônio público causada por entidade privada."],"O habeas corpus protege a liberdade de locomoção diante de ilegalidade ou abuso de poder, conforme art. 5º, LXVIII."],
  [112,"Remédios constitucionais","Garantias constitucionais","O mandado de segurança protege direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for:","autoridade pública ou agente de pessoa jurídica no exercício de atribuições do Poder Público.",["somente juiz de tribunal superior em processo penal.","particular sem qualquer vínculo com função pública.","órgão legislativo, exclusivamente na fase de elaboração de leis.","empresa privada em toda e qualquer relação contratual."],"O art. 5º, LXIX, disciplina o mandado de segurança individual contra ato de autoridade pública ou agente no exercício de atribuições públicas."],
  [113,"Remédios constitucionais","Garantias constitucionais","O mandado de segurança coletivo pode ser impetrado por partido político com representação no Congresso Nacional e por:","organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa de seus membros ou associados.",["qualquer pessoa física, em nome de toda a população.","empresa individual, para defesa de interesses estritamente particulares.","associação recém-criada, ainda que sem vínculo com os interesses defendidos.","órgão policial, para substituir a atuação do Ministério Público."],"O art. 5º, LXX, define os legitimados do mandado de segurança coletivo e exige, para a associação, constituição e funcionamento há pelo menos um ano."],
  [114,"Remédios constitucionais","Garantias constitucionais","Conceder-se-á mandado de injunção quando a falta de norma regulamentadora tornar inviável o exercício:","dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, soberania e cidadania.",["de pretensão patrimonial já decidida em processo judicial definitivo.","de liberdade de locomoção ameaçada por prisão ilegal.","de acesso a dados pessoais em registro governamental.","de revisão de ato administrativo por simples discordância do interessado."],"O art. 5º, LXXI, destina o mandado de injunção à falta de norma regulamentadora que inviabilize direitos, liberdades ou prerrogativas constitucionais."],
  [115,"Remédios constitucionais","Garantias constitucionais","O habeas data é cabível para assegurar o conhecimento de informações relativas à pessoa do impetrante constantes de registros ou bancos de dados:","de entidades governamentais ou de caráter público.",["de qualquer pessoa física, sem necessidade de vínculo com dados pessoais.","exclusivamente de instituições financeiras privadas.","somente quando houver ameaça à liberdade de locomoção.","apenas após condenação judicial transitada em julgado."],"O art. 5º, LXXII, prevê habeas data para conhecer ou retificar informações pessoais em registros de entidades governamentais ou de caráter público."],
  [116,"Remédios constitucionais","Garantias constitucionais","A ação popular pode ser proposta por:","qualquer cidadão.",["qualquer residente, ainda que não eleitor.","somente pelo Ministério Público.","partido político com representação parlamentar.","associação civil constituída há mais de um ano."],"O art. 5º, LXXIII, confere a qualquer cidadão legitimidade para ação popular, destinada à proteção de patrimônio público, moralidade administrativa, meio ambiente e patrimônio histórico-cultural."],
  [117,"Remédios constitucionais","Garantias constitucionais","Na ação popular, o autor, salvo comprovada má-fé, fica isento de:","custas judiciais e ônus de sucumbência.",["provar a sua cidadania no momento da propositura.","indicar o ato lesivo que pretende impugnar.","submeter-se às regras de competência jurisdicional.","responder por litigância de má-fé quando esta for comprovada."],"O art. 5º, LXXIII, isenta o autor popular de custas e sucumbência, salvo comprovada má-fé."],
  [118,"Remédios constitucionais","Garantias constitucionais","São gratuitas, para os reconhecidamente pobres, na forma da lei, entre outras:","as ações de habeas corpus e habeas data.",["todas as ações judiciais, independentemente de objeto e condição econômica.","as demandas empresariais de cobrança de crédito privado.","as ações de indenização decorrentes de contrato comercial.","as perícias particulares solicitadas fora de processo judicial."],"O art. 5º, LXXVII, declara gratuitas as ações de habeas corpus e habeas data e, na forma da lei, atos necessários ao exercício da cidadania."],
  [119,"Remédios constitucionais","Garantias constitucionais","O direito de petição aos Poderes Públicos em defesa de direitos ou contra ilegalidade ou abuso de poder é assegurado:","independentemente do pagamento de taxas.",["somente mediante representação por advogado.","apenas aos brasileiros natos e naturalizados.","mediante prévia autorização da autoridade contra a qual se reclama.","quando o pedido envolver exclusivamente matéria tributária."],"O art. 5º, XXXIV, a, assegura o direito de petição independentemente de taxas, sem exigir advogado ou nacionalidade específica."],
  [120,"Remédios constitucionais","Garantias constitucionais","A todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam:","a celeridade de sua tramitação.",["a eliminação do contraditório em processos de baixa complexidade.","a dispensa de fundamentação das decisões administrativas.","a irrecorribilidade de toda decisão interlocutória.","a substituição do juiz natural por autoridade administrativa."],"O art. 5º, LXXVIII, assegura duração razoável e meios que garantam celeridade processual, sem afastar garantias processuais."],
  [121,"Direitos sociais","Direitos sociais","São direitos sociais expressamente previstos no art. 6º da Constituição:","educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância e assistência aos desamparados.",["apenas saúde, previdência e assistência, por dependerem de contribuição estatal.","somente educação, trabalho e moradia, pois os demais são direitos individuais.","propriedade, herança e livre iniciativa, por terem conteúdo econômico.","nacionalidade, alistamento eleitoral e filiação partidária."],"O art. 6º enumera direitos sociais em rol que inclui educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência, maternidade, infância e assistência aos desamparados."],
  [122,"Direitos sociais","Direitos sociais","A relação de emprego é protegida contra despedida arbitrária ou sem justa causa, nos termos de:","lei complementar, que preverá indenização compensatória, entre outros direitos.",["decreto do Poder Executivo, que fixará estabilidade absoluta.","lei ordinária municipal, que definirá hipóteses de dispensa.","ato unilateral do empregador, desde que motivado.","convenção internacional, independentemente de incorporação ao direito brasileiro."],"O art. 7º, I, prevê proteção contra despedida arbitrária ou sem justa causa nos termos de lei complementar, com indenização compensatória, entre outros direitos."],
  [123,"Direitos sociais","Direitos sociais","É direito dos trabalhadores urbanos e rurais a garantia de salário, nunca inferior ao mínimo, para os que percebem remuneração:","variável.",["exclusivamente em moeda estrangeira.","definida por livre escolha unilateral do empregador.","sem registro contratual ou previsão legal.","apenas por comissões, sem qualquer piso remuneratório."],"O art. 7º, VII, garante salário nunca inferior ao mínimo para quem recebe remuneração variável."],
  [124,"Direitos sociais","Direitos sociais","A duração do trabalho normal não deve ser superior a:","oito horas diárias e quarenta e quatro semanais, facultada compensação ou redução mediante acordo ou convenção coletiva.",["seis horas diárias e trinta semanais, sem exceção coletiva.","dez horas diárias e cinquenta semanais, por regra constitucional.","oito horas diárias, sem limite semanal.","quarenta horas semanais, vedada qualquer compensação."],"O art. 7º, XIII, fixa a jornada normal de até oito horas diárias e quarenta e quatro semanais, admitindo compensação ou redução por negociação coletiva."],
  [125,"Direitos sociais","Direitos sociais","A remuneração do serviço extraordinário deve ser, no mínimo:","cinquenta por cento superior à do normal.",["igual à do serviço normal, salvo contrato individual em sentido diverso.","vinte por cento superior à do normal em qualquer categoria.","dobrada apenas se prestada aos domingos.","definida exclusivamente por ato administrativo."],"O art. 7º, XVI, assegura remuneração do serviço extraordinário superior, no mínimo, em cinquenta por cento à do normal."],
  [126,"Direitos sociais","Direitos sociais","É assegurado ao trabalhador o gozo de férias anuais remuneradas com, pelo menos:","um terço a mais do que o salário normal.",["metade do salário normal, quando houver mais de um ano de contrato.","o valor integral do salário, sem qualquer adicional.","um quarto do salário mínimo, independentemente da remuneração.","adicional variável definido exclusivamente pelo empregador."],"O art. 7º, XVII, prevê férias anuais remuneradas com pelo menos um terço a mais do que o salário normal."],
  [127,"Direitos sociais","Direitos sociais","A licença à gestante, sem prejuízo do emprego e do salário, tem duração mínima de:","cento e vinte dias.",["sessenta dias.","noventa dias.","cento e oitenta dias como regra constitucional geral.","trinta dias, prorrogáveis por convenção coletiva."],"O art. 7º, XVIII, assegura licença à gestante de cento e vinte dias, sem prejuízo do emprego e salário. Programas específicos podem ampliar, mas não alteram esse mínimo constitucional."],
  [128,"Direitos sociais","Direitos sociais","A associação profissional ou sindical é livre, observado que:","ninguém será obrigado a filiar-se ou a manter-se filiado a sindicato.",["a criação de sindicato depende de autorização prévia do Poder Executivo.","é permitida mais de uma organização sindical representativa da mesma categoria na mesma base territorial definida por Município.","o sindicato pode ser dissolvido por ato administrativo sem controle judicial.","a participação sindical é requisito constitucional para contratação de trabalhador."],"O art. 8º assegura liberdade sindical, dispensa autorização estatal e veda a obrigatoriedade de filiação ou permanência no sindicato."],
  [129,"Direitos sociais","Direitos sociais","É assegurado o direito de greve, competindo aos trabalhadores decidir sobre a oportunidade de exercê-lo e sobre os interesses que devam por meio dele defender, observada:","a disciplina estabelecida em lei.",["a autorização individual do empregador antes da paralisação.","a aprovação prévia do Poder Executivo federal em toda categoria.","a vedação de qualquer negociação coletiva durante o movimento.","a exigência de renúncia aos direitos trabalhistas posteriores."],"O art. 9º reconhece o direito de greve e remete à lei a definição de serviços essenciais e atendimento das necessidades inadiáveis da comunidade."],
  [130,"Direitos sociais","Direitos sociais","A participação dos trabalhadores e empregadores nos colegiados dos órgãos públicos em que seus interesses profissionais ou previdenciários sejam objeto de discussão e deliberação é:","assegurada pela Constituição.",["vedada para preservar a imparcialidade administrativa.","limitada exclusivamente a empregados de empresas estatais.","possível apenas mediante autorização judicial individual.","restrita a matérias eleitorais."],"O art. 10 assegura a participação de trabalhadores e empregadores nos colegiados públicos em que seus interesses profissionais ou previdenciários sejam discutidos."],
  [131,"Direitos e garantias fundamentais","Igualdade e liberdade","Homens e mulheres são iguais em direitos e obrigações:","nos termos da Constituição.",["somente nas relações de trabalho privadas.","exceto quando houver ato administrativo que estabeleça diferença geral.","apenas após regulamentação por lei complementar.","desde que pertençam à mesma categoria profissional."],"O art. 5º, I, afirma a igualdade de homens e mulheres em direitos e obrigações, nos termos constitucionais."],
  [132,"Direitos e garantias fundamentais","Igualdade e liberdade","Ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e:","recusar-se a cumprir prestação alternativa fixada em lei.",["manifestar sua crença em local público.","pertencer a religião minoritária.","recusar-se a filiar-se a partido político.","discordar de política pública por escrito."],"O art. 5º, VIII, admite consequência quando a pessoa invoca crença para eximir-se de obrigação legal geral e recusa prestação alternativa prevista em lei."],
  [133,"Direitos e garantias fundamentais","Igualdade e liberdade","É livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de:","censura ou licença.",["responsabilização posterior por dano causado.","respeito aos direitos da personalidade.","observância de regras de proteção à infância previstas em lei.","controle judicial quando houver lesão a direito de terceiro."],"O art. 5º, IX, veda censura ou licença prévia, sem afastar responsabilidade posterior e proteção de outros direitos."],
  [134,"Direitos e garantias fundamentais","Igualdade e liberdade","É livre o exercício de qualquer trabalho, ofício ou profissão, atendidas:","as qualificações profissionais que a lei estabelecer.",["as exigências criadas por regulamento administrativo, ainda que sem previsão legal.","as preferências de associação profissional privada.","as condições definidas unilateralmente pelo empregador.","as autorizações prévias do Poder Judiciário."],"O art. 5º, XIII, consagra a liberdade profissional, permitindo que a lei estabeleça qualificações para certas atividades."],
  [135,"Direitos e garantias fundamentais","Propriedade","A propriedade atenderá a:","sua função social.",["interesse exclusivo e absoluto do proprietário.","autorização anual do Poder Executivo para subsistir.","finalidade obrigatoriamente lucrativa.","controle judicial prévio sobre qualquer uso do bem."],"O art. 5º, XXIII, estabelece que a propriedade atenderá a sua função social."],
  [136,"Direitos e garantias fundamentais","Propriedade","No caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário, se houver dano:","indenização ulterior.",["indenização prévia em dinheiro como condição do uso.","transferência definitiva do bem ao Estado.","isenção de qualquer compensação, mesmo havendo prejuízo.","necessária autorização judicial antes de qualquer medida."],"O art. 5º, XXV, autoriza uso de propriedade particular em perigo público e garante indenização ulterior se houver dano."],
  [137,"Direitos e garantias fundamentais","Igualdade e liberdade","A criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada:","a interferência estatal em seu funcionamento.",["a participação de brasileiros naturalizados em suas diretorias.","a defesa judicial de interesses de seus associados.","a dissolução por decisão judicial transitada em julgado.","a existência de associação com finalidade lícita."],"O art. 5º, XVIII, protege a liberdade associativa e veda interferência estatal; dissolução compulsória exige decisão judicial, com trânsito em julgado."],
  [138,"Direitos e garantias fundamentais","Reunião e associação","Todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, desde que:","não frustrem outra reunião anteriormente convocada para o mesmo local, sendo exigido apenas prévio aviso à autoridade competente.",["obtenham licença administrativa prévia e individual de todos os participantes.","sejam organizados exclusivamente por partidos políticos registrados.","ocorram somente em dias úteis e no período diurno.","tenham finalidade eleitoral ou religiosa reconhecida pelo Estado."],"O art. 5º, XVI, dispensa autorização para reunião pacífica e sem armas, exigindo prévio aviso e respeito a reunião anterior."],
  [139,"Direitos e garantias fundamentais","Reunião e associação","As associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por:","decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado.",["ato administrativo motivado de autoridade competente.","deliberação da maioria simples de seus associados, sem controle judicial.","requisição do Ministério Público, independentemente de decisão judicial.","decreto legislativo aprovado pelo Congresso Nacional."],"Pelo art. 5º, XIX, dissolução ou suspensão compulsória de associação depende de decisão judicial; para dissolução, exige-se trânsito em julgado."],
  [140,"Direitos e garantias fundamentais","Reunião e associação","As entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados:","judicial ou extrajudicialmente.",["somente perante a administração pública federal.","apenas em ações coletivas ambientais.","unicamente se todos os filiados comparecerem pessoalmente ao processo.","desde que tenham natureza sindical."],"O art. 5º, XXI, reconhece a legitimidade das entidades associativas expressamente autorizadas para representar filiados judicial ou extrajudicialmente."],
  [141,"Direitos e garantias fundamentais","Garantias penais","Não há crime sem lei anterior que o defina, nem pena sem prévia:","cominação legal.",["aprovação administrativa da autoridade policial.","concordância da vítima do fato.","decisão judicial anterior à conduta, ainda que sem lei.","previsão em regulamento interno de órgão público."],"O art. 5º, XXXIX, consagra a anterioridade penal: não há crime sem lei anterior nem pena sem prévia cominação legal."],
  [142,"Direitos e garantias fundamentais","Garantias penais","A lei penal não retroagirá, salvo para:","beneficiar o réu.",["agravar pena de crime considerado grave.","alcançar qualquer fato anterior que tenha repercussão social.","modificar regime de execução de modo mais severo.","aplicar nova interpretação administrativa em prejuízo do acusado."],"O art. 5º, XL, estabelece a retroatividade da lei penal apenas quando beneficiar o réu."],
  [143,"Direitos e garantias fundamentais","Garantias penais","A Constituição considera inafiançáveis e insuscetíveis de graça ou anistia, entre outros, os crimes de:","tortura, tráfico ilícito de entorpecentes e drogas afins, terrorismo e os definidos como hediondos.",["calúnia, difamação, injúria e ameaça.","furto simples, apropriação indébita e receptação.","desobediência, desacato e contravenções penais.","todos os crimes contra a administração pública."],"O art. 5º, XLIII, atribui esse tratamento à tortura, tráfico ilícito de entorpecentes, terrorismo e crimes hediondos."],
  [144,"Direitos e garantias fundamentais","Garantias penais","É imprescritível e sujeito à pena de reclusão, nos termos da lei, o crime de:","racismo.",["peculato culposo.","lesão corporal leve.","furto simples.","desobediência."],"O art. 5º, XLII, prevê imprescritibilidade e reclusão para a prática do racismo."],
  [145,"Direitos e garantias fundamentais","Garantias penais","Nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser estendidas aos sucessores:","até o limite do valor do patrimônio transferido.",["sem qualquer limite patrimonial, desde que haja herança.","somente se os sucessores tiverem participado do crime.","mediante pena privativa de liberdade aplicada aos herdeiros.","em valor equivalente ao dobro do dano causado."],"O art. 5º, XLV, consagra a pessoalidade da pena e limita a reparação e o perdimento transmitidos aos sucessores ao valor do patrimônio transferido."],
  [146,"Direitos e garantias fundamentais","Garantias penais","A pena será cumprida em estabelecimentos distintos, de acordo com:","a natureza do delito, a idade e o sexo do apenado.",["a preferência pessoal do condenado e de sua família.","a renda do condenado e a gravidade abstrata do delito.","a categoria profissional da vítima.","a decisão administrativa sem critérios legais."],"O art. 5º, XLVIII, prevê estabelecimentos distintos conforme natureza do delito, idade e sexo do apenado."],
  [147,"Direitos e garantias fundamentais","Garantias processuais penais","Ninguém será considerado culpado até:","o trânsito em julgado de sentença penal condenatória.",["o oferecimento da denúncia pelo Ministério Público.","a prisão em flagrante regularmente formalizada.","a confirmação da condenação em segunda instância, em qualquer caso.","o encerramento do inquérito policial."],"O art. 5º, LVII, consagra a presunção de inocência até o trânsito em julgado de sentença penal condenatória."],
  [148,"Direitos e garantias fundamentais","Garantias processuais penais","A prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente:","ao juiz competente e à família do preso ou à pessoa por ele indicada.",["somente ao Ministério Público, após conclusão do inquérito.","à autoridade administrativa superior, no prazo de cinco dias.","ao empregador do preso, antes de qualquer outra pessoa.","à Defensoria Pública apenas quando houver sentença condenatória."],"O art. 5º, LXII, determina comunicação imediata ao juiz competente e à família do preso ou pessoa indicada."],
  [149,"Direitos e garantias fundamentais","Garantias processuais penais","O preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial, bem como a permanecer:","calado, sendo-lhe assegurada a assistência da família e de advogado.",["incomunicável por até quarenta e oito horas, sem exceção.","obrigado a responder a todas as perguntas da autoridade policial.","sem contato com advogado até o oferecimento da denúncia.","submetido a interrogatório sem conhecimento de seus direitos."],"O art. 5º, LXIII e LXIV, garante o direito ao silêncio, assistência de família e advogado, além da identificação dos responsáveis pela prisão ou interrogatório."],
  [150,"Direitos e garantias fundamentais","Garantias processuais penais","A prisão ilegal será:","imediatamente relaxada pela autoridade judiciária.",["convertida automaticamente em prisão preventiva pela autoridade policial.","mantida até manifestação definitiva do Ministério Público.","substituída por multa administrativa, sem controle judicial.","regularizada por simples confirmação posterior da autoridade que a efetuou."],"O art. 5º, LXV, determina que a prisão ilegal seja imediatamente relaxada pela autoridade judiciária."]
];
const direitoConstitucionalLoteDoisComResposta = direitoConstitucionalLoteDois.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 101) % 5];
  return {id:`direito-constitucional-${String(number).padStart(3,"0")}`,subjectId:"direito-constitucional",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoConstitucionalLoteDoisComResposta);
questionBank.review.direitoConstitucionalLoteDoisReviewed = direitoConstitucionalLoteDoisComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Auditoria jurídica consolidada: ajustes de redação aplicados após todos os
// lotes para que nenhum enunciado permaneça literalmente duplicado.
const auditoriaJuridicaConsolidada = new Map([
  ["administracao-publica-023", "No regime constitucional do voto, quais pessoas podem exercer o alistamento e o sufrágio de forma facultativa?"],
  ["administracao-publica-025", "Quais são os entes políticos autônomos que compõem a estrutura federativa brasileira?"],
  ["direito-constitucional-084", "Identifique uma atribuição administrativa que a Constituição distribui de forma comum entre todos os entes federativos."],
  ["direito-penal-198", "No confronto entre os tipos penais ligados à função pública, qual definição corresponde corretamente ao delito indicado?"]
]);
questionBank.questions = questionBank.questions.map(question=>{
  const stem = auditoriaJuridicaConsolidada.get(question.id);
  return stem ? {...question, stem} : question;
});
questionBank.review.auditoriaJuridicaConsolidada = [...auditoriaJuridicaConsolidada.keys()];
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Administrativo — lote 1 (51–100): organização administrativa e princípios.
// Conteúdo conferido com a Constituição (art. 37), Decreto-Lei 200/1967 e Lei 9.784/1999.
const direitoAdministrativoLoteUm = [
 [51,"Organização administrativa","Administração direta","Na Administração Pública federal, integram a Administração direta:","a Presidência da República e os Ministérios.",["as autarquias e as fundações públicas.","as empresas públicas e as sociedades de economia mista.","as concessionárias de serviço público.","as organizações sociais qualificadas pelo Poder Público."],"A Administração direta reúne os órgãos que compõem as pessoas políticas. Autarquias, fundações, empresas públicas e sociedades de economia mista integram a Administração indireta."],
 [52,"Organização administrativa","Administração indireta","É entidade integrante da Administração indireta:","a autarquia.",["o Ministério de Estado.","a secretaria municipal.","a repartição pública sem personalidade jurídica.","o gabinete de uma autoridade."],"Autarquias, fundações públicas, empresas públicas e sociedades de economia mista compõem a Administração indireta. Ministérios e secretarias são órgãos da Administração direta."],
 [53,"Organização administrativa","Autarquia","A autarquia é criada:","diretamente por lei específica.",["por contrato de gestão firmado com o Poder Executivo.","por registro de ato constitutivo em cartório, sem lei.","por decreto autônomo do chefe do Poder Executivo.","por ato administrativo discricionário do respectivo Ministério."],"A Constituição exige lei específica para criar autarquia. Para as demais entidades da indireta, a lei específica autoriza a instituição."],
 [54,"Organização administrativa","Autarquia","A personalidade jurídica típica de uma autarquia é de direito:","público.",["privado, com regime empresarial obrigatório.","misto, alternando conforme o contrato celebrado.","internacional, quando vinculada à União.","privado, se prestar serviço público."],"A autarquia é pessoa jurídica de direito público, criada por lei para desempenhar atividades administrativas típicas do Estado."],
 [55,"Organização administrativa","Fundação pública","A instituição de fundação pública depende de:","autorização legislativa específica, na forma da lei aplicável.",["decreto do dirigente máximo do órgão interessado.","eleição dos futuros dirigentes pela população.","registro empresarial prévio, sem participação legislativa.","concessão administrativa a particular."],"A Constituição exige autorização legislativa específica para instituir fundação pública, observada a disciplina jurídica correspondente."],
 [56,"Organização administrativa","Empresa pública","Empresa pública é pessoa jurídica:","de direito privado, com capital integralmente público.",["de direito público, criada diretamente por lei.","de direito privado, necessariamente organizada como sociedade anônima.","formada obrigatoriamente por capital público e privado.","sem personalidade jurídica própria."],"A empresa pública tem personalidade de direito privado e capital exclusivamente público, podendo adotar diferentes formas societárias."],
 [57,"Organização administrativa","Sociedade de economia mista","A sociedade de economia mista distingue-se da empresa pública porque possui:","capital misto e, em regra, forma de sociedade anônima.",["capital exclusivamente público e qualquer forma societária.","personalidade jurídica de direito público.","criação dispensada de autorização legislativa.","atividade necessariamente sem finalidade econômica."],"A sociedade de economia mista possui participação pública e privada no capital e, em regra, adota a forma de sociedade anônima."],
 [58,"Organização administrativa","Vinculação","A relação entre um Ministério e uma autarquia a ele vinculada caracteriza:","controle finalístico, sem hierarquia entre as pessoas jurídicas.",["subordinação hierárquica plena sobre todos os atos da autarquia.","relação trabalhista entre órgão e entidade.","delegação de competência legislativa.","ausência completa de fiscalização."],"A vinculação permite supervisão finalística, nos limites legais. Não há hierarquia entre o órgão da Administração direta e a entidade com personalidade própria."],
 [59,"Organização administrativa","Órgãos públicos","Órgão público é corretamente definido como:","centro de competências sem personalidade jurídica própria.",["pessoa jurídica de direito privado criada por contrato.","empresa estatal com capital público integral.","fundação particular subvencionada.","agente público investido em cargo efetivo."],"Órgãos são unidades de atuação integrantes da estrutura administrativa; não possuem personalidade jurídica própria."],
 [60,"Organização administrativa","Teoria do órgão","Pela teoria do órgão, os atos praticados por seus agentes, dentro das atribuições legais, são imputados:","à pessoa jurídica a que o órgão pertence.",["ao agente, em nome próprio, sem relação com a entidade.","ao órgão como pessoa jurídica autônoma.","ao particular beneficiado pelo ato.","ao superior hierárquico, ainda que não tenha competência."],"A teoria do órgão explica a imputação da atuação de seus agentes à pessoa jurídica estatal ou administrativa a que o órgão integra."],
 [61,"Organização administrativa","Descentralização","Há descentralização administrativa quando o Estado:","transfere a execução de atividade a outra pessoa jurídica.",["distribui internamente atribuições entre órgãos da mesma pessoa.","altera a competência de servidor dentro do mesmo setor.","cria função gratificada em órgão já existente.","submete um órgão à chefia de outro órgão."],"A descentralização pressupõe outra pessoa jurídica. A redistribuição interna de atribuições, sem nova pessoa, é desconcentração."],
 [62,"Organização administrativa","Desconcentração","A criação de secretarias dentro de um Município exemplifica:","desconcentração administrativa.",["descentralização por outorga.","delegação de serviço a concessionária.","criação de autarquia.","privatização de atividade pública."],"Secretarias são órgãos da mesma pessoa política. A distribuição interna de competências configura desconcentração."],
 [63,"Organização administrativa","Outorga","A descentralização por outorga ocorre, tipicamente, quando a lei transfere a titularidade e a execução de certa atividade a:","uma entidade da Administração indireta.",["um órgão interno sem personalidade jurídica.","um servidor ocupante de função de confiança.","um particular contratado para tarefa material isolada.","um Poder da República diverso daquele previsto na Constituição."],"Na outorga, a lei atribui serviço ou atividade a pessoa jurídica administrativa, como uma autarquia, dentro dos limites legais."],
 [64,"Organização administrativa","Delegação","A concessão de serviço público a particular é exemplo de descentralização por:","delegação.",["outorga legislativa.","desconcentração interna.","avocação hierárquica.","tutela administrativa."],"A concessão transfere a execução do serviço ao particular mediante contrato; a titularidade estatal permanece, caracterizando delegação."],
 [65,"Organização administrativa","Centralização","Existe centralização administrativa quando a atividade é desempenhada:","pela própria pessoa política, por seus órgãos.",["por autarquia dotada de personalidade própria.","por concessionária de serviço público.","por fundação pública vinculada ao Ministério.","por sociedade de economia mista exploradora de atividade econômica."],"Na centralização, o ente federativo executa a atividade por sua estrutura interna, sem transferi-la a outra pessoa jurídica."],
 [66,"Organização administrativa","Consórcios públicos","Os consórcios públicos podem ser constituídos como:","associação pública ou pessoa jurídica de direito privado, conforme a lei.",["órgãos internos sem personalidade jurídica.","empresas públicas obrigatoriamente federais.","autarquias de regime especial criadas por decreto.","sociedades de economia mista com capital exclusivamente municipal."],"A Lei 11.107/2005 admite consórcios como associação pública ou pessoa jurídica de direito privado, mediante disciplina própria."],
 [67,"Organização administrativa","Agências reguladoras","As agências reguladoras federais são, em regra, qualificadas como:","autarquias sob regime especial.",["órgãos da Presidência sem personalidade jurídica.","empresas públicas exploradoras de atividade econômica.","fundações privadas financiadas pelo mercado.","concessionárias de serviços delegados."],"As agências reguladoras são autarquias em regime especial, com características previstas em suas leis instituidoras."],
 [68,"Organização administrativa","Agências executivas","A qualificação de agência executiva pode ser atribuída a autarquia ou fundação que celebre:","contrato de gestão e cumpra os requisitos legais.",["contrato de concessão com usuário do serviço.","termo de posse de dirigente eleito.","convênio internacional sem previsão normativa.","acordo coletivo de trabalho com sindicatos."],"A qualificação de agência executiva decorre do cumprimento dos requisitos legais e da celebração de contrato de gestão."],
 [69,"Organização administrativa","Terceiro setor","Organização social qualificada pelo Poder Público:","permanece pessoa jurídica privada, embora possa celebrar contrato de gestão.",["passa a integrar automaticamente a Administração indireta.","adquire personalidade de direito público.","substitui a autarquia em todas as suas prerrogativas.","dispensa controle sobre os recursos públicos recebidos."],"Organização social é pessoa jurídica privada sem fins lucrativos; a qualificação não a transforma em entidade da Administração indireta."],
 [70,"Organização administrativa","Entidades paraestatais","Serviço social autônomo, como entidade do chamado terceiro setor, é normalmente:","pessoa jurídica de direito privado que atua em cooperação com o Poder Público.",["órgão da Administração direta sem autonomia patrimonial.","autarquia criada para exercer poder de polícia.","empresa pública de capital exclusivamente estatal.","sociedade de economia mista dependente de licitação para existir."],"Serviços sociais autônomos integram o campo paraestatal e possuem personalidade privada, atuando em colaboração com finalidades públicas."],
 [71,"Organização administrativa","Controle finalístico","A supervisão ministerial sobre entidade vinculada busca verificar, principalmente:","a aderência de sua atuação às finalidades legais.",["a substituição diária de decisões técnicas por ordens hierárquicas.","a eliminação de toda autonomia administrativa.","a imposição de vínculo empregatício aos dirigentes.","a transferência da personalidade jurídica ao Ministério."],"A tutela ou supervisão ministerial é controle finalístico previsto em lei e não cria subordinação hierárquica."],
 [72,"Organização administrativa","Competência","A competência administrativa decorre da lei e, como regra, é:","irrenunciável, podendo ser delegada ou avocada nos limites legais.",["livremente abandonada pelo agente público.","transferida de modo definitivo por acordo verbal.","criada por costume administrativo.","exercida sem limite territorial ou material."],"A competência é atribuída por norma e é irrenunciável. Delegação e avocação são admitidas nos termos legais, sem transferência definitiva da titularidade."],
 [73,"Organização administrativa","Delegação de competência","Segundo a Lei 9.784/1999, não pode ser objeto de delegação:","a edição de atos de caráter normativo.",["a prática de ato material de rotina.","a assinatura de expediente administrativo.","a decisão sobre assunto técnico quando houver autorização legal.","a instrução de processo por unidade competente."],"A Lei 9.784/1999 veda delegação de edição de atos normativos, decisão de recursos administrativos e matérias de competência exclusiva."],
 [74,"Organização administrativa","Avocação","A avocação de competência por órgão hierarquicamente superior é admitida:","em caráter excepcional e por motivos relevantes devidamente justificados.",["como forma permanente de concentrar qualquer atribuição.","sempre que a autoridade preferir decidir pessoalmente.","apenas por autoridade sem vínculo hierárquico.","para suprimir competência exclusiva definida em lei."],"A avocação é excepcional, temporária e deve ser motivada por razões relevantes, respeitadas competências exclusivas."],
 [75,"Organização administrativa","Administração indireta","A criação de subsidiária de empresa pública ou sociedade de economia mista depende de:","autorização legislativa, observadas as condições estabelecidas em lei.",["decreto simples do diretor-presidente.","decisão da assembleia de empregados.","autorização judicial em processo individual.","aprovação popular por plebiscito nacional."],"A Constituição exige autorização legislativa para criação de subsidiárias das entidades da Administração indireta, nos termos da lei."],
 [76,"Organização administrativa","Fundação pública","A fundação pública pode desempenhar atividades de interesse coletivo e sua natureza jurídica dependerá:","do modelo instituído e da disciplina legal aplicável.",["exclusivamente da vontade de seus empregados.","da inexistência de lei autorizadora.","da escolha unilateral de qualquer particular.","da obrigatoriedade de finalidade lucrativa."],"A doutrina distingue fundações públicas de direito público e de direito privado conforme o modelo e a lei instituidora/autorizadora."],
 [77,"Organização administrativa","Empresa estatal","Empresa estatal exploradora de atividade econômica submete-se, em regra:","ao regime próprio das empresas privadas, ressalvadas as previsões constitucionais e legais.",["integralmente ao regime de precatórios de toda pessoa jurídica pública.","à imunidade tributária recíproca sem análise de sua atividade.","à estabilidade automática de todos os empregados celetistas.","à dispensa geral de licitação para contratações."],"A Constituição prevê sujeição das estatais exploradoras de atividade econômica ao regime jurídico próprio das empresas privadas, com as ressalvas aplicáveis."],
 [78,"Organização administrativa","Princípio da legalidade","Para a Administração Pública, legalidade significa que o agente:","atua conforme as competências e finalidades previstas no ordenamento.",["pode agir sempre que não houver proibição expressa.","substitui a lei por critérios pessoais de eficiência.","deixa de motivar atos discricionários.","cria obrigações sem fundamento normativo."],"No direito público, a atuação administrativa deve ter fundamento e limites no ordenamento, diferentemente da liberdade geral do particular."],
 [79,"Princípios administrativos","Legalidade","A expedição de ato administrativo sem base legal ou competência atribuída viola diretamente o princípio da:","legalidade.",["publicidade.","eficiência.","continuidade do serviço público.","especialidade."],"A legalidade exige atuação fundada na ordem jurídica e dentro da competência definida."],
 [80,"Princípios administrativos","Impessoalidade","O uso de publicidade oficial para destacar o nome pessoal de autoridade viola, principalmente, a:","impessoalidade.",["autotutela.","continuidade.","especialidade.","presunção de legitimidade."],"A publicidade oficial deve ter caráter educativo, informativo ou de orientação social, sem promoção pessoal de autoridades."],
 [81,"Princípios administrativos","Moralidade","Uma conduta formalmente possível, mas praticada com deslealdade e desvio ético incompatível com a função, ofende a:","moralidade administrativa.",["publicidade obrigatoriamente.","supremacia do interesse privado.","autonomia da vontade do agente.","continuidade do serviço público."],"A moralidade exige probidade, boa-fé e lealdade institucional, além da conformidade formal com a norma."],
 [82,"Princípios administrativos","Publicidade","A publicidade administrativa tem como regra a divulgação dos atos, ressalvadas:","as hipóteses constitucionais e legais de sigilo.",["as decisões que possam gerar questionamento público.","todas as informações solicitadas por particulares.","os atos praticados por agentes políticos.","os contratos administrativos em fase de execução."],"A publicidade favorece transparência e controle, mas pode ser restringida em hipóteses legítimas de sigilo previstas no ordenamento."],
 [83,"Princípios administrativos","Eficiência","O princípio da eficiência exige que a Administração busque:","resultados adequados com qualidade, economicidade e boa utilização dos recursos.",["resultado a qualquer custo, afastando garantias legais.","redução de etapas mesmo quando prejudicar a segurança.","substituição da legalidade por metas de produtividade.","preferência automática pela alternativa mais barata."],"Eficiência orienta desempenho e qualidade, mas convive com legalidade, controle e proteção de direitos."],
 [84,"Princípios administrativos","Finalidade","O ato praticado para favorecer interesse pessoal do agente, embora formalmente competente, apresenta vício de:","finalidade.",["forma.","objeto vinculado.","publicidade.","competência delegada."],"A finalidade do ato deve atender ao interesse público previsto pela norma. O desvio para interesse particular caracteriza desvio de finalidade."],
 [85,"Princípios administrativos","Motivação","A motivação do ato administrativo consiste na:","indicação dos fatos e fundamentos jurídicos que sustentam a decisão.",["mera assinatura da autoridade competente.","publicação do ato em diário oficial, sem razões.","delegação automática da competência.","presunção de veracidade de qualquer informação."],"Motivar é expor os pressupostos fáticos e jurídicos da decisão, permitindo controle e compreensão do ato."],
 [86,"Princípios administrativos","Razoabilidade e proporcionalidade","A imposição de sanção muito superior ao necessário para cumprir a finalidade pública viola, especialmente, a:","proporcionalidade.",["especialidade.","continuidade.","presunção de legitimidade.","autotutela."],"A proporcionalidade exige adequação e necessidade da medida, vedando excessos entre os meios empregados e o fim público."],
 [87,"Princípios administrativos","Segurança jurídica","A mudança de orientação administrativa deve considerar a proteção da confiança legítima e a estabilidade das relações. Essa diretriz decorre do princípio da:","segurança jurídica.",["hierarquia.","supremacia do interesse privado.","indisponibilidade absoluta de qualquer ato.","especialidade."],"A segurança jurídica busca previsibilidade e proteção da confiança nas relações administrativas, respeitadas as exigências legais."],
 [88,"Princípios administrativos","Autotutela","Ao identificar ilegalidade em ato próprio, a Administração deve:","anulá-lo, respeitados o devido processo e os limites aplicáveis.",["revogá-lo por conveniência, mesmo que a ilegalidade seja comprovada.","mantê-lo até decisão judicial obrigatória.","transferir sua revisão ao Poder Legislativo.","convalidar qualquer vício, inclusive de finalidade."],"A autotutela permite anular atos ilegais e revogar atos válidos por conveniência e oportunidade, observados direitos e limites legais."],
 [89,"Princípios administrativos","Continuidade","O princípio da continuidade dos serviços públicos orienta que sua prestação:","não sofra interrupções indevidas, observadas as hipóteses legais.",["seja obrigatoriamente gratuita a todos os usuários.","dispense planejamento de contingência.","seja substituída por atividade privada sem regulação.","ocorra apenas em horário comercial, qualquer que seja a necessidade."],"Serviços públicos devem ser prestados de forma contínua, sem excluir interrupções legalmente justificadas, como manutenção ou inadimplemento nas condições legais."],
 [90,"Princípios administrativos","Interesse público","A indisponibilidade do interesse público significa que o administrador:","não pode dispor livremente de bens e interesses confiados à sua gestão.",["pode renunciar a receitas públicas por conveniência pessoal.","atua como proprietário privado do patrimônio estatal.","pode afastar licitação por preferência individual.","subordina a finalidade pública ao interesse particular."],"O administrador gere interesses alheios, pertencentes à coletividade, e por isso sua atuação é vinculada às finalidades e limites legais."],
 [91,"Princípios administrativos","Isonomia","Em procedimento administrativo competitivo, a igualdade entre interessados exige:","critérios objetivos aplicados de modo uniforme.",["tratamento preferencial ao participante mais conhecido pelo órgão.","alteração das regras após a apresentação das propostas.","uso de critérios secretos para acelerar a decisão.","dispensa de motivação na escolha do vencedor."],"Isonomia e julgamento objetivo impedem privilégios pessoais e exigem aplicação uniforme dos critérios previamente definidos."],
 [92,"Princípios administrativos","Supremacia do interesse público","A supremacia do interesse público autoriza prerrogativas administrativas, desde que:","sejam exercidas nos limites da lei e para finalidade pública.",["prevaleçam sobre direitos fundamentais em qualquer caso.","dispensem motivação e controle judicial.","permitam sanção sem processo ou defesa.","afastem a proporcionalidade quando houver urgência."],"Prerrogativas administrativas não são ilimitadas: submetem-se à Constituição, à lei, à motivação e ao controle."],
 [93,"Princípios administrativos","Impessoalidade","A vedação de promoção pessoal em atos, programas, obras, serviços e campanhas públicas é aplicação do princípio da:","impessoalidade.",["continuidade.","especialidade.","autotutela.","presunção de legitimidade."],"A Constituição veda nomes, símbolos ou imagens que caracterizem promoção pessoal em publicidade oficial."],
 [94,"Princípios administrativos","Publicidade","O acesso do interessado aos autos de processo administrativo concretiza, entre outros, os princípios do:","contraditório e da publicidade, ressalvado sigilo legal.",["sigilo absoluto e da supremacia privada.","poder hierárquico e da autoexecutoriedade.","mérito administrativo e da irrevogabilidade.","poder regulamentar e da especialidade."],"A Lei 9.784/1999 assegura ciência da tramitação e acesso a autos, ressalvados dados de terceiros protegidos por sigilo ou direito à privacidade."],
 [95,"Princípios administrativos","Eficiência","A avaliação periódica de políticas públicas com divulgação do objeto avaliado e dos resultados alcançados busca reforçar a:","eficiência e a transparência da Administração.",["substituição do controle social por sigilo.","dispensa de planejamento orçamentário.","liberdade absoluta de atuação do gestor.","eliminação do dever de motivar decisões."],"O art. 37, § 16, prevê avaliação de políticas públicas e divulgação de objeto e resultados, reforçando gestão por resultados e transparência."],
 [96,"Princípios administrativos","Motivação","A adoção de fundamento inexistente para justificar ato administrativo torna relevante a teoria dos:","motivos determinantes.",["poderes implícitos.","atos políticos.","fatos consumados.","direitos adquiridos."],"Pela teoria dos motivos determinantes, a validade do ato vincula-se aos motivos indicados pela Administração; se forem falsos ou inexistentes, o ato pode ser invalidado."],
 [97,"Princípios administrativos","Finalidade","Quando a autoridade usa competência legal para finalidade estranha ao interesse público previsto na norma, ocorre:","desvio de finalidade.",["excesso de poder por incompetência.","convalidação obrigatória.","mera irregularidade sem repercussão.","delegação de competência."],"Desvio de finalidade ocorre quando o agente competente utiliza o poder para finalidade diversa da prevista, comprometendo a validade do ato."],
 [98,"Princípios administrativos","Princípios da Lei 9.784/1999","Além dos princípios constitucionais expressos, a Lei 9.784/1999 menciona expressamente, entre outros:","finalidade, motivação, razoabilidade, proporcionalidade e segurança jurídica.",["soberania popular, federação e pluralismo político.","livre iniciativa, propriedade privada e defesa do consumidor.","hereditariedade administrativa e supremacia contratual.","sigilo absoluto, irrecorribilidade e dispensa de fundamentação."],"O art. 2º da Lei 9.784/1999 lista, entre outros, finalidade, motivação, razoabilidade, proporcionalidade, ampla defesa, contraditório, segurança jurídica e eficiência."],
 [99,"Princípios administrativos","Administração e legalidade","A Administração somente pode impor obrigação ao administrado quando houver:","previsão legal que ampare a atuação.",["preferência pessoal da autoridade competente.","interesse financeiro isolado do ente público.","ato interno não publicado e sem fundamento normativo.","pressão de grupo econômico sobre o setor responsável."],"O dever de legalidade impede criação administrativa autônoma de obrigações sem base normativa."],
 [100,"Princípios administrativos","Revisão integrada","Em procedimento disciplinar, a decisão motivada, proporcional, baseada em competência legal e sem favorecimento pessoal concretiza, simultaneamente:","legalidade, impessoalidade, motivação e proporcionalidade.",["hierarquia, sigilo absoluto, pessoalidade e arbitrariedade.","eficiência isolada, ainda que sem fundamento legal.","publicidade como substituta da ampla defesa.","discricionariedade ilimitada do julgador."],"A situação reúne princípios e deveres administrativos: competência e lei, ausência de favorecimento, exposição das razões e adequação da medida." ]
];
const direitoAdministrativoLoteUmComResposta = direitoAdministrativoLoteUm.map(([number,topic,area,stem,correct,wrong,explanation])=>{
  const answer = "ABCDE"[(number - 51) % 5];
  return {id:`direito-administrativo-${String(number).padStart(3,"0")}`,subjectId:"direito-administrativo",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};
});
questionBank.questions.push(...direitoAdministrativoLoteUmComResposta);
questionBank.review.direitoAdministrativoLoteUmReviewed = direitoAdministrativoLoteUmComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

const reescritasSemDuplicidadePosLote = new Map([
  ["direito-constitucional-153", "No federalismo brasileiro, qual medida integra a competência administrativa compartilhada entre União, Estados, Distrito Federal e Municípios?"],
  ["direito-administrativo-061", "A transferência da execução de atividade estatal a uma pessoa jurídica distinta configura qual técnica de organização administrativa?"]
]);
questionBank.questions = questionBank.questions.map(question=>{
  const stem = reescritasSemDuplicidadePosLote.get(question.id);
  return stem ? {...question, stem} : question;
});
questionBank.review.reescritasSemDuplicidadePosLote = [...reescritasSemDuplicidadePosLote.keys()];
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

// Direito Administrativo — lote 2 (101–150): agentes públicos e atos administrativos.
const direitoAdministrativoLoteDois = [
 [101,"Agentes públicos","Agentes políticos","Agente político é aquele que exerce função estatal de direção superior, como:","Ministro de Estado.",["empregado de empresa terceirizada.","particular convocado para júri.","concessionário de serviço público.","estagiário de órgão público."],"Agentes políticos ocupam posições constitucionais ou de direção superior do Estado, como Chefes do Executivo, parlamentares e Ministros de Estado."],
 [102,"Agentes públicos","Servidor estatutário","Servidor público estatutário é vinculado à Administração por:","regime jurídico legal, definido em estatuto.",["contrato civil de prestação de serviço.","mandato eletivo.","concessão administrativa.","contrato de emprego celetista obrigatório."],"O servidor estatutário ocupa cargo público e sua relação jurídica decorre da lei e do estatuto aplicável."],
 [103,"Agentes públicos","Empregado público","O empregado público, em regra, é contratado sob o regime:","celetista.",["estatutário vitalício.","de mandato político.","de concessão pública.","militar obrigatório."],"Empregados públicos mantêm vínculo celetista, comum em empresas públicas e sociedades de economia mista."],
 [104,"Agentes públicos","Cargo, emprego e função","Cargo público é criado por lei e corresponde a conjunto de atribuições destinado a ser provido por:","servidor sujeito a regime estatutário.",["particular contratado verbalmente.","usuário de serviço público.","entidade privada conveniada.","qualquer agente político eleito."],"Cargo público é unidade de atribuições criada por lei e, em regra, provida por servidor estatutário."],
 [105,"Agentes públicos","Função de confiança","As funções de confiança são exercidas exclusivamente por:","servidores ocupantes de cargo efetivo.",["particulares sem vínculo com o Estado.","empregados de concessionárias.","agentes temporários sem concurso.","ocupantes de mandato eletivo."],"A Constituição reserva funções de confiança a servidores ocupantes de cargo efetivo."],
 [106,"Agentes públicos","Cargo em comissão","Cargos em comissão destinam-se apenas às atribuições de:","direção, chefia e assessoramento.",["atividade técnica permanente sem coordenação.","execução material de rotina.","fiscalização privada sem poder público.","representação sindical dos servidores."],"O art. 37, V, limita os cargos em comissão às funções de direção, chefia e assessoramento."],
 [107,"Agentes públicos","Concurso público","A investidura em cargo ou emprego público depende, como regra, de:","aprovação prévia em concurso público.",["indicação pessoal da autoridade.","contrato verbal com o órgão.","aprovação legislativa individual.","exercício prévio como estagiário."],"O concurso é a regra constitucional para investidura em cargo ou emprego público, ressalvados os cargos em comissão legalmente previstos."],
 [108,"Agentes públicos","Contratação temporária","A contratação temporária constitucionalmente admitida exige:","necessidade temporária de excepcional interesse público.",["necessidade permanente de pessoal.","substituição integral de concursos públicos.","livre escolha da autoridade.","atividade privada lucrativa."],"O art. 37, IX, admite contratação temporária apenas nos casos legais de necessidade temporária de excepcional interesse público."],
 [109,"Agentes públicos","Acumulação","A acumulação remunerada constitucionalmente permitida pressupõe, entre outros requisitos:","compatibilidade de horários.",["identidade entre todos os cargos.","autorização judicial prévia.","vínculo apenas com empresa privada.","ausência de concurso público."],"As exceções constitucionais de acumulação dependem de compatibilidade de horários e observância do teto remuneratório."],
 [110,"Agentes públicos","Estágio probatório","O estágio probatório serve para avaliar a aptidão do servidor recém-ingresso para o exercício do:","cargo efetivo.",["mandato eletivo.","cargo político.","contrato de concessão.","emprego privado."],"O estágio probatório integra a trajetória do servidor nomeado para cargo efetivo e avalia requisitos de desempenho."],
 [111,"Agentes públicos","Direito de greve","O direito de greve do servidor público civil deve ser exercido:","nos limites definidos pela ordem jurídica e pela jurisprudência aplicável.",["sem qualquer limite relacionado à continuidade do serviço.","somente após autorização individual do chefe.","com suspensão automática da remuneração em qualquer caso.","exclusivamente por ocupantes de cargo em comissão."],"O direito de greve existe, mas seu exercício observa parâmetros legais e jurisprudenciais, sobretudo em serviços essenciais."],
 [112,"Agentes públicos","Responsabilização","O servidor pode responder civil, penal e administrativamente quando sua conduta preencher os pressupostos próprios de cada esfera:","de modo independente, ressalvadas repercussões legais específicas.",["apenas após condenação penal definitiva.","somente se houver dano material ao Estado.","com exclusão total da esfera administrativa.","mediante escolha exclusiva da vítima."],"As instâncias podem coexistir e possuem fundamentos próprios, sem prejuízo das hipóteses legais de influência de uma decisão sobre outra."],
 [113,"Agentes públicos","Acesso a cargos","Os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham:","os requisitos estabelecidos em lei.",["os requisitos definidos informalmente pelo gestor.","apenas a filiação partidária.","indicação de agente político.","patrimônio mínimo próprio."],"O art. 37, I, assegura acesso conforme os requisitos legais, também contemplando estrangeiros na forma da lei."],
 [114,"Agentes públicos","Teto remuneratório","A remuneração dos agentes públicos sujeita-se, como regra, ao teto constitucional, cujo parâmetro geral é o subsídio dos Ministros do:","Supremo Tribunal Federal.",["Superior Tribunal de Justiça.","Tribunal de Contas da União.","Congresso Nacional.","Conselho Nacional de Justiça."],"O teto geral é o subsídio mensal dos Ministros do STF, com subtetos aplicáveis nos entes federativos."],
 [115,"Agentes públicos","Nepotismo","A vedação ao nepotismo decorre especialmente dos princípios da:","moralidade e impessoalidade.",["continuidade e especialidade.","eficiência e autotutela apenas.","publicidade e supremacia privada.","hierarquia e descentralização."],"A nomeação de parentes em condições vedadas afronta moralidade e impessoalidade, conforme a jurisprudência consolidada."],
 [116,"Agentes públicos","Delegação a particulares","Particular em colaboração com o Poder Público pode exercer atividade pública:","nos limites da delegação legal ou contratual.",["com poderes ilimitados e sem fiscalização.","como servidor estatutário automático.","dispensado de qualquer prestação de contas.","sem submissão a regras do serviço delegado."],"A colaboração privada é possível, mas decorre de vínculo jurídico e permanece submetida à regulação e fiscalização estatal."],
 [117,"Agentes públicos","Agente de fato","O agente de fato atua em situação irregular ou aparente, e seus atos podem ser preservados em favor de terceiros de boa-fé pela:","teoria da aparência.",["teoria da revogação obrigatória.","imunidade absoluta do agente.","ausência de controle judicial.","descentralização por outorga."],"A teoria da aparência busca proteger terceiros de boa-fé e a continuidade administrativa em situações específicas."],
 [118,"Agentes públicos","Responsabilidade do agente","Na ação regressiva do Estado contra seu agente, exige-se demonstração de:","dolo ou culpa.",["mera existência de dano, sem culpa.","autorização da vítima.","condenação criminal obrigatória.","ato político praticado no mandato."],"A responsabilidade estatal perante a vítima é objetiva, mas o regresso contra o agente requer dolo ou culpa."],
 [119,"Agentes públicos","Deveres funcionais","O dever de probidade impõe ao agente público atuação:","honesta, leal e voltada à finalidade pública.",["orientada por interesse patrimonial próprio.","sigilosa em todos os atos administrativos.","dispensada de motivação.","sem observância de regras de conflito de interesses."],"Probidade relaciona-se a honestidade, lealdade institucional e respeito às finalidades públicas."],
 [120,"Agentes públicos","Cargos em comissão","A nomeação para cargo em comissão não afasta:","a submissão do agente aos princípios constitucionais da Administração.",["a possibilidade de livre exoneração quando cabível.","a natureza de direção, chefia ou assessoramento.","a exigência de previsão legal do cargo.","a incidência de controles administrativos."],"Mesmo cargos de livre nomeação e exoneração submetem-se a legalidade, impessoalidade, moralidade e demais controles."],
 [121,"Agentes públicos","Revisão integrada","Servidor efetivo designado para função de confiança e que pratica ato sem competência legal pode violar simultaneamente:","as regras de função e o princípio da legalidade.",["a natureza privada de seu contrato.","a inexistência de vínculo com o órgão.","a liberdade de iniciativa empresarial.","a soberania de Estado estrangeiro."],"Função de confiança exige cargo efetivo, mas não amplia competências além das atribuídas pelo ordenamento."],
 [122,"Atos administrativos","Conceito","Ato administrativo é manifestação unilateral da Administração ou de quem a represente que produz efeitos jurídicos imediatos:","sob regime de direito público.",["apenas após sentença judicial.","somente em relações privadas.","sem necessidade de competência.","exclusivamente entre particulares."],"O ato administrativo é manifestação jurídica da Administração, sujeita a requisitos e regime jurídico administrativo."],
 [123,"Atos administrativos","Competência","A competência é requisito do ato administrativo e, em regra, é:","irrenunciável e definida em lei.",["livremente criada pela autoridade.","transferida definitivamente por acordo verbal.","dispensável em atos discricionários.","substituída pelo interesse pessoal do agente."],"Competência decorre da lei e é irrenunciável, embora possa haver delegação ou avocação nos limites legais."],
 [124,"Atos administrativos","Finalidade","A finalidade do ato administrativo deve corresponder:","ao interesse público previsto pela norma.",["ao benefício privado da autoridade.","à conveniência eleitoral do gestor.","à vontade exclusiva do destinatário.","ao lucro pessoal do agente."],"Todo ato administrativo deve buscar a finalidade pública legalmente prevista; desvio gera vício de finalidade."],
 [125,"Atos administrativos","Forma","Como regra, a forma do ato administrativo é:","elemento vinculado, observando a forma prescrita ou não proibida em lei.",["livre em qualquer situação.","dispensável quando o ato for oral.","substituível por vontade do particular.","irrelevante para controle de validade."],"A forma é requisito do ato e deve respeitar a disciplina normativa, embora certas formalidades possam admitir convalidação se não forem essenciais."],
 [126,"Atos administrativos","Motivo","O motivo do ato administrativo corresponde aos:","pressupostos de fato e de direito que justificam sua edição.",["efeitos produzidos depois da prática.","objetivos genéricos do Estado.","meios materiais usados pelo agente.","interesses privados do destinatário."],"Motivo são as circunstâncias fáticas e jurídicas que autorizam ou determinam a prática do ato."],
 [127,"Atos administrativos","Objeto","O objeto ou conteúdo do ato administrativo é:","o efeito jurídico que ele produz.",["a pessoa que assina o ato.","o motivo de fato apontado pela autoridade.","a competência do órgão.","a publicação em diário oficial."],"O objeto é o conteúdo ou efeito jurídico imediato do ato, devendo ser lícito, possível e determinado."],
 [128,"Atos administrativos","Atributos","A presunção de legitimidade significa que o ato administrativo:","é considerado válido e verdadeiro até prova em contrário.",["não pode ser questionado judicialmente.","dispensa motivação em qualquer hipótese.","produz efeitos penais automaticamente.","é imune a controle interno."],"A presunção é relativa e permite execução inicial, sem afastar controle administrativo ou judicial."],
 [129,"Atos administrativos","Autoexecutoriedade","A autoexecutoriedade permite, nas hipóteses legais ou urgentes, que a Administração:","execute diretamente determinadas medidas sem ordem judicial prévia.",["aplique qualquer sanção sem processo.","ignore contraditório em todos os casos.","crie obrigações sem lei.","substitua definitivamente o Poder Judiciário."],"Autoexecutoriedade não é ilimitada: depende de previsão legal ou situação urgente e não elimina controles posteriores."],
 [130,"Atos administrativos","Imperatividade","A imperatividade permite que certos atos imponham obrigações ao administrado:","independentemente de sua concordância.",["sem base legal.","mesmo quando o ato é inexistente.","somente após aceitação contratual.","sem possibilidade de controle."],"A imperatividade decorre do poder público e permite imposição unilateral em atos que não dependem da adesão do destinatário."],
 [131,"Atos administrativos","Tipicidade","A tipicidade exige que o ato administrativo corresponda:","a figura prevista no ordenamento.",["a criação livre do agente conforme a ocasião.","a prática usual de qualquer particular.","a interesse pessoal do gestor.","a ato judicial sem previsão legal."],"A Administração atua por formas jurídicas previstas em lei; não cria atos típicos inteiramente novos por vontade própria."],
 [132,"Atos administrativos","Atos vinculados","No ato vinculado, a lei estabelece os requisitos e a Administração:","deve praticá-lo quando eles estiverem preenchidos.",["escolhe livremente entre qualquer solução.","dispensa motivação e controle.","pode contrariar a finalidade legal.","atua sem competência definida."],"No ato vinculado, não há espaço para escolha de conveniência quanto aos requisitos previamente definidos."],
 [133,"Atos administrativos","Atos discricionários","A discricionariedade administrativa consiste em margem legal de escolha quanto à conveniência e oportunidade:","dentro dos limites da lei e da finalidade pública.",["acima da Constituição e sem controle.","para criar competências inexistentes.","para afastar direitos fundamentais.","sempre que houver pedido do particular."],"Discricionariedade não é arbitrariedade: exige competência, finalidade, motivo e objeto válidos e pode ser controlada quanto à legalidade."],
 [134,"Atos administrativos","Anulação","A anulação retira do mundo jurídico ato:","ilegal.",["válido, por conveniência e oportunidade.","político, sem qualquer vício.","judicial definitivo.","praticado por particular em contrato privado."],"A Administração deve anular atos ilegais. A revogação, por sua vez, incide sobre ato válido por razões de conveniência e oportunidade."],
 [135,"Atos administrativos","Revogação","A revogação ocorre quando a Administração retira ato válido por razões de:","conveniência e oportunidade.",["ilegalidade originária.","incompetência absoluta.","fraude necessariamente comprovada.","decisão penal condenatória."],"Revogação alcança ato válido e eficaz que deixou de ser conveniente ou oportuno, respeitados direitos e limites legais."],
 [136,"Atos administrativos","Convalidação","A convalidação é admitida para sanar determinados vícios:","sanáveis, desde que não haja lesão ao interesse público nem prejuízo a terceiros.",["de finalidade, em qualquer circunstância.","de objeto ilícito.","de competência exclusiva.","decorrentes de crime."],"A Lei 9.784/1999 admite convalidação de defeitos sanáveis, desde que não haja lesão ao interesse público nem prejuízo a terceiros."],
 [137,"Atos administrativos","Cassação","A cassação do ato administrativo pode ocorrer quando o beneficiário:","deixa de cumprir condição necessária para sua manutenção.",["discorda da política pública adotada.","solicita acesso aos autos.","cumpre integralmente todas as exigências.","não possui vínculo político com a autoridade."],"Cassação é retirada de ato favorável em razão de descumprimento posterior, pelo beneficiário, de condição indispensável."],
 [138,"Atos administrativos","Caducidade","A caducidade ocorre quando lei posterior:","torna incompatível a manutenção do ato antes válido.",["reconhece a conveniência pessoal do gestor.","corrige erro material do ato.","determina promoção automática do destinatário.","substitui a competência da autoridade por vontade privada."],"Caducidade decorre de superveniência normativa que torna incompatível ato anteriormente válido."],
 [139,"Atos administrativos","Contraposição","A contraposição ocorre quando novo ato, fundado em competência diversa, elimina os efeitos de ato anterior:","por incompatibilidade entre eles.",["pela existência de vício originário.","pela desistência do particular apenas.","por simples omissão administrativa.","por decisão judicial sem competência."],"A contraposição retira efeitos de ato anterior porque outro ato posterior, de sentido oposto, tornou-os incompatíveis."],
 [140,"Atos administrativos","Teoria dos motivos determinantes","Se a Administração declara determinado motivo para praticar ato discricionário, sua validade fica vinculada:","à existência e veracidade desse motivo.",["à vontade posterior do agente.","à divulgação em rede social.","à aceitação pelo destinatário.","à ausência de qualquer controle."],"Pela teoria dos motivos determinantes, os motivos indicados vinculam a validade do ato, mesmo quando a motivação não era exigida."],
 [141,"Atos administrativos","Atos gerais e individuais","Ato normativo geral diferencia-se do ato individual porque se dirige:","a destinatários indeterminados e situações abstratas.",["sempre a uma única pessoa.","apenas a servidores efetivos.","a contrato privado específico.","a fato já definitivamente consumado."],"Atos gerais possuem abstração e generalidade; atos individuais têm destinatário determinado ou determinável."],
 [142,"Atos administrativos","Licença e autorização","A licença administrativa é ato, em regra:","vinculado, quando o interessado preenche requisitos legais.",["discricionário e precário em qualquer hipótese.","ilegítimo por não depender de contrato.","judicial, e não administrativo.","sem efeitos para o particular."],"Licença é usualmente ato vinculado e definitivo enquanto persistirem seus pressupostos; autorização tende a ser discricionária e precária."],
 [143,"Atos administrativos","Permissão","A permissão de uso de bem público é tradicionalmente classificada como ato:","discricionário e precário.",["vinculado e definitivo.","legislativo e geral.","judicial e irrevogável.","inexistente no direito administrativo."],"A permissão de uso é, em regra, ato unilateral, discricionário e precário, sujeito às condições estabelecidas."],
 [144,"Atos administrativos","Poder de polícia","A licença para atividade sujeita a controle administrativo ilustra ato de polícia:","preventivo.",["repressivo exclusivamente.","judicial obrigatório.","legislativo sem execução.","estranho à Administração."],"O poder de polícia pode atuar preventivamente, por licenças e fiscalizações, e repressivamente, por sanções nos limites legais."],
 [145,"Atos administrativos","Silêncio administrativo","O silêncio da Administração produz os efeitos previstos:","na lei aplicável ao procedimento.",["sempre de aprovação automática.","sempre de indeferimento definitivo.","sem qualquer possibilidade de controle.","apenas quando houver contrato privado."],"O efeito do silêncio administrativo depende de previsão normativa e do contexto do procedimento; não há regra universal de aprovação ou recusa."],
 [146,"Atos administrativos","Extinção do ato","A retirada de ato válido por perda de conveniência denomina-se:","revogação.",["anulação.","convalidação.","cassação.","caducidade."],"Revogação decorre de mérito administrativo; anulação decorre de ilegalidade."],
 [147,"Atos administrativos","Extinção do ato","Quando ato ilegal é retirado pela própria Administração, há exercício de:","autotutela anulatória.",["poder regulamentar.","delegação legislativa.","descentralização territorial.","controle exclusivamente judicial."],"A Administração exerce autotutela ao anular seus atos ilegais, com respeito ao devido processo quando necessário."],
 [148,"Atos administrativos","Revisão integrada","A prática de ato por autoridade incompetente, com finalidade pública legítima, pode admitir correção se o vício for:","sanável e não houver prejuízo ao interesse público ou a terceiros.",["de finalidade, pois todo desvio é convalidável.","de objeto ilícito, mediante publicação.","de competência exclusiva, por escolha do superior.","de inexistência absoluta, por acordo com o particular."],"Vícios sanáveis, como certas hipóteses de competência e forma, podem ser convalidados. Finalidade, objeto ilícito e competência exclusiva não admitem essa correção."],
 [149,"Atos administrativos","Revisão integrada","A escolha administrativa entre duas soluções legais igualmente aptas, motivada e proporcional, representa exercício de:","discricionariedade.",["arbitrariedade.","ilegalidade automática.","ato inexistente.","desvio de finalidade."],"Quando a lei abre margem de escolha e a Administração respeita competência, finalidade e limites, há discricionariedade legítima."],
 [150,"Atos administrativos","Revisão integrada","A validade de ato administrativo exige, entre outros elementos, competência, finalidade, forma, motivo e:","objeto.",["publicidade pessoal.","vontade privada do agente.","aprovação judicial prévia.","resultado economicamente lucrativo."],"Os elementos clássicos do ato administrativo são competência, finalidade, forma, motivo e objeto." ]
];
const direitoAdministrativoLoteDoisComResposta = direitoAdministrativoLoteDois.map(([number,topic,area,stem,correct,wrong,explanation])=>{const answer="ABCDE"[(number-101)%5];return {id:`direito-administrativo-${String(number).padStart(3,"0")}`,subjectId:"direito-administrativo",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};});
questionBank.questions.push(...direitoAdministrativoLoteDoisComResposta);
questionBank.review.direitoAdministrativoLoteDoisReviewed=direitoAdministrativoLoteDoisComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

const direitoAdministrativoLoteTres = [
 [151,"Poderes administrativos","Hierárquico","O poder hierárquico permite à Administração:","distribuir e revisar internamente atribuições, nos limites legais.",["criar crimes por decreto.","interferir em outro Poder sem previsão constitucional.","revogar decisões judiciais.","delegar competência exclusiva."],"O poder hierárquico organiza a atuação interna, permitindo ordens, fiscalização, delegação e avocação nos limites normativos."],
 [152,"Poderes administrativos","Disciplinar","O poder disciplinar permite aplicar sanções a servidores e a particulares sujeitos a vínculo especial com a Administração:","mediante procedimento e observância das garantias aplicáveis.",["sem previsão normativa ou defesa.","somente após sentença penal.","contra qualquer cidadão sem vínculo.","por decisão secreta do agente."],"Poder disciplinar exige base jurídica e respeito ao devido processo; alcança servidores e particulares com vínculo específico."],
 [153,"Poderes administrativos","Regulamentar","O poder regulamentar do Chefe do Executivo destina-se, em regra, a:","viabilizar a fiel execução da lei.",["criar tributos sem autorização legislativa.","alterar a Constituição.","instituir crimes e penas.","substituir atos do Poder Judiciário."],"Regulamentos detalham a execução da lei, sem inovar autonomamente onde a reserva legal é exigida."],
 [154,"Poderes administrativos","Polícia administrativa","Poder de polícia é a atividade que limita ou disciplina direitos, interesses ou liberdades em razão do:","interesse público.",["interesse patrimonial exclusivo do agente.","desejo do particular fiscalizado.","lucro da entidade estatal.","resultado eleitoral do gestor."],"O CTN define poder de polícia como atividade que condiciona direitos em razão de interesse público, segurança, higiene, ordem e outros valores."],
 [155,"Poderes administrativos","Atributos da polícia","A coercibilidade no poder de polícia significa que a medida administrativa pode:","ser imposta ao administrado, nos limites legais.",["dispensar qualquer fundamento legal.","substituir a jurisdição penal.","ser criada por agente incompetente.","eliminar a defesa em todo processo."],"Coercibilidade é possibilidade de imposição unilateral; não afasta legalidade, proporcionalidade e controle."],
 [156,"Poderes administrativos","Abuso de poder","O abuso de poder pode ocorrer por excesso de poder ou por:","desvio de finalidade.",["presunção de legitimidade.","descentralização.","publicidade.","delegação regular."],"Excesso decorre de atuação além da competência; desvio decorre de uso da competência para finalidade diversa da legal."],
 [157,"Poderes administrativos","Excesso de poder","Há excesso de poder quando a autoridade:","atua além dos limites de sua competência.",["busca finalidade pública prevista em lei.","motiva corretamente ato vinculado.","delega atividade material permitida.","observa a proporcionalidade."],"Excesso de poder é vício ligado à competência e pode levar à invalidação do ato."],
 [158,"Poderes administrativos","Desvio de finalidade","O uso de ato aparentemente regular para perseguir interesse pessoal configura:","desvio de finalidade.",["convalidação.","poder vinculado.","ato complexo.","delegação."],"Desvio de finalidade compromete elemento essencial do ato e não é mero erro formal."],
 [159,"Poderes administrativos","Polícia preventiva","A exigência de licença antes do início de atividade controlada é manifestação de polícia:","preventiva.",["repressiva exclusivamente.","judicial.","legislativa.","contratual privada."],"Licenças, autorizações e vistorias prévias são instrumentos preventivos do poder de polícia."],
 [160,"Poderes administrativos","Polícia repressiva","A aplicação de multa administrativa por infração regularmente apurada representa polícia:","repressiva.",["preventiva.","legislativa.","jurisdicional.","sem poder público."],"Sanções administrativas por infrações configuram atuação repressiva, observados processo e legalidade."],
 [161,"Poderes administrativos","Delegação de polícia","Atos materiais de apoio à fiscalização podem ser executados por particulares quando:","houver previsão legal e preservação das decisões típicas estatais.",["o particular criar livremente sanções.","não houver qualquer supervisão pública.","a competência exclusiva for transferida integralmente.","o agente privado dispensar contrato ou lei."],"A delegação deve respeitar limites legais; funções decisórias e coercitivas típicas exigem análise estrita."],
 [162,"Poderes administrativos","Discricionariedade","A escolha entre medidas legalmente possíveis pelo administrador deve respeitar:","razoabilidade, proporcionalidade e finalidade pública.",["vontade pessoal do agente.","interesse privado do destinatário.","ausência de motivação.","imunidade a controle."],"Mérito administrativo não autoriza arbitrariedade e permanece sujeito ao controle de legalidade."],
 [163,"Poderes administrativos","Poder vinculado","No exercício de competência vinculada, a Administração:","deve seguir os requisitos previamente definidos pela lei.",["pode escolher livremente finalidade e objeto.","dispensa motivação sempre.","atua sem competência.","altera os requisitos por conveniência."],"Atos vinculados não deixam margem de escolha quanto aos pressupostos legais."],
 [164,"Poderes administrativos","Revisão integrada","Sanção aplicada por autoridade incompetente e sem defesa do interessado apresenta vícios relacionados à:","competência e ao devido processo.",["publicidade e continuidade apenas.","descentralização territorial.","livre iniciativa.","autonomia privada."],"Competência é elemento do ato; processo sancionador exige contraditório e ampla defesa."],
 [165,"Poderes administrativos","Revisão integrada","A interdição administrativa urgente de estabelecimento pode admitir execução imediata quando:","a lei ou a urgência legitimarem a autoexecutoriedade.",["a autoridade desejar punir sem fundamento.","não existir risco à coletividade.","o interessado for desconhecido.","não houver competência administrativa."],"Autoexecutoriedade depende de previsão legal ou urgência, e a medida deve ser proporcional e controlável."],
 [166,"Poderes administrativos","Regulamentar","Decreto regulamentar que cria obrigação sem suporte legal viola a:","reserva legal.",["continuidade.","hierarquia privada.","desconcentração.","teoria do órgão."],"Regulamento não pode inovar contra ou além da lei quando a matéria depende de previsão legislativa."],
 [167,"Poderes administrativos","Hierarquia","A avocação, no âmbito hierárquico, é:","excepcional, temporária e motivada.",["permanente e imotivada.","possível entre órgãos sem vínculo.","forma de criar competência exclusiva.","meio de afastar lei."],"A Lei 9.784/1999 exige excepcionalidade e motivação para avocação temporária."],
 [168,"Poderes administrativos","Polícia administrativa","A atividade de polícia administrativa distingue-se da polícia judiciária porque se volta, em regra, à:","prevenção e disciplina de atividades e bens.",["apuração de infrações penais exclusivamente.","execução de sentenças civis.","representação judicial do Estado.","edição de leis."],"Polícia administrativa atua preventivamente e repressivamente sobre atividades; polícia judiciária apura infrações penais."],
 [169,"Poderes administrativos","Poder disciplinar","A punição de particular que descumpre contrato administrativo decorre, entre outros fundamentos, do poder:","disciplinar.",["regulamentar.","constituinte.","jurisdicional.","eleitoral."],"O vínculo contratual especial com a Administração pode sujeitar o particular a sanções administrativas previstas."],
 [170,"Poderes administrativos","Revisão integrada","O poder de polícia não autoriza a Administração a:","restringir direitos sem competência legal e sem finalidade pública.",["fiscalizar atividade sujeita a licença.","aplicar sanção prevista após processo.","exigir medida preventiva proporcional.","inspecionar nas hipóteses legais."],"Toda limitação administrativa deve ter base legal, finalidade pública e respeito à proporcionalidade e ao devido processo."],
 [171,"Processo administrativo","Princípios","No processo administrativo federal, aplicam-se, entre outros, os princípios da:","motivação, razoabilidade, ampla defesa e segurança jurídica.",["hereditariedade e privilégio pessoal.","irrecorribilidade e sigilo absoluto.","autonomia privada e livre concorrência apenas.","supremacia de decisão sem fundamentação."],"A Lei 9.784/1999 elenca esses e outros princípios para a Administração Pública federal."],
 [172,"Processo administrativo","Direitos do administrado","O administrado tem direito, perante a Administração, a:","ser tratado com respeito e ter ciência da tramitação do processo.",["ser impedido de apresentar alegações.","acessar autos sempre sigilosos.","dispensar identificação quando exigida por lei.","substituir a autoridade competente."],"A Lei 9.784/1999 assegura tratamento respeitoso, ciência da tramitação, vista dos autos e apresentação de alegações."],
 [173,"Processo administrativo","Dever de decidir","A Administração tem o dever de:","decidir explicitamente os processos e solicitações de sua competência.",["aguardar indefinidamente sem manifestação.","remeter todo pedido ao Poder Judiciário.","decidir apenas quando houver interesse político.","dispensar motivação em decisões finais."],"A Lei 9.784/1999 prevê dever de decidir, ressalvadas situações previstas em lei."],
 [174,"Processo administrativo","Impedimento","A autoridade que tenha interesse direto ou indireto na matéria deve:","declarar-se impedida de atuar.",["decidir normalmente para evitar atraso.","delegar apenas a assinatura final.","manter sigilo sobre seu interesse.","atuar se houver conveniência administrativa."],"Impedimento protege imparcialidade e legitimidade do processo administrativo."],
 [175,"Processo administrativo","Suspeição","A amizade íntima ou inimizade notória com interessado pode fundamentar:","arguição de suspeição.",["avocação legislativa.","convalidação automática.","descentralização.","recurso ao Congresso."],"A Lei 9.784/1999 prevê suspeição em hipóteses que possam comprometer a imparcialidade da autoridade."],
 [176,"Processo administrativo","Motivação","Devem ser motivados, entre outros, atos que:","imponham ou agravem deveres, encargos ou sanções.",["apenas alterem a cor de formulários internos.","sejam praticados por particulares.","não produzam efeito jurídico.","nunca afetem direitos."],"A Lei 9.784/1999 exige motivação em diversos atos, especialmente os que afetam direitos ou aplicam sanções."],
 [177,"Processo administrativo","Recurso","Salvo disposição legal específica, o recurso administrativo tramitará por, no máximo:","três instâncias administrativas.",["uma instância obrigatória.","cinco instâncias sem limite.","duas instâncias judiciais.","nenhuma instância."],"A Lei 9.784/1999 prevê até três instâncias administrativas, salvo disposição legal diversa."],
 [178,"Processo administrativo","Revisão","Processos de que resultem sanções podem ser revistos a qualquer tempo quando surgirem:","fatos novos ou circunstâncias relevantes suscetíveis de justificar inadequação da sanção.",["preferências pessoais do gestor.","interesse político momentâneo.","mudança de chefia sem fato novo.","pedido de terceiro sem qualquer vínculo."],"A revisão sancionatória pode ocorrer diante de fatos novos ou circunstâncias relevantes e não pode agravar a sanção."],
 [179,"Processo administrativo","Prazo","Concluída a instrução, a Administração possui, como regra da Lei 9.784/1999, prazo de até:","trinta dias para decidir, prorrogável por igual período mediante motivação.",["cinco dias improrrogáveis.","cento e oitenta dias sem motivação.","um ano sem possibilidade de controle.","prazo inexistente."],"A lei estabelece prazo de até trinta dias após a instrução, admitida prorrogação por igual período com motivação."],
 [180,"Processo administrativo","Revisão integrada","O contraditório em processo administrativo assegura ao interessado:","conhecimento e possibilidade de influenciar a decisão.",["decisão secreta sem manifestação.","substituição da autoridade por escolha própria.","dispensa de provas pertinentes.","presunção de culpa."],"Contraditório envolve ciência e participação efetiva, associado à ampla defesa."],
 [181,"Controle da Administração","Autotutela","A Administração pode revogar seus atos quando:","válidos, mas inconvenientes ou inoportunos.",["ilegais, necessariamente.","judiciais transitados em julgado.","praticados por outro Poder sem limite.","houver direito adquirido contra a revogação."],"Revogação atua sobre ato válido por razões de mérito, respeitados direitos adquiridos e limitações legais."],
 [182,"Controle da Administração","Controle judicial","O Poder Judiciário, ao controlar ato administrativo, examina principalmente:","sua legalidade e compatibilidade com direitos.",["a conveniência administrativa livremente.","a preferência pessoal do juiz.","a escolha política sem parâmetro jurídico.","o mérito administrativo em qualquer hipótese."],"O controle judicial não substitui livremente o mérito, mas alcança legalidade, finalidade, motivação, proporcionalidade e direitos."],
 [183,"Controle da Administração","Controle legislativo","O controle externo da Administração, no âmbito federal, é exercido pelo Congresso Nacional com auxílio do:","Tribunal de Contas da União.",["Supremo Tribunal Federal.","Conselho Nacional de Justiça.","Ministério Público Federal.","Banco Central."],"A Constituição atribui ao Congresso o controle externo, auxiliado pelo TCU."],
 [184,"Controle da Administração","Tribunal de Contas","O Tribunal de Contas aprecia, para fins de registro, a legalidade dos atos de admissão de pessoal, excetuadas:","as nomeações para cargo em comissão.",["as aposentadorias.","as reformas militares.","as pensões.","as admissões em cargo efetivo."],"A Constituição excepciona da apreciação para registro as nomeações para cargo em comissão."],
 [185,"Controle da Administração","Controle interno","O controle interno busca apoiar a gestão e verificar legalidade, eficiência e resultados:","dentro da própria estrutura administrativa.",["somente pelo Poder Judiciário.","exclusivamente por particulares.","sem relação com prevenção de falhas.","apenas após dano consumado."],"Controle interno é exercido no âmbito da própria Administração e contribui para prevenção, correção e prestação de contas."],
 [186,"Controle da Administração","Controle social","O cidadão pode participar do controle da Administração por instrumentos como:","denúncia, representação e acesso a informações, nos termos legais.",["substituição automática de agentes públicos.","anulação unilateral de leis.","ordem direta a servidores sem competência.","dispensa de regras de sigilo legal."],"Controle social decorre da participação cidadã e de mecanismos de transparência e provocação dos órgãos competentes."],
 [187,"Controle da Administração","Prescrição","A invalidação de atos administrativos favoráveis ao destinatário observa, em regra federal, prazo decadencial de:","cinco anos, salvo comprovada má-fé.",["um ano em qualquer caso.","dez anos sem exceção.","prazo inexistente.","trinta dias improrrogáveis."],"A Lei 9.784/1999 estabelece decadência de cinco anos para anular atos favoráveis, salvo comprovada má-fé."],
 [188,"Controle da Administração","Revisão integrada","A anulação administrativa de ato ilegal deve observar:","o devido processo quando a medida afetar esfera jurídica do interessado.",["a dispensa de motivação.","a prevalência automática de interesse pessoal.","a impossibilidade de controle judicial.","a revogação como única técnica possível."],"Autotutela anulatória não dispensa garantias processuais quando o desfazimento repercute sobre direitos do destinatário."],
 [189,"Controle da Administração","Responsabilidade","O controle administrativo pode resultar em correção de falhas e responsabilização:","quando presentes os pressupostos legais.",["por mera discordância política.","sem apuração dos fatos.","sem possibilidade de defesa.","apenas contra particulares."],"Responsabilização requer base legal, apuração adequada e garantias compatíveis com a natureza do procedimento."],
 [190,"Controle da Administração","Revisão integrada","A existência de recurso administrativo não impede:","o controle judicial de lesão ou ameaça a direito.",["a atuação do interessado no processo.","a motivação da decisão.","o acesso a informações não sigilosas.","a revisão interna prevista em lei."],"O acesso ao Judiciário é assegurado constitucionalmente e não depende, em regra, de esgotamento da via administrativa."],
 [191,"Responsabilidade civil","Risco administrativo","A responsabilidade civil objetiva do Estado exige, em regra:","conduta administrativa, dano e nexo causal.",["dolo do agente como requisito perante a vítima.","condenação penal anterior.","contrato entre vítima e Estado.","prova de culpa exclusiva do Estado."],"A teoria do risco administrativo exige conduta, dano e nexo causal; causas excludentes podem afastar ou reduzir o dever de indenizar."],
 [192,"Responsabilidade civil","Excludentes","Culpa exclusiva da vítima pode:","romper o nexo causal e afastar a responsabilidade estatal.",["gerar indenização automática em dobro.","ser irrelevante em qualquer caso.","substituir a conduta administrativa.","transformar responsabilidade objetiva em penal."],"Se o dano decorre exclusivamente da vítima, falta nexo causal imputável ao Estado."],
 [193,"Responsabilidade civil","Omissão estatal","Em casos de omissão estatal, a responsabilidade depende da análise do:","dever jurídico de agir e do nexo com o dano.",["desejo pessoal da vítima.","cargo político do agente.","valor econômico do pedido apenas.","silêncio da Administração."],"A responsabilidade por omissão exige análise específica do dever de agir, da falha do serviço e do nexo causal."],
 [194,"Responsabilidade civil","Ação regressiva","Após indenizar vítima por dano causado por agente, o Estado pode buscar regresso se demonstrar:","dolo ou culpa do agente.",["apenas a existência do pagamento.","interesse político da chefia.","condenação criminal obrigatória.","vantagem econômica da vítima."],"A ação regressiva depende de dolo ou culpa do agente responsável."],
 [195,"Responsabilidade civil","Pessoa privada prestadora","Pessoa jurídica privada prestadora de serviço público responde pelos danos de seus agentes, nessa qualidade, de modo:","objetivo perante terceiros.",["subjetivo em qualquer hipótese.","apenas contratual.","penal automático.","inexistente."],"O art. 37, § 6º, alcança pessoas privadas prestadoras de serviço público quanto a danos causados por seus agentes."],
 [196,"Responsabilidade civil","Revisão integrada","Dano causado por agente público fora de suas atribuições, sem aparência de atuação estatal, pode afastar:","o nexo causal com a atividade administrativa.",["a necessidade de prova do dano.","a possibilidade de defesa do Estado.","a competência judicial.","a existência da vítima."],"A imputação ao Estado exige nexo entre o dano e a atuação do agente nessa qualidade, analisadas as circunstâncias."],
 [197,"Responsabilidade civil","Revisão integrada","O Estado responde objetivamente perante a vítima, mas o agente somente responde regressivamente mediante:","dolo ou culpa.",["interesse da autoridade.","ato político.","pedido verbal.","dispensa de processo."],"A distinção entre responsabilidade objetiva estatal e subjetiva regressiva do agente é central no art. 37, § 6º."],
 [198,"Responsabilidade civil","Revisão integrada","A culpa concorrente da vítima pode:","reduzir proporcionalmente a indenização.",["eliminar sempre o dano reconhecido.","impedir qualquer análise do nexo.","converter o fato em ilícito penal.","aumentar automaticamente a indenização."],"A contribuição da vítima para o resultado pode influenciar o nexo e reduzir a indenização conforme as circunstâncias."],
 [199,"Responsabilidade civil","Revisão integrada","A ação indenizatória contra o Estado não exige, como regra:","prévia condenação criminal do agente.",["demonstração de dano.","nexo causal com a atuação estatal.","identificação da atividade administrativa envolvida.","legitimidade do prejudicado."],"A pretensão civil tem pressupostos próprios; não depende de prévia condenação penal do agente."],
 [200,"Responsabilidade civil","Revisão integrada","A responsabilidade objetiva estatal não significa:","responsabilidade automática sem dano e sem nexo causal.",["possibilidade de regresso contra agente culpado.","análise de excludentes de responsabilidade.","proteção do terceiro lesado.","incidência sobre prestadores privados de serviço público."],"Objetividade dispensa prova de culpa estatal, mas exige dano e nexo causal, admitindo excludentes." ]
];
const direitoAdministrativoLoteTresComResposta=direitoAdministrativoLoteTres.map(([number,topic,area,stem,correct,wrong,explanation])=>{const answer="ABCDE"[(number-151)%5];return {id:`direito-administrativo-${String(number).padStart(3,"0")}`,subjectId:"direito-administrativo",number,topic,area,stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation};});
questionBank.questions.push(...direitoAdministrativoLoteTresComResposta);
questionBank.review.direitoAdministrativoLoteTresReviewed=direitoAdministrativoLoteTresComResposta.map(question=>question.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});
questionBank.questions = questionBank.questions.map(question=>question.id === "direito-administrativo-151" ? {...question, stem:"No âmbito interno da Administração, qual faculdade decorre do vínculo hierárquico regularmente estabelecido?"} : question);
questionBank.review.direitoAdministrativoLoteTresAudited = [151];
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});

