const administrativoFechamentoBlocos=[
 ["Licitações e contratos","Planejamento",["estudo técnico preliminar subsidia a definição da solução a contratar.","termo de referência descreve objeto, requisitos e condições de execução.","pesquisa de preços deve buscar estimativa compatível com o mercado.","gestão de riscos orienta medidas para eventos que possam afetar a contratação.","planejamento deve preceder a seleção do fornecedor."],["edital pode dispensar a descrição do objeto.","preço estimado substitui a justificativa da necessidade.","riscos só são examinados após a assinatura do contrato.","planejamento é etapa exclusiva do contratado.","pesquisa de preços autoriza escolha subjetiva."]],
 ["Licitações e contratos","Julgamento",["critério de julgamento deve constar previamente do edital.","proposta pode ser desclassificada quando não atende às exigências editalícias.","tratamento isonômico impede favorecimento sem base legal.","diligência pode esclarecer informação, sem alterar substancialmente a proposta.","decisão de julgamento deve ser motivada e documentada."],["comissão pode criar critério após conhecer as propostas.","isonomia exige aplicar requisitos distintos a cada licitante.","diligência permite substituir livremente proposta vencida.","motivação é dispensável quando há menor preço.","edital não vincula a etapa de julgamento."]],
 ["Licitações e contratos","Contratos administrativos",["equilíbrio econômico-financeiro preserva a relação inicial entre encargos e remuneração.","alteração contratual deve observar hipóteses e limites legais.","fiscalização registra ocorrências relevantes da execução.","recebimento do objeto não elimina a responsabilidade por vícios identificáveis.","prorrogação depende de justificativa e interesse público quando admitida."],["equilíbrio permite elevar preço por conveniência do contratado.","alteração dispensa motivação se houver urgência alegada.","fiscal só atua após o encerramento do contrato.","recebimento provisório impede qualquer verificação posterior.","prorrogação é automática em qualquer contrato."]],
 ["Licitações e contratos","Sanções e recursos",["sanção contratual exige processo que assegure defesa ao interessado.","penalidade deve ser proporcional à infração e às circunstâncias do caso.","recurso administrativo integra as garantias do procedimento.","impedimento de licitar possui alcance e prazo definidos em lei.","declaração de inidoneidade depende de competência e processo próprios."],["sanção pode ser aplicada verbalmente pelo fiscal.","gravidade da falta é irrelevante para a penalidade.","recurso elimina o dever de motivar a decisão.","impedimento é pena perpétua.","inidoneidade independe de contraditório."]],
 ["Serviços públicos","Direitos do usuário",["usuário tem direito a receber serviço adequado e informações pertinentes.","manifestação do usuário deve poder ser apresentada por canais de atendimento.","avaliação da qualidade auxilia o aperfeiçoamento da prestação.","cobrança deve observar regras de transparência e modicidade aplicáveis.","tratamento do usuário deve respeitar igualdade e urbanidade."],["usuário não pode questionar falha de prestação.","informação sobre tarifa deve permanecer reservada.","qualidade é definida apenas pelo prestador.","atendimento pode discriminar usuários por conveniência.","reclamação dispensa registro e resposta."]],
 ["Serviços públicos","Delegação e extinção",["poder concedente conserva dever de fiscalização sobre serviço delegado.","encampação decorre de interesse público, com requisitos legais e indenização cabível.","caducidade relaciona-se ao inadimplemento do concessionário, após procedimento.","reversão alcança bens vinculados ao serviço nas condições contratuais e legais.","delegação não transfere a titularidade estatal do serviço."],["concessionário substitui definitivamente o poder concedente.","encampação é punição automática por descumprimento.","caducidade ocorre sem apuração da inadimplência.","reversão permite apropriação de qualquer bem estranho ao serviço.","delegação elimina controle público."]],
 ["Processo administrativo","Lei 9.784/1999",["processo administrativo busca proteção dos direitos dos administrados e melhor cumprimento dos fins públicos.","interessado tem direito de acompanhar a tramitação e obter ciência dos atos.","decisão administrativa deve indicar pressupostos de fato e de direito quando a motivação for exigida.","Administração tem dever de decidir processos de sua competência.","recurso administrativo permite reexame da decisão nas condições legais."],["processo existe apenas para aplicar sanções.","interessado não pode acessar elementos do processo.","decisão pode dispensar fundamento em qualquer hipótese.","autoridade pode deixar processo sem decisão indefinidamente.","recurso depende de autorização do particular favorecido."]],
 ["Poderes administrativos","Poder de polícia",["poder de polícia condiciona direitos e atividades em favor do interesse coletivo.","autoexecutoriedade não está presente em toda medida de polícia.","coercibilidade permite impor obrigações nos limites legais.","ato de polícia deve observar competência, finalidade e proporcionalidade.","sanção de polícia exige previsão normativa e procedimento adequado."],["poder de polícia serve a interesses particulares do agente.","autoexecutoriedade dispensa fundamento legal.","coercibilidade autoriza medida desproporcional.","competência é irrelevante para ato de polícia.","sanção pode ser criada por ordem verbal."]],
 ["Controle da Administração","Formas de controle",["controle interno é exercido no âmbito da própria estrutura administrativa.","controle externo envolve fiscalização atribuída constitucionalmente ao Legislativo com auxílio dos Tribunais de Contas.","controle judicial incide sobre legalidade, sem substituir mérito administrativo legítimo.","controle social é favorecido por publicidade e acesso a informações.","autotutela permite à Administração rever seus próprios atos nos limites legais."],["controle interno é realizado apenas pelo Poder Judiciário.","Tribunal de Contas substitui integralmente o administrador.","Judiciário pode escolher livremente a conveniência do ato válido.","publicidade impede qualquer fiscalização social.","autotutela permite ignorar direitos adquiridos."]],
 ["Responsabilidade civil do Estado","Risco administrativo",["responsabilidade estatal por ato de agente público exige dano e nexo causal, observadas as excludentes aplicáveis.","ação regressiva contra agente demanda demonstração de dolo ou culpa.","responsabilidade objetiva não dispensa prova do dano.","culpa exclusiva da vítima pode romper o nexo causal.","prestador privado de serviço público pode responder pelos danos ligados à prestação."],["Estado responde sem dano demonstrado.","ação regressiva independe de culpa ou dolo.","responsabilidade objetiva presume qualquer alegação do particular.","nexo causal é irrelevante na responsabilidade estatal.","delegação elimina proteção ao usuário."]],
 ["Agentes públicos","Regime jurídico",["cargo público é unidade de atribuições criada por lei e preenchida nos termos constitucionais.","emprego público submete-se, em regra, ao regime contratual aplicável.","função de confiança é exercida exclusivamente por servidor ocupante de cargo efetivo.","acumulação remunerada somente é admitida nas hipóteses constitucionais.","responsabilização do agente pode ocorrer nas esferas civil, penal e administrativa, quando cabível."],["cargo pode ser criado por ato verbal.","emprego público dispensa concurso quando permanente.","função de confiança é livremente atribuída a particular.","acumulação é sempre permitida se houver compatibilidade de horários.","uma esfera de responsabilidade elimina necessariamente as demais."]],
 ["Atos administrativos","Atributos e invalidação",["presunção de legitimidade admite prova em contrário.","imperatividade decorre do poder público de impor obrigações dentro da lei.","anulação alcança ato ilegal e pode ser feita pela Administração ou pelo Judiciário.","revogação recai sobre ato válido por razões de conveniência e oportunidade.","convalidação pode sanar vício corrigível quando não houver prejuízo ao interesse público ou a terceiros."],["presunção de legitimidade torna ato imune a controle.","imperatividade permite criar obrigação sem lei.","anulação é forma de retirar ato válido por mérito.","revogação é obrigatória diante de toda ilegalidade.","convalidação corrige qualquer vício, inclusive de finalidade."]],
 ["Organização administrativa","Entidades e órgãos",["autarquia é pessoa jurídica de direito público criada por lei.","empresa pública pode adotar qualquer forma societária admitida em direito.","sociedade de economia mista tem capital com participação estatal e privada.","órgão público não possui personalidade jurídica própria.","desconcentração distribui competências dentro da mesma pessoa jurídica."],["autarquia nasce por registro privado.","empresa pública deve ser necessariamente sociedade anônima.","sociedade de economia mista tem capital exclusivamente privado.","órgão público celebra contratos em nome próprio como pessoa autônoma.","desconcentração cria nova pessoa jurídica."]],
 ["Improbidade administrativa","Lei 8.429/1992",["enriquecimento ilícito requer vantagem patrimonial indevida vinculada ao exercício de função pública.","dano ao erário exige demonstração de prejuízo efetivo e dos elementos legais.","mera ilegalidade não se confunde automaticamente com improbidade.","sanções de improbidade dependem de decisão judicial no processo próprio.","aplicação das sanções considera gravidade, extensão do dano e proveito obtido, quando existentes."],["vantagem lícita recebida fora da função configura enriquecimento ilícito.","todo erro formal gera dano ao erário presumido.","qualquer divergência interpretativa é improbidade.","gestor aplica sanção de improbidade sem ação judicial.","sanções ignoram as circunstâncias concretas."]],
 ["Revisão integrada","Governança pública",["boa governança combina planejamento, integridade, gestão de riscos e prestação de contas.","transparência permite controle sem afastar hipóteses legais de sigilo.","decisão pública deve perseguir finalidade pública e observar competência legal.","motivação qualificada facilita controle e reduz arbitrariedade.","integridade administrativa exige prevenção e tratamento de conflitos de interesse."],["governança dispensa controles quando há confiança no gestor.","transparência exige divulgar dado protegido por sigilo legal.","finalidade pública pode ser substituída por promoção pessoal.","motivação é detalhe sem efeito sobre validade.","conflito de interesse é irrelevante sem dano comprovado."]]
];
const administrativoFechamentoAdicional=administrativoFechamentoBlocos.flatMap(([topic,area,corrects,wrongs],block)=>corrects.map((correct,index)=>{const number=226+block*5+index;const answer="ABCDE"[(number-201)%5];const opts=[wrongs[index],wrongs[(index+1)%5],wrongs[(index+2)%5],wrongs[(index+3)%5]];opts.splice("ABCDE".indexOf(answer),0,correct);return{id:`direito-administrativo-${String(number).padStart(3,"0")}`,subjectId:"direito-administrativo",number,topic,area,stem:`Sobre ${area.toLowerCase()}, assinale a alternativa correta.`,options:opts.map((text,i)=>({letter:"ABCDE"[i],text})),answer,explanation:`A alternativa correta expressa a regra aplicável a ${area.toLowerCase()}. Os demais itens alteram requisito, competência, alcance ou consequência jurídica da disciplina.`};}));
