// Medicina Legal — Lote 5: interpretação toxicológica, matrizes e confiabilidade pericial.
const medicinaLegalLoteCincoDados=[
["Matriz biológica","A escolha da matriz biológica em exame toxicológico deve considerar principalmente:","a pergunta pericial, o tempo transcorrido e a possibilidade de preservação confiável da amostra.",["a preferência estética do laudo.","a classificação jurídica do caso.","a disponibilidade de apenas um reagente.","o número de testemunhas."],"Sangue, urina, humor vítreo, conteúdo gástrico e outros materiais respondem a perguntas diferentes."],
["Sangue periférico","Em necropsia, a preferência por sangue periférico busca reduzir:","a influência de redistribuição pós-morte observada em algumas substâncias.",["a necessidade de identificar a amostra.","a avaliação de achados de necropsia.","o registro da hora de coleta.","a análise de outros materiais."],"A matriz deve sempre ser identificada, pois concentração e significado podem variar conforme o local de coleta."],
["Urina","Em toxicologia forense, resultado urinário positivo costuma demonstrar com maior segurança:","exposição prévia ou eliminação de substância, sem definir sozinho o grau de efeito no momento do fato.",["incapacidade atual obrigatória.","a dose exata ingerida.","a causa de morte concluída.","a intenção da pessoa examinada."],"A urina é útil para triagem e janela de detecção, mas exige correlação para inferências sobre efeito."],
["Humor vítreo","O humor vítreo pode ser especialmente útil em perícias porque:","pode oferecer matriz relativamente protegida para determinados analitos e complementar outros achados.",["substitui toda análise de sangue.","dispensa a necropsia completa.","identifica autoria do evento.","elimina alterações pós-morte."],"Seu uso depende do analito, método e circunstâncias; é uma fonte complementar, não uma resposta isolada."],
["Conteúdo gástrico","A detecção de medicamento no conteúdo gástrico permite afirmar, com cautela:","que houve presença do material no trato digestivo, sem quantificar automaticamente absorção ou toxicidade sistêmica.",["que toda a dose foi absorvida.","que a morte decorreu necessariamente do medicamento.","que a ingestão foi voluntária.","que o horário exato da ingestão está definido."],"O conteúdo gástrico deve ser correlacionado com sangue, achados clínicos e circunstâncias."],
["Cadeia de custódia","Na coleta de amostra para toxicologia, a cadeia de custódia tem como finalidade principal:","documentar origem, identificação, transferência e integridade do material examinado.",["substituir o método analítico.","provar antecipadamente a autoria.","dispensar lacre e registro.","definir a pena aplicável."],"Rastreabilidade preserva o valor técnico e probatório da evidência."],
["Lacre","Um lacre rompido sem registro na cadeia de custódia exige:","avaliação crítica da integridade da amostra e documentação da ocorrência antes da interpretação conclusiva.",["desconsiderar todos os demais dados automaticamente.","emitir resultado sem ressalvas.","presumir fraude sem apuração.","repetir a coleta retroativamente."],"A irregularidade não autoriza conclusões automáticas, mas deve ser explicitada e ponderada."],
["Triagem","Teste de triagem positivo para classe de drogas deve ser seguido, quando a finalidade exige identificação conclusiva, por:","método confirmatório mais específico e interpretação compatível com suas limitações.",["conclusão imediata sobre dose e incapacidade.","descarte da amostra remanescente.","substituição de todos os registros.","presunção de causalidade."],"Triagem pode sofrer reações cruzadas; confirmação aumenta especificidade analítica."],
["Confirmação analítica","A principal vantagem de método confirmatório em toxicologia é:","distinguir com maior especificidade a substância investigada de compostos semelhantes ou interferentes.",["eliminar toda possibilidade de erro pré-analítico.","definir a intenção do examinando.","substituir a avaliação clínica.","tornar desnecessária a cadeia de custódia."],"A confirmação melhora a identificação, mas ainda requer contexto clínico e pericial."],
["Limite de detecção","O limite de detecção de um método informa:","a menor quantidade que pode ser distinguida de forma confiável das condições analíticas definidas.",["a dose ingerida pela pessoa.","o grau de incapacidade produzido.","a hora exata da exposição.","a responsabilidade penal."],"Conhecer o desempenho do método evita interpretações além do que o exame suporta."],
["Limite de quantificação","Ao relatar concentração de uma substância, é relevante distinguir limite de quantificação porque ele:","indica a faixa em que o valor numérico pode ser apresentado com confiabilidade prevista pelo método.",["converte qualquer resultado em causa de morte.","dispensa controle de qualidade.","substitui identificação da matriz.","determina a via de exposição."],"Resultado detectável nem sempre é quantitativamente confiável na mesma medida."],
["Interferente analítico","Interferente analítico é fator que pode:","alterar ou simular sinal do analito, exigindo método e controles capazes de reconhecê-lo.",["provar exposição por si só.","substituir contraprova.","confirmar automaticamente um resultado.","tornar toda amostra inutilizável."],"Interferências são avaliadas na validação e na revisão crítica do resultado."],
["Controle interno","Em rotina laboratorial, controle interno de qualidade serve para:","acompanhar se o sistema analítico mantém desempenho esperado ao longo das análises.",["selecionar o investigado.","definir a hipótese policial.","classificar a lesão corporal.","dispensar calibração."],"Controles ajudam a identificar desvios antes de liberar resultados."],
["Calibração","A calibração em exame quantitativo contribui para:","relacionar resposta instrumental a concentrações conhecidas dentro da faixa validada.",["determinar causalidade jurídica.","substituir padrões de referência.","eliminar a necessidade de controle.","informar a intenção de uso."],"A curva de calibração é um dos elementos de confiabilidade da quantificação."],
["Amostra hemolisada","Uma amostra hemolisada deve ser tratada pelo perito como:","condição pré-analítica que pode afetar determinados exames e deve ser considerada no laudo.",["prova automática de intoxicação.","motivo para inventar novo valor.","garantia de resultado inválido em todos os métodos.","evidência de autoria."],"O impacto depende do analito e do método; a condição da amostra precisa ser registrada."],
["Conservação","Para reduzir degradação de amostras toxicológicas, é essencial:","adotar acondicionamento, temperatura e prazo compatíveis com o analito e protocolo aplicável.",["manter todas as amostras em condição idêntica.","dispensar identificação após refrigerar.","usar recipiente não identificado.","priorizar somente a rapidez do laudo."],"Conservação adequada integra a qualidade pré-analítica."],
["Reanálise","A manutenção de alíquota remanescente permite:","reanálise ou contraprova quando tecnicamente cabível e devidamente registrada.",["alterar resultado já liberado sem documentação.","dispensar a cadeia de custódia.","substituir amostra original por relato.","definir o desfecho judicial."],"A possibilidade de reexame fortalece rastreabilidade e controle técnico."],
["Resultado abaixo da quantificação","Quando há sinal detectado abaixo do limite de quantificação, a redação técnica adequada é:","informar a detecção conforme a política do método, sem atribuir valor numérico não validado.",["estimar livremente uma concentração.","declarar ausência absoluta de substância.","concluir toxicidade obrigatória.","converter o achado em dose ingerida."],"A linguagem do laudo deve refletir a capacidade real de medição."],
["Polifarmácia","Em caso com vários fármacos detectados, a análise pericial deve:","examinar possíveis interações e contribuição conjunta, sem presumir que um único achado explica todo o quadro.",["ignorar os compostos de menor concentração.","somar concentrações de matrizes diferentes.","atribuir causa ao primeiro resultado liberado.","concluir sem avaliar necropsia."],"Associações podem modificar efeitos; interpretação integrada é indispensável."],
["Tolerância","A tolerância farmacológica é relevante porque pode:","modificar a resposta individual a determinada concentração, sem tornar o resultado laboratorial irrelevante.",["impedir qualquer intoxicação.","provar dependência em todos os casos.","definir a via de administração.","eliminar risco de interação."],"Tolerância é uma variável clínica; deve ser considerada junto a demais elementos."],
["Janela de detecção","A janela de detecção depende, entre outros fatores, de:","substância, dose, metabolismo, matriz, método e intervalo entre exposição e coleta.",["somente idade cronológica.","tipo penal da ocorrência.","identidade do solicitante.","ordem de impressão do laudo."],"Por isso um resultado negativo pode não excluir exposição ocorrida fora da janela analítica."],
["Caso: coleta tardia","Após coleta realizada dias depois de evento suspeito, resultado sanguíneo negativo deve ser interpretado como:","dado que exige confronto com tempo decorrido, janela de detecção e outros vestígios disponíveis.",["prova de que não houve exposição.","confirmação de que o relato é falso.","causa de encerramento obrigatório do caso.","substituto de avaliação clínica."],"O tempo transcorrido pode reduzir a detectabilidade de alguns analitos."],
["Caso: triagem positiva","Triagem urinária positiva, sem confirmação, sustenta corretamente a afirmação de que:","há achado presuntivo a ser confirmado antes de identificação conclusiva da substância.",["a dose e o horário de uso estão definidos.","a incapacidade está provada.","o laudo definitivo pode ignorar limitações.","a causa do evento está estabelecida."],"Resultados presuntivos devem ser relatados e manejados conforme o objetivo da perícia."],
["Caso: duas matrizes","Sangue negativo e urina positiva para metabólito podem ser compatíveis com:","exposição anterior com eliminação urinária persistente e ausência de concentração sanguínea detectável na coleta.",["contradição que invalida todos os exames.","prova de intoxicação atual grave.","erro obrigatório de laboratório.","identificação da dose exata."],"Matrizes possuem janelas e significados distintos."],
["Caso: resultado inesperado","Resultado incompatível com quadro clínico e investigação inicial deve levar o perito a:","revisar identificação, cadeia de custódia, método, interferências e necessidade de confirmação.",["adaptar o quadro clínico ao resultado.","omitir a divergência no laudo.","atribuir fraude sem exame.","descartar todos os documentos clínicos."],"A discrepância é motivo para revisão crítica, não para conclusão precipitada."],
["Redistribuição pós-morte","Redistribuição pós-morte descreve alteração de concentração após a morte que pode ocorrer por:","movimentação de substâncias entre tecidos e sangue, entre outros fenômenos pós-mortem.",["mudança da autoria do fato.","erro obrigatório do laboratório.","coleta de urina exclusivamente.","existência de lacre identificado."],"O fenômeno reforça a importância de registrar matriz e local de coleta."],
["Interpretação quantitativa","Concentração tóxica de referência deve ser usada em perícia como:","parâmetro auxiliar, considerando tolerância, matriz, interações e circunstâncias específicas.",["limite jurídico automático de causa de morte.","prova isolada de incapacidade.","substituto do exame necroscópico.","critério para dispensar confirmação."],"Faixas de referência não eliminam a necessidade de contextualização individual."],
["Relatório técnico","Ao apresentar resultado toxicológico, o laudo deve separar com clareza:","achados analíticos, interpretação técnica e limites da conclusão.",["resultados laboratoriais e identificação da amostra.","método e material analisado.","dados objetivos e hipótese investigativa.","todos os itens anteriores em um único juízo jurídico."],"Separar níveis de conclusão torna o documento mais transparente e tecnicamente defensável."],
["Nexo causal","Para sustentar nexo causal entre substância e morte, é necessário avaliar:","concentração, efeitos conhecidos, necropsia, circunstâncias, exclusão de alternativas e limitações do exame.",["somente a presença da substância.","apenas a história familiar.","o tipo de recipiente encontrado.","a classificação policial provisória."],"Nexo causal é conclusão integrada, não simples transcrição de resultado laboratorial."],
["Exposição ocupacional","Em suspeita de exposição ocupacional a agente químico, informação especialmente relevante é:","caracterização da atividade, via, duração, ventilação, proteção utilizada e compatibilidade clínica.",["somente o cargo registrado.","a opinião do empregador isoladamente.","o horário de emissão do laudo.","a existência de um rótulo no local."],"A perícia deve reconstruir condições reais de exposição antes de estabelecer relação."],
["Álcool","Na perícia envolvendo álcool, o resultado analítico deve ser interpretado juntamente com:","matriz, tempo de coleta, quadro clínico, relato e demais elementos do caso.",["nome comercial da bebida.","preferência da autoridade solicitante.","apenas a idade da pessoa.","a classificação administrativa do fato."],"A concentração é dado importante, porém seu significado exige correlação contextual."],
["Monóxido de carbono","Em suspeita de exposição a monóxido de carbono, a avaliação pericial deve integrar:","história ambiental, achados clínicos ou necroscópicos e exame adequado à hipótese.",["somente cheiro percebido no local.","apenas a cor da pele.","a existência de motor próximo.","declaração de uma testemunha isolada."],"Nenhum indício isolado substitui a investigação técnico-científica conjunta."],
["Agentes corrosivos","No exame de possível exposição a corrosivo, é importante correlacionar:","lesões, história, vestígios de recipientes e análise de materiais quando possível.",["somente a intensidade da dor relatada.","o tipo penal registrado.","a aparência externa do frasco sem conteúdo.","a ausência de testemunhas."],"Agentes corrosivos podem produzir lesões características, mas a conclusão exige documentação e contexto."],
["Metabólito","A identificação de metabólito pode ser útil porque:","pode apoiar a demonstração de exposição e auxiliar a distinguir transformação do composto no organismo.",["define sempre a concentração do composto original.","prova a via de uso em qualquer caso.","substitui confirmação analítica.","estabelece intenção."],"O significado do metabólito depende do composto, matriz e método empregado."],
["Falso positivo","Para reduzir o risco de falso positivo, o laboratório deve valorizar:","validação do método, controles, revisão técnica e confirmação quando indicada.",["uso de apenas uma reação de triagem.","interpretação sem conhecer a matriz.","eliminação de amostra remanescente.","omissão de limitações."],"A confiabilidade é construída por controles e etapas de confirmação."],
["Falso negativo","Falso negativo pode ocorrer, por exemplo, quando:","a coleta ocorre fora da janela de detecção ou a concentração está abaixo da capacidade do método.",["há identificação correta da amostra.","o laudo informa suas limitações.","o resultado é confirmado por técnica específica.","a cadeia de custódia está documentada."],"Entender limites analíticos impede concluir ausência absoluta de exposição."],
["Documentação","A documentação da coleta deve registrar de forma suficiente:","identificação, data, hora, coletor, matriz, acondicionamento e lacres empregados.",["somente o resultado esperado.","a tipificação penal definitiva.","a conclusão jurídica do perito.","o nome de uma testemunha opcional."],"Esses dados permitem rastrear a evidência desde a origem até o exame."],
["Contraprova","A contraprova tem relevância porque possibilita:","verificação independente ou reexame do material preservado, quando técnica e legalmente cabível.",["substituir todo exame inicial automaticamente.","alterar a identificação da amostra.","dispensar controle de qualidade.","eliminar a necessidade de laudo."],"Sua utilidade depende de amostra adequada, preservação e registro."],
["Caso: frasco no local","Frasco de medicamento encontrado próximo ao corpo, sem resultado toxicológico correspondente, deve ser considerado:","vestígio circunstancial que demanda correlação com demais dados antes de atribuir relevância causal.",["prova suficiente de intoxicação fatal.","demonstração de dose ingerida.","confirmação de uso voluntário.","substituto do exame laboratorial."],"A presença de objeto indica possibilidade de acesso, não comprovação isolada de ingestão."],
["Caso: laudo limitado","Quando o método empregado não abrange determinada classe de substâncias, o laudo deve:","explicitar essa limitação e evitar inferir ausência da classe não pesquisada.",["declarar que todas as drogas foram excluídas.","omitir o escopo do exame.","atribuir resultado negativo a qualquer composto.","substituir o método após liberar o resultado."],"O alcance analítico precisa estar claro para que a conclusão não exceda o exame realizado."],
["Caso: amostra inadequada","Se a amostra chega sem identificação compatível, a conduta técnica inicial é:","interromper a liberação conclusiva e verificar a rastreabilidade conforme protocolo.",["atribuir a amostra ao caso mais provável.","manter o resultado sem ressalva.","descartar o registro de recebimento.","concluir que houve intoxicação."],"Identificação e rastreabilidade precedem qualquer interpretação de mérito."],
["Caso: valor extremo","Resultado numérico muito elevado, mas incompatível com sobrevivência e quadro descrito, exige:","revisão analítica e pré-analítica antes de afirmar erro ou causalidade.",["aceitação imediata por ser valor elevado.","conclusão de fraude sem verificação.","descarte da hipótese de interferência.","omissão do achado."],"Valores inesperados devem acionar revisão de amostra, diluição, calibração, interferências e contexto."],
["Caso: múltiplos laudos","Havendo resultados de laboratórios diferentes para o mesmo caso, a comparação adequada considera:","matriz, momento de coleta, método, unidades e limites de cada exame.",["somente qual laudo chegou primeiro.","a preferência da parte interessada.","apenas o valor numérico maior.","a extensão do texto de cada documento."],"Resultados não são diretamente comparáveis sem equivalência de matriz e método."],
["Boa prática pericial","A conclusão toxicológica de qualidade se caracteriza por:","ser proporcional à evidência, tecnicamente fundamentada e explícita quanto às suas limitações.",["resolver questões jurídicas além do escopo técnico.","afirmar certeza quando há dados incompletos.","ignorar evidências divergentes.","priorizar uma hipótese sem análise."],"Prudência metodológica aumenta clareza e confiabilidade do laudo."],
["Síntese","Em toxicologia forense, o resultado mais útil para decisão pericial decorre de:","evidência analítica confiável interpretada com dados clínicos, necroscópicos e circunstanciais.",["um número isolado sem identificação de matriz.","triagem positiva sem contexto em qualquer situação.","presunção de causalidade pelo objeto encontrado.","conclusão jurídica antecipada."],"A integração das evidências é o núcleo da interpretação toxicológica responsável."],
["Síntese","A principal cautela ao ler exame toxicológico é distinguir:","detecção de substância, exposição, efeito clínico e nexo causal médico-legal.",["data de coleta e nome do laboratório.","método e unidade de medida.","amostra e recipiente.","laudo e relatório."],"Esses níveis não são equivalentes e exigem fundamentação própria."],
["Síntese","Uma limitação declarada no laudo deve ser entendida como:","informação técnica necessária para delimitar corretamente o alcance da conclusão.",["falha que torna todo exame inútil.","autorização para ignorar o resultado.","prova de ausência de controle.","substituto da explicação pericial."],"Transparência sobre limites protege contra interpretações indevidas do resultado."],
["Síntese","A sequência mais adequada para conclusão pericial toxicológica é:","confirmar identidade e qualidade da amostra, avaliar método e resultado e correlacioná-los ao caso.",["concluir a causa e depois escolher a matriz.","definir autoria antes de analisar o exame.","descobrir a pena e selecionar o resultado.","relatar apenas a substância detectada."],"A conclusão deve seguir a evidência e não uma hipótese previamente fechada."],
["Revisão por pares","A revisão técnica de resultado toxicológico com repercussão pericial relevante contribui para:","identificar inconsistências de cálculo, identificação, interpretação ou redação antes da liberação do laudo.",["substituir os controles do método.","definir a autoria da ocorrência.","dispensar a assinatura do responsável.","eliminar a necessidade de documentação."],"A revisão independente é uma barreira adicional contra erros de processo e de interpretação."],
["Síntese","Diante de evidência toxicológica limitada, a conduta pericial mais adequada é:","apresentar o achado de forma proporcional, indicar limitações e apontar quais dados seriam necessários para conclusão mais robusta.",["preencher as lacunas com presunções.","afirmar ausência absoluta de exposição.","atribuir causa de morte pelo resultado isolado.","omitir a incerteza para tornar o laudo conclusivo."],"Conclusão prudente não diminui o valor do laudo: ela preserva sua fidelidade científica."]
];
const medicinaLegalLoteCinco=medicinaLegalLoteCincoDados.map(([topic,stem,correct,wrongs,explanation],index)=>{const number=201+index,answer="ABCDE"[index%5];return{id:`medicina-legal-${String(number).padStart(3,"0")}`,subjectId:"medicina-legal",number,topic,area:"Toxicologia forense",stem,options:opcoesIntegradas(correct,wrongs,answer),answer,explanation};});
questionBank.questions.push(...medicinaLegalLoteCinco);
