// Medicina Legal — Lote 6: traumatologia forense e interpretação das lesões.
const medicinaLegalLoteSeisDados=[
["Traumatologia forense","A Traumatologia Forense estuda principalmente:","lesões corporais, seus mecanismos de produção e sua interpretação médico-legal.",["somente doenças infecciosas.","apenas alterações pós-morte.","exclusivamente substâncias tóxicas.","a classificação penal definitiva."],"A análise correlaciona achados do corpo, possível energia vulnerante e circunstâncias."],
["Energia mecânica","Lesões produzidas por energia mecânica resultam, em geral, de:","ação de instrumento ou força que atua por choque, pressão, corte, perfuração ou combinação desses mecanismos.",["alteração metabólica sem agente externo.","exposição exclusiva a agente químico.","processo natural de decomposição.","apenas ação térmica."],"O mecanismo deve ser inferido a partir do conjunto de características da lesão."],
["Instrumento contundente","Instrumento contundente tende a atuar por:","impacto, compressão ou choque de superfície sem gume ou ponta predominante.",["secção linear produzida por lâmina.","perfuração exclusiva por ponta aguda.","ação cáustica química.","radiação ionizante."],"Pode produzir escoriações, equimoses, hematomas, feridas contusas e fraturas."],
["Escoriação","A escoriação é caracterizada, em regra, por:","lesão superficial da pele decorrente de atrito, raspagem ou tangenciamento.",["separação completa de segmento corporal.","solução profunda por ponta estreita.","alteração produzida apenas após a morte.","lesão interna sem repercussão cutânea."],"A morfologia e a localização podem ajudar na reconstrução do evento."],
["Equimose","Equimose corresponde a:","infiltração de sangue nos tecidos em decorrência de trauma, usualmente sem solução de continuidade da pele.",["acúmulo purulento por infecção.","ferida produzida por objeto cortante.","marca exclusivamente pós-morte.","fragmentação óssea."],"A interpretação exige considerar evolução temporal, local e demais achados."],
["Hematoma","O hematoma se diferencia da equimose por apresentar, em geral:","coleção mais delimitada de sangue em cavidade ou plano tecidual.",["ausência total de sangue extravasado.","necessariamente uma ferida aberta.","origem exclusivamente natural.","produção apenas por calor."],"A denominação não substitui a investigação do mecanismo vulnerante."],
["Ferida contusa","Ferida contusa decorre tipicamente de:","ação de instrumento contundente que rompe tecidos por esmagamento ou compressão.",["corte limpo de lâmina afiada.","entrada exclusiva de projétil.","ação direta de corrosivo.","fenômeno cadavérico."],"Bordas irregulares e pontes de tecido podem ser elementos úteis na descrição."],
["Ferida incisa","Em ferida incisa, é mais esperado encontrar:","predomínio de comprimento sobre profundidade, associado a instrumento dotado de gume.",["predomínio obrigatório de profundidade sobre comprimento.","bordas esmagadas por superfície romba.","ausência de solução de continuidade.","produção exclusiva por projétil."],"A classificação depende do exame do conjunto lesional e não apenas de uma medida isolada."],
["Ferida punctória","Ferida punctória relaciona-se principalmente à ação de:","instrumento de ponta capaz de penetrar tecidos com pequeno orifício externo.",["superfície larga e romba.","gume que atua por deslizamento.","agente térmico.","substância cáustica."],"A profundidade pode superar as dimensões aparentes do orifício cutâneo."],
["Ferida perfurocortante","Instrumento perfurocortante combina, de modo relevante:","ponta para penetração e gume para seccionar tecidos.",["superfície romba e calor intenso.","pressão atmosférica e explosão.","energia elétrica e umidade.","ação química e térmica."],"A descrição pericial deve evitar concluir o objeto específico apenas pela forma da lesão."],
["Ferida cortocontusa","Ação cortocontusa é mais compatível com instrumento que reúne:","massa e gume, produzindo corte associado a efeito de impacto.",["ponta muito fina sem massa.","superfície lisa sem gume.","apenas corrente elétrica.","somente gás comprimido."],"A lesão pode alcançar planos profundos pela energia associada ao instrumento."],
["Ferida perfurocontusa","Lesão perfurocontusa pode ocorrer quando há:","ponta associada a força de impacto capaz de penetrar e contundir tecidos.",["gume que atua somente por deslizamento.","atrito superficial sem penetração.","agente químico sem contato físico.","fenômeno de putrefação."],"A classificação é orientada pelo mecanismo predominante e pelas características observadas."],
["Fratura","No exame médico-legal, fratura deve ser documentada quanto a:","localização, tipo, extensão, estruturas associadas e compatibilidade com a dinâmica alegada.",["somente presença ou ausência em radiografia.","opinião sobre autoria do fato.","classificação jurídica da lesão.","nome do instrumento como certeza."],"A documentação pode incluir exame externo, imagem, necropsia e correlação circunstancial."],
["Lesão vital","Sinais de vitalidade em lesão indicam, em termos gerais:","resposta do organismo ocorrida enquanto havia circulação ou atividade biológica relevante.",["certeza do momento exato da lesão.","identificação obrigatória do agressor.","ausência de qualquer doença prévia.","causa jurídica do evento."],"A vitalidade precisa ser interpretada com cautela e com apoio de exame completo."],
["Lesão pós-morte","Uma lesão produzida após a morte tende a exigir avaliação para distinguir-se de lesão vital por:","ausência ou menor expressão de reações orgânicas compatíveis com vitalidade, conforme o tempo pós-morte.",["cor diferente em todos os casos.","presença obrigatória de fratura.","localização exclusiva em membros.","ausência absoluta de qualquer alteração local."],"Não há sinal único universal; o diagnóstico é integrado."],
["Exame descritivo","Em traumatologia forense, descrição adequada de ferida inclui:","localização, dimensões, forma, bordas, profundidade quando possível e estruturas atingidas.",["apenas o nome presumido do instrumento.","somente a fotografia do achado.","a tipificação penal do caso.","conclusão sem registro morfológico."],"Descrição objetiva permite revisão e correlação posterior."],
["Fotografia pericial","A fotografia de lesão tem maior utilidade quando:","é associada à descrição, escala apropriada e identificação do registro no exame.",["substitui a inspeção clínica ou necroscópica.","dispensa medidas da lesão.","define autoria pelo aspecto da imagem.","elimina necessidade de laudo."],"A imagem é documentação complementar, não um substituto do exame técnico."],
["Compatibilidade","A expressão 'compatível com' em laudo pericial indica que:","o achado pode corresponder ao mecanismo proposto, sem transformar possibilidade em certeza exclusiva.",["o instrumento exato foi necessariamente identificado.","a dinâmica está provada sem outras evidências.","a autoria está definida.","a lesão é sempre recente."],"A linguagem deve refletir o grau de suporte oferecido pelos vestígios."],
["Instrumento específico","A partir de uma lesão isolada, o perito deve evitar:","afirmar identificação absoluta de instrumento específico sem elementos suficientes para tanto.",["descrever as características da ferida.","comparar a lesão com mecanismos possíveis.","registrar limitações da análise.","solicitar exames complementares."],"Muitos instrumentos podem gerar lesões semelhantes; a conclusão deve ser proporcional à evidência."],
["Caso: queda","Em pessoa com escoriações em proeminências ósseas e fratura, a hipótese de queda deve ser:","avaliada pela distribuição das lesões, história, local, exames e possibilidade de outras dinâmicas.",["aceita ou descartada apenas pela presença da fratura.","confirmada porque há escoriação.","atribuída a agressão sem investigação.","definida pela idade isoladamente."],"Dinâmica de queda depende de múltiplos elementos e pode coexistir com outras circunstâncias."],
["Caso: defesa","Lesões em mãos e antebraços podem ter relevância porque:","podem ser compatíveis com reação defensiva, devendo ser correlacionadas com o restante do exame.",["provam autoria de quem as apresenta.","sempre indicam uso de arma branca.","excluem acidente automaticamente.","dispensam exame de outras regiões."],"O caráter defensivo é hipótese técnica e não conclusão automática."],
["Caso: múltiplas lesões","Na presença de lesões de diferentes mecanismos, a conduta pericial adequada é:","descrever cada grupo e avaliar se podem resultar de um ou mais eventos, sem simplificação prematura.",["escolher apenas a lesão mais grave.","atribuir todas ao mesmo instrumento obrigatoriamente.","ignorar lesões superficiais.","concluir sem examinar a dinâmica."],"A diversidade lesional pode exigir hipóteses múltiplas e exames complementares."],
["Caso: bordas irregulares","Ferida com bordas irregulares e pontes de tecido é mais sugestiva de:","mecanismo contuso, a ser confirmado pela avaliação global da lesão.",["corte limpo por gume fino.","perfuração simples por ponta.","lesão exclusivamente térmica.","alteração cadavérica obrigatória."],"Pontes de tecido e contusão marginal são achados tradicionalmente associados a feridas contusas."],
["Caso: corte limpo","Ferida de bordas regulares, sem pontes de tecido evidentes, orienta inicialmente para:","ação por instrumento cortante, ressalvada a necessidade de exame integral.",["trauma exclusivamente contundente.","lesão por agente químico.","fenômeno natural pós-morte.","fratura sem ferida."],"A morfologia guia a hipótese, mas não autoriza determinação absoluta do objeto."],
["Energia vulnerante","Na linguagem médico-legal, energia vulnerante refere-se a:","forma de energia ou mecanismo capaz de produzir lesão no organismo.",["categoria jurídica da infração.","nome obrigatório de uma arma.","resultado de exame laboratorial.","tempo de sobrevida."],"Mecânica, térmica, elétrica, química e outras energias podem ser lesivas."],
["Concausa","Ao avaliar gravidade de lesão, condição prévia da vítima pode ser relevante porque:","pode influenciar evolução clínica sem apagar a necessidade de analisar o trauma efetivamente ocorrido.",["elimina automaticamente o nexo entre trauma e dano.","substitui exame das lesões.","prova intenção do agente.","impede qualquer conclusão pericial."],"Condições preexistentes podem atuar como concausas e exigem fundamentação cuidadosa."],
["Nexo traumático","O nexo entre trauma e dano é mais bem sustentado por:","coerência entre mecanismo, lesões, cronologia, exames e informações circunstanciais.",["uma hipótese isolada do solicitante.","a gravidade aparente da lesão apenas.","o relato sem exame físico.","a fotografia sem descrição."],"O raciocínio pericial deve explicitar os elementos que sustentam ou limitam a correlação."],
["Cronologia","A estimativa temporal de lesão deve ser apresentada:","com cautela, reconhecendo variações individuais, locais e de método de avaliação.",["como horário exato em todos os casos.","sem mencionar limitações.","somente pela cor de uma equimose.","independentemente de exames complementares."],"Achados evoluem de forma variável; precisão excessiva sem base técnica é inadequada."],
["Escala","O emprego de escala métrica em registro fotográfico auxilia a:","documentar dimensões e permitir comparação objetiva da lesão ao longo do exame.",["definir o instrumento com certeza.","substituir o texto do laudo.","indicar a autoria.","determinar causa de morte."],"A escala deve ser usada sem ocultar características relevantes da lesão."],
["Exame complementar","Diante de suspeita de lesão interna após trauma, pode ser necessário:","integrar exame clínico, imagem, necropsia ou outros métodos conforme o contexto.",["limitar-se à inspeção externa.","descartar a hipótese sem investigação.","concluir pela ausência de dano.","classificar o instrumento sem exame."],"Lesões internas podem não ter correspondência externa proporcional."],
["Lesão por pressão","Força compressiva prolongada pode produzir:","lesões cujas características dependem de intensidade, duração e região corporal envolvida.",["somente feridas incisas.","efeitos independentes da duração.","achados exclusivamente químicos.","sempre a mesma morfologia."],"O mecanismo deve ser reconstruído com base em vestígios e contexto."],
["Instrumento misto","Quando um instrumento possui mais de uma característica vulnerante, o perito deve:","avaliar qual mecanismo predominou na lesão e registrar possíveis componentes associados.",["escolher uma classificação sem examinar a ferida.","considerar apenas o nome popular do objeto.","presumir que todas as lesões são idênticas.","ignorar profundidade e bordas."],"Instrumentos podem combinar ponta, gume e massa, gerando padrões complexos."],
["Lesões associadas","A presença de escoriação ao redor de uma ferida pode ser relevante porque:","pode indicar componente de atrito ou impacto associado, a depender do contexto.",["identifica automaticamente o agressor.","torna desnecessária a descrição da ferida.","prova uma única dinâmica possível.","exclui lesão por queda."],"Achados periféricos devem ser descritos e integrados à análise da dinâmica."],
["Falso determinismo","Em traumatologia forense, é inadequado:","concluir que uma característica isolada prova de forma absoluta toda a dinâmica do evento.",["registrar elementos compatíveis.","apontar limitações do exame.","comparar hipóteses com os vestígios.","documentar lesões menores."],"A interpretação científica trabalha com graus de suporte e correlação de evidências."],
["Caso: acidente ou agressão","Para diferenciar hipótese de acidente e agressão, o perito deve considerar:","padrão lesional, história, local, vestígios, exames e consistência entre as versões.",["somente a declaração de um envolvido.","apenas a intensidade da dor.","o tamanho da maior lesão.","a classificação inicial da ocorrência."],"A perícia fornece elementos técnicos; a análise deve permanecer aberta às alternativas plausíveis."],
["Caso: lesão mínima","Pequena lesão externa após mecanismo de alta energia exige:","cautela quanto a possível dano interno e avaliação conforme sinais, sintomas e circunstâncias.",["conclusão de que não houve trauma relevante.","dispensa de observação clínica.","certeza de simulação.","exclusão de exame complementar."],"A aparência externa isolada pode subestimar a extensão de lesões internas."],
["Caso: descrição insuficiente","Laudo que apenas registra 'ferimento no braço' é tecnicamente limitado porque:","não permite avaliar morfologia, extensão, mecanismo possível ou evolução do achado.",["identifica o instrumento com precisão.","substitui fotografias e medidas.","determina a gravidade jurídica.","resolve a dinâmica do evento."],"Descrição pormenorizada é requisito básico para que o achado possa ser interpretado e revisado."],
["Caso: várias equimoses","Múltiplas equimoses devem ser analisadas quanto a:","localização, forma, distribuição, possível cronologia e compatibilidade com as hipóteses do caso.",["cor isolada como prova de horário exato.","autoria definida pela posição da lesão.","um único mecanismo obrigatório.","ausência de necessidade de fotografia."],"Distribuição corporal pode ser informativa, mas exige correlação com os demais elementos."],
["Caso: objeto apreendido","Apreensão de objeto supostamente usado deve levar o perito a:","comparar suas características com as lesões sem afirmar correspondência exclusiva quando os vestígios não permitem.",["declarar que o objeto causou a lesão só porque foi encontrado.","ignorar a morfologia da ferida.","substituir a inspeção corporal.","concluir autoria pelo objeto."],"A compatibilidade pode ser discutida tecnicamente, mas raramente é absoluta sem evidências adicionais."],
["Síntese","A melhor prática na descrição traumatológica é:","registrar objetivamente o que se observa antes de formular hipóteses sobre mecanismo e dinâmica.",["começar pela conclusão jurídica.","nomear o instrumento como certeza.","eliminar achados menores.","substituir medidas por opinião."],"Separar descrição e interpretação aumenta transparência e qualidade do laudo."],
["Síntese","A interpretação de lesão corporal deve levar em conta:","morfologia, profundidade, localização, vitalidade, exames complementares e contexto do fato.",["somente o tamanho aparente.","apenas o relato de dor.","a fotografia isolada.","o tipo penal indicado."],"Nenhum elemento isolado resume a complexidade de um exame traumatológico."],
["Síntese","A conclusão pericial responsável em traumatologia deve:","explicitar o que os achados sustentam, o que apenas sugerem e quais limitações permanecem.",["afirmar certeza onde há possibilidade.","definir autoria e intenção.","ignorar hipóteses alternativas.","dispensar fundamentação."],"A precisão da linguagem protege a utilidade técnica da perícia."],
["Síntese","Quando não há elementos para determinar o instrumento exato, o laudo pode adequadamente:","indicar a classe ou mecanismo mais compatível e registrar a impossibilidade de maior especificação.",["inventar um instrumento provável.","omitir a limitação.","concluir que não houve lesão.","converter hipótese em certeza."],"Delimitar a conclusão é parte essencial do trabalho pericial."],
["Síntese","A reconstrução de dinâmica traumática é mais sólida quando:","converge entre vestígios corporais, local, exames e informações cronologicamente consistentes.",["se baseia apenas em uma fotografia.","segue a primeira narrativa recebida.","ignora achados divergentes.","usa apenas classificação da lesão."],"Convergência de fontes independentes fortalece a hipótese técnico-pericial."],
["Síntese","Em caso de dúvida técnica relevante, o perito deve:","apresentar a incerteza de forma fundamentada e indicar os limites dos elementos disponíveis.",["escolher a conclusão mais grave.","omitir a dúvida do documento.","usar linguagem absoluta para encerrar o caso.","recusar toda análise."],"Reconhecer limites é postura científica e aumenta a confiabilidade do laudo."],
["Síntese","O objetivo da traumatologia forense é contribuir para a Justiça por meio de:","análise científica e documentada das lesões, sem ultrapassar os limites do exame médico-legal.",["decisão judicial definitiva.","substituição da investigação policial.","presunção de autoria.","classificação moral da vítima."],"A contribuição pericial decorre da documentação e interpretação técnica dos vestígios corporais." ],
["Lesão de saída","Em lesões perfurantes, a caracterização de possível orifício de saída deve ser feita:","pela avaliação completa de suas características e do trajeto, sem usar uma regra visual isolada.",["somente pelo maior diâmetro aparente.","pela presença obrigatória de bordas regulares.","sem examinar as demais lesões.","a partir de fotografia sem inspeção."],"Aspecto, trajeto, tecidos atingidos e contexto são necessários para análise segura."],
["Lesão em roupa","O exame de roupas associadas a trauma pode contribuir porque:","pode registrar danos, resíduos e alinhamento com lesões corporais, devendo ser correlacionado ao corpo e local.",["substitui obrigatoriamente o exame corporal.","define autoria pelo rasgo encontrado.","elimina necessidade de cadeia de custódia.","determina sozinho o instrumento."],"Vestígios em vestes são complementares e exigem preservação e documentação adequadas."],
["Trajeto lesional","A reconstrução de trajeto de lesão deve considerar:","planos anatômicos atingidos, direção provável, posição possível e limites impostos pelos vestígios.",["somente a posição final do corpo.","a hipótese inicialmente narrada.","o instrumento presumido sem exame.","a gravidade jurídica do fato."],"Trajeto é inferência técnica e deve ser expresso com o grau de certeza compatível."],
["Síntese","Na comparação entre versões de um evento traumático, o papel do perito é:","avaliar quais versões apresentam maior compatibilidade técnica com os achados documentados, indicando limites.",["escolher a versão mais detalhada.","atribuir culpa diretamente.","rejeitar toda versão divergente.","substituir a decisão judicial."],"A perícia oferece análise de compatibilidade, não juízo definitivo sobre responsabilidade." ]
];
const medicinaLegalLoteSeis=medicinaLegalLoteSeisDados.map(([topic,stem,correct,wrongs,explanation],index)=>{const number=251+index,answer="ABCDE"[index%5];return{id:`medicina-legal-${String(number).padStart(3,"0")}`,subjectId:"medicina-legal",number,topic,area:"Traumatologia forense",stem,options:opcoesIntegradas(correct,wrongs,answer),answer,explanation};});
questionBank.questions.push(...medicinaLegalLoteSeis);
questionBank.review.medicinaLegalLoteSeisReviewed=medicinaLegalLoteSeis.map(q=>q.number);
questionBank.subjects.forEach(s=>{s.count=questionBank.questions.filter(q=>q.subjectId===s.id).length;});

// Medicina Legal — Lote 7: asfixiologia, tanatologia e identificação humana.
const medicinaLegalLoteSeteDados=[
["Asfixiologia","A Asfixiologia Forense estuda:","mecanismos que comprometem a oxigenação e seus achados médico-legais.",["somente intoxicações medicamentosas.","apenas traumas mecânicos.","exclusivamente doenças pulmonares.","a autoria criminal."],"O diagnóstico exige integração de local, necropsia e circunstâncias."],
["Enforcamento","No enforcamento, a constrição cervical ocorre tipicamente por:","laço tracionado pelo peso total ou parcial do próprio corpo.",["compressão manual direta.","imersão em líquido.","obstrução por alimento.","exposição a gás inerte."],"A posição do corpo e o mecanismo devem ser documentados sem conclusões apressadas."],
["Estrangulamento","O estrangulamento por laço diferencia-se do enforcamento porque a força constritiva decorre principalmente de:","ação externa ao peso corporal da vítima.",["gravidade atuando sobre o laço.","imersão total.","agente químico.","fenômeno cadavérico."],"A perícia deve examinar sulco, lesões internas e contexto."],
["Esganadura","A esganadura é forma de asfixia mecânica produzida por:","compressão do pescoço com as mãos ou antebraços.",["laço sustentado pelo corpo.","líquido aspirado.","gás tóxico somente.","objeto cortante."],"Podem existir lesões cervicais e marcas defensivas, mas nenhum achado isolado é absoluto."],
["Sufocação","Sufocação direta pode resultar de:","obstrução das vias aéreas por meio externo aplicado à boca e ao nariz.",["fratura de membro.","corte superficial.","exposição solar.","intoxicação alimentar."],"A investigação considera também vestígios em face, mãos e ambiente."],
["Soterramento","No soterramento, a morte pode relacionar-se a:","compressão torácica, obstrução respiratória e condições ambientais do recobrimento.",["somente afogamento.","apenas intoxicação medicamentosa.","ferida incisa obrigatória.","morte natural presumida."],"O local é especialmente relevante para reconstruir a dinâmica."],
["Afogamento","Afogamento é processo de comprometimento respiratório por:","submersão ou imersão em meio líquido.",["presença de água em roupa apenas.","exposição a umidade ambiental.","lesão química cutânea.","hipotermia obrigatória."],"O diagnóstico não se apoia em sinal isolado e demanda correlação pericial."],
["Confinamento","Ambiente confinado pode gerar risco asfíxico quando:","há redução de oxigênio ou acúmulo de gases capazes de comprometer a respiração.",["a porta está aberta.","existe iluminação suficiente.","há ausência de lesões externas.","a pessoa está em repouso."],"A avaliação ambiental é essencial para estabelecer a plausibilidade do mecanismo."],
["Gases inertes","Gases inertes podem causar asfixia principalmente por:","deslocarem o oxigênio disponível no ambiente respirável.",["produzirem queimadura química obrigatória.","cortarem tecidos do pescoço.","aumentarem a pressão arterial.","deixarem odor característico em todos os casos."],"O exame do local e a análise ambiental podem ser decisivos."],
["Sinais gerais","Sinais gerais de asfixia devem ser interpretados como:","achados de apoio que não substituem a análise completa do mecanismo e do local.",["prova exclusiva de um tipo de asfixia.","indicação automática de homicídio.","marcadores de horário exato.","evidência de autoria."],"Muitos sinais são inespecíficos e podem ocorrer em diferentes condições."],
["Sulco cervical","O sulco cervical deve ser descrito quanto a:","posição, direção, profundidade, continuidade, aspecto e estruturas associadas.",["somente sua cor.","a identidade do agressor.","o tipo penal definitivo.","um instrumento específico como certeza."],"Descrição detalhada permite avaliar compatibilidade com diferentes mecanismos."],
["Caso: corpo em água","Corpo encontrado em água exige que o perito considere:","possibilidade de submersão, morte prévia e alterações ambientais antes de concluir afogamento.",["que toda recuperação em água é afogamento.","apenas a presença de roupas molhadas.","que não é necessário exame interno.","que a causa é definida pelo local."],"O local de encontro do corpo não determina sozinho a causa da morte."],
["Caso: marca no pescoço","Marca cervical sem contexto suficiente deve ser interpretada:","com exame interno, história e vestígios do local, evitando classificação automática.",["como enforcamento comprovado.","como esganadura obrigatória.","como lesão pós-morte certa.","sem documentação fotográfica."],"Morfologia isolada não resolve toda a dinâmica."],
["Tanatologia","A Tanatologia Forense aborda:","fenômenos da morte, alterações cadavéricas e sua relevância pericial.",["apenas identificação genética.","exclusivamente lesões por arma.","somente doenças infecciosas.","decisão judicial."],"Inclui análise da cronologia e das alterações do cadáver."],
["Morte","Em Medicina Legal, morte é compreendida como:","cessação irreversível das funções vitais do organismo conforme critérios técnicos aplicáveis.",["ausência temporária de resposta verbal.","qualquer perda de consciência.","presença de lesão externa.","interrupção breve da respiração."],"Os critérios e o contexto clínico-pericial definem a avaliação."],
["Fenômenos abióticos","Fenômenos abióticos consecutivos à morte incluem:","resfriamento, rigidez e livores cadavéricos, entre outras alterações.",["cicatrização de feridas.","regeneração celular.","crescimento de pelos.","formação de hematoma vital."],"A evolução varia conforme ambiente, corpo e circunstâncias."],
["Algor mortis","O resfriamento cadavérico deve ser usado para estimativa temporal:","com cautela, pois sofre influência de ambiente, vestes, massa corporal e outras variáveis.",["como relógio exato universal.","somente pela temperatura ambiente.","sem considerar o local.","independentemente do corpo."],"A estimativa do intervalo pós-morte é sempre aproximada e integrada."],
["Livores","Livores cadavéricos resultam, em geral, de:","acúmulo gravitacional de sangue em regiões declivosas após cessar a circulação.",["infiltração vital por trauma.","ação de instrumento cortante.","congelamento obrigatório.","atividade muscular."],"Sua distribuição pode auxiliar na análise de posição, com limitações."],
["Rigidez","A rigidez cadavérica corresponde a:","enrijecimento muscular pós-morte decorrente de alterações bioquímicas.",["contração voluntária preservada.","sinal exclusivo de violência.","fratura muscular.","processo infeccioso."],"Início e duração variam com condições individuais e ambientais."],
["Putrefação","Putrefação é processo relacionado sobretudo a:","decomposição por atividade microbiana e alterações progressivas dos tecidos.",["cicatrização vital.","resposta inflamatória ativa.","formação de osso novo.","aplicação de laço cervical."],"O ambiente pode acelerar ou retardar o processo."],
["Cronotanatognose","A estimativa do intervalo pós-morte deve considerar:","conjunto de fenômenos cadavéricos, ambiente, informações circunstanciais e limites técnicos.",["uma única alteração corporal.","o relato de uma testemunha isolada.","somente a rigidez.","a idade da vítima."],"O termo expressa estimativa e não determinação exata de horário."],
["Lesões vitais","Diferenciar lesão vital de alteração pós-morte requer:","avaliação morfológica, histológica quando indicada e correlação com a cronologia.",["apenas cor da lesão.","a posição do corpo somente.","uma fotografia distante.","o tipo penal."],"A vitalidade é questão técnico-pericial e pode exigir exames complementares."],
["Caso: mudança de posição","Livores incompatíveis com a posição final do corpo podem sugerir:","possível mudança de posição após sua instalação, exigindo análise contextual.",["autoria definida.","causa de morte certa.","hora exata do óbito.","ausência de morte."],"O achado é indiciário e deve ser confrontado com o restante da perícia."],
["Identificação","A identificação humana busca:","estabelecer identidade por confronto de características confiáveis e adequadas ao caso.",["apenas estimar idade.","substituir exame necroscópico.","definir causa de morte.","atribuir responsabilidade penal."],"Métodos devem ser selecionados conforme condição do corpo e dados comparativos disponíveis."],
["Identidade","Em perícia, identidade humana é:","conjunto de atributos que individualiza uma pessoa e permite distingui-la das demais.",["somente o nome informado por familiar.","uma fotografia sem comparação.","o local em que o corpo foi achado.","a causa de morte."],"Identificação demanda correspondência tecnicamente sustentada."],
["Papiloscopia","A papiloscopia tem valor identificatório porque:","padrões papilares possuem individualidade e podem ser comparados com registros conhecidos.",["depende apenas da cor da pele.","substitui toda documentação.","define idade exata.","é útil somente em vivos."],"A qualidade do material e a existência de padrão comparativo são fundamentais."],
["Odontologia legal","A Odontologia Legal pode contribuir para identificação por meio de:","confronto entre características dentárias e documentação odontológica ante mortem.",["análise de grupo sanguíneo isolado.","estimativa de profissão exclusivamente.","identificação pelo vestuário.","opinião de testemunha."],"Tratamentos e particularidades odontológicas podem fornecer elementos comparativos robustos."],
["DNA","O exame de DNA é especialmente útil quando:","há amostra adequada e referência comparativa confiável para estabelecer vínculo identificatório.",["não existe qualquer controle de amostra.","se pretende definir causa de morte sozinho.","a identificação visual já é suficiente em todos os casos.","não há necessidade de cadeia de custódia."],"O resultado deve ser interpretado conforme método, referência e qualidade do material."],
["Antropologia forense","A Antropologia Forense pode auxiliar principalmente em:","estimativas de perfil biológico e análise de restos humanos, dentro de seus limites.",["determinação automática de nome civil.","definição de autoria criminal.","substituição de DNA em todos os casos.","diagnóstico de intoxicação."],"Sexo, idade, estatura e ancestralidade estimada são inferências com margens de incerteza."],
["Reconhecimento visual","O reconhecimento visual de cadáver deve ser tratado:","como dado que pode orientar, mas pode requerer confirmação por método técnico adequado.",["como prova infalível em qualquer condição.","como substituto obrigatório do DNA.","sem registro documental.","como critério de causa de morte."],"Decomposição, trauma e tempo podem reduzir sua confiabilidade."],
["Caso: corpo carbonizado","Em corpo carbonizado, métodos de identificação podem incluir:","odontologia, DNA, antropologia e outros meios compatíveis com a preservação dos vestígios.",["somente reconhecimento visual.","apenas impressão digital íntegra.","a causa presumida do incêndio.","o local de encontro."],"A estratégia é definida pela condição dos restos e pelos materiais comparativos disponíveis."],
["Caso: documentos","Documentos encontrados junto ao corpo devem ser considerados:","indícios de identidade que necessitam confronto técnico antes de identificação definitiva.",["prova definitiva em qualquer circunstância.","substitutos de exame pericial.","elementos sem qualquer valor.","evidência de causa de morte."],"Objetos podem pertencer a outra pessoa ou ter sido deslocados; confirmação é necessária."],
["Cadeia de custódia","Em identificação por DNA, a cadeia de custódia é indispensável para:","assegurar rastreabilidade entre amostra questionada, referência e resultado emitido.",["aumentar a concentração de DNA.","substituir controles laboratoriais.","definir parentesco sem comparação.","eliminar a necessidade de laudo."],"Trocas ou contaminação comprometem gravemente a interpretação identificatória."],
["Confronto","A identificação pericial mais robusta se baseia em:","confronto entre dados questionados e padrões ante mortem ou referências confiáveis.",["uma semelhança genérica.","relato não documentado.","impressão subjetiva do examinador.","localização geográfica."],"Quanto mais individualizante e bem documentado o confronto, maior sua força."],
["Síntese","Diante de possível asfixia, a conclusão pericial correta deve:","integrar achados corporais, exame interno, local, circunstâncias e exclusão de hipóteses alternativas.",["usar apenas um sinal externo.","presumir modalidade pelo local.","definir autoria pela lesão.","ignorar dados ambientais."],"Asfixias exigem análise multifatorial e linguagem cautelosa."],
["Síntese","Em tanatologia, a melhor prática é:","usar fenômenos cadavéricos como elementos complementares de uma estimativa, não como relógio absoluto.",["fixar horário exato pelo resfriamento.","ignorar temperatura ambiental.","usar somente os livores.","desconsiderar informações do caso."],"A cronologia pós-morte é inferência probabilística e contextual."],
["Síntese","Em identificação humana, a conclusão deve ser proporcional:","à qualidade dos vestígios, ao método empregado e ao material comparativo disponível.",["à necessidade de encerrar rapidamente o caso.","ao reconhecimento visual isolado.","ao relato de um familiar apenas.","à hipótese policial inicial."],"Método e evidência determinam o alcance da conclusão identificatória."],
["Síntese","A finalidade comum de documentação, cadeia de custódia e comparação técnica é:","permitir que a conclusão médico-legal seja rastreável, verificável e cientificamente fundamentada.",["substituir o exame pericial.","definir a sentença.","reduzir a necessidade de registros.","transformar hipótese em certeza."],"Esses pilares sustentam a confiabilidade do trabalho pericial." ],
["Asfixia mecânica","A classificação de asfixia mecânica deve apoiar-se em:","mecanismo demonstrável, achados periciais e circunstâncias tecnicamente compatíveis.",["sinal único de face.","posição final isolada.","opinião de testemunha apenas.","presunção jurídica."],"O mecanismo precisa ser sustentado por conjunto de evidências."],
["Afogamento","A espuma em vias aéreas, quando presente, deve ser considerada:","achado a ser correlacionado com necropsia, local e demais elementos, sem valor absoluto isolado.",["prova exclusiva de afogamento.","sinal de autoria.","indicador de horário preciso.","achado incompatível com submersão."],"Achados isolados têm limitações diagnósticas."],
["Tanatologia","A documentação de fenômenos cadavéricos deve informar:","condições ambientais, posição do corpo e características observadas no momento do exame.",["somente a hipótese de causa de morte.","o nome do responsável pelo caso.","a classificação jurídica.","apenas a temperatura corporal."],"Contexto ambiental influencia a interpretação de alterações pós-morte."],
["Putrefação","A intensidade da putrefação pode variar com:","temperatura, umidade, acesso de insetos, ambiente e características do corpo.",["a profissão da pessoa.","a decisão judicial.","a ordem de coleta.","o número de testemunhas."],"Por isso não se usa decomposição como marcador temporal rígido."],
["Identificação odontológica","Para confronto odontológico confiável, é especialmente útil dispor de:","registros ante mortem comparáveis, como fichas, imagens e tratamentos documentados.",["apenas relato oral de familiar.","a fotografia do local.","a causa presumida da morte.","o vestuário do cadáver."],"A comparação depende de dados individualizantes documentados."],
["DNA","Em identificação genética, contaminação de amostra pode:","comprometer a interpretação e exigir avaliação da cadeia de custódia e controles laboratoriais.",["aumentar automaticamente a certeza.","substituir amostra de referência.","confirmar parentesco por si só.","eliminar a necessidade de laudo."],"Prevenção e rastreabilidade são requisitos essenciais."],
["Antropologia","Estimativa de idade em restos esqueletizados deve ser apresentada:","como faixa ou estimativa técnica, acompanhada de método e incertezas pertinentes.",["como idade exata obrigatória.","sem referência ao método.","como identificação civil direta.","independentemente da preservação."],"Estimativas biológicas possuem limites inerentes."],
["Caso integrado","Restos humanos sem identificação visual disponível devem ser examinados por:","métodos complementares compatíveis com o estado dos vestígios e referências obtidas.",["documentos achados no local apenas.","uma fotografia de roupa.","hipótese policial inicial.","causa presumida do evento."],"A combinação de métodos pode aumentar a segurança identificatória."],
["Caso integrado","Em possível morte por asfixia em ambiente fechado, a perícia deve priorizar:","documentar corpo, ambiente, fontes de gás, ventilação e resultados de exames pertinentes.",["concluir apenas pela ausência de trauma externo.","ignorar condições ambientais.","atribuir culpa pelo local fechado.","restringir-se à inspeção da face."],"O ambiente pode ser determinante para compreender o mecanismo."],
["Síntese","A estimativa de intervalo pós-morte é mais adequada quando:","é expressa como avaliação fundamentada, com margem de incerteza e fatores que podem alterá-la.",["define horário exato sem ressalvas.","usa apenas a rigidez.","dispensa exame do local.","ignora alterações ambientais."],"Transparência sobre limites é essencial em cronotanatognose."],
["Síntese","Em Medicina Legal, identificação e causa de morte são conclusões:","distintas, que podem exigir métodos e evidências próprios, ainda que se complementem no caso.",["sempre idênticas.","obtidas apenas por reconhecimento visual.","dispensáveis em necropsia.","definidas por um único documento."],"Separar as perguntas periciais evita extrapolar o alcance de cada exame."],
["Síntese","A atitude pericial adequada diante de vestígio limitado é:","preservá-lo, documentá-lo e indicar com clareza o que ele permite ou não concluir.",["descartá-lo por ser incompleto.","transformá-lo em certeza.","omitir sua existência.","substituí-lo por hipótese."],"Vestígios limitados ainda podem ser úteis quando interpretados com rigor." ]
];
