// Criminalística — Lote 1: fundamentos, local de crime e cadeia de custódia.
const criminalisticaLoteUmDados=[
["Fundamentos","A Criminalística tem como finalidade principal:","examinar vestígios materiais para subsidiar a reconstrução tecnicamente fundamentada de fatos.",["definir a sentença.","substituir o inquérito.","atribuir culpa sem exame.","produzir apenas fotografias."],"A perícia trabalha com vestígios e método científico, dentro de seus limites."],
["Vestígio","Vestígio é entendido, em contexto pericial, como:","todo material, marca ou informação objetiva que possa ter relação com o fato investigado.",["somente objeto com DNA.","prova já valorada pelo juiz.","relato de testemunha exclusivamente.","conclusão final do laudo."],"O valor do vestígio depende de coleta, preservação, análise e correlação."],
["Local de crime","A preservação inicial do local busca principalmente:","evitar alteração, perda, contaminação ou acréscimo de vestígios antes do exame pericial.",["confirmar a hipótese inicial.","agilizar a liberação sem registro.","substituir fotografias por relatos.","definir autoria no atendimento."],"Isolamento e controle de acesso protegem a integridade do cenário."],
["Isolamento","O isolamento de local de crime deve:","delimitar área compatível com a dinâmica possível e controlar a entrada de pessoas.",["restringir-se ao ponto mais visível.","ocorrer depois da coleta.","dispensar registro de acesso.","seguir apenas a conveniência do local."],"A área pode precisar ser ampliada conforme novos vestígios são identificados."],
["Preservação","Preservar um local não significa:","impedir todo atendimento indispensável à vida e à segurança, que deve ser documentado.",["reduzir acessos desnecessários.","registrar alterações inevitáveis.","proteger vestígios frágeis.","controlar riscos no ambiente."],"Atendimento emergencial tem prioridade, mas alterações devem ser registradas."],
["Cadeia de custódia","A cadeia de custódia assegura:","rastreabilidade do vestígio desde o reconhecimento até seu descarte ou devolução.",["a conclusão jurídica automática.","a autoria do fato.","a infalibilidade do exame.","a substituição do laudo."],"Registro de cada etapa permite verificar origem, integridade e circulação do material."],
["Reconhecimento","Na cadeia de custódia, reconhecimento corresponde a:","ato de distinguir vestígio com potencial interesse para a persecução penal.",["examinar conclusivamente no laboratório.","emitir o laudo final.","descartar o objeto.","transportar a amostra."],"A etapa antecede coleta e exige observação técnica do cenário."],
["Fixação","A fixação de vestígio pode envolver:","descrição, fotografia, vídeo, croqui e outras formas de registro antes de sua remoção.",["apenas embalagem final.","somente relato oral.","destruição após observação.","decisão judicial."],"Registrar posição e condição original auxilia a reconstituição posterior."],
["Coleta","A coleta adequada deve:","usar técnica compatível com o tipo de vestígio e reduzir risco de perda ou contaminação.",["reunir materiais distintos na mesma embalagem.","dispensar identificação.","ocorrer sem registro.","priorizar rapidez sobre integridade."],"Método e embalagem dependem da natureza do material."],
["Acondicionamento","O acondicionamento de vestígio tem por objetivo:","preservar integridade e evitar mistura, degradação ou alteração do material.",["ocultar a identificação.","substituir o lacre.","eliminar a necessidade de coleta.","definir a pertinência jurídica."],"Cada vestígio deve receber embalagem e identificação adequadas."],
["Lacre","O lacre aplicado ao invólucro serve para:","evidenciar eventual violação e preservar a integridade documentada do conteúdo.",["identificar o autor do fato.","substituir a cadeia de custódia.","determinar a natureza do vestígio.","impedir toda abertura autorizada."],"Aberturas necessárias devem ser registradas conforme protocolo."],
["Recebimento","No recebimento em unidade pericial, é essencial conferir:","identificação, integridade de embalagens, lacres e registros de transferência.",["apenas o nome da ocorrência.","a opinião da autoridade.","a hipótese de autoria.","o resultado esperado."],"Inconsistências devem ser registradas antes da análise."],
["Processamento","O processamento de vestígio deve respeitar:","método validado, documentação das etapas e limites técnicos da análise.",["a conclusão desejada.","a narrativa mais detalhada.","a urgência sem controle.","a preferência do solicitante."],"A confiabilidade depende de procedimento, controle e interpretação proporcional."],
["Descarte","O descarte de vestígio deve ocorrer:","de forma documentada e conforme normas aplicáveis, preservando a rastreabilidade.",["assim que o laudo é iniciado.","sem registro para liberar espaço.","por decisão do perito isoladamente.","antes de eventual contraprova."],"A destinação é etapa integrante da cadeia de custódia."],
["Contaminação","Contaminação de vestígio pode ocorrer quando:","material externo é introduzido ou há transferência indevida entre fontes.",["a embalagem está identificada.","há fotografia do local.","o exame é documentado.","o lacre está íntegro."],"Uso de EPI, troca de materiais e separação de itens reduzem riscos."],
["Vestígio biológico","Em vestígio biológico, uma precaução importante é:","evitar contato cruzado entre amostras e documentar sua origem e acondicionamento.",["misturar fragmentos para ganhar tempo.","lavar a amostra sem registro.","dispensar luvas.","usar embalagem sem identificação."],"Contaminação pode comprometer análise e interpretação genética."],
["Vestígio digital","A busca por impressões papilares deve considerar:","superfície, condições ambientais e técnica de revelação compatível com o suporte.",["apenas a cor do objeto.","a autoria presumida.","o valor econômico do item.","a declaração de testemunhas."],"O método escolhido depende do tipo de superfície e estado do vestígio."],
["Vestígio latente","Vestígio latente é aquele que:","não é imediatamente perceptível e pode exigir técnica de revelação apropriada.",["não possui valor pericial.","já está identificado por etiqueta.","não pode ser fotografado.","é sempre biológico."],"A invisibilidade inicial não diminui sua potencial relevância."],
["Croqui","O croqui pericial auxilia porque:","representa relações espaciais entre vestígios, medidas e elementos relevantes do local.",["substitui todas as fotografias.","define autoria.","dispensa descrição escrita.","é obrigatório em qualquer situação sem exceção."],"Pode complementar registros fotográficos e descritivos."],
["Fotografia","A fotografia de local deve priorizar:","registro progressivo do geral ao particular, preservando contexto e detalhes dos vestígios.",["somente imagens aproximadas.","apenas os itens mais dramáticos.","alterar objetos para melhor enquadramento.","substituir a descrição."],"Sequência lógica facilita compreensão do cenário posteriormente."],
["Busca","A metodologia de busca em local deve ser:","planejada conforme tipo e extensão do ambiente, com documentação do percurso adotado.",["aleatória para evitar viés.","restrita a uma área sem justificativa.","realizada após remover todos os objetos.","independente do tipo de ocorrência."],"Método sistemático reduz risco de omissões."],
["Local interno","Em ambiente interno, o perito deve atentar para:","acessos, superfícies, distribuição de objetos e possíveis rotas de entrada e saída.",["somente o cômodo principal.","a versão inicial exclusivamente.","objetos de maior valor.","a aparência estética do ambiente."],"A análise do espaço integra a leitura da dinâmica."],
["Local externo","Em local externo, fatores que exigem atenção incluem:","chuva, vento, circulação de pessoas e veículos, que podem degradar ou deslocar vestígios.",["somente iluminação artificial.","o horário de emissão do boletim.","a identidade presumida.","a decisão judicial."],"Proteção rápida e documentação inicial são particularmente importantes."],
["Vestígio frágil","Diante de vestígio frágil, a prioridade é:","documentar e proteger o material antes que condições ambientais ou manuseio o alterem.",["aguardar alteração para confirmar sua fragilidade.","removê-lo sem registro.","abrir o local ao público.","substituí-lo por relato."],"A ordem de atuação deve considerar risco de perda."],
["Caso: socorro","Quando socorro altera a posição de objetos ou da vítima, a equipe deve:","registrar, quando possível, as alterações informadas e considerá-las na interpretação do local.",["desconsiderar o atendimento.","presumir que não houve alteração.","concluir a dinâmica imediatamente.","recriar a cena sem registro."],"Mudanças necessárias à assistência devem ser incorporadas à análise técnica."],
["Caso: acesso indevido","Entrada de pessoas não autorizadas em local isolado pode:","introduzir, remover ou deslocar vestígios e prejudicar a leitura da cena.",["aumentar a confiabilidade.","substituir a perícia.","confirmar a autoria.","eliminar a necessidade de controle."],"Controle de acesso é medida elementar de preservação."],
["Caso: objeto molhado","Vestígio úmido exige acondicionamento compatível porque:","umidade pode favorecer degradação e alterar características do material.",["todo material úmido deve ser lacrado sem avaliação.","a umidade confirma origem biológica.","não há risco de alteração.","fotografia basta para preservá-lo."],"O protocolo aplicável deve orientar secagem, embalagem e transporte."],
["Caso: embalagem comum","Embalar itens distintos juntos pode ser inadequado pois:","aumenta risco de transferência cruzada e dificulta individualização de origem.",["reduz o trabalho documental.","garante conservação idêntica.","confirma que os itens têm a mesma origem.","torna o lacre mais forte."],"Separação e identificação individual são boas práticas frequentes."],
["Vestígio questionado","Ao receber vestígio sem identificação suficiente, o laboratório deve:","registrar a inconsistência e verificar rastreabilidade antes de liberar conclusão técnica.",["atribuir origem provável.","examinar e ignorar a falha.","alterar a etiqueta sem registro.","descartar todos os registros."],"A identificação é requisito para vincular resultado ao caso correto."],
["Laudo","O laudo criminalístico deve distinguir:","observações, métodos empregados, resultados e interpretações compatíveis com os dados.",["fato e suposição como equivalentes.","hipótese e certeza absoluta.","resultado e decisão judicial.","registro e opinião pessoal."],"Transparência permite avaliar o alcance da conclusão."],
["Limitação","Quando a qualidade do vestígio limita o exame, o perito deve:","explicitar a limitação e evitar afirmar além do que os dados permitem.",["omitir o problema.","transformar indício em certeza.","descartar a documentação.","concluir pela autoria."],"Reconhecer limites faz parte da boa prática pericial."],
["Confronto","Um confronto pericial consistente exige:","comparação entre características do vestígio e padrões adequados, com método documentado.",["semelhança visual genérica.","opinião de testemunha.","objeto encontrado no local apenas.","uma hipótese investigativa."],"A força do confronto depende de qualidade, quantidade e individualização das características."],
["Reconstituição","A reconstituição técnica de dinâmica deve:","ser sustentada por vestígios e ser compatível com os limites da evidência disponível.",["seguir a primeira versão recebida.","definir responsabilidade penal.","ignorar hipóteses alternativas.","substituir exames laboratoriais."],"Hipóteses devem ser testadas contra os elementos materiais."],
["Princípio da troca","O princípio da troca, em Criminalística, orienta que:","interações podem produzir transferências materiais entre pessoas, objetos e ambientes.",["todo contato produz DNA identificável.","nenhum vestígio se perde.","a transferência prova autoria.","o local nunca sofre alteração."],"A possibilidade de transferência não elimina a necessidade de interpretar origem e contexto."],
["Caso: transferência secundária","A hipótese de transferência secundária deve ser considerada quando:","o vestígio pode ter chegado ao suporte por intermediário, exigindo cautela interpretativa.",["há resultado positivo conclusivo em qualquer contexto.","a amostra possui etiqueta.","o local está isolado.","o laudo é longo."],"A presença de material não explica sozinha como ele foi depositado."],
["Ordem de exame","A ordem de exames em um vestígio deve considerar:","técnicas potencialmente destrutivas, preservação de material e objetivo pericial.",["preferência pessoal sem critério.","apenas o custo do exame.","a hipótese de autoria.","o prazo judicial isolado."],"Planejamento evita que uma análise impeça outra mais informativa."],
["Material de referência","A coleta de padrão de referência exige:","identificação segura, documentação e procedimento que evite contaminação ou troca.",["apenas consentimento verbal informal.","embalagem conjunta com vestígio questionado.","ausência de registro.","resultado prévio positivo."],"Padrões são essenciais para comparações e precisam ter origem inequívoca."],
["Síntese","A qualidade de uma perícia de local depende de:","preservação, documentação, coleta adequada, cadeia de custódia e interpretação técnica integrada.",["uma fotografia isolada.","a convicção do perito.","a hipótese inicial.","a pressa de liberação."],"Cada etapa influencia a confiabilidade das seguintes."],
["Síntese","O controle de acesso a local de crime é importante porque:","reduz alterações não documentadas e facilita identificar fontes possíveis de vestígios.",["substitui o isolamento físico.","impede todo atendimento emergencial.","prova autoria.","dispensa fotografias."],"Registro de pessoas e intervenções contextualiza potenciais alterações."],
["Síntese","A conclusão criminalística tecnicamente responsável deve:","indicar o que os vestígios sustentam, o que é apenas compatível e quais limites permanecem.",["resolver questões jurídicas finais.","ocultar incertezas.","escolher uma versão sem confronto.","afirmar certeza em qualquer achado."],"A linguagem deve ser proporcional à evidência."],
["Síntese","A cadeia de custódia protege principalmente:","a rastreabilidade e a integridade documentada do vestígio ao longo de sua trajetória.",["a certeza de condenação.","a classificação do crime.","a autoria presumida.","a dispensa de exame."],"Sem rastreabilidade, a vinculação entre objeto e resultado pode ser questionada."],
["Síntese","Em Criminalística, preservar o local significa:","manter o maior número possível de informações materiais disponíveis para exame técnico posterior.",["impedir registro de mudanças.","remover objetos rapidamente.","aceitar alterações não documentadas.","definir a dinâmica antes do exame."],"A preservação permite que hipóteses sejam confrontadas com vestígios."],
["Síntese","Quando há dúvida sobre a origem de um vestígio, o perito deve:","registrar hipóteses plausíveis e limitar a conclusão ao que o exame efetivamente permite.",["atribuir origem mais conveniente.","descartar o vestígio sem exame.","concluir autoria pelo local.","ocultar a dúvida."],"A origem do vestígio depende de contexto, não apenas de sua detecção." ],
["Vestígio digital","Antes de manusear objeto com possível impressão papilar, é prudente:","avaliar e registrar a superfície, evitando contato que possa sobrepor ou apagar marcas latentes.",["limpar a superfície primeiro.","embalar vários objetos juntos.","concluir que não há vestígio visível.","permitir manuseio livre."],"O tratamento inicial pode definir a possibilidade de posterior revelação."],
["Vestígio balístico","Em local com possível vestígio balístico, a documentação deve incluir:","posição, contexto e identificação individual dos itens antes de sua remoção.",["apenas o calibre presumido.","a autoria apontada no boletim.","a hipótese de trajetória como certeza.","somente a fotografia do projétil."],"A posição e a relação espacial podem ser tão relevantes quanto o exame posterior do item."],
["Vestígio documental","Documento questionado deve ser preservado de modo a:","evitar alterações, dobras desnecessárias, contaminação e perda de características examináveis.",["permitir anotações sobre o original.","misturá-lo a outros papéis.","substituir o original por cópia.","carimbá-lo antes do exame."],"Manuseio inadequado pode prejudicar exames grafoscópicos, químicos ou de impressões."],
["Vestígio odorífero","A eventual coleta de vestígio odorífero exige:","procedimento especializado, controle de contaminação e documentação da origem do material.",["uso de embalagem comum sem identificação.","conclusão por cheiro percebido.","mistura com outros vestígios.","dispensa de cadeia de custódia."],"Como todo vestígio, sua validade depende de método apropriado e limites claros."],
["Relato pericial","A linguagem de um laudo deve ser preferencialmente:","clara, objetiva, tecnicamente fundamentada e proporcional ao grau de suporte dos achados.",["absoluta mesmo em dados incompletos.","baseada em expressões vagas.","voltada a confirmar hipótese prévia.","independente do método usado."],"Boa redação separa observação, resultado, interpretação e limitação."],
["Revisão","A revisão de documentação de local antes de encerrar o exame serve para:","verificar se registros, fotografias, identificação e coleta representam adequadamente os vestígios observados.",["substituir a análise laboratorial.","definir autoria.","eliminar necessidade de laudo.","alterar o local após liberação."],"Revisão reduz omissões e inconsistências no fluxo pericial."],
["Síntese","A preservação de vestígios e a documentação da cena permitem:","que hipóteses futuras sejam testadas sem depender apenas da memória dos envolvidos.",["eliminar toda incerteza.","substituir contraditório.","definir responsabilidade penal.","dispensar análise especializada."],"O registro técnico mantém disponível informação que pode ser reavaliada ao longo da investigação." ]
];
