// Criminalística — Lote 4: perícias de local e informática forense.
const criminalisticaLoteQuatroBases=[
["Dispositivo eletrônico","um dispositivo eletrônico apreendido", "preservar seu estado, documentar condição e aplicar procedimento forense que evite alteração indevida",["explorar livremente o conteúdo","conectar à internet sem registro","formatar o dispositivo","atribuir usuário pelo simples porte"]],
["Integridade digital","evidência digital", "verificar e registrar mecanismos de integridade que permitam demonstrar preservação do conteúdo analisado",["editar arquivos para facilitar leitura","ignorar metadados","dispensar cópia forense","presumir autenticidade absoluta"]],
["Metadados","metadados de arquivo", "interpretar data, origem e histórico considerando sistema, configuração, cópias e limites técnicos",["tratar data como prova absoluta","ignorar fuso horário","definir autoria pelo metadado","dispensar confronto com outros dados"]],
["Registro de acesso","registro de acesso digital", "correlacionar identificadores, horários, fonte do registro e demais evidências antes de atribuir conduta a pessoa",["equiparar IP a autoria certa","ignorar compartilhamento de conta","omitir origem do log","dispensar análise temporal"]],
["Imagem forense","imagem forense de mídia", "criar cópia tecnicamente verificável e trabalhar sobre a cópia preservando o original",["analisar apenas o original","alterar arquivos do original","dispensar verificação","apagar dados irrelevantes"]],
["Local de crime","vestígio em local complexo", "planejar busca, setores, registro de acessos e prioridades de preservação conforme risco de perda",["coletar itens sem ordem","liberar acesso amplo","registrar somente ao final","examinar só área principal"]],
["Vestígio temporal","cronologia de vestígios", "confrontar horários de fontes independentes e registrar diferenças de relógio ou configuração",["usar uma hora isolada","assumir sincronização perfeita","ignorar logs divergentes","definir autor pelo horário"]],
["Geolocalização","dado de geolocalização", "avaliar precisão, método de obtenção, intervalo temporal e contexto antes de inferir posição",["tratá-lo como coordenada infalível","ignorar margem de erro","definir atividade pelo ponto","dispensar outras fontes"]],
["Nuvem","dado armazenado em nuvem", "documentar origem, forma de obtenção, escopo e preservação dos dados recebidos",["supor que todo dado é local","misturar contas diferentes","omitir data de obtenção","dispensar registro de custódia"]],
["Laudo digital","conclusão de informática forense", "explicitar ferramentas, dados analisados, resultados e limitações sem extrapolar para autoria automática",["resolver questão jurídica","ocultar limitações","confundir conta com pessoa","afirmar certeza sem suporte"]]
];
const criminalisticaLoteQuatro=criminalisticaLoteQuatroBases.flatMap(([topic,obj,correct,wrongs],b)=>[
`No exame de ${obj}, a providência inicial tecnicamente correta é:`,
`Para preservar o valor probatório de ${obj}, é necessário:`,
`Diante de resultado relacionado a ${obj}, o perito deve:`,
`A interpretação inadequada de ${obj} ocorreria ao:`,
`No laudo referente a ${obj}, a conclusão deve:`
].map((stem,i)=>{const number=151+b*5+i,answer="ABCDE"[(number-1)%5],explicacao=["A providência inicial deve preservar o estado encontrado e evitar alterações desnecessárias.","A força probatória depende de demonstrar que o dado permaneceu íntegro e identificável.","O resultado deve ser correlacionado a outras fontes antes de qualquer inferência pessoal.","A leitura inadequada transforma um dado técnico limitado em conclusão que ele não suporta.","O laudo precisa expor método, escopo e limites com clareza."][i];return{id:`criminalistica-${String(number).padStart(3,"0")}`,subjectId:"criminalistica",number,topic,area:"Perícias de local e informática forense",stem,options:opcoesContextualizadas(correct,wrongs,answer,i),answer,explanation:`${explicacao} Em ${topic.toLowerCase()}, preservação e contexto são indispensáveis.`};}));
questionBank.questions.push(...criminalisticaLoteQuatro);
questionBank.review.criminalisticaLoteQuatroReviewed=criminalisticaLoteQuatro.map(q=>q.number);
questionBank.subjects.forEach(s=>{s.count=questionBank.questions.filter(q=>q.subjectId===s.id).length;});

// Criminalística — Lote 5: locais de crime, preservação e reconstrução técnica.
const criminalisticaLoteCincoDados=[
["Isolamento de local","Ao chegar a local com vestígios expostos à chuva, a medida inicial mais adequada é:","controlar o acesso e proteger os vestígios vulneráveis sem modificar sua posição.",["recolher todos os itens sem registro.","lavar áreas contaminadas antes da inspeção.","permitir circulação para identificar testemunhas.","definir a dinâmica antes da documentação."],"O isolamento reduz perdas e preserva a possibilidade de exame posterior."],
["Isolamento de local","A ampliação do perímetro de isolamento deve ocorrer quando:","a área inicialmente delimitada deixa de abranger trajetos, vestígios ou riscos relevantes.",["a equipe deseja reduzir fotografias.","não há qualquer vestígio aparente.","a investigação já definiu a autoria.","a coleta laboratorial foi concluída."],"O perímetro deve acompanhar o que é tecnicamente relevante, e não uma delimitação arbitrária."],
["Controle de acesso","O registro de entrada e saída no local periciado é relevante porque:","permite identificar intervenções e avaliar possíveis fontes de alteração ou contaminação.",["substitui o relatório fotográfico.","define a responsabilidade penal dos presentes.","dispensa a cadeia de custódia dos itens.","elimina a necessidade de isolamento."],"Saber quem acessou a cena preserva a rastreabilidade do exame."],
["Controle de acesso","Um profissional sem atribuição técnica pede para entrar no local já isolado. A conduta adequada é:","restringir o acesso enquanto não houver justificativa funcional e registro da entrada.",["autorizar a entrada se o fato for público.","permitir uma inspeção breve sem anotação.","entregar um vestígio para que ele observe.","liberar o acesso após fotografar a área."],"O acesso deve ser limitado ao necessário e documentado."],
["Preservação","Em cenário com possibilidade de atendimento emergencial, a perícia deve:","registrar as alterações inevitáveis e diferenciar o estado original do estado após o socorro.",["impedir qualquer atendimento à vítima.","desconsiderar mudanças causadas pelo resgate.","atribuir toda alteração ao autor do fato.","encerrar o exame antes de registrar intervenções."],"O socorro é prioritário, mas as modificações precisam ser corretamente contextualizadas."],
["Preservação","A movimentação de um objeto para eliminar risco imediato deve ser seguida de:","anotação de quem o moveu, por qual razão, quando e qual era sua posição conhecida.",["descarte do objeto após o risco cessar.","reposição estimada sem registro.","conclusão de que o item perdeu todo valor.","substituição por fotografia de arquivo."],"A documentação da alteração permite avaliar seu impacto na interpretação."],
["Documentação","A sequência mais apropriada para documentar um local é:","registrar a visão geral, relacionar áreas e, então, detalhar os vestígios relevantes.",["fotografar somente os itens já coletados.","medir antes de localizar os vestígios.","produzir croqui sem inspeção visual.","descrever o local apenas ao final do laudo."],"A progressão do geral ao particular mantém o vínculo entre objeto e contexto."],
["Documentação","A descrição escrita do local complementa as fotografias porque:","pode registrar condições, odores, posição relativa e observações que a imagem isolada não explica.",["dispensa o uso de escala nas imagens.","é suficiente para substituir a fotografia.","atribui automaticamente autoria aos envolvidos.","define a causa jurídica do evento."],"Fotografia, croqui e descrição são registros complementares."],
["Croqui","Em um croqui técnico, as medidas entre vestígio, parede e ponto fixo servem para:","permitir a reconstrução espacial da posição do vestígio no ambiente.",["identificar o responsável pelo fato.","substituir a cadeia de custódia.","confirmar a idade do vestígio.","eliminar a necessidade de fotografias."],"Referências mensuráveis tornam a localização verificável."],
["Cronologia","Quando diferentes registros indicam horários incompatíveis, o perito deve:","confrontar a origem de cada horário, configuração de relógios e sequência dos eventos antes de concluir.",["adotar automaticamente o primeiro horário informado.","descartar o registro que contraria a hipótese inicial.","calcular uma média e tratá-la como fato.","atribuir a divergência a erro intencional."],"Cronologia pericial depende de fontes e condições de registro verificáveis."],
["Busca sistemática","A divisão de um local amplo em setores tem como finalidade principal:","organizar a busca, reduzir omissões e vincular cada vestígio à área de origem.",["acelerar a liberação sem inspeção.","substituir a documentação individual.","concentrar todos os itens em uma embalagem.","eliminar a necessidade de revisão final."],"Setorização favorece cobertura ordenada e controle do trabalho."],
["Busca sistemática","A escolha do método de busca em local externo deve considerar:","dimensões, tipo de terreno, número de examinadores e natureza esperada dos vestígios.",["a preferência pessoal do primeiro agente.","a hipótese de autoria já divulgada.","o menor número possível de registros.","apenas a proximidade da via pública."],"Não existe um único padrão de busca adequado para todo cenário."],
["Vestígio frágil","Uma impressão pouco nítida em superfície instável deve ser priorizada porque:","pode se degradar com o tempo, manuseio ou alterações ambientais.",["necessariamente identifica uma pessoa.","dispensa registro fotográfico.","pode ser revelada depois de qualquer limpeza.","substitui outros vestígios do local."],"O risco de perda orienta a ordem de preservação e documentação."],
["Vestígio frágil","Antes de coletar vestígio suscetível a dispersão pelo vento, é correto:","documentar sua posição e empregar acondicionamento compatível com sua natureza.",["transferi-lo para outro ponto da cena.","juntar materiais parecidos em recipiente único.","aguardar até o encerramento do exame.","removê-lo sem identificar sua origem."],"Vestígios frágeis exigem prioridade e individualização."],
["Manchas","A análise de manchas em uma superfície deve evitar:","inferir mecanismo único sem considerar substrato, distribuição, documentação e hipóteses alternativas.",["registrar dimensões das manchas.","relacionar o padrão a outros vestígios.","informar os limites do exame.","preservar amostras para testes."],"A interpretação depende do conjunto de dados, não de uma aparência isolada."],
["Manchas","Uma mancha parcialmente removida por ação de terceiros deve ser tratada como:","elemento cuja alteração precisa ser documentada, com cautela sobre o alcance de inferências posteriores.",["vestígio sem qualquer valor técnico.","prova definitiva de ocultação.","base para reconstrução exata sem limitações.","material que deve ser lavado antes do registro."],"Alteração não impede necessariamente o exame, mas limita conclusões."],
["Trajetória","Para estimar a direção associada a danos em diferentes suportes, é necessário:","correlacionar medidas, características dos danos, obstáculos e demais dados do local.",["usar apenas a posição final de um objeto.","considerar uma única marca suficiente.","presumir que todo dano é linear.","atribuir a direção à narrativa de uma testemunha."],"Reconstrução espacial deve expor premissas e limitações."],
["Trajetória","Um diagrama de reconstrução técnica deve apresentar:","dados observados, referências utilizadas, hipóteses adotadas e limites de precisão.",["somente a conclusão final.","a identidade presumida do autor.","afirmações jurídicas sem método.","fotografias sem escala ou legenda."],"Transparência metodológica permite avaliar a solidez do modelo."],
["Reconstrução","Ao testar duas hipóteses compatíveis com os vestígios, o perito deve:","indicar quais dados sustentam ou limitam cada hipótese, sem selecionar uma por conveniência.",["eliminar a hipótese menos comum sem análise.","adotar a versão mais narrada nos autos.","apresentar ambas como certezas simultâneas.","omitir a hipótese que contraria a suspeita."],"A análise técnica deve confrontar explicações alternativas com os achados."],
["Reconstrução","A ausência de um vestígio esperado em determinado cenário pode:","ser relevante, desde que se considerem condições de produção, preservação, busca e sensibilidade do método.",["provar automaticamente que o fato não ocorreu.","confirmar a versão mais conveniente.","substituir todos os vestígios presentes.","dispensar registro de busca."],"Ausências precisam ser interpretadas à luz das condições concretas de detecção."],
["Cadeia de custódia","A individualização de embalagens na coleta busca principalmente:","manter a relação entre item, origem, identificação e histórico de custódia.",["aumentar o volume de material enviado.","eliminar a necessidade de lacre.","dispensar exames posteriores.","definir o valor jurídico do vestígio."],"Itens separados preservam sua origem e evitam transferências indevidas."],
["Cadeia de custódia","Ao receber item lacrado para exame, o primeiro registro relevante é:","sua identificação, condição da embalagem, lacre e informações de recebimento.",["a conclusão sobre autoria.","a escolha imediata da técnica analítica.","o descarte da embalagem externa.","a classificação penal do fato."],"A condição de recebimento integra a rastreabilidade do vestígio."],
["Cadeia de custódia","Se a identificação externa de uma embalagem diverge da requisição, a medida adequada é:","registrar a inconsistência e adotar providência técnica e administrativa antes de vincular o conteúdo ao caso.",["corrigir a etiqueta sem registro.","presumir que o conteúdo está correto.","ignorar a divergência se o item parecer semelhante.","descartar imediatamente o material."],"Inconsistências de identificação devem ser tratadas de modo rastreável."],
["Contaminação","A utilização de controles de coleta contribui para:","avaliar se procedimento, ambiente ou materiais introduziram elementos que afetem a interpretação.",["confirmar autoria de forma independente.","substituir a amostra questionada.","dispensar coleta de referência.","aumentar a quantidade do vestígio."],"Controles ajudam a distinguir achados do caso de possíveis interferências."],
["Contaminação","A suspeita de transferência cruzada entre itens exige:","revisar sequência de manipulação, embalagens, controles e impacto possível no resultado.",["declarar fraude sem análise.","manter a conclusão original sem ressalvas.","eliminar todos os registros do exame.","atribuir o evento ao último manipulador."],"A revisão deve ser técnica, documentada e proporcional ao risco."],
["Incêndio","Em local atingido por incêndio, a análise de origem e causa deve:","considerar padrões de danos, fontes de ignição, materiais, contexto e hipóteses concorrentes.",["basear-se apenas no odor percebido.","atribuir dolo pela intensidade das chamas.","usar um ponto carbonizado isolado como prova conclusiva.","dispensar documentação antes da remoção."],"Incêndios exigem avaliação integrada e cautela contra inferências intuitivas."],
["Incêndio","A coleta de material com possível interesse para exame de acelerantes requer:","acondicionamento compatível, identificação da origem e prevenção de perdas por volatilização ou contaminação.",["embalagem aberta para ventilação.","mistura de amostras de áreas distintas.","lavagem do recipiente antes do envio.","conclusão de causa antes do exame."],"Condições de embalagem influenciam diretamente a utilidade analítica."],
["Explosões","No exame de local de explosão, a segurança e a preservação exigem inicialmente:","avaliar riscos remanescentes e organizar o acesso antes da busca detalhada por fragmentos.",["reunir curiosos para identificar peças.","movimentar todos os fragmentos para o centro.","descartar peças pequenas sem registro.","atribuir tipo de artefato por impressão visual."],"A cena pode conter riscos e vestígios dispersos que exigem controle rigoroso."],
["Explosões","Fragmentos recuperados após explosão devem ser tratados como:","itens individualizáveis cuja posição e relação espacial podem contribuir para reconstrução.",["resíduos sem necessidade de origem.","prova isolada da autoria.","objetos que devem ser limpos antes da foto.","material a ser agrupado apenas por cor."],"A distribuição de fragmentos pode ser tão relevante quanto sua composição."],
["Acidente de trânsito","Na reconstrução de ocorrência viária, marcas no pavimento devem ser avaliadas com:","registro de extensão, orientação, condições da via e correlação com veículos e demais vestígios.",["apenas estimativa visual de velocidade.","presunção de culpa pelo ponto final.","desconsideração das condições climáticas.","substituição do levantamento por relato."],"Marcas viárias adquirem sentido com medidas e contexto físico."],
["Acidente de trânsito","A posição final de veículos após colisão, isoladamente:","não permite reconstruir toda a dinâmica sem análise de danos, trajetória e condições do cenário.",["define a velocidade exata.","identifica automaticamente o condutor.","substitui a inspeção dos veículos.","elimina a necessidade de croqui."],"A posição final é um dado relevante, porém incompleto."],
["Vestígio em veículo","Ao documentar dano em veículo, o perito deve:","relacionar sua localização, altura, deformação e possíveis transferências a outros elementos do caso.",["reparar a área antes da fotografia.","atribuir culpa pela cor do veículo.","medir apenas a parte mais visível.","desconsiderar danos preexistentes."],"Danos e transferências devem ser contextualizados e comparados."],
["Vestígio digital no local","Uma tela de equipamento encontrada ligada no local deve ser:","documentada quanto ao estado visível e tratada com procedimento que minimize alterações no conteúdo.",["navegada livremente para localizar provas.","desligada sem registro em qualquer situação.","fotografada apenas após alterações.","associada automaticamente ao usuário presente."],"O estado inicial pode conter informações relevantes e deve ser preservado."],
["Vestígio digital no local","Uma mensagem exibida em dispositivo não permite, por si só:","atribuir autoria do texto sem examinar contexto, conta, dispositivo e demais dados disponíveis.",["registrar a tela observada.","indicar uma linha investigativa.","preservar o dispositivo.","solicitar análise especializada."],"Conta, aparelho e autor físico podem não ser a mesma pessoa."],
["Relatório pericial","Ao redigir conclusão sobre local de crime, o laudo deve:","distinguir observações diretas, resultados de exames, inferências e limitações técnicas.",["apresentar hipótese como fato indiscutível.","substituir a decisão judicial.","omitir dados divergentes.","usar linguagem conclusiva sem método."],"A clareza evita que a força da evidência seja superestimada."],
["Relatório pericial","O emprego de termos como \"compatível com\" em um laudo pode ser adequado quando:","os achados sustentam uma hipótese, mas não excluem de forma técnica outras possibilidades razoáveis.",["o perito quer evitar descrever o método.","há certeza absoluta de autoria.","não houve qualquer exame.","o resultado é juridicamente irrelevante."],"A linguagem deve refletir o real grau de suporte do material."],
["Relatório pericial","Uma limitação metodológica relevante deve constar no laudo porque:","permite que o alcance da conclusão seja compreendido e avaliado de modo transparente.",["enfraquece automaticamente todo resultado.","substitui a descrição dos achados.","dispensa a apresentação do método.","define a responsabilidade criminal."],"Limitações explicitadas qualificam, e não invalidam por si, a conclusão."],
["Integração de vestígios","A correlação entre vestígios físicos, digitais e documentais é mais confiável quando:","cada fonte é preservada, examinada e relacionada por dados verificáveis e independentes.",["uma única fonte confirma todas as demais.","a hipótese precede a análise dos dados.","os registros divergentes são omitidos.","a autoria é presumida pela proximidade."],"Convergência exige fontes com origem e método identificáveis."],
["Integração de vestígios","Em local complexo, a revisão final da documentação tem por objetivo:","verificar se áreas, itens coletados, fotografias e registros de acesso formam conjunto coerente.",["eliminar a necessidade de laudo.","alterar a posição dos itens para melhorar imagens.","definir a autoria antes dos exames.","reduzir o número de vestígios enviados."],"Revisão final reduz lacunas e inconsistências no fluxo pericial."],
["Hipóteses","A hipótese inicial apresentada pela investigação deve ser usada pelo perito como:","informação de contexto a ser confrontada criticamente com os vestígios, e não como conclusão antecipada.",["base suficiente para selecionar apenas evidências favoráveis.","motivo para ignorar versões alternativas.","prova da dinâmica do fato.","substituto de exame técnico."],"Imparcialidade técnica exige testar, e não apenas confirmar, hipóteses."],
["Hipóteses","Quando os vestígios sustentam mais de uma reconstrução plausível, a conclusão adequada é:","explicitar as alternativas e indicar quais dados seriam necessários para discriminá-las melhor.",["escolher a versão mais provável sem justificar.","afirmar que todas são igualmente comprovadas.","omitir a incerteza para simplificar o laudo.","atribuir a escolha à autoridade policial."],"O laudo deve traduzir o grau de discriminação efetivamente alcançado."],
["Vestígio questionado","Um vestígio encontrado fora da área inicialmente delimitada deve ser:","documentado, avaliado quanto à relação com o caso e incorporado ao controle de acesso e perímetro se pertinente.",["ignorado por estar fora do croqui inicial.","coletado sem registrar posição.","descoberto apenas após liberação do local.","atribuído automaticamente a terceiro."],"O perímetro pode precisar ser revisto diante de novos achados."],
["Vestígio questionado","A diferença entre vestígio e evidência, no uso pericial, está em que:","o vestígio é o elemento material observado, cujo significado probatório depende de exame e interpretação contextual.",["todo vestígio prova autoria imediatamente.","evidência é apenas objeto físico sem análise.","vestígio não pode ser documentado.","os termos dispensam a cadeia de custódia."],"O valor probatório não decorre apenas da presença material de um item."],
["Locais de crime","A preservação adequada do local busca, principalmente:","manter disponíveis as informações materiais necessárias para exame técnico e confronto de hipóteses.",["garantir que nenhuma pessoa seja responsabilizada.","definir a versão definitiva no local.","substituir entrevistas e investigações.","evitar toda alteração ambiental possível."],"Preservação reduz perdas, mas o exame ainda deve reconhecer suas limitações."],
["Locais de crime","A decisão sobre a ordem de coleta deve priorizar:","o risco de perda ou alteração do vestígio, sua relevância e a compatibilidade entre procedimentos.",["o item visualmente mais chamativo.","a coleta mais rápida, independentemente do risco.","a hipótese defendida por uma das partes.","o material mais fácil de embalar."],"Prioridades técnicas evitam que uma coleta prejudique outra análise possível."],
["Locais de crime","O encerramento do exame de local é mais seguro após:","revisão de registros, verificação dos itens coletados e avaliação de pendências técnicas documentadas.",["a primeira fotografia panorâmica.","a identificação de um suspeito.","a chegada de testemunha ao local.","o recolhimento do maior vestígio."],"O encerramento deve resultar de checagem sistemática, não de impressão subjetiva."],
["Síntese","Uma conclusão pericial robusta sobre dinâmica de local depende de:","vestígios preservados, documentação completa, método explícito e interpretação limitada ao suporte disponível.",["narrativa única sem exame complementar.","quantidade de fotografias sem contexto.","presunção de autoria pelo cenário.","afirmações categóricas sem indicar dados."],"A robustez vem da rastreabilidade e da convergência de informações."],
["Reconstituição","A reprodução técnica de uma posição ou sequência de eventos somente é útil quando:","suas premissas são documentadas e compatíveis com medidas, registros e vestígios do caso.",["substitui os dados originais já coletados.","é construída para confirmar uma narrativa prévia.","dispensa a indicação de margens de erro.","elimina hipóteses alternativas por si só."],"Uma reconstituição é um modelo técnico e deve poder ser confrontada com os dados que a sustentam."],
["Avaliação crítica","Ao identificar lacuna relevante na documentação de local, o perito deve:","registrar a limitação e avaliar de que modo ela restringe as conclusões possíveis.",["preencher a lacuna com suposições não verificadas.","omitir a ausência para preservar a narrativa.","tratar a limitação como prova de autoria.","substituir o registro ausente por memória de terceiros."],"Reconhecer uma lacuna permite delimitar adequadamente o alcance técnico do laudo."],
["Síntese","No exame de locais, a conduta que mais compromete a análise é:","alterar ou manipular elementos antes de documentar sua posição e condição originais.",["registrar a cena em etapas.","individualizar itens coletados.","controlar os acessos ao perímetro.","revisar a documentação final."],"A posição e o estado originais podem ser irreversivelmente perdidos por intervenção precoce."]
];
const criminalisticaLoteCinco=criminalisticaLoteCincoDados.map(([topic,stem,correct,wrongs,explanation],index)=>{const number=201+index,answer="ABCDE"[index%5];return{id:`criminalistica-${String(number).padStart(3,"0")}`,subjectId:"criminalistica",number,topic,area:"Locais de crime, preservação e reconstrução",stem,options:opcoesIntegradas(correct,wrongs,answer),answer,explanation};});
questionBank.questions.push(...criminalisticaLoteCinco);
questionBank.review.criminalisticaLoteCincoReviewed=criminalisticaLoteCinco.map(q=>q.number);
questionBank.subjects.forEach(s=>{s.count=questionBank.questions.filter(q=>q.subjectId===s.id).length;});

