const refinarDistratorCriminalistica=text=>text
  .replace(/concluir identidade por semelhança geral/gi,"admitir identificação a partir de semelhança geral, sem confronto suficiente")
  .replace(/definir autoria criminal/gi,"atribuir autoria com base exclusivamente no achado técnico")
  .replace(/definir autoria do portador/gi,"atribuir autoria ao portador sem correlação adicional")
  .replace(/definir autoria pelo metadado/gi,"atribuir autoria a partir de metadado isolado")
  .replace(/definir dinâmica do fato sozinho/gi,"explicar a dinâmica exclusivamente a partir daquele achado")
  .replace(/omitir a divergência/gi,"tratar a divergência como irrelevante sem análise complementar")
  .replace(/descartar toda documentação/gi,"atribuir peso reduzido à documentação disponível")
  .replace(/presumir autenticidade absoluta/gi,"presumir autenticidade sem verificar origem e integridade")
  .replace(/usar resultado como certeza/gi,"conferir ao resultado alcance superior ao permitido pelo método")
  .replace(/limpar antes de examinar/gi,"iniciar o exame após limpeza prévia da superfície")
  .replace(/considerar ausência definitiva/gi,"tratar a ausência de revelação como resultado definitivo")
  .replace(/dispensa\s+([^.]*)/gi,"trata como secundária a exigência de $1")
  .replace(/\bdispensar\s+([^.]*)/gi,"considerar secundária a necessidade de $1")
  .replace(/\bignorar\s+([^.]*)/gi,"atribuir relevância reduzida a $1")
  .replace(/\bautomaticamente\b/gi,"por relação direta")
  .replace(/\bde forma absoluta\b/gi,"de maneira definitiva")
  .replace(/\bcerteza absoluta\b/gi,"conclusão definitiva")
  .replace(/\bcerteza\b/gi,"conclusão definitiva")
  .replace(/\babsoluta\b/gi,"sem ressalvas")
  .replace(/\bapenas\b/gi,"predominantemente")
  .replace(/\bqualquer\b/gi,"uma única")
  .replace(/\bsempre\b/gi,"necessariamente")
  .replace(/\bnunca\b/gi,"em hipótese alguma")
  .replace(/exigência de o /gi,"exigência do ");
questionBank.questions.filter(q=>q.subjectId==="criminalistica").forEach(q=>{
  q.options=q.options.map(option=>option.letter===q.answer?option:{...option,text:refinarDistratorCriminalistica(option.text)});
});

// Reforma editorial de Inglês — lote 1: textos curtos, inferência e referência real.
const inglesReworkLoteUmCasos=[
["Data quality and automated decisions","A public agency introduced a screening tool to help prioritize applications. The tool reduced processing time, but an internal review found that incomplete historical records produced uneven results across regions. For that reason, the agency kept human review for borderline cases while improving the underlying database.","The text presents automation as useful but dependent on reliable data and human oversight.","Faster processing did not remove the need to examine how the tool affected different regions.","that reason","the uneven results linked to incomplete historical records","underlying","serving as the basis for something","explain a cautious institutional response to a useful technology"],
["Water-quality monitoring","After heavy rainfall, a municipal laboratory increased the frequency of water sampling. Early tests indicated a change in turbidity, not a confirmed contamination event. The laboratory therefore issued a preventive notice and scheduled confirmatory analyses before recommending restrictions on use.","The text distinguishes an initial warning sign from a confirmed public-health conclusion.","The laboratory considered additional testing necessary before adopting stronger measures.","therefore","the need to respond cautiously to the preliminary result","confirmatory","intended to verify an initial result","describe a sequence of proportionate technical actions"],
["Digital evidence preservation","Investigators collected a mobile device during an inspection. Before examining its contents, they documented its condition, isolated it from external networks and created a forensic copy. The original device was retained so that later analysis could be checked against the source material.","The passage emphasizes preserving the source and documenting each step before analysis.","The procedure was designed to allow later verification of the examination.","its contents","the information stored on the mobile device","retained","kept for future use or verification","justify safeguards used when handling digital evidence"],
["Public policy evaluation","A city expanded a training program after a pilot project showed higher completion rates among participants. The report, however, noted that the pilot involved volunteers and did not measure long-term employment outcomes. Officials treated the results as encouraging evidence, not as a final assessment of the program's impact.","The report supports expansion while recognizing limits in the available evidence.","The observed completion rates do not by themselves establish long-term employment effects.","however","the limits of the pilot evidence","impact","the effect produced by an intervention","present a qualified interpretation of program results"],
["Method validation","A laboratory adopted a new analytical method for a complex sample matrix. Before using it in routine examinations, the team tested accuracy, precision and possible interference under conditions similar to those expected in casework. The method was approved only after the results met the predefined acceptance criteria.","The passage describes validation as testing whether a method is fit for its intended use.","The laboratory did not assume that good results in one setting would automatically apply to every sample.","those expected in casework","conditions similar to the real cases the laboratory expects to examine","interference","a factor that may affect the result","explain why validation precedes routine application"],
["Climate-data communication","A research bulletin reported that a recent temperature trend was consistent with several climate models. It also stated that short-term variation could occur within the broader pattern. The authors used the word 'consistent' to show agreement with available evidence, not to claim that every future measurement had been predetermined.","The bulletin distinguishes long-term evidence from certainty about each short-term observation.","The authors accept that individual measurements may vary without disproving the broader trend.","broader pattern","the long-term temperature trend discussed in the bulletin","predetermined","fixed in advance with no possibility of variation","clarify the level of certainty attached to a scientific statement"],
["Procurement transparency","During a procurement review, an agency published the technical criteria used to compare proposals. It did not disclose protected commercial information, but it explained how the criteria were weighted and recorded the reasons for the final decision. This approach allowed external scrutiny without treating transparency as unlimited disclosure.","The text presents transparency as reasoned disclosure compatible with lawful confidentiality.","Public access can coexist with protection for information that is legally restricted.","This approach","the combination of disclosed criteria and protected commercial information","scrutiny","careful external examination","show how accountability can be balanced with confidentiality"],
["Data protection","A university revised its research-data policy after finding that several teams were collecting more personal information than their projects required. The new policy requires researchers to justify each category of data and to remove identifiers when they are no longer necessary for the approved purpose.","The policy seeks to limit data collection and retention to what a research purpose requires.","The institution treats unnecessary identifiers as a risk even when the information was collected lawfully.","they","identifiers that are no longer necessary","retention","the act of keeping information over time","describe a policy designed to reduce unnecessary exposure of personal data"],
["Epidemiological surveillance","A surveillance unit observed an increase in reports of a respiratory syndrome in two districts. Because reporting practices had changed in one of them, analysts compared the notifications with hospital admissions and laboratory findings before describing the increase as evidence of broader transmission.","The text shows that surveillance data must be interpreted with attention to changes in reporting and other evidence.","A rise in notifications may reflect more than one explanation.","one of them","one of the two districts","broader","covering a wider area or range","illustrate why multiple sources are used in epidemiological interpretation"],
["Risk communication","Following a product recall, a regulator issued guidance explaining what consumers should check, which products were affected and where additional information could be found. The notice avoided predicting individual outcomes because the available reports did not establish the risk for every user.","The notice provides practical guidance while avoiding conclusions unsupported by the reports.","The regulator considered it important to communicate action steps without overstating individual risk.","The notice","the regulator's guidance about the recall","affected","included in or influenced by the recall","describe responsible communication under uncertainty"]
];
const inglesReworkPerguntas=(caso)=>{const [area,text,main,inference,reference,referent,word,meaning,purpose]=caso;return[
["Ideia central",`Read the text:\n\n“${text}”\n\nWhat is the main idea of the passage?`,main,["It reduces the discussion to a secondary operational detail.","It presents a provisional finding as a final conclusion.","It reverses the relationship between evidence and action.","It treats a single example as the only relevant factor."]],
["Inferência",`Read the text:\n\n“${text}”\n\nWhich inference is best supported?`,inference,["The passage excludes the need for further assessment.","The author treats every reported result as equally conclusive.","The text assumes that context cannot affect interpretation.","The conclusion depends on information not mentioned in the passage."]],
["Referência textual",`Read the text:\n\n“${text}”\n\nIn context, **${reference}** refers to:`,referent,["a separate procedure mentioned only as a possibility.","an institution not identified in the passage.","a conclusion that the author explicitly rejects.","a result expected to occur in the future."]],
["Vocabulário em contexto",`Read the text:\n\n“${text}”\n\nThe word **${word}** is closest in meaning to:`,meaning,["concealed from every reader","eliminated from the process","misunderstood in context","postponed until later"]],
["Propósito comunicativo",`Read the text:\n\n“${text}”\n\nThe author mainly intends to:`,purpose,["give a biography of the institution involved.","announce a result that no longer requires review.","describe an unrelated historical episode.","provide instructions for operating a device."]]
];};
const inglesReworkLoteUm=inglesReworkLoteUmCasos.flatMap((caso,bloco)=>inglesReworkPerguntas(caso).map(([topic,stem,correct,wrong],indice)=>{const number=151+bloco*5+indice,answer="ABCDE"[(number-151)%5];return{id:`ingles-${String(number).padStart(3,"0")}`,subjectId:"ingles",number,topic,area:caso[0],stem,options:opcoesIntegradas(correct,wrong,answer),answer,explanation:"A alternativa correta decorre das relações de sentido, das qualificações e do vocabulário presentes no texto. Os distratores alteram o alcance da afirmação, confundem referência ou extrapolam o que o trecho permite concluir."};}));
const inglesReworkLoteUmPorNumero=new Map(inglesReworkLoteUm.map(question=>[question.number,question]));
questionBank.questions=questionBank.questions.map(question=>question.subjectId==="ingles"&&inglesReworkLoteUmPorNumero.has(question.number)?inglesReworkLoteUmPorNumero.get(question.number):question);
questionBank.review.inglesReworkLoteUmReviewed=inglesReworkLoteUm.map(question=>question.number);

// Mantém a numeração sequencial também na ordem física do banco, inclusive quando
// lotes de uma mesma matéria foram publicados em momentos diferentes.
const ordemMaterias=new Map(questionBank.subjects.map((subject,index)=>[subject.id,index]));
questionBank.questions.sort((a,b)=>(ordemMaterias.get(a.subjectId)-ordemMaterias.get(b.subjectId))||a.number-b.number);
questionBank.subjects.forEach(subject=>{subject.count=questionBank.questions.filter(question=>question.subjectId===subject.id).length;});
